  b.push(wp(wr('What was the employee doing just before the incident?', { b: true })), P(r.doingBefore || '—', { after: 100 }));
  b.push(KV('Object or substance that directly harmed the employee', r.objectSubstance));
  b.push(H('Section 5: Equipment / Product Involved'));
