ATL_SRC.push(['@atl/training/program.js', 0, `// Generated by build-training.ps1 from the Piper 2027 Safety & Training Program (the program's own text, unchanged).
// Do not edit by hand - re-run the script after the documents change.
export const PROGRAM = {"title":"2027 Warehouse Safety \\u0026 Training Program","year":2027,"start":"2027-01-04","source":"C:\\\\Users\\\\JoshP\\\\OneDrive - 07-2020 Piper Logistics\\\\ATLANTA\\\\Admin Form\\\\Training Program\\\\Piper_2027_Safety_Training_Program.zip","weekly":[{"code":"W01","week":1,"doc":"PWH-MTR-2027-W01","date":"2027-01-04","holiday":false,"month":1,"title":"Your Stop-Work Authority: When and How to Call It","behavior":"Find one thing on your shift that should be stopped or fixed — a leaning stack, a missing chock, a blocked exit — and call it out to me before lunch.","track":"","file":"Part 3 - Weekly Jan-Apr/W01 Jan 4 - Your Stop-Work Authority When and How to Call It.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nYour Stop-Work Authority: When and How to Call It"]],["tr",["Doc No: PWH-MTR-2027-W01\\nWeek: 1 · Mon Jan 4, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 1 of 52 · January 2027"]],["tr",["Monday training title","Your Stop-Work Authority: When and How to Call It"]],["tr",["Monthly theme","Safety Leadership Kickoff: Stop-Work, Hazards \\u0026 Near Misses"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company policy — awareness"]],["tr",["Training objective","Every employee can say the stop-work words and name who they notify."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Raise your hand if you\\u0027ve ever watched something happen on the floor and thought \\"that\\u0027s not right\\" — but kept quiet. Starting today, quiet is not an option. Every one of you has the authority to stop unsafe work."],["h","3. KEY TEACHING POINTS"],["pt","1. Anyone can stop any job."],["p","New hire, temp, lead, driver, supervisor. No permission needed and no need to be certain."],["pt","2. Use plain words."],["p","\\"Stop. That\\u0027s not safe.\\" Loud enough to be heard over the equipment."],["pt","3. Make it safe, then get your supervisor."],["p","Set the load down, shut off the truck, step out of the path. Then call [SITE: supervisor / lead name or radio channel]."],["pt","4. Work restarts only after the fix."],["p","The supervisor or lead confirms the hazard is corrected or controlled before anyone restarts."],["pt","5. No one is punished for a good-faith stop."],["p","Not stopping something you knew was unsafe is the violation."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Here\\u0027s how it works on this shift. If you see something that could hurt somebody, you say \\"Stop, that\\u0027s not safe.\\" You don\\u0027t have to be right. You don\\u0027t have to know the rule number. If it looks wrong, call it."],["p","After you call it, make it safe if you can do it without putting yourself in danger. If it\\u0027s a truck, the operator sets the load down and shuts it off. If it\\u0027s a person walking into a travel path, they step back. Then you get me or the lead on the radio. We look at it together, we fix it, and then the job restarts."],["p","I\\u0027ll be honest about the part that matters most: how I react. If you stop a job and it turns out to be fine, I\\u0027m going to thank you, not give you a hard time. The only thing I\\u0027ll have a problem with is if you saw something and said nothing."],["call","SHOW IT: Point to the radio channel or phone number on the board and make everyone repeat the stop-work words once out loud."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. Rolls stacked too high at the dock."],["p","A lead sees a clamp operator setting a third roll on a column in the dock staging lane where the posted limit is two. He says \\"Stop, that\\u0027s over height,\\" the operator sets the roll back on the floor, and the lead calls the supervisor. The stack is rebuilt within the limit before anyone walks the lane."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What would make you hesitate to stop a job here — and what can I do about it?"],["p","Listen for: Fear of looking dumb, fear of slowing down production, not wanting to call out a senior operator. Answer each one directly: good-faith stops are never punished."],["h","7. KNOWLEDGE CHECK"],["pt","1. You\\u0027re not sure whether a job is unsafe. Should you stop it?"],["p","Answer: Yes. You don\\u0027t need to be certain. Stop it, make it safe, and get your supervisor to look at it."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Find one thing on your shift that should be stopped or fixed — a leaning stack, a missing chock, a blocked exit — and call it out to me before lunch."],["h","9. SUPERVISOR VERIFICATION"],["li","Ask three employees at random to say the stop-work words and who they call."],["li","Respond to any stop called today within 5 minutes and thank the person in front of the crew."],["li","Log any stops or hazards raised today on PWH-FRM-204-1."],["p","References: Safety Incident / Near Miss Report PWH-FRM-204-1 • Food Safety Culture Policy PWH-POL-122-2 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W02","week":2,"doc":"PWH-MTR-2027-W02","date":"2027-01-11","holiday":false,"month":1,"title":"Hazard Recognition and Near-Miss Reporting in Two Minutes","behavior":"Do a three-level scan of your first work area before you start. Report at least one hazard or near miss to me by the end of the shift.","track":"","file":"Part 3 - Weekly Jan-Apr/W02 Jan 11 - Hazard Recognition and Near-Miss Reporting in Two Minutes.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nHazard Recognition and Near-Miss Reporting in Two Minutes"]],["tr",["Doc No: PWH-MTR-2027-W02\\nWeek: 2 · Mon Jan 11, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 2 of 52 · January 2027"]],["tr",["Monday training title","Hazard Recognition and Near-Miss Reporting in Two Minutes"]],["tr",["Monthly theme","Safety Leadership Kickoff: Stop-Work, Hazards \\u0026 Near Misses"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company policy — awareness"]],["tr",["Training objective","Employees can scan their work area at three levels and report a near miss on PWH-FRM-204-1 the same shift."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Last week we talked about stopping unsafe work. This week is about seeing it before it happens — and writing it down so it gets fixed instead of forgotten."],["h","3. KEY TEACHING POINTS"],["pt","1. Scan at three levels."],["p","Overhead (raised loads, stack tops, rack beams, sprinkler heads), eye level (trucks, people, corners, mirrors) and the floor (wrap, pallet scraps, wet spots, cracks, bolts)."],["pt","2. A near miss is a warning, not luck."],["p","Anything that could have hurt someone or damaged product, equipment or the building — but didn\\u0027t."],["pt","3. Report on PWH-FRM-204-1 before the end of the shift."],["p","What happened, exact location, what could have happened, and what you did right away. Your supervisor completes root cause and corrective actions."],["pt","4. Can\\u0027t write it? Say it."],["p","Tell your supervisor or lead and they will fill out the form with you. Spanish is fine."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Take a look around right now. Up high: is anything leaning, overhanging or sitting too close to the sprinklers? At eye level: where can a truck come around a corner without seeing you? On the floor: any wrap, broken pallet boards, wet spots or cracks? That\\u0027s a three-level scan. Do it every time you start a task in a new area."],["p","When something almost goes wrong — a roll that rocks, a pedestrian who steps out in front of a truck, a lift that taps a rack — that\\u0027s a near miss. Most people shake it off. We write it up, because the same situation with someone standing one foot to the left is an injury."],["p","The form is PWH-FRM-204-1. It\\u0027s a two-minute job: date, area, what happened, what could have happened, what you did. Check the boxes that fit. I handle the root cause and the fix. I\\u0027d rather read ten forms a week than fill out one injury report."],["call","SHOW IT: Hold up a blank PWH-FRM-204-1 and point to Sections 1–6 — that is all an employee fills out."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The rack tap nobody mentioned."],["p","An operator backing out of an aisle taps a rack upright with the counterweight. He looks, sees no dent, and keeps going. Two weeks later a beam drops an inch under load. Rack damage isn\\u0027t always visible — any contact gets reported the same shift so the upright can be inspected and unloaded if needed."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s one hazard you walked past last week that nobody reported?"],["p","Listen for: Specific locations: a door, an aisle end, a dock plate, a floor crack. Write each one down and assign it today."],["h","7. KNOWLEDGE CHECK"],["pt","1. Your lift touches a rack upright and you see no damage. What do you do?"],["p","Answer: Report it to your supervisor and write it up on PWH-FRM-204-1 the same shift. Rack damage is not always visible."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Do a three-level scan of your first work area before you start. Report at least one hazard or near miss to me by the end of the shift."],["h","9. SUPERVISOR VERIFICATION"],["li","Count near-miss / hazard reports received from this crew today and log them."],["li","Walk one area with an employee and ask them to point out one hazard at each level."],["li","Assign an owner and due date for every hazard reported today."],["p","References: Safety Incident / Near Miss Report PWH-FRM-204-1 • CAPA form PWH-FRM-216-1 • Manager Safety Walk (GEMBA) PWH-FRM-101-2 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W03","week":3,"doc":"PWH-MTR-2027-W03","date":"2027-01-18","holiday":true,"month":1,"title":"PPE by Area: What You Wear, Where, and Why","behavior":"Before your first task, check your own PPE for damage and make sure you have the task-specific items for anything you\\u0027ll do today.","track":"","file":"Part 3 - Weekly Jan-Apr/W03 Jan 18 - PPE by Area What You Wear, Where, and Why.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPPE by Area: What You Wear, Where, and Why"]],["tr",["Doc No: PWH-MTR-2027-W03\\nWeek: 3 · Mon Jan 18, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 3 of 52 · January 2027 · MLK Day — if the site is closed, deliver at the first shift start this week"]],["tr",["Monday training title","PPE by Area: What You Wear, Where, and Why"]],["tr",["Monthly theme","Safety Leadership Kickoff: Stop-Work, Hazards \\u0026 Near Misses"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA-required program (PPE, 29 CFR 1910.132) — refresher"]],["tr",["Training objective","Every employee wears the PPE required for their area and task, and can explain what each item protects against."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Everything you wear on this floor is there because of something that already happened to somebody. Today we make sure everyone knows what\\u0027s required where — and why."],["h","3. KEY TEACHING POINTS"],["pt","1. Warehouse floor, every person, every time:"],["p","Safety-toe footwear and a high-visibility vest. No open-toed shoes anywhere in the building (GMP Policy PWH-POL-114-1)."],["pt","2. Operating a lift:"],["p","Seat belt fastened whenever the truck moves. No headphones or personal phone use while operating."],["pt","3. Task-specific PPE:"],["p","Safety glasses and insulated/leather gloves for LP cylinder changes; face shield, chemical gloves and apron for battery service; cut-resistant gloves for banding and wrap; gloves for clamp work when required by PWH-SOP-171."],["pt","4. Damaged PPE is replaced, not tolerated."],["p","A torn vest, cracked glasses or worn-through gloves get swapped before you start. Ask your supervisor — the company provides it."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Let\\u0027s go head to toe. Feet: safety-toe shoes, because a pallet jack wheel or a dropped roll edge will crush a regular shoe. Body: a hi-vis vest, because a clamp operator backing out of an aisle needs to see you in the half-second he looks over his shoulder. Hands and eyes: depends on the job, and I\\u0027ll cover that next."],["p","If you\\u0027re changing a propane cylinder, it\\u0027s safety glasses and insulated or leather gloves, every time. Liquid propane comes out at about 44 below zero and will freeze-burn skin in seconds. If you\\u0027re watering or servicing a battery: face shield, chemical gloves and apron, because battery acid splashes. Cutting bands or wrap: cut-resistant gloves and a safety knife, not a razor blade."],["p","If your PPE is damaged or you don\\u0027t have the right item for a task, stop and come get it from me. Doing the job without it is not an option, and I\\u0027d rather lose five minutes than lose an eye."],["call","SHOW IT: Hold up each item [SITE: vest, safety glasses, LP gloves, cut-resistant gloves, face shield] and ask the crew which task it\\u0027s for."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The two-minute cylinder change."],["p","An operator changes an LP cylinder in cotton work gloves because his leather pair is in his locker. The coupling sprays when he loosens it, the cotton soaks up liquid propane and holds it against his fingers, and he ends up with a freeze burn. The right gloves were 60 feet away."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which piece of PPE do people here skip most often, and why?"],["p","Listen for: Usually glasses during LP changes, vests on short walks, seat belts on quick moves. Fix the \\u0027why\\u0027 — availability, fit, comfort — today."],["h","7. KNOWLEDGE CHECK"],["pt","1. What PPE is required to change a propane cylinder?"],["p","Answer: Safety glasses and insulated or leather gloves (long sleeves recommended). Never cotton or knit gloves."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before your first task, check your own PPE for damage and make sure you have the task-specific items for anything you\\u0027ll do today."],["h","9. SUPERVISOR VERIFICATION"],["li","Spot-check PPE on every person on the crew during the first hour."],["li","Observe one LP change or battery service and confirm the correct PPE."],["li","Replace any damaged PPE found and note what was replaced."],["p","References: OSHA 29 CFR 1910.132 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 6) • PWH-SOP-171 (Sec. 4.0) • GMP Policy PWH-POL-114-1 • [SITE: PPE hazard assessment] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W04","week":4,"doc":"PWH-MTR-2027-W04","date":"2027-01-25","holiday":false,"month":1,"title":"Winter Walking Surfaces: Ice, Snowmelt and Wet Dock Floors","behavior":"Check the dock doors in your area at the start of the shift and after every third trailer. Cone and clean any water you find.","track":"","file":"Part 3 - Weekly Jan-Apr/W04 Jan 25 - Winter Walking Surfaces Ice, Snowmelt and Wet Dock Floors.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nWinter Walking Surfaces: Ice, Snowmelt and Wet Dock Floors"]],["tr",["Doc No: PWH-MTR-2027-W04\\nWeek: 4 · Mon Jan 25, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 4 of 52 · January 2027"]],["tr",["Monday training title","Winter Walking Surfaces: Ice, Snowmelt and Wet Dock Floors"]],["tr",["Monthly theme","Safety Leadership Kickoff: Stop-Work, Hazards \\u0026 Near Misses"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA walking-working surfaces (29 CFR 1910.22) — seasonal awareness"]],["tr",["Training objective","Employees identify, flag and clean winter slip hazards the same shift, and operators adjust speed on wet floors."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: This time of year, every trailer and every pair of boots brings water into the building. Wet dock floors are where slips and lift skids happen. Let\\u0027s keep both off the injury log."],["h","3. KEY TEACHING POINTS"],["pt","1. Snowmelt collects at dock doors, trailer noses and man doors."],["p","Check those spots at the start of the shift and after every few trailers."],["pt","2. Flag it, then clean it."],["p","Put a wet-floor cone out immediately, then squeegee or absorb it. Don\\u0027t walk past a puddle."],["pt","3. Lifts lose traction on wet concrete and wet dock plates."],["p","Slow down, brake early, and never turn sharply on a wet surface (PWH-SOP-229-1 Sec. 8c)."],["pt","4. Walk like it\\u0027s icy outside."],["p","Short steps, hands out of pockets, three points of contact getting on and off trucks and dock edges."],["pt","5. Report what you can\\u0027t fix."],["p","Ice in the yard, a leaking roof seam or a dock door that won\\u0027t seal — tell your supervisor the same shift."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When a trailer comes in from the snow, the water comes off the tires and the floor of the trailer and runs right onto the dock plate. That plate is steel. Wet steel under a clamp truck tire is like ice. Slow down crossing plates this month, and brake earlier than you think you need to."],["p","If you see water, put a cone on it right away and clean it up. Cones and squeegees are at [SITE: location]. The worst thing we can do is walk around a puddle all shift because it\\u0027s \\u0027not my area\\u0027."],["p","Outside: if you\\u0027re walking the yard to check a trailer or a railcar, watch for ice, especially in shade along the building. If the yard is bad, tell me before someone falls, not after."],["p","And in food-grade areas, standing water isn\\u0027t just a slip hazard — it\\u0027s a sanitation issue. Clean it the same shift."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The plate at door [SITE]."],["p","A clamp operator crosses a dock plate wet from snowmelt at normal speed, brakes to stop inside the trailer and slides about a foot into the stacked rolls. The roll shifts but stays up. Nobody is hurt — and it\\u0027s reported as a near miss. The fix: absorbent mats at the door, a cone check every hour, and slower crossings in winter."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where in this building does water collect worst in winter?"],["p","Listen for: Specific dock doors, the man door, under the [SITE] roof seam, the battery or LP area. Assign each a check owner."],["h","7. KNOWLEDGE CHECK"],["pt","1. You find a puddle at a dock door. What two things do you do?"],["p","Answer: Put out a wet-floor cone right away, then clean it up (squeegee or absorbent). Report it if it keeps coming back."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check the dock doors in your area at the start of the shift and after every third trailer. Cone and clean any water you find."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk all dock doors at mid-shift and check for water and cones."],["li","Watch operators cross dock plates; coach anyone not slowing on wet plates."],["li","Report recurring leaks to maintenance with a work order."],["p","References: OSHA 29 CFR 1910.22 (Walking-Working Surfaces) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8) • Rules of Safe Operation – New Hire Orientation SOP (Part F.3) • Master Sanitation WI 12.2.5 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W05","week":5,"doc":"PWH-MTR-2027-W05","date":"2027-02-01","holiday":false,"month":2,"title":"The Pre-Shift Truck Inspection Done Right","behavior":"Complete every line of your Pre-Shift Inspection Form today, including the hour meter and your signature, before the first lift.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W05 Feb 1 - The Pre-Shift Truck Inspection Done Right.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nThe Pre-Shift Truck Inspection Done Right"]],["tr",["Doc No: PWH-MTR-2027-W05\\nWeek: 5 · Mon Feb 1, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 5 of 52 · February 2027"]],["tr",["Monday training title","The Pre-Shift Truck Inspection Done Right"]],["tr",["Monthly theme","Powered Industrial Truck Fundamentals"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA-required (29 CFR 1910.178(q)(7)) — refresher"]],["tr",["Training objective","Every operator completes every line of the Pre-Shift Inspection Form before the truck\\u0027s first move, and tags out any truck that fails."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: If you wouldn\\u0027t sign for it, it doesn\\u0027t move. That\\u0027s the whole lesson today. A pre-shift inspection takes about five minutes and catches the leaking fitting, worn tire, weak brake or dead horn before it hurts someone."],["h","3. KEY TEACHING POINTS"],["pt","1. Inspect before first use, every shift."],["p","If the truck runs around the clock, each shift\\u0027s operator inspects it at the start of their shift."],["pt","2. Truck OFF: visual checks."],["p","Forks and carriage, mast, chains and hoses, tires, leaks underneath, overhead guard, load backrest, data plate, LP tank locked in and hose connected (or battery cables), seat belt, fire extinguisher."],["pt","3. Truck ON: operational checks."],["p","Horn, lights, backup alarm, service and parking brakes, steering, lift/lower/tilt with no drift, gauges. Clamp trucks: clamp pads free of paper debris, no hose leaks, clamp rotates and releases smoothly."],["pt","4. Fill out every line."],["p","Truck number, date, shift, hour meter, each item, signature. A blank sheet or one with every box checked in two seconds is not an inspection."],["pt","5. Fail = tag out."],["p","Remove the key, hang a DO NOT OPERATE tag, park out of the travel path and tell your supervisor. It returns to service only when repaired and released by the supervisor."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","OSHA requires that every truck be examined before it\\u0027s placed in service, and our MHE SOP requires it every shift. But forget the regulation for a second. The truck you\\u0027re about to drive weighs as much as three or four cars once it\\u0027s loaded. You want to know the brakes work before you\\u0027re coming down an aisle with a roll on it."],["p","Walk around with the truck off first. Look under it for drips. Look at the forks or clamp arms for cracks and bends. Look at the tires for chunks missing. Check the LP tank is locked in with the pin seated, or the battery cables aren\\u0027t frayed. Make sure the seat belt latches. Then turn it on and test the horn, lights, alarm, brakes, steering and every hydraulic function."],["p","Write down what you find. If you check every box in ten seconds, I know you didn\\u0027t look, and so will an auditor. If something fails, don\\u0027t \\u0027just use it carefully.\\u0027 Tag it out and tell me. A good inspection that takes a truck out of service is a win."],["call","SHOW IT: Stage one truck. Have an operator do the walk-around out loud while the crew follows along on a blank Pre-Shift Inspection Form."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The dead horn."],["p","A second-shift operator finds the horn doesn\\u0027t work but figures he\\u0027ll be careful and uses it anyway. Coming out of a trailer he can\\u0027t warn a pedestrian walking the dock. The pedestrian steps back in time. The right call: tag the truck out, tell the supervisor and take a different truck."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the item on the checklist people are most likely to skip, and why?"],["p","Listen for: Under-truck leaks, chains, seat belt latch, clamp pads. Often \\u0027I\\u0027m in a hurry\\u0027. Remind them the five minutes is built into the shift."],["h","7. KNOWLEDGE CHECK"],["pt","1. Your horn doesn\\u0027t work during your pre-shift inspection. What do you do?"],["p","Answer: Do not operate the truck. Tag it out, remove the key, and tell your supervisor. If you wouldn\\u0027t sign for it, it doesn\\u0027t move."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Complete every line of your Pre-Shift Inspection Form today, including the hour meter and your signature, before the first lift."],["h","9. SUPERVISOR VERIFICATION"],["li","Collect and review every inspection form from this shift before end of day: complete, signed, hour meter filled."],["li","Watch one operator perform the inspection start to finish."],["li","Confirm any defective truck is tagged out, keyed, and has a repair request."],["p","References: OSHA 29 CFR 1910.178(q)(7) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 7) • Rules of Safe Operation SOP (Part B) • PWH-SOP-171 (Sec. 5.1) • PWH-FRM-MHE-01 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W06","week":6,"doc":"PWH-MTR-2027-W06","date":"2027-02-08","holiday":false,"month":2,"title":"Seat Belts, the Stability Triangle and Tip-Over Response","behavior":"Buckle your seat belt every time the truck moves today — including short moves at the dock.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W06 Feb 8 - Seat Belts, the Stability Triangle and Tip-Over Response.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nSeat Belts, the Stability Triangle and Tip-Over Response"]],["tr",["Doc No: PWH-MTR-2027-W06\\nWeek: 6 · Mon Feb 8, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 6 of 52 · February 2027"]],["tr",["Monday training title","Seat Belts, the Stability Triangle and Tip-Over Response"]],["tr",["Monthly theme","Powered Industrial Truck Fundamentals"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178) — refresher"]],["tr",["Training objective","Operators wear the seat belt 100% of the time and can explain what makes a truck tip and what to do if it starts to."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A lift can tip over in a turn faster than you can react. The seat belt is the only thing that keeps you inside the overhead guard when it does. Today: why trucks tip, and what to do if yours starts to."],["h","3. KEY TEACHING POINTS"],["pt","1. The stability triangle."],["p","The area between the two front wheels and the rear axle pivot. The combined center of gravity of truck and load must stay inside it or the truck tips."],["pt","2. What pushes the center of gravity out:"],["p","Overloading, raising the load while moving, turning too fast, braking hard, driving across a slope, uneven floors, and carrying a load tilted forward."],["pt","3. Seat belt on whenever the truck moves."],["p","Even for a ten-foot move. No exceptions (PWH-SOP-229-1 Sec. 6b)."],["pt","4. If it tips: stay in, hold on, lean away."],["p","Do not jump. Keep your belt on, grip the wheel, brace your feet, and lean away from the direction of the fall."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Lifts steer with the rear wheels and have a short wheelbase, so they tip much more easily than a car in a sudden turn. Add a roll held up high or a hard brake and the center of gravity moves outside that triangle. That\\u0027s when the truck goes over."],["p","When a truck starts to tip, every instinct says jump. Don\\u0027t. People who jump get caught under the overhead guard — it lands on them. People who stay in, belted, usually walk away. So: stay in, hold on to the wheel, brace your feet, lean away from the fall."],["p","And that only works if the belt is on. I\\u0027ll be checking belts this week on every truck that moves. If I see one off, the truck stops and we talk."],["call","SHOW IT: Sit in a parked truck. Show the belt, then physically show the tip-over position: hands on the wheel, feet braced, lean away."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The quick turn at the aisle end."],["p","An operator carrying a roll takes an aisle end at speed and cuts the turn short. The truck lifts onto two wheels and drops back down. Unbelted, he would have been thrown toward the open side. He reports it; the fix is slowing at every aisle end and a refresher on turning with a load."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Why do you think people skip the seat belt?"],["p","Listen for: \\u0027Quick move\\u0027, \\u0027in and out of the truck all day\\u0027, \\u0027uncomfortable\\u0027. Answer: tip-overs happen on quick moves too."],["h","7. KNOWLEDGE CHECK"],["pt","1. Your truck starts to tip over. Do you jump?"],["p","Answer: No. Stay belted in, hold the wheel, brace your feet and lean away from the fall."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Buckle your seat belt every time the truck moves today — including short moves at the dock."],["h","9. SUPERVISOR VERIFICATION"],["li","Observe every truck in motion at least twice during the shift for belt use."],["li","Stop any truck moving without a belt and coach on the spot."],["li","Record seat-belt checks on PWH-FRM-MHE-01."],["p","References: OSHA 29 CFR 1910.178 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 4d, 6b) • Rules of Safe Operation SOP (Parts E, F) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W07","week":7,"doc":"PWH-MTR-2027-W07","date":"2027-02-15","holiday":false,"month":2,"title":"Leaving a Truck Unattended: Forks Down, Neutral, Brake, Power Off","behavior":"Every time you step off your truck today, lower the forks or clamp arms flat to the floor before you leave the seat.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W07 Feb 15 - Leaving a Truck Unattended Forks Down, Neutral, Brake, Power Off.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nLeaving a Truck Unattended: Forks Down, Neutral, Brake, Power Off"]],["tr",["Doc No: PWH-MTR-2027-W07\\nWeek: 7 · Mon Feb 15, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 7 of 52 · February 2027"]],["tr",["Monday training title","Leaving a Truck Unattended: Forks Down, Neutral, Brake, Power Off"]],["tr",["Monthly theme","Powered Industrial Truck Fundamentals"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178(m)(5)) — refresher"]],["tr",["Training objective","No truck is left unattended with forks or clamp arms raised, controls engaged, brake off or power on."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A parked truck is still a hazard. Raised forks are a shin-height trip and a head-height strike. A truck left in gear with the brake off can roll. Today we lock in how to park."],["h","3. KEY TEACHING POINTS"],["pt","1. \\"Unattended\\" means more than 25 feet away or out of your sight."],["p","That\\u0027s when the full shutdown is required."],["pt","2. Shutdown sequence:"],["p","Forks or clamp arms fully lowered, tips flat on the floor → controls in neutral → parking brake set → power off → key removed and returned to key control."],["pt","3. Park only in designated spots."],["p","Never in aisles, in front of exits, fire equipment, electrical panels or dock doors in use. On an incline, block the wheels."],["pt","4. End of shift."],["p","Electric trucks go on charge; LP trucks park away from heat sources and dock heaters."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Even if you\\u0027re only stepping off to scan a label, put the forks or clamp arms down. Raised forks at knee or shin height are one of the most common trip injuries around lifts. Raised clamp arms are worse — they\\u0027re at head level for someone walking by."],["p","If you\\u0027re going more than 25 feet away, or somewhere you can\\u0027t see the truck, it\\u0027s unattended. Forks down, neutral, brake, power off, take the key. The key goes back to [SITE: key control location], not in your pocket and not left on the seat."],["p","Where you park matters too. A truck parked in front of an electrical panel or a fire extinguisher blocks it in an emergency. A truck parked across an aisle forces people to walk around it into traffic."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The truck in the aisle."],["p","An operator stops halfway down an aisle to grab a scanner from the office, leaving the truck running with forks at knee height. A pedestrian cutting through clips the fork tip and goes down. The fix is simple: lower, neutral, brake, off, every time you step off."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do trucks end up getting parked on this shift that they shouldn\\u0027t be?"],["p","Listen for: Aisle ends, in front of panels, the battery area doorway, dock lanes. Agree on the right spots."],["h","7. KNOWLEDGE CHECK"],["pt","1. What are the four steps before you walk away from a truck?"],["p","Answer: Forks or arms fully lowered and flat, controls in neutral, parking brake set, power off (and remove the key)."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Every time you step off your truck today, lower the forks or clamp arms flat to the floor before you leave the seat."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk the floor twice this shift looking for any parked truck with raised forks, power on or key in."],["li","Check keys are returned to key control at shift end."],["li","Note parking violations and coach the operator the same shift."],["p","References: OSHA 29 CFR 1910.178(m)(5) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 4e, 12) • Forklift / Clamp Truck Performance Test PWH-FRM-213-1 (item 24) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W08","week":8,"doc":"PWH-MTR-2027-W08","date":"2027-02-22","holiday":false,"month":2,"title":"Battery Charging and Propane Cylinder Changes","behavior":"If you change a cylinder or charge a battery today, do it in the designated area with full PPE and the six steps — and I\\u0027ll come watch one.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W08 Feb 22 - Battery Charging and Propane Cylinder Changes.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nBattery Charging and Propane Cylinder Changes"]],["tr",["Doc No: PWH-MTR-2027-W08\\nWeek: 8 · Mon Feb 22, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 8 of 52 · February 2027"]],["tr",["Monday training title","Battery Charging and Propane Cylinder Changes"]],["tr",["Monthly theme","Powered Industrial Truck Fundamentals"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (1910.178(f), (g)) \\u0026 LP-gas (1910.110) — task refresher"]],["tr",["Training objective","Only trained employees change LP cylinders or charge batteries, using the correct PPE and the six-step change-out every time."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Changing a propane tank or plugging in a battery is the most routine job in the building — which is exactly why people stop paying attention to it. Routine is where burns happen."],["h","3. KEY TEACHING POINTS"],["pt","1. Right place, engine off, no flames."],["p","Designated change-out or charging area only; never in a dock pit or near a dock heater or charger. No smoking, open flames or sparks within 25 feet."],["pt","2. LP: close valve, run it dry, then disconnect slowly by hand."],["p","Face and body away from the fitting. A short puff is normal; a steady spray is not."],["pt","3. Inspect the new cylinder."],["p","Dents, gouges, bulges, heavy rust, damaged collar or foot ring, missing or cracked O-ring — tag it, cage it apart from full tanks, tell your supervisor."],["pt","4. Mount it right and leak-check without flame."],["p","Locating pin seated, relief valve up, strap latched, coupling hand-tight. Smell, listen, look for frost; soapy water only."],["pt","5. Batteries: charger off before connecting or disconnecting."],["p","Covers open while charging; face shield, chemical gloves and apron for service; eyewash accessible; spill kit for electrolyte."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Liquid propane leaves the tank at about 44 below zero. On bare skin it freeze-burns in seconds. And propane is heavier than air, so a leak sinks into dock pits and under dock plates, where one spark turns a cold burn into a fire. That\\u0027s why the change area is where it is, and why there\\u0027s no smoking anywhere near it."],["p","The six rules from our November meeting still stand: gear up; right place, engine off; close the valve and run it dry; inspect the new tank; mount it right and check for leaks; and if it hits your skin, flush with lukewarm water, never hot, and report it."],["p","For electric trucks: turn the charger off before you plug or unplug. Pulling a connector under load can arc. Keep the battery cover open while it charges so gas can vent. If acid spills, use the spill kit and tell me, especially if it\\u0027s anywhere near product."],["call","SHOW IT: At the LP cage [SITE], point out the gloves, glasses, soapy-water bottle, extinguisher and the \\u0027no smoking within 25 feet\\u0027 boundary."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The cotton gloves."],["p","From our own November 2026 meeting: cotton or knit gloves soak up liquid propane and hold it against your skin. The right gloves are insulated or leather. If you don\\u0027t have them, stop and get them."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the first thing you do if propane sprays on your hand?"],["p","Listen for: Don\\u0027t rub it; flush with lukewarm (not hot) water; tell your supervisor right away for medical care; report it the same shift."],["h","7. KNOWLEDGE CHECK"],["pt","1. How do you check a new propane connection for leaks?"],["p","Answer: Smell for rotten eggs, listen for hissing, look for frost on the fitting, and use soapy water. Never use a flame."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: If you change a cylinder or charge a battery today, do it in the designated area with full PPE and the six steps — and I\\u0027ll come watch one."],["h","9. SUPERVISOR VERIFICATION"],["li","Observe at least one LP change or battery connection this shift with correct PPE."],["li","Check the LP cage: full and empty tanks in marked spots, valves closed, door shut, nothing piled against it."],["li","Check eyewash and extinguisher at the charging area are accessible and in date."],["p","References: OSHA 29 CFR 1910.178(f)–(g) • OSHA 29 CFR 1910.110 • NFPA 58 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 11) • Propane SDS (posted at change-out area) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W09","week":9,"doc":"PWH-MTR-2027-W09","date":"2027-03-01","holiday":false,"month":3,"title":"Handwashing and Hygiene: When, How, and Why Gloves Aren\\u0027t Enough","behavior":"Wash your hands at every trigger point today — especially after breaks and after handling trash or damaged product.","track":"Food","file":"Part 3 - Weekly Jan-Apr/W09 Mar 1 - Handwashing and Hygiene When, How, and Why Gloves Aren\\u0027t Enough.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nHandwashing and Hygiene: When, How, and Why Gloves Aren\\u0027t Enough"]],["tr",["Doc No: PWH-MTR-2027-W09\\nWeek: 9 · Mon Mar 1, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 9 of 52 · March 2027"]],["tr",["Monday training title","Handwashing and Hygiene: When, How, and Why Gloves Aren\\u0027t Enough"]],["tr",["Monthly theme","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Every employee washes hands at each required trigger point and knows how to do it properly."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Your hands touch trucks, pallets, trash, door handles and your phone — then they touch food-grade packaging. Handwashing is the cheapest food safety control we have."],["h","3. KEY TEACHING POINTS"],["pt","1. When to wash:"],["p","After using the restroom (before leaving it); before eating, drinking or smoking; after breaks; after handling trash, chemicals, pest-control areas or damaged product; and whenever hands are visibly dirty."],["pt","2. How to wash:"],["p","Wet, soap, scrub at least 20 seconds (backs of hands, between fingers, under nails), rinse, dry with a paper towel, use the towel to turn off the tap and open the door."],["pt","3. Gloves don\\u0027t replace handwashing."],["p","Work gloves pick up everything they touch. If they\\u0027re contaminated, change them; if your hands are, wash them."],["pt","4. Cuts and sores."],["p","Report open cuts or sores on your hands to your supervisor. Bandaged hands are covered with a glove (GMP Policy PWH-POL-114-1)."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Our GMP policy says employees wash their hands before leaving the restroom, before eating, and as often as needed to remove dirt and contaminants. That last part is the one people forget: after you clean up a spill, after you empty trash, after you handle a damaged bag of product, wash."],["p","Twenty seconds is longer than people think. Hum \\u0027Happy Birthday\\u0027 twice. Get the backs of your hands and under your nails, because that\\u0027s where the dirt stays. Dry with a paper towel and use it to open the door so you don\\u0027t pick up what the last person left."],["p","If a handwash sink is out of soap or towels, that\\u0027s a food-safety issue, not a housekeeping complaint. Tell me and it gets fixed the same shift."],["call","SHOW IT: Walk the crew to the nearest handwash sink and point to the \\u0027Employees Must Wash Hands\\u0027 placard. Check soap and towels together."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The spill clean-up."],["p","An associate cleans up a leaking case of syrup in a food-grade aisle, throws the rags away and goes straight back to scanning and handling pallets. The sticky residue on his gloves and hands goes onto every label and stretch-wrap he touches for the next hour. The fix: change gloves and wash hands right after clean-up."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Besides the restroom, when did you last need to wash your hands on shift and didn\\u0027t?"],["p","Listen for: After trash, after damaged product, after break, after the LP cage. Reinforce each as a trigger."],["h","7. KNOWLEDGE CHECK"],["pt","1. Do work gloves replace handwashing?"],["p","Answer: No. Gloves get contaminated too. Change contaminated gloves and wash your hands at every trigger point."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Wash your hands at every trigger point today — especially after breaks and after handling trash or damaged product."],["h","9. SUPERVISOR VERIFICATION"],["li","Check every handwash station for soap, paper towels and posted signage."],["li","Observe employees returning from break and the restroom."],["li","Restock or submit a work order for any station that isn\\u0027t ready."],["p","References: GMP Policy PWH-POL-114-1 • 21 CFR 117.10 (Personnel) • Building placard: Employees Must Wash Hands • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W10","week":10,"doc":"PWH-MTR-2027-W10","date":"2027-03-08","holiday":false,"month":3,"title":"GMP Personal Practices: Food, Drink, Shoes, Personal Items and Illness","behavior":"Before you start, clear your truck and work area of any food, drink or personal items and put them in your locker or the break room.","track":"Food","file":"Part 3 - Weekly Jan-Apr/W10 Mar 8 - GMP Personal Practices Food, Drink, Shoes, Personal Items and Illness.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nGMP Personal Practices: Food, Drink, Shoes, Personal Items and Illness"]],["tr",["Doc No: PWH-MTR-2027-W10\\nWeek: 10 · Mon Mar 8, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 10 of 52 · March 2027"]],["tr",["Monday training title","GMP Personal Practices: Food, Drink, Shoes, Personal Items and Illness"]],["tr",["Monthly theme","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Employees follow every personal-practice rule in GMP Policy PWH-POL-114-1 throughout the shift."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A dropped candy wrapper in a rack aisle will feed a mouse for a week. Our personal-practice rules exist because small habits add up to audit findings and pest problems."],["h","3. KEY TEACHING POINTS"],["pt","1. Food, drink, gum and tobacco only in the break room or designated areas."],["p","Never on the warehouse floor, in a truck cab or on a rack. \\u0027No food or beverage beyond this point\\u0027 signs mean exactly that."],["pt","2. No open-toed shoes or sandals anywhere in the building."],["p","Safety-toe footwear on the floor."],["pt","3. Personal belongings stay in lockers."],["p","No jackets, bags, lunches or phones left on racks, pallets or in storage areas."],["pt","4. Report illness, cuts and sores before your shift."],["p","Communicable illness or open sores on hands — tell your supervisor. Bandaged hands get gloved."],["pt","5. Glass and brittle plastic."],["p","A broken light, mirror or plastic part on a truck or in a storage area is reported right away so nearby product can be inspected (PWH-SOP-229-1 Sec. 13d)."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Most of this is common sense, and most of it gets broken in small ways: a water bottle in a truck cup holder, a jacket hanging off a rack, a snack eaten at the dock desk. Each one is a GMP violation an auditor will write up, and each one attracts pests."],["p","You\\u0027ll notice our policy doesn\\u0027t require hairnets or jewelry removal. Our risk assessment found we don\\u0027t contact open product. That\\u0027s a privilege that depends on us following everything else."],["p","If you\\u0027re sick, especially with vomiting or diarrhea, tell me before your shift. If you cut your hand, get first aid, bandage it, and put a glove over the bandage."],["p","And if a truck light, mirror or anything plastic or glass breaks near product, stop, keep people out of the area, and tell me. We inspect the nearby product before anything moves."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The coffee cup on the clamp truck."],["p","During a customer walk-through, the visitor notices a coffee cup in a truck\\u0027s cup holder in a food-grade aisle. It\\u0027s written up as a GMP observation in the customer\\u0027s report. One cup cost us a finding in front of a customer."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where on this floor do people most often end up eating or drinking?"],["p","Listen for: Dock desks, truck cabs, the battery room, the back corner. Agree on a fix (break schedule, a designated hydration spot outside food zones)."],["h","7. KNOWLEDGE CHECK"],["pt","1. Can you keep a drink in your truck\\u0027s cup holder in a food-grade area?"],["p","Answer: No. Food and drink are allowed only in the break room or designated areas."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before you start, clear your truck and work area of any food, drink or personal items and put them in your locker or the break room."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk all trucks and dock desks for food, drinks and personal items."],["li","Confirm \\u0027No Food or Beverage Beyond This Point\\u0027 signage is posted and readable."],["li","Record any GMP observations on the monthly GMP inspection (PWH-FRM-101-2)."],["p","References: GMP Policy PWH-POL-114-1 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 13) • Building placard: No Food or Beverage Beyond This Point • 21 CFR 117.10 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W11","week":11,"doc":"PWH-MTR-2027-W11","date":"2027-03-15","holiday":false,"month":3,"title":"Receiving Food-Grade Loads: Trailer Condition, Damaged Packaging, Odors","behavior":"On every food-grade receipt today, complete the trailer inspection sheet before the first pallet comes off.","track":"Food","file":"Part 3 - Weekly Jan-Apr/W11 Mar 15 - Receiving Food-Grade Loads Trailer Condition, Damaged Packaging, Odors.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nReceiving Food-Grade Loads: Trailer Condition, Damaged Packaging, Odors"]],["tr",["Doc No: PWH-MTR-2027-W11\\nWeek: 11 · Mon Mar 15, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 11 of 52 · March 2027"]],["tr",["Monday training title","Receiving Food-Grade Loads: Trailer Condition, Damaged Packaging, Odors"]],["tr",["Monthly theme","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Every food-grade receipt is inspected and documented before and during unloading; damaged or suspect product is held."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: The fastest way to bring a problem into this building is to unload it. Today\\u0027s lesson: look before you unload, and look at every pallet as it comes off."],["h","3. KEY TEACHING POINTS"],["pt","1. Verify first."],["p","Seal number and trailer number match the paperwork before the doors open."],["pt","2. Inspect the trailer."],["p","Clean, dry, no odors (fuel, chemical, musty, spoiled), no pests or droppings, no holes, no light through the roof or floor. Record it on the Trailer Inspection Sheet 12.6.5.2."],["pt","3. Inspect every pallet as it comes off."],["p","Torn wrap, crushed or wet cases, stains, leaks, broken pallets, signs of pests. Anything suspect goes to the hold area, tagged."],["pt","4. Stop and call if the trailer fails."],["p","Don\\u0027t keep unloading a trailer with pests, mold, odor or wet product. Supervisor decides reject, hold or accept with documentation."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Before you break the seal, check the seal number against the bill of lading. If it doesn\\u0027t match or the seal is broken, stop and call me. That load may have been tampered with."],["p","When the doors open, take a breath before you take a step. Smell for fuel, chemicals, mildew or anything spoiled. Look at the floor and walls for water, pests or debris. Look up for light through the roof. Write it on the trailer inspection sheet — every line."],["p","As each pallet comes off, look at it like the customer will. A crushed corner or wet case goes to the hold area with a tag and gets written up. Don\\u0027t put it away and hope someone else catches it."],["p","Remember the mold complaint we worked through in 2026: product was found with mold after transfer. Moisture problems often start with one wet trailer or one wet pallet that nobody stopped."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The trailer that smelled like diesel."],["p","A receiver opens a food-grade trailer and smells fuel but the product looks fine, so he starts unloading. The customer later rejects the lot for odor contamination. The right call: stop, call the supervisor, document the odor on the inspection sheet, and hold the product for the customer\\u0027s decision."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What would make you stop unloading a trailer halfway through?"],["p","Listen for: Pests or droppings, wet or moldy product, odor, broken seal, chemical containers mixed with food, damaged floor."],["h","7. KNOWLEDGE CHECK"],["pt","1. The seal number doesn\\u0027t match the paperwork. What do you do?"],["p","Answer: Don\\u0027t open or unload. Call your supervisor — it\\u0027s a possible tampering or food defense issue."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: On every food-grade receipt today, complete the trailer inspection sheet before the first pallet comes off."],["h","9. SUPERVISOR VERIFICATION"],["li","Review every trailer inspection sheet from this shift for completeness and signatures."],["li","Watch one food-grade unload from seal check to put-away."],["li","Check the hold area: every item tagged with date, reason and who placed it."],["p","References: Trailer Inspection Sheet 12.6.5.2 • Loading, Transport and Staging Practices PWH-POL-156-2 • Controlled Trailer/Rail Inspection and Load/Unload Sheet • PWH-SOP-171 (Sec. 7.2) • Disposition of Recalled, Withdrawn and Non-conformance Product SOP 2.4.4 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W12","week":12,"doc":"PWH-MTR-2027-W12","date":"2027-03-22","holiday":false,"month":3,"title":"Cross-Contamination: Chemicals, Non-Food Items and Segregation","behavior":"Look above and beside every food-grade location you work in today. Report or move anything that doesn\\u0027t belong there.","track":"Food","file":"Part 3 - Weekly Jan-Apr/W12 Mar 22 - Cross-Contamination Chemicals, Non-Food Items and Segregation.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nCross-Contamination: Chemicals, Non-Food Items and Segregation"]],["tr",["Doc No: PWH-MTR-2027-W12\\nWeek: 12 · Mon Mar 22, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 12 of 52 · March 2027"]],["tr",["Monday training title","Cross-Contamination: Chemicals, Non-Food Items and Segregation"]],["tr",["Monthly theme","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","No chemical, non-food item or leaking equipment is stored or staged over, beside or against food-grade product."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Food-grade product can be ruined without anyone touching it — by what\\u0027s stored above it, beside it or leaking onto it. Today is about keeping things apart."],["h","3. KEY TEACHING POINTS"],["pt","1. Food-grade product is kept separate."],["p","Never stored under or beside chemicals, cleaning supplies, pest-control materials, batteries, fuel or non-food freight."],["pt","2. Chemicals live in the designated chemical area only."],["p","Never left on a rack beam, a pallet or a truck. Every chemical container labeled."],["pt","3. Leaking equipment stays out of product areas."],["p","A truck with a hydraulic, oil or fuel leak is not operated in product storage areas (PWH-SOP-229-1 Sec. 13a)."],["pt","4. Contact = hold."],["p","If fluid, acid or fuel touches product, pallets or packaging: stop, isolate, place on hold, notify the supervisor."],["pt","5. Allergens."],["p","Damaged packages of allergen-containing product are cleaned up and isolated so they don\\u0027t contact other product (Allergen Management SOP 2.8)."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Look up at the beams above food-grade pallets. Nothing should be up there but product of the same type. A jug of cleaner or a can of lubricant left on a beam can leak onto every pallet below it."],["p","Our staging rules say food-grade product is always kept separate from non-food items and hazardous materials, and dry goods are kept away from wet areas. When you build a staging lane, ask: what\\u0027s next to this?"],["p","If your truck is dripping, don\\u0027t take it into a food aisle. Park it, tag it and tell me. If anything drips on product, that product goes on hold until we decide what to do with it."],["p","Allergens: if a case of product containing peanuts, milk, soy or another allergen is damaged, clean it up carefully and keep the debris from getting onto other product."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The battery acid at the end of the aisle."],["p","A battery is watered too high and acid spills on the floor beside a staging lane. Nobody notices until a pallet is set down in it. That pallet is a non-conformance. The right response: spill kit, isolate the area, hold the affected pallet and report it."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What non-food items do we store in this building that could end up near food-grade product?"],["p","Listen for: Paper rolls, pallets of chemicals for other customers, cleaning supplies, pest materials, LP tanks, batteries. Confirm where each belongs."],["h","7. KNOWLEDGE CHECK"],["pt","1. Hydraulic fluid drips from a truck onto a food-grade pallet. What do you do?"],["p","Answer: Stop, take the truck out of the area, isolate the pallet, place it on hold and tell your supervisor."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Look above and beside every food-grade location you work in today. Report or move anything that doesn\\u0027t belong there."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk food-grade aisles looking up at beams and along staging lanes for chemicals or non-food items."],["li","Check trucks working food-grade areas for leaks."],["li","Confirm the chemical storage area is labeled, organized and away from product."],["p","References: Loading, Transport and Staging Practices PWH-POL-156-2 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 13) • Allergen Management SOP 2.8 • Disposition of Non-conformance Product SOP 2.4.4 • OSHA HazCom 29 CFR 1910.1200 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W13","week":13,"doc":"PWH-MTR-2027-W13","date":"2027-03-29","holiday":false,"month":3,"title":"Pest Prevention: Signs to Report and Devices You Never Touch","behavior":"Before you start moving freight, spend 60 seconds checking the door seals, the floor-to-wall line and behind the first row of pallets in your area. Report anything you find.","track":"Food","file":"Part 3 - Weekly Jan-Apr/W13 Mar 29 - Pest Prevention Signs to Report and Devices You Never Touch.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPest Prevention: Signs to Report and Devices You Never Touch"]],["tr",["Doc No: PWH-MTR-2027-W13\\nWeek: 13 · Mon Mar 29, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 13 of 52 · March 2027"]],["tr",["Monday training title","Pest Prevention: Signs to Report and Devices You Never Touch"]],["tr",["Monthly theme","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Doors stay closed when idle, pest signs are logged on the Pest Sighting Log 12.2.4 the same shift, and no employee moves or resets a pest device."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Spring is when pests start moving — and pests are the fastest way to lose a food-grade account. Our pest control operator visits on a schedule. We\\u0027re here every day."],["h","3. KEY TEACHING POINTS"],["pt","1. Doors closed. Every time."],["p","Dock doors, man doors and trailer doors close when freight isn\\u0027t moving through them. Report light around seals or torn curtains the same shift."],["pt","2. See it, say it, log it."],["p","Live or dead pests, droppings, webbing, gnaw marks, birds in the rafters — tell your supervisor and log it on the Pest Sighting Log 12.2.4 before you leave."],["pt","3. Hands off bait stations and traps."],["p","Only the licensed pest control operator services devices. If one is hit, moved, damaged or missing, report it — don\\u0027t reset it."],["pt","4. Keep the 18-inch perimeter clear."],["p","Clear aisle along the walls so devices can be inspected. Empty pallets stacked neatly and off the walls."],["pt","5. Spills and damaged product now, not later."],["p","A spill is a food source within hours."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","This is our own 10-minute meeting on pest prevention, and it\\u0027s worth repeating every spring. Six things: doors closed, report and log sightings, hands off devices, clean spills now, keep the 18-inch perimeter, and no food or personal items on the floor."],["p","Inside the building we use glue boards and mechanical traps, numbered and mapped. If a truck knocks one over or it disappears, it shows up on the pest operator\\u0027s report as a missing device — and that\\u0027s an audit finding. Tell me so it gets serviced correctly."],["p","Nobody gets in trouble for reporting a pest. People get in trouble for not reporting one."],["call","SHOW IT: Walk to the nearest interior device. Show its number on the wall map and point out the clear 18-inch perimeter."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The ants in the break room."],["p","In 2026, ants were found in the break room and went through our CAPA process. It started with food left out. The same thing happens on the floor with a broken case or a dropped snack — caught early, it\\u0027s a cleanup; caught late, it\\u0027s a CAPA and a customer concern."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: It\\u0027s 2 a.m. on second shift and you find droppings behind a pallet. Who do you tell and what do you fill out?"],["p","Listen for: Tell the supervisor/lead on shift; log it on the Pest Sighting Log 12.2.4 before end of shift; don\\u0027t move devices; check nearby product."],["h","7. KNOWLEDGE CHECK"],["pt","1. A bait station has been crushed by a truck. Can you replace it with one from the supply closet?"],["p","Answer: No. Report it. Only the licensed pest control operator places and services devices."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before you start moving freight, spend 60 seconds checking the door seals, the floor-to-wall line and behind the first row of pallets in your area. Report anything you find."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk all dock doors mid-shift: closed when idle, seals intact."],["li","Check the 18-inch perimeter in two aisles."],["li","Review today\\u0027s Pest Sighting Log entries and confirm corrective actions are opened."],["p","References: 10-Minute Food Safety Meeting PWH-REF-226-1 • Pest Control Devices SOP PWH-SOP-132-1 • Preventable Measures SOP 12.2.4 • Pest Sighting Log 12.2.4 • Master Sanitation Cleaning Schedule 12.2.5 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W14","week":14,"doc":"PWH-MTR-2027-W14","date":"2027-04-05","holiday":false,"month":4,"title":"Walkways, Crossings and No-Pedestrian Zones","behavior":"Walk only in marked walkways today. If you catch yourself leaving one, note where and tell me at end of shift.","track":"","file":"Part 3 - Weekly Jan-Apr/W14 Apr 5 - Walkways, Crossings and No-Pedestrian Zones.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nWalkways, Crossings and No-Pedestrian Zones"]],["tr",["Doc No: PWH-MTR-2027-W14\\nWeek: 14 · Mon Apr 5, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 14 of 52 · April 2027"]],["tr",["Monday training title","Walkways, Crossings and No-Pedestrian Zones"]],["tr",["Monthly theme","Pedestrian–Equipment Separation \\u0026 Traffic Management"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company traffic rules — awareness"]],["tr",["Training objective","Pedestrians stay in marked walkways and cross only at marked crossings; no one enters a no-pedestrian zone while trucks are working."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: The lines on this floor are the only thing between you and a several-ton truck coming out of an aisle. This week: walk the lines."],["h","3. KEY TEACHING POINTS"],["pt","1. Walk only in marked walkways."],["p","[SITE: color] lines mark pedestrian routes. They lead to the break room, restrooms, offices, exits and the dock desk."],["pt","2. Cross only at marked crossings."],["p","Stop at the edge, look both ways, and make eye contact with any operator before you cross."],["pt","3. No-pedestrian zones."],["p","[SITE: active dock lanes, roll storage aisles, rail dock while cars are worked] are off-limits on foot while trucks are operating. Get an operator to stop first."],["pt","4. Report bad lines."],["p","Faded paint or a walkway that doesn\\u0027t go where people need to go — tell your supervisor so we fix the line, not ignore it."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Most of the time someone gets hit by a lift, they were somewhere they didn\\u0027t need to be on foot: cutting through an aisle, crossing a dock lane to save 30 seconds, walking behind a truck that was backing out of a trailer."],["p","Our walkways go everywhere you need to go on foot. If you have to go into an aisle — to check a label, count rolls, look at damage — stop at the end of the aisle, get the operator\\u0027s attention, and make sure they stop before you go in."],["p","If a walkway is in the wrong place or the paint is gone, tell me. We\\u0027ll fix the line. What I won\\u0027t accept is everyone ignoring it."],["call","SHOW IT: Point out on the floor map [SITE] the walkway from the break room to the dock desk, and the crossing nearest this huddle."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The shortcut to the dock desk."],["p","Second shift kept cutting through roll aisle [SITE] to reach the dock desk because the walkway went the long way around. After a near miss with a clamp truck, the supervisor added a marked crossing and a convex mirror at the aisle end. Shortcuts dropped to zero."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do you or others leave the walkway most often, and why?"],["p","Listen for: Usually to save time. Capture each spot; decide whether it needs a new crossing, a mirror or enforcement."],["h","7. KNOWLEDGE CHECK"],["pt","1. You need to check a roll label inside an aisle where a clamp truck is working. What do you do?"],["p","Answer: Stop at the aisle end, get the operator\\u0027s attention, wait until they stop and acknowledge you, then enter."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Walk only in marked walkways today. If you catch yourself leaving one, note where and tell me at end of shift."],["h","9. SUPERVISOR VERIFICATION"],["li","Observe pedestrian routes for 10 minutes at the busiest crossing."],["li","List faded or missing floor markings and submit a repaint request."],["li","Coach any shortcut observed on the spot."],["p","References: Rules of Safe Operation SOP (Part C) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8g) • [SITE: traffic plan / floor map] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W15","week":15,"doc":"PWH-MTR-2027-W15","date":"2027-04-12","holiday":false,"month":4,"title":"Speed Limits and the Cross-Aisle Horn Rule","behavior":"Sound your horn at every aisle end and doorway today, and keep three truck lengths behind any truck in front of you.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W15 Apr 12 - Speed Limits and the Cross-Aisle Horn Rule.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nSpeed Limits and the Cross-Aisle Horn Rule"]],["tr",["Doc No: PWH-MTR-2027-W15\\nWeek: 15 · Mon Apr 12, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 15 of 52 · April 2027"]],["tr",["Monday training title","Speed Limits and the Cross-Aisle Horn Rule"]],["tr",["Monthly theme","Pedestrian–Equipment Separation \\u0026 Traffic Management"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178(n)) — refresher"]],["tr",["Training objective","Operators travel at or below the posted speed, slow down and sound the horn at every intersection, aisle end, blind corner, doorway, trailer and railcar."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A loaded clamp truck needs much more room to stop than an empty one. The only way to stop in time is to already be going slow enough."],["h","3. KEY TEACHING POINTS"],["pt","1. Posted limit is the maximum, not the target."],["p","[SITE: mph]. Travel at a speed that lets you stop safely at all times."],["pt","2. Slow down for conditions."],["p","Corners, doorways, docks, wet or uneven floors, ramps and dock plates."],["pt","3. Horn at every intersection, aisle end, blind corner and doorway."],["p","And every time you enter or leave a trailer or railcar."],["pt","4. Three truck lengths."],["p","Keep at least three truck lengths behind another truck; never pass at intersections or blind spots."],["pt","5. Hear a horn, slow down."],["p","Another truck is coming out of an aisle or trailer."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Speed is completely in your control, and it\\u0027s the biggest factor in how bad an incident is. A truck going 4 mph that hits a pedestrian is an injury. The same truck at 8 mph can be a fatality."],["p","The horn is your voice. Use it at every intersection and aisle end, even if you think nobody\\u0027s there. Most near misses at aisle ends happen when two trucks or a truck and a person both assume the other is clear."],["p","If you\\u0027re following another truck, stay three lengths back. If they stop short with a roll on, you need room."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The quiet aisle end."],["p","An operator comes out of an aisle at speed without sounding the horn. A pedestrian walking the main aisle hears nothing and steps into the intersection. The operator stops with about three feet to spare. Reported as a near miss; the fix is the horn and a stop sign at that aisle end."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where is it tempting to speed in this building?"],["p","Listen for: Long main aisles, empty return trips, end of shift. Agree that empty trucks follow the same limits."],["h","7. KNOWLEDGE CHECK"],["pt","1. You\\u0027re coming to an aisle end and can\\u0027t see anyone. Do you still sound the horn?"],["p","Answer: Yes. Slow down and sound the horn at every intersection and aisle end, whether you see anyone or not."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Sound your horn at every aisle end and doorway today, and keep three truck lengths behind any truck in front of you."],["h","9. SUPERVISOR VERIFICATION"],["li","Stand at a main intersection for 10 minutes and count horn use vs. trucks passing."],["li","Observe speed on the longest aisle; coach anyone over the limit."],["li","Record results on PWH-FRM-MHE-01 (Section 6)."],["p","References: OSHA 29 CFR 1910.178(n) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8c–f) • Rules of Safe Operation SOP (Part C.2) • PWH-SOP-171 (Sec. 5.2) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W16","week":16,"doc":"PWH-MTR-2027-W16","date":"2027-04-19","holiday":false,"month":4,"title":"Eye Contact Before Movement: Communicating With Operators","behavior":"Make eye contact with every operator or pedestrian before you move near them today — every time.","track":"","file":"Part 3 - Weekly Jan-Apr/W16 Apr 19 - Eye Contact Before Movement Communicating With Operators.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nEye Contact Before Movement: Communicating With Operators"]],["tr",["Doc No: PWH-MTR-2027-W16\\nWeek: 16 · Mon Apr 19, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 16 of 52 · April 2027"]],["tr",["Monday training title","Eye Contact Before Movement: Communicating With Operators"]],["tr",["Monthly theme","Pedestrian–Equipment Separation \\u0026 Traffic Management"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company traffic rule — awareness"]],["tr",["Training objective","Operators and pedestrians confirm eye contact before any approach, crossing or close work near a truck."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A wave from across the dock doesn\\u0027t mean the operator saw you. Eye contact does. The rule this week: no eye contact, no movement."],["h","3. KEY TEACHING POINTS"],["pt","1. Pedestrians: get eye contact before you step into a truck\\u0027s path or work near it."],["p","If the operator is looking at the load or over the other shoulder, they haven\\u0027t seen you."],["pt","2. Operators: stop or slow until you\\u0027ve made eye contact with anyone near your path."],["p","Then signal clearly — a nod or hand signal — before moving."],["pt","3. Never drive toward someone in front of a fixed object."],["p","A person between a truck and a rack, wall or stack has nowhere to go."],["pt","4. Radios and hearing protection change the rules."],["p","Don\\u0027t rely on voice or horn alone. Move into the operator\\u0027s line of sight and wait for acknowledgment."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Eye contact is the handshake between an operator and a pedestrian. Both people know the other one knows. Without it, each one is guessing."],["p","Pedestrians: stand where the operator can see you — not behind the load, not in a blind spot — and wait until they look at you and signal. Operators: if someone is near your path, stop until you\\u0027ve seen their eyes and they\\u0027ve seen yours."],["p","If you need to talk to an operator, don\\u0027t walk up beside a moving truck. Get in front of them at a safe distance, make eye contact, and wait for them to stop and set the load down."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The driver at door [SITE]."],["p","A truck driver climbs down to check his trailer while a clamp operator is loading it. The driver waves at the operator, who\\u0027s looking over his shoulder at the roll and never sees the wave. Nothing happens — this time. The fix: drivers wait in the designated area [SITE], and operators stop work when anyone is near the trailer until eye contact is made."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: When is it hardest to get eye contact here, and what\\u0027s the backup?"],["p","Listen for: Loud areas, inside trailers, night shift, hearing protection. Backup: stop, step into sight, use agreed hand signals, radio the operator."],["h","7. KNOWLEDGE CHECK"],["pt","1. A pedestrian waves at you from the side of the aisle while you\\u0027re watching your load. Do you have eye contact?"],["p","Answer: No. Stop or slow, look at them directly and signal before you move."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Make eye contact with every operator or pedestrian before you move near them today — every time."],["h","9. SUPERVISOR VERIFICATION"],["li","Watch three pedestrian–truck interactions and note whether eye contact happened."],["li","Remind visiting drivers of the designated waiting area."],["li","Coach any approach without acknowledgment on the spot."],["p","References: MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8g) • Rules of Safe Operation SOP (Part C) • OSHA 29 CFR 1910.178(m)(1) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W17","week":17,"doc":"PWH-MTR-2027-W17","date":"2027-04-26","holiday":false,"month":4,"title":"Blind Corners, Mirrors and Traveling With an Obstructed View","behavior":"Travel in reverse whenever a load blocks your view, and sound your horn and check the mirror at every blind corner today.","track":"PIT","file":"Part 3 - Weekly Jan-Apr/W17 Apr 26 - Blind Corners, Mirrors and Traveling With an Obstructed View.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nBlind Corners, Mirrors and Traveling With an Obstructed View"]],["tr",["Doc No: PWH-MTR-2027-W17\\nWeek: 17 · Mon Apr 26, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 17 of 52 · April 2027"]],["tr",["Monday training title","Blind Corners, Mirrors and Traveling With an Obstructed View"]],["tr",["Monthly theme","Pedestrian–Equipment Separation \\u0026 Traffic Management"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178(n)(6)) — refresher"]],["tr",["Training objective","Operators travel in reverse or use a spotter whenever the load blocks the forward view, and slow and sound the horn at blind corners."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A paper roll on a clamp truck blocks everything in front of you. That\\u0027s why our clamp SOP says you always drive in reverse with a roll. Today: how to travel when you can\\u0027t see."],["h","3. KEY TEACHING POINTS"],["pt","1. Look in the direction of travel."],["p","If the load blocks your forward view, travel in reverse. With rolls on a clamp truck, always travel in reverse (PWH-SOP-171)."],["pt","2. Turn your head, don\\u0027t just use mirrors."],["p","Mirrors help at corners; they don\\u0027t replace looking where you\\u0027re going."],["pt","3. Blind corners: slow, horn, check the mirror, then proceed."],["p","Watch your rear-end swing in turns."],["pt","4. Use a spotter when you can\\u0027t see."],["p","Placing a load where neither direction gives a clear view — stop and get a spotter."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When you travel in reverse, turn your body and look over your shoulder in the direction you\\u0027re moving. Don\\u0027t drive by mirror. Mirrors at aisle ends and dock corners are there to show you what\\u0027s coming around the corner, not to replace looking."],["p","At a blind corner: slow down, sound the horn, check the convex mirror if there is one, and then go. And remember the back of a lift swings wide when you turn, because it steers from the rear. People standing at the corner can get clipped by the counterweight."],["p","If you have to place a load somewhere you can\\u0027t see either way — deep in a trailer nose, a tight corner — stop and ask for a spotter. That\\u0027s not a sign of weakness. It\\u0027s the SOP."],["call","SHOW IT: Sit in a clamp truck with a roll staged in front of it. Let a few employees sit in the seat and see how little of the floor ahead is visible."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The forward drive with a roll."],["p","An operator drives forward with a 60-inch roll because it\\u0027s a short move. He doesn\\u0027t see a lead kneeling to read a label on the floor ahead. The lead hears the truck and rolls out of the way. This is exactly why the rule says always reverse with rolls."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where are the worst blind corners in this building? Do they have mirrors?"],["p","Listen for: List them; request mirrors, stop signs or layout changes where needed."],["h","7. KNOWLEDGE CHECK"],["pt","1. You\\u0027re carrying a roll on a clamp truck. Which direction do you travel?"],["p","Answer: In reverse, looking in the direction of travel, sounding the horn at intersections and doorways."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Travel in reverse whenever a load blocks your view, and sound your horn and check the mirror at every blind corner today."],["h","9. SUPERVISOR VERIFICATION"],["li","Watch every clamp truck carrying a roll for travel direction."],["li","Walk the blind corners and confirm mirrors are present, clean and aimed correctly."],["li","Record on PWH-FRM-MHE-01 (\\u0027Roll operators travel in reverse\\u0027)."],["p","References: OSHA 29 CFR 1910.178(n)(6) • PWH-SOP-171 Roll Clamp Truck Operation (Sec. 5.2) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8d) • Rules of Safe Operation SOP (Part F) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W18","week":18,"doc":"PWH-MTR-2027-W18","date":"2027-05-03","holiday":false,"month":5,"title":"Clamp Attachment Inspection: Pads, Arms, Hoses and Rotation","behavior":"Wipe both clamp pads and check hoses, welds and rotation before your first roll today, and note it on your inspection form.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W18 May 3 - Clamp Attachment Inspection Pads, Arms, Hoses and Rotation.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nClamp Attachment Inspection: Pads, Arms, Hoses and Rotation"]],["tr",["Doc No: PWH-MTR-2027-W18\\nWeek: 18 · Mon May 3, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 18 of 52 · May 2027"]],["tr",["Monday training title","Clamp Attachment Inspection: Pads, Arms, Hoses and Rotation"]],["tr",["Monthly theme","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every clamp operator inspects the clamp attachment, not just the truck, before the first roll of every shift."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Your pre-shift inspection covers the truck. The clamp is what\\u0027s actually holding a ton or more of paper over the floor. It gets its own look every shift."],["h","3. KEY TEACHING POINTS"],["pt","1. Pads."],["p","Clean of paper debris; not cracked, torn, delaminating or worn smooth. Debris between a pad and a roll acts like ball bearings."],["pt","2. Arms and frame."],["p","No cracks at welds, no bends, no loose or missing bolts."],["pt","3. Hydraulics."],["p","No leaks at hoses, fittings or cylinders; hoses not worn, kinked or rubbing."],["pt","4. Function."],["p","Rotates smoothly both ways; opens, closes and releases cleanly; holds without drifting; pressure gauge reads."],["pt","5. Fail = tag out."],["p","Any clamp defect that affects safe handling takes the truck out of service until repaired and released."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Start with the truck off. Look at both pads closely. Paper dust and torn wrapper build up on pads, and it doesn\\u0027t take much to make a roll slip in the arms. Wipe them clean before your first pickup."],["p","Look at the arms where they\\u0027re welded to the frame — that\\u0027s where cracks start. Look for drips under the hydraulic cylinders and fittings. A leak isn\\u0027t just a mechanical problem; if hydraulic fluid gets on product, that product goes on hold."],["p","Then turn it on. Rotate the clamp both ways, open and close it, and watch the gauge. If the clamp drifts open while it\\u0027s holding, or the gauge doesn\\u0027t move, tag the truck out. Our performance test, PWH-FRM-213-1, checks you on exactly these things: rotating smoothly, releasing smoothly, reading the gauge."],["call","SHOW IT: On a parked clamp truck, wipe a pad with a rag and show the debris that comes off. Point out the weld points and hose fittings."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The slipping roll."],["p","An operator lifts a roll and feels it slide half an inch in the arms as he brakes. He sets it down and finds a layer of paper dust and wrapper on one pad. Cleaned, the pad holds fine. That half-inch is how rolls end up on the floor."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the one clamp item you\\u0027ve seen fail most often on our trucks?"],["p","Listen for: Pad wear or debris, hose leaks, rotation drift, gauge failures. Make sure maintenance hears it."],["h","7. KNOWLEDGE CHECK"],["pt","1. Your clamp slowly drifts open while holding a roll during your check. What do you do?"],["p","Answer: Set the roll down, tag the truck out, remove the key and tell your supervisor. It doesn\\u0027t run until repaired."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Wipe both clamp pads and check hoses, welds and rotation before your first roll today, and note it on your inspection form."],["h","9. SUPERVISOR VERIFICATION"],["li","Check one clamp truck\\u0027s pads at shift start for debris."],["li","Review inspection forms for clamp-specific items being checked."],["li","Confirm any clamp defect has a tag-out and a repair request."],["p","References: PWH-SOP-171 (Sec. 5.1) • Rules of Safe Operation SOP (Part B.2: Roll Clamp Trucks) • PWH-FRM-213-1 (Section 3) • OSHA 29 CFR 1910.178(q)(7) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W19","week":19,"doc":"PWH-MTR-2027-W19","date":"2027-05-10","holiday":false,"month":5,"title":"Clamp Pressure: Matching the Setting to the Roll","behavior":"Check the pressure chart and your gauge at every grade or diameter change today.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W19 May 10 - Clamp Pressure Matching the Setting to the Roll.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nClamp Pressure: Matching the Setting to the Roll"]],["tr",["Doc No: PWH-MTR-2027-W19\\nWeek: 19 · Mon May 10, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 19 of 52 · May 2027"]],["tr",["Monday training title","Clamp Pressure: Matching the Setting to the Roll"]],["tr",["Monthly theme","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every operator sets clamp pressure from the posted chart for the roll being handled and verifies it on the gauge."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Too much pressure crushes a core and the customer can\\u0027t run the roll. Too little and the roll slips out. The right number is on the chart, not in your gut."],["h","3. KEY TEACHING POINTS"],["pt","1. Pressure depends on roll size and weight."],["p","Use the posted chart [SITE] built from the clamp manufacturer\\u0027s guidelines and each customer\\u0027s handling spec."],["pt","2. Set it at every change."],["p","New grade, diameter, width or customer = check the chart and adjust before the first pickup."],["pt","3. Read the gauge on the first squeeze."],["p","Confirm the reading is in range before lifting."],["pt","4. Signs pressure is wrong:"],["p","Too high — cores go oval, wrapper wrinkles or splits at the arms, flat spots. Too low — roll slides or rotates in the arms on stops or turns."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Our SOP says adjust pressure according to roll size and weight to avoid core crushing or roll slippage. That\\u0027s a balance, and the chart is how we hit it every time. If you don\\u0027t know the right setting for a roll, stop and ask the lead before you pick it up."],["p","When you change from one grade or diameter to another, the first thing you do is look at the chart. The second is set the pressure. The third is squeeze and read the gauge before you lift."],["p","If you notice cores going oval or wrinkles where the arms grip, the pressure is too high. If rolls are slipping or turning in the arms, it\\u0027s too low or the pads are dirty. Either way, stop and fix it, and tell the lead so any affected rolls get checked."],["call","SHOW IT: Point to the chart at [SITE] and walk through finding the setting for the roll currently staged."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The customer claim."],["p","A customer rejects six rolls from one shipment for crushed cores. All six were moved by the same operator, right after switching from a heavy liner grade. The pressure was never adjusted. One chart check would have prevented the claim."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: When are you most likely to forget to change the pressure?"],["p","Listen for: Mixed orders, end of shift, rushing a trailer, covering another operator\\u0027s area. Agree on a habit: chart check at every new SKU."],["h","7. KNOWLEDGE CHECK"],["pt","1. What three things do you do when you switch to a different roll grade?"],["p","Answer: Check the pressure chart, set the pressure, and verify on the gauge with the first squeeze before lifting."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check the pressure chart and your gauge at every grade or diameter change today."],["h","9. SUPERVISOR VERIFICATION"],["li","Ask two operators to show you the correct pressure for the roll they\\u0027re handling and the gauge reading."],["li","Inspect a sample of rolls handled today for oval cores or arm wrinkles."],["li","Record on PWH-FRM-MHE-01 (\\u0027Proper clamp pressure used\\u0027)."],["p","References: PWH-SOP-171 (Sec. 5.1, 5.2) • PWH-FRM-213-1 (Section 3, item 3: reads pressure gauge) • [SITE: clamp pressure chart] • Clamp attachment manufacturer\\u0027s manual • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W20","week":20,"doc":"PWH-MTR-2027-W20","date":"2027-05-17","holiday":false,"month":5,"title":"Picking Up a Roll: Squared, Centered, Full Pad Contact","behavior":"On every pickup today, stop, square up, center the arms and clamp near the bottom before you lift.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W20 May 17 - Picking Up a Roll Squared, Centered, Full Pad Contact.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPicking Up a Roll: Squared, Centered, Full Pad Contact"]],["tr",["Doc No: PWH-MTR-2027-W20\\nWeek: 20 · Mon May 17, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 20 of 52 · May 2027"]],["tr",["Monday training title","Picking Up a Roll: Squared, Centered, Full Pad Contact"]],["tr",["Monthly theme","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every roll is approached square, clamped centered and low with even pressure, and lifted only when the truck is stopped."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Most dropped rolls are decided before the roll ever leaves the floor. A good pickup is square, centered and low."],["h","3. KEY TEACHING POINTS"],["pt","1. Approach squarely."],["p","Line up straight to the roll, not at an angle."],["pt","2. Center the arms."],["p","Align the clamp arms with the center of the roll so the pads have full contact."],["pt","3. Engage near the bottom."],["p","Clamp near the bottom of the roll, close gently and evenly on both sides."],["pt","4. Lift only when stopped."],["p","Never lift or lower a roll while moving. Carry 4–6 inches off the floor."],["pt","5. Never push or roll product with the arms."],["p","If a roll needs to move an inch, pick it up and set it down."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When you come at a roll at an angle, one pad touches before the other and the roll gets pushed or twisted. That\\u0027s how edges get damaged and how rolls end up off-center in the arms. Come in straight."],["p","Center the arms on the roll and engage near the bottom. Close slowly so both pads meet the roll at the same time with even pressure. Then lift, only when the truck is completely stopped."],["p","Don\\u0027t nudge rolls into position with the clamp arms or roll them along the floor. Our SOP prohibits it, and it\\u0027s the fastest way to damage the wrapper and edges."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The angled pickup."],["p","An operator in a hurry picks a roll at a slight angle from a tight column. One pad catches the roll\\u0027s edge and tears the wrapper and the first few layers. The roll is now a damage claim, and it was one second of setup."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where is it hardest to get square to a roll in our storage layout?"],["p","Listen for: Tight columns, trailer noses, end-of-aisle stacks. Discuss setup and when to ask for a spotter."],["h","7. KNOWLEDGE CHECK"],["pt","1. Can you lift a roll while you\\u0027re still rolling forward?"],["p","Answer: No. Lift or lower only when the truck is stopped."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: On every pickup today, stop, square up, center the arms and clamp near the bottom before you lift."],["h","9. SUPERVISOR VERIFICATION"],["li","Watch five pickups by different operators: square, centered, low, stopped."],["li","Look for torn wrappers or edge damage in today\\u0027s put-away."],["li","Coach any arm-pushing or angled pickups on the spot."],["p","References: PWH-SOP-171 (Sec. 5.2: Positioning, Clamping, Lifting \\u0026 transport) • PWH-FRM-213-1 (items 10–15) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W21","week":21,"doc":"PWH-MTR-2027-W21","date":"2027-05-24","holiday":false,"month":5,"title":"Reading Roll Damage: Out-of-Round, Crushed Cores, Head and Edge Damage","behavior":"Look at the core and both ends of every roll you touch today, and report any damage before it goes into storage.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W21 May 24 - Reading Roll Damage Out-of-Round, Crushed Cores, Head and Edge Damage.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nReading Roll Damage: Out-of-Round, Crushed Cores, Head and Edge Damage"]],["tr",["Doc No: PWH-MTR-2027-W21\\nWeek: 21 · Mon May 24, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 21 of 52 · May 2027"]],["tr",["Monday training title","Reading Roll Damage: Out-of-Round, Crushed Cores, Head and Edge Damage"]],["tr",["Monthly theme","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Operators recognize roll damage before storage or shipping, set damaged rolls aside, tag and report them."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Every damaged roll is either a safety warning, a customer claim, or both. The sooner we see it, the cheaper it is."],["h","3. KEY TEACHING POINTS"],["pt","1. Crushed or oval core."],["p","The center hole isn\\u0027t round. Usually too much clamp pressure."],["pt","2. Out-of-round / flat spot."],["p","The roll sits unevenly or has a flat side. Unstable in a stack."],["pt","3. Head and edge damage."],["p","Dents, cuts or tears on the ends from misaligned stacking, angled pickups or drops."],["pt","4. Telescoping, wrapper tears, gouges and water marks."],["p","Shifted layers, torn or wet wrapper, fork or pallet-board gouges."],["pt","5. Damaged rolls don\\u0027t go into storage."],["p","Set aside, tag, report to the lead or CSR, and document it before it becomes our claim."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Look at every roll before you move it and after you set it down. Check the core: round or oval? Check both ends for dents and tears. Check the wrapper for tears, gouges and water."],["p","An out-of-round roll isn\\u0027t just a quality problem. A roll with a flat spot doesn\\u0027t sit level in a column and can make the whole stack lean."],["p","If you find damage on an inbound roll, document it on the receiving paperwork right away so it\\u0027s the carrier\\u0027s or shipper\\u0027s, not ours. If you caused it, report it. That\\u0027s how we fix the cause, and it\\u0027s always better than a customer finding it."],["call","SHOW IT: Show photos or a sample [SITE] of each damage type and have the crew name them."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The wet wrapper."],["p","During unloading, an operator notices a dark water mark on three rolls near the trailer nose where the roof had a pinhole. He notes it on the inspection sheet and sets the rolls aside before put-away. The customer files the claim against the carrier, not Piper."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which type of damage do we cause most often, and why?"],["p","Listen for: Usually oval cores (pressure) and edge damage (alignment or angled pickups). Tie back to Weeks 19 and 20."],["h","7. KNOWLEDGE CHECK"],["pt","1. You find a roll with a torn end during put-away. What do you do?"],["p","Answer: Don\\u0027t store it. Set it aside, tag it and report it to the lead or CSR so it\\u0027s documented."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Look at the core and both ends of every roll you touch today, and report any damage before it goes into storage."],["h","9. SUPERVISOR VERIFICATION"],["li","Check the damage/hold area: every roll tagged with date, reason and who found it."],["li","Confirm inbound damage was noted on receiving paperwork."],["li","Spot-check five stored rolls for unreported damage."],["p","References: PWH-SOP-171 (Sec. 7.2: inspect rolls after unloading) • Controlled Trailer/Rail Inspection and Load/Unload Sheet • Piper Warehouse Vendor Claim Form • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W22","week":22,"doc":"PWH-MTR-2027-W22","date":"2027-05-31","holiday":true,"month":5,"title":"Stacking and Storage: Height Limits, Column Stability, Clearances","behavior":"Before you set any roll down today, check the floor is clean, the roll will sit perfectly on the one below, and the label will face out at 45°.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W22 May 31 - Stacking and Storage Height Limits, Column Stability, Clearances.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nStacking and Storage: Height Limits, Column Stability, Clearances"]],["tr",["Doc No: PWH-MTR-2027-W22\\nWeek: 22 · Mon May 31, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 22 of 52 · May 2027 · Memorial Day — deliver at the first shift start this week if the site is closed"]],["tr",["Monday training title","Stacking and Storage: Height Limits, Column Stability, Clearances"]],["tr",["Monthly theme","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every roll column is built on a clean, level floor, perfectly aligned, within height limits, with correct gaps, clearances and label orientation."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A column of rolls is only as stable as its worst-aligned roll. This week: build every stack like someone\\u0027s going to walk next to it — because they will."],["h","3. KEY TEACHING POINTS"],["pt","1. Floor first."],["p","Sweep before placing rolls; check for bolts, cracks, indents or unevenness and report them to management."],["pt","2. Upright, compressed, perfectly aligned."],["p","Each roll sits squarely on the one below. Misalignment damages edges and makes columns lean."],["pt","3. Gaps and labels."],["p","2–3 inches (a fist) between columns; labels face out at 45° so they can be read from the aisle."],["pt","4. Height and clearance."],["p","Stack height by roll size [SITE: chart]; at least 5 feet below the ceiling; clear of sprinklers, lights, HVAC and anything hanging from the rafters."],["pt","5. Zones and rotation."],["p","Rolls go only in designated roll zones, by SKU and business unit, following FIFO/FEFO or the customer\\u0027s rotation."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Before a roll goes on the floor, the spot is swept. A small piece of debris or a bolt head under the bottom roll tilts the whole column. If there\\u0027s a crack or an indent, tell management before you stack on it."],["p","Each roll goes exactly on top of the one below. If it overhangs, it\\u0027s not \\u0027close enough\\u0027 — lift it and set it again. Leave about a fist between columns so they don\\u0027t rub and people can see between them."],["p","Labels face out at 45 degrees. It sounds like housekeeping, but it means nobody has to walk between columns or pull a roll to read it."],["p","Height: follow the chart for the roll size and keep 5 feet below the ceiling, clear of sprinklers and lights. Sprinklers need open space to work in a fire, and paper burns fast."],["call","SHOW IT: Walk to the nearest roll aisle and grade three columns together: aligned? gap? labels? height?"],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The column by the sprinkler line."],["p","During a GEMBA walk, a manager finds a column in aisle [SITE] stacked within about 3 feet of the sprinkler heads because the operator was \\u0027filling the spot\\u0027. The top roll is removed and the column re-stacked within the height limit."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where in our storage is it tempting to go over height or squeeze columns together?"],["p","Listen for: End of aisles, near docks during busy weeks, odd-size rolls. Agree on what to do when a location is full."],["h","7. KNOWLEDGE CHECK"],["pt","1. How far below the ceiling must roll stacks stay?"],["p","Answer: At least 5 feet, and clear of sprinklers, lights and HVAC."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before you set any roll down today, check the floor is clean, the roll will sit perfectly on the one below, and the label will face out at 45°."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk two roll aisles: alignment, gaps, labels, height and clearance."],["li","Correct any non-conforming stack before end of shift."],["li","Record on PWH-FRM-MHE-01 (Section 4: stacking, labels, spacing)."],["p","References: PWH-SOP-171 (Sec. 6) • Storage \\u0026 Put Away SOP PWH-SOP-208 (Sec. 6: Rolls) • [SITE: stack height chart] • OSHA 29 CFR 1910.176(b) (secure storage) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W23","week":23,"doc":"PWH-MTR-2027-W23","date":"2027-06-07","holiday":false,"month":6,"title":"Trailer Secured Before Entry: Restraint, Chocks and Dock Lights","behavior":"Before your first entry into every trailer today, physically check the restraint or chocks and, for drop trailers, the stand.","track":"","file":"Part 4 - Weekly May-Aug/W23 Jun 7 - Trailer Secured Before Entry Restraint, Chocks and Dock Lights.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nTrailer Secured Before Entry: Restraint, Chocks and Dock Lights"]],["tr",["Doc No: PWH-MTR-2027-W23\\nWeek: 23 · Mon Jun 7, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 23 of 52 · June 2027"]],["tr",["Monday training title","Trailer Secured Before Entry: Restraint, Chocks and Dock Lights"]],["tr",["Monthly theme","Dock, Trailer \\u0026 Railcar Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178(k)(1), (m)(7)) + company policy — refresher"]],["tr",["Training objective","No lift enters a trailer until the vehicle restraint or chocks are in place and, for uncoupled trailers, a trailer stand is under the nose."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A trailer that moves while a lift is on the plate can drop the truck and operator four feet to the ground. This week: nothing enters a trailer until it\\u0027s secured."],["h","3. KEY TEACHING POINTS"],["pt","1. Restraint or chocks, every trailer."],["p","Vehicle restraint engaged and light showing safe [SITE: green inside], or wheel chocks against the rear wheels at doors without a restraint."],["pt","2. Trailer stand under uncoupled trailers."],["p","Drop trailers get a stand (jack) under the nose so the trailer can\\u0027t tip forward under a heavy truck."],["pt","3. Tandems back for roll loads."],["p","Confirm the driver slid the tandems back before loading rolls."],["pt","4. Check before every entry."],["p","Trailer number and door match the paperwork; secure; plate seated. Then go in, sounding the horn."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","OSHA requires trailers to be braked and chocked or otherwise secured while lifts are boarding them. There\\u0027s legal history about who enforces that for over-the-road trucks. None of that matters here: at Piper every trailer is restrained or chocked before the first lift goes in."],["p","At doors with a vehicle restraint, engage it and check the light. If the restraint can\\u0027t catch the trailer\\u0027s bar, chock the wheels. At doors without a restraint, chocks go against the rear tires, both sides if you can."],["p","If the trailer isn\\u0027t connected to a tractor, it needs a stand under the nose. A loaded clamp truck rolling to the front of a drop trailer without a stand can tip it forward."],["call","SHOW IT: At the nearest door, show the restraint control and light, chock placement and the trailer stand location."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The driver who pulled forward."],["p","A driver at door [SITE] thought the load was done and pulled forward six inches as the clamp truck was backing out. The chocks held the trailer. Without them, the truck\\u0027s rear wheels would have dropped off the plate."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which doors give us trouble securing trailers, and what do we do about it?"],["p","Listen for: Restraints that don\\u0027t catch, missing chocks, damaged lights. Write work orders and assign chocks to every door."],["h","7. KNOWLEDGE CHECK"],["pt","1. A drop trailer is at the door with no tractor. What two things must be in place before you enter?"],["p","Answer: Restraint or wheel chocks, and a trailer stand under the nose."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before your first entry into every trailer today, physically check the restraint or chocks and, for drop trailers, the stand."],["h","9. SUPERVISOR VERIFICATION"],["li","Check every active door twice this shift for restraint/chocks and stands."],["li","Function-test one vehicle restraint and its lights."],["li","Review the \\u0027Wheels Chocked?\\u0027 and \\u0027Trailer Stand Applied?\\u0027 boxes on today\\u0027s load sheets."],["p","References: OSHA 29 CFR 1910.178(k)(1), (m)(7) • OSHA CPL 02-01-030 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 10a) • PWH-SOP-171 (Sec. 7.1) • Controlled Trailer/Rail Inspection and Load/Unload Sheet • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W24","week":24,"doc":"PWH-MTR-2027-W24","date":"2027-06-14","holiday":false,"month":6,"title":"Trailer Floors, Nose Inspection and Dock Plates","behavior":"Walk the full length of every trailer before your lift enters it today and check the plate is fully seated.","track":"","file":"Part 4 - Weekly May-Aug/W24 Jun 14 - Trailer Floors, Nose Inspection and Dock Plates.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nTrailer Floors, Nose Inspection and Dock Plates"]],["tr",["Doc No: PWH-MTR-2027-W24\\nWeek: 24 · Mon Jun 14, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 24 of 52 · June 2027"]],["tr",["Monday training title","Trailer Floors, Nose Inspection and Dock Plates"]],["tr",["Monthly theme","Dock, Trailer \\u0026 Railcar Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA (29 CFR 1910.178(k) and (m), 1910.30(a)) + company policy — refresher"]],["tr",["Training objective","Every trailer is walked and inspected before a lift drives in, weak floors are rejected, and dock plates are rated and fully seated."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Walk it before you drive it. A trailer floor that gives way under a loaded clamp truck doesn\\u0027t give a warning."],["h","3. KEY TEACHING POINTS"],["pt","1. Walk the trailer first."],["p","Holes, cracks, missing or soft boards, nails, metal sticking out, debris, water, odors."],["pt","2. Light through the floor = reject."],["p","Light shining through floorboards means weak boards (PWH-SOP-171 Sec. 7.1)."],["pt","3. Check the roof and walls."],["p","Holes, leaks, light at seams; for food-grade, clean, dry and odor-free."],["pt","4. Dock plate rated and seated."],["p","Know truck + load weight; plate fully seated on the trailer bed, not on the edge; cross slowly and straight."],["pt","5. Stay 4 feet from dock edges."],["p","Never drive along an open dock edge (Rules of Safe Operation)."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Before you drive in, walk to the nose and back. Look at every board. Stomp on spots that look soft. Look up for light through the roof. Sweep out debris and pull nails that could damage rolls."],["p","If you see light through the floor, that\\u0027s not a judgment call: the trailer is rejected. Tell the lead or CSR so the carrier sends a replacement and it\\u0027s documented."],["p","Dock plates have a rated capacity. A clamp truck with a heavy roll may be near it. The plate has to sit fully on the trailer bed. If it\\u0027s resting on the edge, or the trailer is too high or low for it to sit right, stop and get help."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The soft board near the nose."],["p","An operator walking a trailer finds a soft, cracked board three feet from the nose. The trailer is rejected and documented. The carrier confirms the board was rotted through underneath."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the worst trailer condition you\\u0027ve seen arrive here?"],["p","Listen for: Holes, rot, nails, mold, odors. Reinforce reject/document every time."],["h","7. KNOWLEDGE CHECK"],["pt","1. You see light through the trailer floorboards. What do you do?"],["p","Answer: Reject the trailer and document it. Don\\u0027t drive in."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Walk the full length of every trailer before your lift enters it today and check the plate is fully seated."],["h","9. SUPERVISOR VERIFICATION"],["li","Watch two operators: do they walk the trailer before entering?"],["li","Review floor and roof inspection lines on today\\u0027s load sheets."],["li","Inspect dock plates and levelers at active doors; tag any damaged."],["p","References: OSHA 29 CFR 1910.178(k), (m) • OSHA 29 CFR 1910.30(a) • PWH-SOP-171 (Sec. 7.1) • Rules of Safe Operation SOP (Part C, D) • Trailer Inspection Sheet 12.6.5.2 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W25","week":25,"doc":"PWH-MTR-2027-W25","date":"2027-06-21","holiday":false,"month":6,"title":"Railcar Safety: Car Stops, Derails, Blue Flags and Bridge Plates","behavior":"Before entering any railcar today, personally confirm the blue flag, derail, hand brake, wheel blocks and bridge plate.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W25 Jun 21 - Railcar Safety Car Stops, Derails, Blue Flags and Bridge Plates.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nRailcar Safety: Car Stops, Derails, Blue Flags and Bridge Plates"]],["tr",["Doc No: PWH-MTR-2027-W25\\nWeek: 25 · Mon Jun 21, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 25 of 52 · June 2027"]],["tr",["Monday training title","Railcar Safety: Car Stops, Derails, Blue Flags and Bridge Plates"]],["tr",["Monthly theme","Dock, Trailer \\u0026 Railcar Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PIT (29 CFR 1910.178(k), (m)(7)) + railroad rules — refresher"]],["tr",["Training objective","No lift enters a railcar unless blue-flag protection and derail are in place, the hand brake is set, wheels are blocked, and the bridge plate is rated and secured."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Rail is what makes Piper different — and a railcar is heavier than anything else we handle. A car that moves while a lift is inside or on the plate can crush everything in its path."],["h","3. KEY TEACHING POINTS"],["pt","1. Blue flag and derail first."],["p","Blue-flag protection and the derail are placed per [SITE: rail procedure] before anyone enters or works a car. Only [SITE: authorized person] places or removes them."],["pt","2. Hand brake set and wheels blocked."],["p","The car\\u0027s hand brake is set and wheels are blocked so it can\\u0027t move during loading or unloading."],["pt","3. Bridge plate rated and secured."],["p","Rated for truck plus load; positioned and secured so it can\\u0027t slip."],["pt","4. Doors: never with the forks or clamp."],["p","Rail car doors are fully open and secured; never open, close or push them with a lift."],["pt","5. Check the car floor and contents."],["p","Floor damage, debris, shifted or damaged rolls and blocking before you drive in."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Blue flag means people are working on or around this car and it must not be moved. The derail physically stops a car rolling toward our dock. Those go up before anyone steps onto the plate, and they come down only when everyone\\u0027s out and the work is done."],["p","Set the hand brake and block the wheels. Then the bridge plate: it has to be rated for the lift plus the heaviest roll and secured so it can\\u0027t slide when you drive on or off."],["p","Never use the forks or clamp arms to move railcar doors. Doors that jump the track or swing can crush someone. If a door won\\u0027t open, get the railroad or maintenance."],["p","Inside the car, look for shifted rolls and loose blocking before you drive in. A roll that shifted in transit can be leaning against the door."],["call","SHOW IT: At the rail dock, point to the blue flag, the derail position, the car stops and the bridge plate rating [SITE]."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The switch crew."],["p","A railroad switch crew arrives to pull cars while a car is still being unloaded. The blue flag and derail are in place, so they wait. That\\u0027s exactly why they exist: they protect people the railroad can\\u0027t see."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What would you do if the railroad showed up to move cars while you were still unloading?"],["p","Listen for: Stay out of the car, keep blue flag and derail in place, tell the supervisor; only the authorized person removes protection when everyone is clear."],["h","7. KNOWLEDGE CHECK"],["pt","1. Can you open a stuck railcar door by pushing it with the clamp arms?"],["p","Answer: No. Never move, open or close railcar doors with a lift. Get the railroad or maintenance."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before entering any railcar today, personally confirm the blue flag, derail, hand brake, wheel blocks and bridge plate."],["h","9. SUPERVISOR VERIFICATION"],["li","Inspect the rail dock at start and mid-shift: protection in place on every car being worked."],["li","Confirm the bridge plate rating is marked and adequate."],["li","Review rail unload paperwork for car condition and seal verification."],["p","References: OSHA 29 CFR 1910.178(k), (m)(7) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 10b) • [SITE: rail procedure and serving railroad\\u0027s blue-flag rules] • Controlled Trailer/Rail Inspection and Load/Unload Sheet • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W26","week":26,"doc":"PWH-MTR-2027-W26","date":"2027-06-28","holiday":false,"month":6,"title":"Heat Inside Trailers and Railcars","behavior":"Bring water to the dock today and check on anyone working inside a trailer or railcar near you.","track":"","file":"Part 4 - Weekly May-Aug/W26 Jun 28 - Heat Inside Trailers and Railcars.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nHeat Inside Trailers and Railcars"]],["tr",["Doc No: PWH-MTR-2027-W26\\nWeek: 26 · Mon Jun 28, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 26 of 52 · June 2027"]],["tr",["Monday training title","Heat Inside Trailers and Railcars"]],["tr",["Monthly theme","Dock, Trailer \\u0026 Railcar Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness (heat) — seasonal"]],["tr",["Training objective","Crews working inside trailers and railcars rotate, hydrate and watch each other for heat illness."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A trailer or boxcar sitting in the sun gets much hotter inside than the dock. Starting this week, we treat every trailer and railcar like the hottest room in the building — because it is."],["h","3. KEY TEACHING POINTS"],["pt","1. Inside is hotter than outside."],["p","Metal trailers and boxcars in direct sun trap heat; humidity makes it worse."],["pt","2. Rotate out."],["p","When heat procedures are in effect, rotate crews out of trailers and railcars per [SITE: schedule]."],["pt","3. Water close by."],["p","Bring water to the dock; drink about a cup every 15–20 minutes."],["pt","4. Fans and doors."],["p","Use dock fans [SITE]; open both doors on railcars where safe to move air."],["pt","5. Buddy checks."],["p","Check on anyone working alone inside a trailer or car at least every [SITE] minutes."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Next month we go deep on heat illness. This week is about the place it happens most for us: inside trailers and railcars. On a hot afternoon the inside of a closed boxcar can be dangerous within minutes of hard work."],["p","When heat procedures are in effect, we rotate people out on a schedule, even if they say they\\u0027re fine. We keep water at the dock, not in the break room. We use fans and open railcar doors on both sides where it\\u0027s safe."],["p","And nobody works inside a hot trailer or car without someone checking on them."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The afternoon boxcar."],["p","A two-person crew unloads a boxcar in the late afternoon. One starts cramping and feels dizzy, sits on a roll and says he\\u0027ll be fine. His partner gets him out to the cool-down area with water and tells the lead. He recovers in 20 minutes. Caught early, heat exhaustion stays heat exhaustion."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the hottest trailer or railcar job we do, and how long are people in there?"],["p","Listen for: Long boxcar unloads, afternoon outbound loads. Plan rotations around those jobs."],["h","7. KNOWLEDGE CHECK"],["pt","1. How often should you drink water when working in a hot trailer?"],["p","Answer: About a cup every 15–20 minutes, before you\\u0027re thirsty."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Bring water to the dock today and check on anyone working inside a trailer or railcar near you."],["h","9. SUPERVISOR VERIFICATION"],["li","Water at the dock and rail dock all shift."],["li","Rotation schedule followed when heat procedures are announced."],["li","Dock fans working and positioned."],["p","References: OSHA heat guidance and Heat National Emphasis Program • OSH Act Section 5(a)(1) • [SITE: heat illness prevention plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W27","week":27,"doc":"PWH-MTR-2027-W27","date":"2027-07-05","holiday":true,"month":7,"title":"Heat Illness: Exhaustion vs. Stroke and What to Do","behavior":"Know where the cool-down area, ice and the 911 address are before the afternoon heat hits today.","track":"","file":"Part 4 - Weekly May-Aug/W27 Jul 5 - Heat Illness Exhaustion vs. Stroke and What to Do.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nHeat Illness: Exhaustion vs. Stroke and What to Do"]],["tr",["Doc No: PWH-MTR-2027-W27\\nWeek: 27 · Mon Jul 5, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 27 of 52 · July 2027 · Independence Day observed — deliver at the first shift start this week if the site is closed"]],["tr",["Monday training title","Heat Illness: Exhaustion vs. Stroke and What to Do"]],["tr",["Monthly theme","Heat Stress, Fatigue \\u0026 First Response"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness (heat illness) — OSHA General Duty Clause / Heat NEP"]],["tr",["Training objective","Employees can name the warning signs of heat exhaustion and heat stroke and the correct response to each."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Heat stroke kills people who felt fine an hour earlier. The person in trouble often can\\u0027t tell — so all of us need to know what to look for."],["h","3. KEY TEACHING POINTS"],["pt","1. Heat exhaustion:"],["p","Heavy sweating, muscle cramps, headache, dizziness, nausea, weakness, cool clammy skin."],["pt","2. Exhaustion response:"],["p","Stop work, move to the cool-down area [SITE], loosen clothing, sip cool water, cool the skin with wet towels. Tell the lead. If not improving in [SITE: 15–30] minutes, get medical help."],["pt","3. Heat stroke:"],["p","Confusion, slurred speech, strange behavior, fainting or seizures; skin hot (dry or sweating)."],["pt","4. Stroke response:"],["p","Call 911 first. Move them somewhere cool, cool them fast with water, ice packs (neck, armpits, groin) and fanning. Stay with them."],["pt","5. Confusion means 911."],["p","Don\\u0027t wait for them to ask for help."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Two conditions, two responses. Heat exhaustion is your body falling behind. You\\u0027ll see someone sweating heavily, cramping, dizzy, pale. Get them out of the heat and cooling down, and tell the lead."],["p","Heat stroke is your body losing control of its temperature. The sign that matters most is the brain: confusion, slurred speech, acting strange, collapsing. That\\u0027s a 911 call, right now. While you wait, cool them as fast as you can."],["p","The cool-down area is [SITE]. Ice and cold towels are at [SITE]. The address to give 911 is [SITE: street address and dock door]."],["call","SHOW IT: Point to the cool-down area, ice/cold-water location and the posted address for 911."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The co-worker who \\u0027was fine\\u0027."],["p","On a hot afternoon, an operator stops answering his radio. His lead finds him sitting in his truck, confused about which trailer he was loading. She calls 911, gets him to the cool-down area and starts cooling him with water and ice. Paramedics confirm heat stroke. Her fast action made the difference."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What address and dock door would you give 911 from this building?"],["p","Listen for: Make sure everyone knows: [SITE: address]. Post it at the dock desk if it isn\\u0027t already."],["h","7. KNOWLEDGE CHECK"],["pt","1. A co-worker is sweating, confused and slurring words. Exhaustion or stroke, and what do you do?"],["p","Answer: Heat stroke. Call 911, move them somewhere cool, cool them fast with water and ice, and stay with them."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Know where the cool-down area, ice and the 911 address are before the afternoon heat hits today."],["h","9. SUPERVISOR VERIFICATION"],["li","Ask three employees to describe one heat stroke sign and the first thing they\\u0027d do."],["li","Check ice, cold towels and water at the cool-down area."],["li","Confirm the 911 address is posted at the dock desk and break room."],["p","References: OSHA heat illness guidance • OSHA Heat National Emphasis Program (revised April 10, 2026) • OSHA 29 CFR 1910.151 • [SITE: heat illness prevention plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W28","week":28,"doc":"PWH-MTR-2027-W28","date":"2027-07-12","holiday":false,"month":7,"title":"Hydration and Acclimatization for New and Returning Workers","behavior":"Fill your water bottle before shift start and drink a cup every 15–20 minutes while working the dock or inside trailers.","track":"","file":"Part 4 - Weekly May-Aug/W28 Jul 12 - Hydration and Acclimatization for New and Returning Workers.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nHydration and Acclimatization for New and Returning Workers"]],["tr",["Doc No: PWH-MTR-2027-W28\\nWeek: 28 · Mon Jul 12, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 28 of 52 · July 2027"]],["tr",["Monday training title","Hydration and Acclimatization for New and Returning Workers"]],["tr",["Monthly theme","Heat Stress, Fatigue \\u0026 First Response"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness (heat illness) — prevention"]],["tr",["Training objective","Employees drink on schedule in heat, and new or returning workers follow a gradual heat-exposure schedule."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Most heat illness happens to people in their first days on the job or back from time off. Your body needs time to adjust to heat, and water before you\\u0027re thirsty."],["h","3. KEY TEACHING POINTS"],["pt","1. Drink before you\\u0027re thirsty."],["p","About one cup (8 oz) every 15–20 minutes in heat. Don\\u0027t wait for lunch."],["pt","2. Electrolytes on long, sweaty shifts."],["p","Water first; sports drinks help when you\\u0027re sweating for hours. Limit energy drinks and alcohol the night before."],["pt","3. Acclimatize."],["p","New and returning workers (a week or more off) get extra rotation out of trailers and railcars for their first [SITE: 7–14] days."],["pt","4. Check your urine color."],["p","Dark yellow means you\\u0027re behind on fluids."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","The body adjusts to heat over roughly one to two weeks: you sweat earlier and lose fewer electrolytes. Until then, you\\u0027re at much higher risk. If you\\u0027re new, or you\\u0027ve been out a week or more, you\\u0027ll rotate out of the hottest jobs more often for your first [SITE] days. That\\u0027s not a judgment on your toughness."],["p","Thirst shows up after you\\u0027re already behind. Keep a bottle at the dock and drink a cup every 15 to 20 minutes when it\\u0027s hot."],["p","Energy drinks and a lot of coffee don\\u0027t hydrate you, and drinking alcohol the night before a hot shift sets you up for trouble."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The first week back."],["p","An experienced operator returns from two weeks of vacation in July and goes straight back to unloading boxcars. By mid-afternoon he\\u0027s cramping and nauseous. Two weeks off was enough to lose his heat tolerance. Rotation for returning workers prevents exactly this."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Who on this crew is new or just back from time off?"],["p","Listen for: Identify them by name (privately if needed) and set their rotation now."],["h","7. KNOWLEDGE CHECK"],["pt","1. How much water should you drink when working in heat?"],["p","Answer: About one cup every 15–20 minutes, starting before you feel thirsty."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Fill your water bottle before shift start and drink a cup every 15–20 minutes while working the dock or inside trailers."],["h","9. SUPERVISOR VERIFICATION"],["li","Identify new or returning employees and assign their rotation."],["li","Check water stations stocked at mid-shift."],["li","Observe breaks being taken in hot areas."],["p","References: OSHA heat illness guidance (water, rest, shade; acclimatization) • [SITE: heat illness prevention plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W29","week":29,"doc":"PWH-MTR-2027-W29","date":"2027-07-19","holiday":false,"month":7,"title":"Fatigue: Long Shifts, Overtime and Knowing When You\\u0027re Impaired","behavior":"If you feel your attention drifting today, stop and tell me before you take the next load.","track":"","file":"Part 4 - Weekly May-Aug/W29 Jul 19 - Fatigue Long Shifts, Overtime and Knowing When You\\u0027re Impaired.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nFatigue: Long Shifts, Overtime and Knowing When You\\u0027re Impaired"]],["tr",["Doc No: PWH-MTR-2027-W29\\nWeek: 29 · Mon Jul 19, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 29 of 52 · July 2027"]],["tr",["Monday training title","Fatigue: Long Shifts, Overtime and Knowing When You\\u0027re Impaired"]],["tr",["Monthly theme","Heat Stress, Fatigue \\u0026 First Response"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness — fatigue management"]],["tr",["Training objective","Employees recognize fatigue in themselves and others and report it; supervisors reassign without penalty."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Being awake 17 to 19 hours can slow your reactions about as much as being legally drunk. On a clamp truck, that\\u0027s not a risk we take."],["h","3. KEY TEACHING POINTS"],["pt","1. Know the signs."],["p","Heavy eyelids, yawning, drifting attention, missed steps, slow reactions, \\u0027blanking out\\u0027 for a second."],["pt","2. Fatigue is a stop-work call on yourself."],["p","Tell your supervisor. You\\u0027ll be moved to a different task, not disciplined."],["pt","3. Watch the high-risk times."],["p","Overnight hours, the end of long or double shifts, the first night shift after days off."],["pt","4. Protect your sleep."],["p","Seven to nine hours where possible; dark, cool room on night shifts."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Research consistently finds that being awake 17 to 19 hours can slow reaction time about as much as a blood alcohol level near the legal limit. You wouldn\\u0027t drive a truck drunk. Don\\u0027t drive one exhausted."],["p","If you\\u0027re nodding off, missing things or catching yourself \\u0027blanking out\\u0027, tell me. You\\u0027ll be reassigned to something off the truck. That\\u0027s using your stop-work authority on yourself, and it\\u0027s exactly what I want."],["p","Supervisors: when we\\u0027re short-staffed and asking for overtime, we watch for fatigue harder, not less. No one runs equipment through a double shift without rest."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. Hour fourteen."],["p","On a double shift, an operator clips a trailer door frame coming out with a roll. He says he blanked out. It\\u0027s reported as a near miss and he\\u0027s moved off the truck. The fix includes scheduling: no more doubles on equipment without a rest break."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What makes it hard to admit you\\u0027re too tired to drive here?"],["p","Listen for: Fear of losing hours, looking weak, letting the crew down. Supervisor response: reassignment, not discipline."],["h","7. KNOWLEDGE CHECK"],["pt","1. You\\u0027re catching yourself zoning out on the truck. What do you do?"],["p","Answer: Stop, park safely and tell your supervisor so you can be reassigned. Reporting fatigue is never punished."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: If you feel your attention drifting today, stop and tell me before you take the next load."],["h","9. SUPERVISOR VERIFICATION"],["li","Review overtime and double-shift assignments for equipment operators this week."],["li","Check in with each operator in the last two hours of the shift."],["li","Document any fatigue-related reassignment or near miss."],["p","References: Safety Incident / Near Miss Report PWH-FRM-204-1 • MHE Forklift Operation SOP PWH-SOP-229-1 • CDC/NIOSH work schedules and fatigue guidance • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W30","week":30,"doc":"PWH-MTR-2027-W30","date":"2027-07-26","holiday":false,"month":7,"title":"First Response: Report Every Injury, Find the Kit, Call for Help","behavior":"Before you start, walk to the nearest first-aid kit and AED from your work area so you know exactly where they are.","track":"","file":"Part 4 - Weekly May-Aug/W30 Jul 26 - First Response Report Every Injury, Find the Kit, Call for Help.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nFirst Response: Report Every Injury, Find the Kit, Call for Help"]],["tr",["Doc No: PWH-MTR-2027-W30\\nWeek: 30 · Mon Jul 26, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 30 of 52 · July 2027"]],["tr",["Monday training title","First Response: Report Every Injury, Find the Kit, Call for Help"]],["tr",["Monthly theme","Heat Stress, Fatigue \\u0026 First Response"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA first aid (29 CFR 1910.151) — awareness"]],["tr",["Training objective","Every employee knows where first-aid kits, the AED and eyewash are, how to call for help, and that every injury is reported the same shift."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: In an emergency, the minutes before help arrives matter most. Do you know, right now, where the nearest first-aid kit and AED are?"],["h","3. KEY TEACHING POINTS"],["pt","1. Report every injury the same shift."],["p","Even small cuts and strains. Late reports make treatment and investigation harder."],["pt","2. Know the locations."],["p","First-aid kits [SITE], AED [SITE], eyewash/shower at the battery area [SITE], the 911 address [SITE]."],["pt","3. Serious injury: 911 first, then the supervisor."],["p","Don\\u0027t move someone with a suspected back, neck or crush injury unless they\\u0027re in immediate danger."],["pt","4. Eyes: flush 15 minutes."],["p","Chemical or battery acid in the eyes — eyewash immediately, holding eyelids open."],["pt","5. Refusing treatment is documented."],["p","Supervisors use PWH-FRM-229-1 when an employee declines treatment, and keep checking on them."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Every injury gets reported to me before you leave, even if you think it\\u0027s nothing. Small cuts get infected. A tweaked back on Monday can be a serious injury by Friday. Reporting is how you get care and how we fix the cause."],["p","For anything serious: call 911 first, then me. Give the address and dock door. Send someone to the front to meet the ambulance. If someone is pinned or has a back or neck injury, don\\u0027t move them unless they\\u0027re in danger where they are."],["p","If acid or a chemical gets in your eyes, get to the eyewash and flush for a full 15 minutes, holding your eyelids open, then get medical attention."],["call","SHOW IT: Walk the crew to the nearest first-aid kit and AED. Open the kit and check that it\\u0027s stocked."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The cut that got worse."],["p","An associate slices a finger on a band, wraps it in tape and keeps working without reporting. Three days later it\\u0027s infected and requires a clinic visit. Reported on day one, it would have been cleaned and bandaged properly, and the safety-knife issue fixed."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where is the closest AED to where you work, and who here knows CPR?"],["p","Listen for: Know the location and identify trained responders by name [SITE]."],["h","7. KNOWLEDGE CHECK"],["pt","1. You cut your hand on a band and it\\u0027s minor. Do you need to report it?"],["p","Answer: Yes. Report every injury to your supervisor the same shift, however minor."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before you start, walk to the nearest first-aid kit and AED from your work area so you know exactly where they are."],["h","9. SUPERVISOR VERIFICATION"],["li","Inspect first-aid kits for stock and expiration dates."],["li","Check the AED status indicator and eyewash flow."],["li","Confirm any injuries this month were reported and documented the same shift."],["p","References: OSHA 29 CFR 1910.151 • OSHA 29 CFR 1904 (injury recordkeeping) • Employee Refusal of Medical Treatment PWH-FRM-229-1 • [SITE: emergency action plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W31","week":31,"doc":"PWH-MTR-2027-W31","date":"2027-08-02","holiday":false,"month":8,"title":"Lifting Mechanics: Power Zone, Pivot, Don\\u0027t Twist","behavior":"On every manual lift today, get close, bend your knees and pivot your feet instead of twisting.","track":"","file":"Part 4 - Weekly May-Aug/W31 Aug 2 - Lifting Mechanics Power Zone, Pivot, Don\\u0027t Twist.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nLifting Mechanics: Power Zone, Pivot, Don\\u0027t Twist"]],["tr",["Doc No: PWH-MTR-2027-W31\\nWeek: 31 · Mon Aug 2, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 31 of 52 · August 2027"]],["tr",["Monday training title","Lifting Mechanics: Power Zone, Pivot, Don\\u0027t Twist"]],["tr",["Monthly theme","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness — ergonomics"]],["tr",["Training objective","Employees lift manual loads in the power zone with good mechanics and use help or tools for heavy and awkward items."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Backs get hurt on the twist, not the lift. This week: power zone, pivot your feet, ask for help."],["h","3. KEY TEACHING POINTS"],["pt","1. Plan the lift."],["p","Test the weight, check your path, decide whether you need help or a tool."],["pt","2. Get close and get low."],["p","Feet shoulder-width, bend at the knees and hips, back straight, tight grip."],["pt","3. Power zone."],["p","Keep the load between mid-thigh and mid-chest, close to your body."],["pt","4. Pivot, don\\u0027t twist."],["p","Turn your feet to change direction."],["pt","5. Heavy, awkward or overhead = help or a tool."],["p","Pallet jack, second person, lift."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","We lift by hand more than we think: pallet boards, roll mats, slip sheets, damaged cases, dunnage, trash. Most back injuries come from bending at the waist and twisting with the load away from the body."],["p","Get the load close. Bend your knees. Keep it between your thighs and chest. When you need to turn, move your feet. If it\\u0027s heavy, awkward, or you\\u0027d have to reach above your shoulders, get help or a tool."],["call","SHOW IT: Lift a box wrong (bend at the waist, twist) and right (close, knees bent, pivot). Have two employees try it."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The roll mat stack."],["p","An associate pulls a stack of heavy rubber roll mats off a pallet by bending at the waist and twisting to throw them on the dock. He strains his lower back. Moving the pallet closer to the dock and lifting the mats in the power zone would have taken the twist out."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What do we lift by hand most often here that hurts people?"],["p","Listen for: Mats, dunnage, pallet boards, damaged cases. Ask what tool or layout change would help."],["h","7. KNOWLEDGE CHECK"],["pt","1. You need to move a box to a pallet beside you. Do you twist at the waist?"],["p","Answer: No. Keep the box close and pivot your feet to turn."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: On every manual lift today, get close, bend your knees and pivot your feet instead of twisting."],["h","9. SUPERVISOR VERIFICATION"],["li","Observe five manual lifts and coach technique."],["li","Identify one heavy manual task that could use a tool or second person."],["li","Ask employees about any back or shoulder discomfort."],["p","References: NIOSH lifting guidance • OSHA Ergonomics guidance for warehousing • OSH Act Section 5(a)(1) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W32","week":32,"doc":"PWH-MTR-2027-W32","date":"2027-08-09","holiday":false,"month":8,"title":"Never Stop a Moving Roll: Manual Roll Handling and Roll Bars","behavior":"If you see any roll that looks like it could move — off a mat, on debris, out-of-round — stop and report it before anyone works near it.","track":"Clamp","file":"Part 4 - Weekly May-Aug/W32 Aug 9 - Never Stop a Moving Roll Manual Roll Handling and Roll Bars.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nNever Stop a Moving Roll: Manual Roll Handling and Roll Bars"]],["tr",["Doc No: PWH-MTR-2027-W32\\nWeek: 32 · Mon Aug 9, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 32 of 52 · August 2027"]],["tr",["Monday training title","Never Stop a Moving Roll: Manual Roll Handling and Roll Bars"]],["tr",["Monthly theme","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company rule (PWH-SOP-171) — awareness"]],["tr",["Training objective","No employee ever tries to stop, steer or catch a moving or falling roll, and manual roll adjustments use only approved tools and methods."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A paper roll that starts to roll weighs as much as a car and won\\u0027t stop for a hand or a boot. This week\\u0027s rule is short: get out of its way."],["h","3. KEY TEACHING POINTS"],["pt","1. A moving roll wins."],["p","Never stop, steer, catch or chock a moving roll with your hands, feet or body. Shout a warning and get clear."],["pt","2. Never try to save a falling roll."],["p","Let it fall. Product can be replaced; you can\\u0027t."],["pt","3. Move rolls with the clamp truck."],["p","Never push or roll product with the clamp arms or by hand (PWH-SOP-171)."],["pt","4. Roll bars and pushers only as trained."],["p","If your site uses a roll bar for small adjustments, use it only as trained, from the side, never in the roll\\u0027s path [SITE]."],["pt","5. Report every rolling or falling roll."],["p","As a near miss, with the cause."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","If a roll starts rolling, your instinct is to stop it. Fight that instinct. Put your boot against a moving roll and it rolls over your foot. Put your hands on it and it pins you against a column. Yell \\"Roll!\\" and get out of the way, sideways, not in front of it."],["p","Rolls should never move under their own power in our building. If one does, it was set down off-center, on debris, on a crack, or off its mat. Report it so we find out why."],["p","And we never use clamp arms or our bodies to push or roll rolls into place. Pick it up and set it down."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The boot against the roll."],["p","A roll set at the end of a column starts to roll toward the aisle. An associate puts his boot against it. It rolls over his foot, and only his safety-toe shoe prevents a crush injury. The right response: shout, step aside, let it stop."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Why do rolls sometimes move on their own here?"],["p","Listen for: Debris under the roll, uneven floor, cracks, off-center placement, out-of-round rolls. Tie back to floor sweeping and stacking standards."],["h","7. KNOWLEDGE CHECK"],["pt","1. A roll starts rolling toward a co-worker. What do you do?"],["p","Answer: Shout a warning and get clear. Never try to stop it with your hands or feet."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: If you see any roll that looks like it could move — off a mat, on debris, out-of-round — stop and report it before anyone works near it."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk roll aisles for rolls off mats, on debris or unstable."],["li","Observe whether anyone pushes rolls by hand or with clamp arms."],["li","Review any rolling-roll near misses for root cause."],["p","References: PWH-SOP-171 (Sec. 5.2: never push or roll product with the clamp arms; Sec. 6.2 cleanliness) • Safety Incident / Near Miss Report PWH-FRM-204-1 • [SITE: roll bar procedure if used] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W33","week":33,"doc":"PWH-MTR-2027-W33","date":"2027-08-16","holiday":false,"month":8,"title":"Pinch Points, Banding and Safety Knives","behavior":"Swap any razor blade you carry for a safety knife before you start, and keep your hands out of pinch points all shift.","track":"","file":"Part 4 - Weekly May-Aug/W33 Aug 16 - Pinch Points, Banding and Safety Knives.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPinch Points, Banding and Safety Knives"]],["tr",["Doc No: PWH-MTR-2027-W33\\nWeek: 33 · Mon Aug 16, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 33 of 52 · August 2027"]],["tr",["Monday training title","Pinch Points, Banding and Safety Knives"]],["tr",["Monthly theme","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness — hand injury prevention"]],["tr",["Training objective","Employees keep hands out of pinch points, cut bands and wrap only with safety knives, and control band ends."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: If you can\\u0027t see your hands, they\\u0027re in the wrong place. This week is about the places hands get crushed and cut in our building."],["h","3. KEY TEACHING POINTS"],["pt","1. Pinch points everywhere loads move."],["p","Between a roll and a column, pallets and racks, dock plate lip and trailer bed, fork carriage and mast, clamp arms and anything."],["pt","2. Ask before you reach:"],["p","\\u0027If this moves, where does my hand go?\\u0027"],["pt","3. Safety knives only."],["p","Self-retracting blade; razor blades and box cutters are not allowed for bands or wrap."],["pt","4. Cut away from your body."],["p","Other hand out of the cutting path."],["pt","5. Bands under tension whip."],["p","Stand to the side, hold the free end, and cut with the knife or band cutter."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Most hand injuries here happen in two places: between things that move, and at the end of a knife. Before you put your hand between a roll and a column or under a pallet, ask where your hand goes if the load shifts."],["p","For cutting, it\\u0027s safety knives only. A razor blade doesn\\u0027t retract, and the cut usually happens on the follow-through when the band gives way. Cut away from your body, keep your other hand clear, and wear cut-resistant gloves."],["p","Steel or poly banding is under tension. When it\\u0027s cut it snaps back. Stand to the side and control the end."],["call","SHOW IT: Show a safety knife next to a razor blade, and how to cut a band while holding the free end and standing to the side."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The dock plate lip."],["p","An associate reaches under the lip of a dock leveler to pull out a piece of wrap while the lip is still raised. The lip drops onto his fingers. Never put hands under a leveler lip or between moving surfaces — tag it and call for help."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where\\u0027s the worst pinch point in your area?"],["p","Listen for: Roll columns, dock levelers, pallet stacks, clamp arms. Note any that need guarding or a procedure change."],["h","7. KNOWLEDGE CHECK"],["pt","1. What tool do you use to cut stretch wrap and bands?"],["p","Answer: A safety knife with a self-retracting blade (or a band cutter), cutting away from your body, with cut-resistant gloves."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Swap any razor blade you carry for a safety knife before you start, and keep your hands out of pinch points all shift."],["h","9. SUPERVISOR VERIFICATION"],["li","Collect razor blades and issue safety knives."],["li","Watch one band-cutting task for stance and hand placement."],["li","List pinch points identified today and assign follow-up."],["p","References: OSHA 29 CFR 1910.138 (Hand protection) • OSHA 29 CFR 1910.212 (Machine guarding) • [SITE: knife policy] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W34","week":34,"doc":"PWH-MTR-2027-W34","date":"2027-08-23","holiday":false,"month":8,"title":"Gloves and Hand Protection: Right Glove, Right Task","behavior":"Check that you have the right gloves for every task on your list today, and replace any damaged pair before you start.","track":"","file":"Part 4 - Weekly May-Aug/W34 Aug 23 - Gloves and Hand Protection Right Glove, Right Task.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nGloves and Hand Protection: Right Glove, Right Task"]],["tr",["Doc No: PWH-MTR-2027-W34\\nWeek: 34 · Mon Aug 23, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 34 of 52 · August 2027"]],["tr",["Monday training title","Gloves and Hand Protection: Right Glove, Right Task"]],["tr",["Monthly theme","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA PPE (29 CFR 1910.138) — refresher"]],["tr",["Training objective","Employees wear the correct glove for each task and replace damaged gloves."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A work glove is not a cut glove, and a cut glove is not a chemical glove. The right glove depends on the job."],["h","3. KEY TEACHING POINTS"],["pt","1. Cutting bands and wrap:"],["p","Cut-resistant gloves [SITE: ANSI cut level]."],["pt","2. Propane cylinder changes:"],["p","Insulated or leather gloves — never cotton or knit."],["pt","3. Battery service and chemicals:"],["p","Chemical-resistant gloves, with face shield and apron for batteries."],["pt","4. General handling:"],["p","Work gloves for splinters and abrasion from pallets and mats."],["pt","5. Damaged gloves are replaced."],["p","Holes, cuts, soaked or contaminated gloves get swapped before you continue."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Each glove protects against one kind of hazard. A cotton glove won\\u0027t stop a blade and it\\u0027ll soak up liquid propane against your skin. A cut glove won\\u0027t stop battery acid. Match the glove to the task."],["p","If your gloves are torn, soaked or contaminated with chemicals or product, change them. Gloves that touched a spill or trash shouldn\\u0027t touch clean food-grade packaging."],["p","Replacements are at [SITE]. If the right glove isn\\u0027t available, stop and ask — don\\u0027t substitute."],["call","SHOW IT: Lay out each glove type and ask the crew to match each to a task."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The wrong glove for the battery."],["p","An associate tops off a battery wearing regular work gloves. Electrolyte splashes and soaks through to his hand, causing a chemical burn. Chemical gloves, face shield and apron were required."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which glove do we run out of most, and what do people use instead?"],["p","Listen for: Usually cut gloves. Fix supply levels."],["h","7. KNOWLEDGE CHECK"],["pt","1. Can you wear cotton gloves to change a propane cylinder?"],["p","Answer: No. Use insulated or leather gloves; cotton soaks up liquid propane and holds it against your skin."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check that you have the right gloves for every task on your list today, and replace any damaged pair before you start."],["h","9. SUPERVISOR VERIFICATION"],["li","Check glove stock levels for each type."],["li","Observe one task of each type for correct glove use."],["li","Replace damaged gloves found on the floor."],["p","References: OSHA 29 CFR 1910.138 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 6c) • [SITE: PPE hazard assessment] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W35","week":35,"doc":"PWH-MTR-2027-W35","date":"2027-08-30","holiday":false,"month":8,"title":"Machine Guarding and LOTO Awareness: Conveyors, Levelers, Wrappers, Balers","behavior":"Before using any powered equipment today, confirm its guards are in place. Report any missing guard immediately.","track":"","file":"Part 4 - Weekly May-Aug/W35 Aug 30 - Machine Guarding and LOTO Awareness Conveyors, Levelers, Wrappers, Bal.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nMachine Guarding and LOTO Awareness: Conveyors, Levelers, Wrappers, Balers"]],["tr",["Doc No: PWH-MTR-2027-W35\\nWeek: 35 · Mon Aug 30, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 35 of 52 · August 2027"]],["tr",["Monday training title","Machine Guarding and LOTO Awareness: Conveyors, Levelers, Wrappers, Balers"]],["tr",["Monthly theme","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA LOTO awareness (29 CFR 1910.147) \\u0026 machine guarding (1910.212) — affected/other employees"]],["tr",["Training objective","Employees never remove or bypass guards, never reach into equipment that isn\\u0027t locked out, and never touch a lock or tag."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Equipment doesn\\u0027t know the difference between a jammed piece of wrap and your hand. Guards and locks are the only things that do."],["h","3. KEY TEACHING POINTS"],["pt","1. Guards stay on."],["p","Conveyors, dock levelers, stretch wrappers, balers and chargers run only with guards in place. Missing guard = equipment tagged out."],["pt","2. Never reach into running or energized equipment."],["p","To clear a jam, the equipment is stopped and locked out by an authorized employee."],["pt","3. Never touch a lock or tag."],["p","Don\\u0027t remove it, don\\u0027t operate the switch or valve, don\\u0027t try to start the machine."],["pt","4. Only the person who applied a lock removes it."],["p","After the work is signed off (PWH-SOP-207)."],["pt","5. Affected vs. authorized."],["p","Most of us are affected or other employees: recognize lockout and stay clear. Only trained authorized employees perform lockout."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When maintenance or a contractor works on a leveler, conveyor, wrapper or baler, they shut it down and put a lock and tag on the energy source so nobody can start it. That lock has their name on it. It\\u0027s their life on that switch."],["p","If you see a lock or a tag, you never remove it, you never flip that switch, and you never try to start that equipment. Only the person who put the lock on takes it off, after the work is signed off."],["p","If equipment jams, don\\u0027t reach in. Stop it, tag it, and get an authorized person to lock it out and clear it. And if a guard is missing, the equipment doesn\\u0027t run."],["call","SHOW IT: Show a lock, tag and hasp from the LOTO station [SITE] and point out where lockout points are on the nearest dock leveler."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The wrapper jam."],["p","A stretch wrapper\\u0027s film carriage jams. An associate leans in to pull out the film while the machine is in standby. The carriage restarts and catches his sleeve. Stop, lock out and clear — never \\u0027just reach in quickly\\u0027."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What equipment here do people try to clear without locking out?"],["p","Listen for: Wrappers, conveyors, levelers, balers. Confirm who the authorized employees are."],["h","7. KNOWLEDGE CHECK"],["pt","1. You see a lock and tag on a leveler and the work looks done. Can you remove the lock?"],["p","Answer: No. Only the person who applied it removes it, after the work is signed off."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before using any powered equipment today, confirm its guards are in place. Report any missing guard immediately."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk all powered equipment and check guards."],["li","Confirm the LOTO station is stocked and the Lockout Tagout Log is current."],["li","Confirm the list of authorized employees is posted [SITE]."],["p","References: Lockout/Tagout Procedure PWH-SOP-207 (OP-005) • OSHA 29 CFR 1910.147 • OSHA 29 CFR 1910.212 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W36","week":36,"doc":"PWH-MTR-2027-W36","date":"2027-09-06","holiday":true,"month":9,"title":"Traveling With Rolls: Load Low, Speed, Visibility","behavior":"Every trip today: roll 4–6 inches up, reverse, no lifting while moving, no sharp turns.","track":"Clamp","file":"Part 5 - Weekly Sep-Dec/W36 Sep 6 - Traveling With Rolls Load Low, Speed, Visibility.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nTraveling With Rolls: Load Low, Speed, Visibility"]],["tr",["Doc No: PWH-MTR-2027-W36\\nWeek: 36 · Mon Sep 6, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 36 of 52 · September 2027 · Labor Day — deliver at the first shift start this week if the site is closed"]],["tr",["Monday training title","Traveling With Rolls: Load Low, Speed, Visibility"]],["tr",["Monthly theme","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every roll is carried 4–6 inches off the floor, in reverse, at controlled speed, with no lifting, lowering or stacking while moving."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: The trip between the stack and the trailer is where rolls slip, shift and fall. This week: low, slow, reverse — every trip."],["h","3. KEY TEACHING POINTS"],["pt","1. Carry 4–6 inches off the ground."],["p","Low keeps the center of gravity inside the stability triangle."],["pt","2. Always reverse with a roll."],["p","A roll blocks the forward view (PWH-SOP-171)."],["pt","3. No lifting, lowering or stacking while moving."],["p","Stop first, then raise or lower."],["pt","4. No sharp turns, no speeding."],["p","Sharp turns shift rolls or tip trucks; stay under the posted limit."],["pt","5. One package at a time."],["p","Rolls packaged two or more per pack: one package per trip. Carry multiple rolls only as allowed for that size and equipment [SITE]."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Everything we learned in February applies with more weight here. A roll held high moves the center of gravity up and forward. Turn sharp with it up and the truck can tip or the roll can shift in the arms. Keep it low."],["p","Always reverse with a roll. Turn your body and look where you\\u0027re going. Sound the horn at intersections and doorways."],["p","Raise and lower only when you\\u0027ve stopped. And if rolls are packaged two or more to a pack, take one package at a time — two packs at once is how bottom rolls end up on the floor."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The quick turn with a roll up."],["p","An operator lifts a roll to stacking height while still rolling toward the column and turns into the aisle. The roll shifts in the arms and he stops hard. It stays in the clamp, barely. He reports the near miss. Stop, then lift; turn with the roll low."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do you feel pressure to rush trips with rolls?"],["p","Listen for: Long hauls to trailers, end of shift, carrier appointments. Remind them speed doesn\\u0027t save time if a roll goes down."],["h","7. KNOWLEDGE CHECK"],["pt","1. When can you raise a roll to stacking height?"],["p","Answer: Only when the truck is completely stopped at the stack."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Every trip today: roll 4–6 inches up, reverse, no lifting while moving, no sharp turns."],["h","9. SUPERVISOR VERIFICATION"],["li","Watch ten roll trips: height, direction, speed, lift only when stopped."],["li","Record on PWH-FRM-MHE-01 (Section 6)."],["li","Coach any violation on the spot."],["p","References: PWH-SOP-171 (Sec. 5.2) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8–9) • PWH-FRM-213-1 (items 12–13, 22) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W37","week":37,"doc":"PWH-MTR-2027-W37","date":"2027-09-13","holiday":false,"month":9,"title":"Trailer Loading for Rolls: Pattern, Weight Distribution, Securement","behavior":"On every roll trailer today, follow the load plan, mat every roll and strap the rear cluster before calling the lead to verify.","track":"Clamp","file":"Part 5 - Weekly Sep-Dec/W37 Sep 13 - Trailer Loading for Rolls Pattern, Weight Distribution, Securement.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nTrailer Loading for Rolls: Pattern, Weight Distribution, Securement"]],["tr",["Doc No: PWH-MTR-2027-W37\\nWeek: 37 · Mon Sep 13, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 37 of 52 · September 2027"]],["tr",["Monday training title","Trailer Loading for Rolls: Pattern, Weight Distribution, Securement"]],["tr",["Monthly theme","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every roll trailer is loaded to the load-plan pattern with weight split over the tandems, a mat under every roll and straps on split loads and the rear cluster."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A roll load is only as good as how it rides down the highway. If it shifts, someone at the other end opens the doors on it."],["h","3. KEY TEACHING POINTS"],["pt","1. Get the right documents and verify."],["p","Loading documents from the CSR; order, trailer number and door match."],["pt","2. Prep the trailer."],["p","Tandems slid back; trailer stand on drop trailers; trailer walked, swept and inspected."],["pt","3. Follow the load-plan binder by roll diameter."],["p","Split the weight over the front and rear tandems."],["pt","4. Mat every roll."],["p","A rubber mat under every roll to prevent shifting."],["pt","5. Strap split loads and the rear cluster."],["p","Unitize the load so nothing moves in transit."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","The load plan isn\\u0027t a suggestion. It\\u0027s built so the weight sits over the axles where the trailer was designed to carry it, and so rolls lock against each other. An unbalanced load overloads an axle, can get the driver fined at the scale, and can make the trailer harder to control."],["p","Mats grip the trailer floor and the roll. Without them, rolls slide on hard stops. Straps unitize the rear cluster and any split load so the last rolls in can\\u0027t walk toward the doors."],["p","Then the accountability steps: count matches the pack list, every roll checked off, physical count inside the trailer, supervisor or lead verification, seal applied and recorded, staging lane clear."],["call","SHOW IT: Open the load-plan binder to the plan for today\\u0027s most common diameter and point out where the mats and straps go."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The rear cluster."],["p","A trailer is loaded to plan but the rear cluster isn\\u0027t strapped. At the customer, two rolls have rolled against the doors. The receiver opens them carefully, and nobody is hurt. Straps on the rear cluster prevent exactly this."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which load plans or roll sizes give us the most trouble?"],["p","Listen for: Mixed diameters, partial loads, odd counts. Flag plans that need updating."],["h","7. KNOWLEDGE CHECK"],["pt","1. What goes under every roll on a trailer, and what holds the rear cluster?"],["p","Answer: A rubber mat under every roll; straps on the rear cluster and any split load."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: On every roll trailer today, follow the load plan, mat every roll and strap the rear cluster before calling the lead to verify."],["h","9. SUPERVISOR VERIFICATION"],["li","Verify at least two roll trailers before sealing: pattern, mats, straps."],["li","Check \\u0027Tandems Slid Back?\\u0027 and \\u0027Mats Applied?\\u0027 on load sheets."],["li","Confirm the load-plan binder covers every diameter loaded today."],["p","References: PWH-SOP-171 (Sec. 7.1) • Rules of Safe Operation SOP (Part D.2) • Operator Accountability Policy and Controlled Load/Unload Sheet • [SITE: load-plan binder] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W38","week":38,"doc":"PWH-MTR-2027-W38","date":"2027-09-20","holiday":false,"month":9,"title":"Railcar Roll Unloading: Car Condition, Plates and Roll Stability","behavior":"Before entering any railcar today, look at the entire load from the plate and confirm every roll is stable.","track":"Clamp","file":"Part 5 - Weekly Sep-Dec/W38 Sep 20 - Railcar Roll Unloading Car Condition, Plates and Roll Stability.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nRailcar Roll Unloading: Car Condition, Plates and Roll Stability"]],["tr",["Doc No: PWH-MTR-2027-W38\\nWeek: 38 · Mon Sep 20, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 38 of 52 · September 2027"]],["tr",["Monday training title","Railcar Roll Unloading: Car Condition, Plates and Roll Stability"]],["tr",["Monthly theme","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Every railcar is protected, verified and inspected before entry, rolls are checked for shift before handling, and damage is documented at unload."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Rolls ride a long way in a railcar and they don\\u0027t always arrive the way they were loaded. This week: protect the car, read the load, then go in."],["h","3. KEY TEACHING POINTS"],["pt","1. Protection first."],["p","Blue flag and derail in place, hand brake set, wheels blocked, bridge plate rated and secured."],["pt","2. Verify seal and car number."],["p","Against the paperwork before opening."],["pt","3. Read the load before you enter."],["p","Shifted, leaning or crushed rolls, broken blocking or dunnage."],["pt","4. Doors by hand or approved tool — never the clamp."],["p","Fully open and secured before entry."],["pt","5. Inspect and report damage at unload."],["p","So it\\u0027s documented against the railroad or shipper."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When the doors come open, stand to the side, not in front. Rolls that shifted in transit can be leaning against the door."],["p","Look at the whole load before you drive in. Are rolls still upright and tight? Is the blocking intact? Any roll that\\u0027s leaning, crushed or wedged gets assessed by the lead before anyone touches it."],["p","After each roll comes out, look at the core and both ends. Damage found here goes on the paperwork immediately with photos [SITE] so the claim goes to the right party."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The leaning roll at the door."],["p","An operator opens a boxcar door and a roll that shifted in transit is resting against it. Because he\\u0027s standing to the side, the door swings and the roll settles without hitting him. He calls the lead before entering."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What railcar conditions have you seen that should stop an unload?"],["p","Listen for: Broken blocking, leaning rolls, damaged floors, missing seals, doors off track."],["h","7. KNOWLEDGE CHECK"],["pt","1. Where do you stand when opening a railcar door?"],["p","Answer: To the side of the door, never directly in front of it, in case rolls shifted against it."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before entering any railcar today, look at the entire load from the plate and confirm every roll is stable."],["h","9. SUPERVISOR VERIFICATION"],["li","Observe one railcar from protection to final roll."],["li","Confirm seal and car numbers recorded on rail paperwork."],["li","Review damage documentation from today\\u0027s rail unloads."],["p","References: MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 10b) • PWH-SOP-171 (Sec. 7.2) • Controlled Trailer/Rail Inspection and Load/Unload Sheet • [SITE: rail procedure] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W39","week":39,"doc":"PWH-MTR-2027-W39","date":"2027-09-27","holiday":false,"month":9,"title":"The Top Clamp Operator Mistakes and When to Stop","behavior":"If anything about a roll doesn\\u0027t feel right today, stop and call me before you continue.","track":"Clamp","file":"Part 5 - Weekly Sep-Dec/W39 Sep 27 - The Top Clamp Operator Mistakes and When to Stop.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nThe Top Clamp Operator Mistakes and When to Stop"]],["tr",["Doc No: PWH-MTR-2027-W39\\nWeek: 39 · Mon Sep 27, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 39 of 52 · September 2027"]],["tr",["Monday training title","The Top Clamp Operator Mistakes and When to Stop"]],["tr",["Monthly theme","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company procedure PWH-SOP-171 under OSHA PIT program — refresher"]],["tr",["Training objective","Operators can name the most common clamp mistakes and stop work on any unstable or damaged roll."]],["call","NOT A CERTIFICATION. Awareness only. Operating any lift still requires completed training, a passed hands-on evaluation (PWH-FRM-213-1) and supervisor authorization."],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Almost every roll incident we\\u0027ve seen traces back to a short list of mistakes. Know the list, and know when to stop."],["h","3. KEY TEACHING POINTS"],["pt","1. Pressure not reset at a grade change."],["p","Check the chart every time."],["pt","2. Angled pickups and arms not centered."],["p","Square up; center; clamp near the bottom."],["pt","3. Two packs at once; lifting or stacking while moving; forward travel with a roll."],["p","One package, stop to lift, always reverse."],["pt","4. Pushing or rolling product with the arms."],["p","Never."],["pt","5. Skipping mats, straps or the trailer walk."],["p","Every roll, every load."],["pt","6. Unstable, leaning or damaged roll = stop."],["p","Set it down if safe, keep people back, call the lead."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","None of these mistakes are new. They happen when we\\u0027re rushed, distracted or covering an unfamiliar job. That\\u0027s why the list matters: when you feel rushed, run the list in your head."],["p","And the most important part: when a roll doesn\\u0027t look or feel right — leaning, slipping, crushed, wedged — you stop. You don\\u0027t try to save it. You set it down if you safely can, keep people out of the area and call the lead. That\\u0027s stop-work authority applied to the job you do every day."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The roll that \\u0027felt light\\u0027."],["p","An operator picks a roll that feels like it\\u0027s slipping in the arms but keeps going because the trailer is almost done. It slips on the dock plate and drops. Nobody is under it. If he\\u0027d stopped and reset, it would have been a 30-second delay."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which of these mistakes is most tempting when you\\u0027re behind?"],["p","Listen for: Usually pressure resets, mats/straps, forward travel. Agree that the carrier waits, not the SOP."],["h","7. KNOWLEDGE CHECK"],["pt","1. A roll starts slipping in the clamp. What do you do?"],["p","Answer: Stop, set it down if you safely can, keep people back, and call the lead. Don\\u0027t try to save it."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: If anything about a roll doesn\\u0027t feel right today, stop and call me before you continue."],["h","9. SUPERVISOR VERIFICATION"],["li","Ask each clamp operator to name three common mistakes."],["li","Complete a PWH-FRM-MHE-01 observation on every clamp operator this week."],["li","Review the month\\u0027s roll damage and near misses against this list."],["p","References: PWH-SOP-171 • PWH-FRM-213-1 • PWH-FRM-MHE-01 • Safety Incident / Near Miss Report PWH-FRM-204-1 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W40","week":40,"doc":"PWH-MTR-2027-W40","date":"2027-10-04","holiday":false,"month":10,"title":"Paper Warehouse Fire Risk: Ignition Sources and Hot Work","behavior":"Clear any wrap, paper or trash from around chargers, heaters and lights in your area today.","track":"","file":"Part 5 - Weekly Sep-Dec/W40 Oct 4 - Paper Warehouse Fire Risk Ignition Sources and Hot Work.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPaper Warehouse Fire Risk: Ignition Sources and Hot Work"]],["tr",["Doc No: PWH-MTR-2027-W40\\nWeek: 40 · Mon Oct 4, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 40 of 52 · October 2027"]],["tr",["Monday training title","Paper Warehouse Fire Risk: Ignition Sources and Hot Work"]],["tr",["Monthly theme","Fire Prevention, Emergency Response \\u0026 Electrical Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA Fire Prevention Plan (29 CFR 1910.39) — awareness"]],["tr",["Training objective","Employees control ignition sources around paper, LP and chargers, and recognize when hot work requires a permit and fire watch."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Paper and pulp are fuel. Our job is to keep heat and sparks away from them. This is Fire Prevention Week — let\\u0027s start with how fires start here."],["h","3. KEY TEACHING POINTS"],["pt","1. Smoking only in designated areas."],["p","Never in the warehouse, on the dock or near trash or wrap."],["pt","2. No flames or sparks within 25 feet of LP storage or charging."],["p","Includes heaters and grinders."],["pt","3. Hot work needs a permit and fire watch."],["p","Welding, cutting, grinding by maintenance or contractors — permit, combustibles moved or covered, fire watch [SITE: duration]."],["pt","4. Electrical heat sources."],["p","Damaged cords, overloaded outlets, chargers with damaged cables — out of service and reported."],["pt","5. Housekeeping is fire prevention."],["p","Wrap, dust and trash off the floor, especially near chargers, heaters and lights."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Fires in warehouses usually start small and ordinary: a cigarette tossed in a trash can, sparks from a grinder landing in shrink wrap, a heater pushed too close to pallets, a frayed charger cable. In a paper building, small doesn\\u0027t stay small for long."],["p","If you see a contractor welding, cutting or grinding, there should be a hot-work permit posted and someone on fire watch. If there isn\\u0027t, stop the work and get a supervisor."],["p","And keep your area clean. Shrink wrap and paper dust near a heater or charger is exactly how fires start."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The grinder sparks."],["p","A contractor grinds a dock leveler hinge without a permit. Sparks land in a pile of wrap behind the door. An associate notices smoke and pulls the wrap away. The fix: hot-work permits, combustibles cleared and a fire watch every time."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the most likely ignition source in your area?"],["p","Listen for: Chargers, heaters, LP, cords, contractors. Assign a fix for anything found."],["h","7. KNOWLEDGE CHECK"],["pt","1. A contractor is grinding near roll storage with no permit or fire watch. What do you do?"],["p","Answer: Stop the work and get a supervisor. Hot work requires a permit, cleared combustibles and a fire watch."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Clear any wrap, paper or trash from around chargers, heaters and lights in your area today."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk charger, LP and heater areas for combustibles and ignition risks."],["li","Confirm any hot work this week has a permit."],["li","Check designated smoking area is used and away from the building [SITE]."],["p","References: OSHA 29 CFR 1910.39 • OSHA 29 CFR 1910.252 (hot work) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 11) • NFPA 51B • [SITE: Fire Prevention Plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W41","week":41,"doc":"PWH-MTR-2027-W41","date":"2027-10-11","holiday":false,"month":10,"title":"Evacuation Routes, Assembly Points and Headcount","behavior":"Walk your primary and backup evacuation routes from your work area before lunch today.","track":"","file":"Part 5 - Weekly Sep-Dec/W41 Oct 11 - Evacuation Routes, Assembly Points and Headcount.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nEvacuation Routes, Assembly Points and Headcount"]],["tr",["Doc No: PWH-MTR-2027-W41\\nWeek: 41 · Mon Oct 11, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 41 of 52 · October 2027"]],["tr",["Monday training title","Evacuation Routes, Assembly Points and Headcount"]],["tr",["Monthly theme","Fire Prevention, Emergency Response \\u0026 Electrical Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA Emergency Action Plan (29 CFR 1910.38) — review"]],["tr",["Training objective","Every employee can walk their evacuation route, name their assembly point and knows how headcount works."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: In a real fire, you won\\u0027t have time to figure out where to go. This week every one of us walks our route."],["h","3. KEY TEACHING POINTS"],["pt","1. Know two ways out."],["p","Your nearest exit and a backup from where you usually work."],["pt","2. On the alarm: stop, park, leave."],["p","Lower loads, park out of aisles and doorways, shut off if it takes seconds. Don\\u0027t go back for anything."],["pt","3. Go to the assembly point."],["p","[SITE: location]. Stay there until released."],["pt","4. Headcount."],["p","Supervisors count from the shift roster and visitor log [SITE]; report missing people to the incident lead, never go back in to search."],["pt","5. Visitors and drivers come with you."],["p","Escort them out and include them in the count."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Walk with me to your nearest exit from here. Now point to the backup exit. If one is blocked by fire or smoke, you need the other."],["p","When the alarm sounds, don\\u0027t finish the load. Lower it, park out of the way and go. Once you\\u0027re out, go straight to [SITE] and find your supervisor. If you\\u0027re not there, someone may go looking for you — and that\\u0027s how rescuers get hurt."],["p","If someone is missing, tell the incident lead and the fire department. Nobody goes back in."],["call","SHOW IT: Walk the crew from the huddle point to the nearest exit and on to the assembly point. Time it."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The 2026 mock drill."],["p","[SITE: one real lesson from the October 20, 2026 mock fire drill crisis record, e.g., headcount took X minutes because the visitor log wasn\\u0027t brought out.]"],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where would you go if the nearest exit to your work area were blocked?"],["p","Listen for: Each person names a backup route."],["h","7. KNOWLEDGE CHECK"],["pt","1. You\\u0027re unloading a trailer when the alarm sounds. What do you do?"],["p","Answer: Lower the load, park out of the way, shut off if quick, leave the trailer and building by the nearest safe exit, and go to the assembly point."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Walk your primary and backup evacuation routes from your work area before lunch today."],["h","9. SUPERVISOR VERIFICATION"],["li","Confirm evacuation maps are posted and accurate in every area."],["li","Confirm exit doors open freely and paths are clear."],["li","Confirm the roster and visitor log can be grabbed quickly in an emergency."],["p","References: OSHA 29 CFR 1910.38 • OSHA 29 CFR 1910.36–.37 (Exit routes) • Crisis Management Plan SOP 2.6.4 • Guest Policy 12.3.4 • [SITE: Emergency Action Plan] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W42","week":42,"doc":"PWH-MTR-2027-W42","date":"2027-10-18","holiday":false,"month":10,"title":"Fire Extinguishers: When to Use One and When to Leave","behavior":"Find the extinguisher nearest your work area today and make sure nothing is blocking it.","track":"","file":"Part 5 - Weekly Sep-Dec/W42 Oct 18 - Fire Extinguishers When to Use One and When to Leave.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nFire Extinguishers: When to Use One and When to Leave"]],["tr",["Doc No: PWH-MTR-2027-W42\\nWeek: 42 · Mon Oct 18, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 42 of 52 · October 2027"]],["tr",["Monday training title","Fire Extinguishers: When to Use One and When to Leave"]],["tr",["Monthly theme","Fire Prevention, Emergency Response \\u0026 Electrical Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA portable extinguishers (29 CFR 1910.157) — awareness (hands-on training separate if employees are designated to use extinguishers)"]],["tr",["Training objective","Employees know when an extinguisher is appropriate, how PASS works, and that evacuation comes first."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: An extinguisher can stop a trash-can fire. It cannot stop a burning roll stack. Knowing the difference is the whole lesson."],["h","3. KEY TEACHING POINTS"],["pt","1. Alarm first."],["p","Raise the alarm and make sure people are leaving before you fight anything."],["pt","2. Only small, early fires."],["p","Smaller than you, contained (trash can, small pile), not in a stack."],["pt","3. Only if trained and your exit is behind you."],["p","Never let fire get between you and the way out."],["pt","4. PASS."],["p","Pull the pin, Aim at the base, Squeeze the handle, Sweep side to side."],["pt","5. If in doubt, get out."],["p","Paper fires grow faster than people expect."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Most extinguishers here are [SITE: type, e.g., ABC dry chemical] and empty in roughly 10 to 20 seconds. That\\u0027s enough for a small fire, not a stack."],["p","If you decide to use one: alarm raised, exit behind you, stand back [SITE: 6–8 feet], pull the pin, aim at the base of the flames, squeeze and sweep. If it isn\\u0027t out quickly, drop it and leave."],["p","Never block extinguishers with trucks or product. Each has a monthly inspection tag. If one is missing, discharged or blocked, tell me."],["call","SHOW IT: Point to the nearest extinguisher, its gauge and inspection tag. Walk through PASS without discharging."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The trash can by the dock desk."],["p","Smoke comes from a trash can by the dock desk. An associate yells \\"fire\\", a lead pulls the alarm, and a trained employee puts it out with one short burst from an extinguisher, exit behind him. Small, early and contained — that\\u0027s when an extinguisher works."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where is the nearest extinguisher to your work area, and is it blocked?"],["p","Listen for: Each person names it. Clear any blocked ones."],["h","7. KNOWLEDGE CHECK"],["pt","1. A roll stack is burning at the top. Do you use an extinguisher?"],["p","Answer: No. Raise the alarm and evacuate. Extinguishers are only for small, early, contained fires."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Find the extinguisher nearest your work area today and make sure nothing is blocking it."],["h","9. SUPERVISOR VERIFICATION"],["li","Check every extinguisher in your area: present, gauge in green, tag current, unobstructed."],["li","Report missing or discharged extinguishers."],["li","Confirm who is designated and trained to use extinguishers [SITE]."],["p","References: OSHA 29 CFR 1910.157 • OSHA 29 CFR 1910.38 • NFPA 10 • [SITE: Emergency Action Plan / extinguisher policy] • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W43","week":43,"doc":"PWH-MTR-2027-W43","date":"2027-10-25","holiday":false,"month":10,"title":"Electrical Awareness: Cords, Panels and Chargers","behavior":"Check every cord you use today for damage, and make sure nothing is parked or stacked in front of a panel in your area.","track":"","file":"Part 5 - Weekly Sep-Dec/W43 Oct 25 - Electrical Awareness Cords, Panels and Chargers.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nElectrical Awareness: Cords, Panels and Chargers"]],["tr",["Doc No: PWH-MTR-2027-W43\\nWeek: 43 · Mon Oct 25, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 43 of 52 · October 2027"]],["tr",["Monday training title","Electrical Awareness: Cords, Panels and Chargers"]],["tr",["Monthly theme","Fire Prevention, Emergency Response \\u0026 Electrical Safety"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","OSHA electrical safety-related work practices (29 CFR 1910.331–.335) — awareness"]],["tr",["Training objective","Employees keep panels clear, take damaged cords and chargers out of service, and never perform electrical work they\\u0027re not qualified for."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Electricity gives almost no warning. A damaged cord or a blocked panel is a problem waiting for the worst possible moment."],["h","3. KEY TEACHING POINTS"],["pt","1. Panels clear."],["p","At least 3 feet clear in front of electrical panels at all times. No trucks, product or pallets."],["pt","2. Damaged cords out of service."],["p","Frayed, cut, crushed, taped or missing ground prong — tag and report."],["pt","3. No daisy chains."],["p","No power strips plugged into power strips or extension cords used as permanent wiring."],["pt","4. Chargers."],["p","Cables and connectors intact; charger off before connecting or disconnecting."],["pt","5. Report heat, sparks, buzzing or burning smells."],["p","Stop using the equipment and tell your supervisor. Only qualified people open panels or repair electrical equipment, after lockout."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Three feet in front of every panel is the rule because in an emergency someone has to get to the breaker fast. Look around: is anything parked or stacked in front of a panel right now?"],["p","Cords get run over by trucks, pinched in doors and stretched across walkways. A damaged cord can shock you or start a fire. Tag it and report it. Don\\u0027t tape it up."],["p","If a charger, outlet or panel feels hot, buzzes, sparks or smells like burning, stop using it and tell me. And never open a panel or try a repair yourself unless you\\u0027re qualified and it\\u0027s locked out."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The cord under the door."],["p","A cord for a dock fan runs across the threshold and gets pinched by the dock door every time it closes. After a week, the insulation splits and the fan trips the breaker. Caught before anyone was shocked; the cord is replaced and rerouted."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do we use extension cords or power strips that we shouldn\\u0027t?"],["p","Listen for: Dock desks, fans, chargers, break room. Fix or replace."],["h","7. KNOWLEDGE CHECK"],["pt","1. How much space must stay clear in front of an electrical panel?"],["p","Answer: At least 3 feet, at all times."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check every cord you use today for damage, and make sure nothing is parked or stacked in front of a panel in your area."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk all panels in your area: 3 feet clear, doors closed, labeled."],["li","Inspect charger cables and connectors."],["li","Remove daisy-chained power strips and damaged cords."],["p","References: OSHA 29 CFR 1910.303(g) • OSHA 29 CFR 1910.331–.335 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 11d) • Lockout/Tagout Procedure PWH-SOP-207 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W44","week":44,"doc":"PWH-MTR-2027-W44","date":"2027-11-01","holiday":false,"month":11,"title":"Food-Grade Storage: Off the Floor, Off the Wall, FIFO/FEFO","behavior":"Check every food-grade location you put product in today: off the floor, off the wall, right zone, scanned.","track":"Food","file":"Part 5 - Weekly Sep-Dec/W44 Nov 1 - Food-Grade Storage Off the Floor, Off the Wall, FIFOFEFO.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nFood-Grade Storage: Off the Floor, Off the Wall, FIFO/FEFO"]],["tr",["Doc No: PWH-MTR-2027-W44\\nWeek: 44 · Mon Nov 1, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 44 of 52 · November 2027"]],["tr",["Monday training title","Food-Grade Storage: Off the Floor, Off the Wall, FIFO/FEFO"]],["tr",["Monthly theme","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Food-grade product is stored on clean pallets, off the wall, segregated by SKU and lot/expiration, rotated correctly and scanned on every move."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Peak season starts now. Space gets tight, and that\\u0027s exactly when storage rules slip. This week we hold the line."],["h","3. KEY TEACHING POINTS"],["pt","1. Off the floor."],["p","On clean, undamaged pallets — never directly on the floor."],["pt","2. Off the wall."],["p","Keep the 18-inch inspection perimeter clear along every wall."],["pt","3. Segregated."],["p","By SKU and expiration, or SKU and business unit. No co-mingling incompatible inventory (PWH-SOP-208)."],["pt","4. Rotated."],["p","FEFO, FIFO or the customer\\u0027s rotation — oldest/earliest expiration ships first."],["pt","5. Scanned and synced."],["p","Scan SKU, SKID ID and location on every move; sync per the WMS SOP."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When the building fills up, the temptation is to put a pallet wherever it fits: against the wall, in the wrong customer\\u0027s zone, on the floor at the end of an aisle. Every one of those is an audit finding, a pest risk or a traceability problem."],["p","The 18-inch perimeter lets us see the walls and the pest devices. Segregation keeps customers\\u0027 product separate and keeps food away from non-food items. Rotation keeps product from expiring on our racks."],["p","And scanning every move is what lets us find a lot in a recall. If it isn\\u0027t scanned, the WMS doesn\\u0027t know where it is — and neither do we."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The pallet against the wall."],["p","During peak, an operator puts three food-grade pallets tight against the back wall to clear a staging lane. An inspection a week later finds rodent droppings behind them that nobody could see. The perimeter exists so we can catch that early."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: When the building is full, what should you do with a pallet that has no proper location?"],["p","Listen for: Stop and ask the inventory supervisor; never put it against a wall, on the floor or in another customer\\u0027s zone."],["h","7. KNOWLEDGE CHECK"],["pt","1. How far must food-grade product be kept from the walls?"],["p","Answer: Keep the 18-inch perimeter along the walls clear."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check every food-grade location you put product in today: off the floor, off the wall, right zone, scanned."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk the perimeter of two food-grade aisles."],["li","Spot-check five pallets for correct zone, rotation and WMS location."],["li","Coach any unscanned or mis-located move."],["p","References: Storage \\u0026 Put Away SOP PWH-SOP-208 • Food Safety \\u0026 Goods Storage Policy 2.2.1 • 10-Minute Food Safety Meeting PWH-REF-226-1 • Piper WMS SOP PWH-SOP-214 • Loading, Transport and Staging Practices PWH-POL-156-2 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W45","week":45,"doc":"PWH-MTR-2027-W45","date":"2027-11-08","holiday":false,"month":11,"title":"Sanitation and Housekeeping in Food-Grade Zones","behavior":"Complete and sign your sanitation tasks today on the day you do them, and leave your area free of trash and debris at shift end.","track":"Food","file":"Part 5 - Weekly Sep-Dec/W45 Nov 8 - Sanitation and Housekeeping in Food-Grade Zones.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nSanitation and Housekeeping in Food-Grade Zones"]],["tr",["Doc No: PWH-MTR-2027-W45\\nWeek: 45 · Mon Nov 8, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 45 of 52 · November 2027"]],["tr",["Monday training title","Sanitation and Housekeeping in Food-Grade Zones"]],["tr",["Monthly theme","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Sanitation tasks are completed on schedule and signed honestly on the day they\\u0027re done; housekeeping is maintained every shift."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: A clean building is a food-safe building. And a sanitation record is only worth something if it\\u0027s true."],["h","3. KEY TEACHING POINTS"],["pt","1. Follow the Master Sanitation Cleaning Schedule 12.2.5."],["p","Weekly, monthly, quarterly, semi-annual and annual tasks, by zone."],["pt","2. Sign it the day you do it."],["p","Your real name, the real date. Never pre-sign or sign for someone else."],["pt","3. Couldn\\u0027t do it? Say so."],["p","Write that it wasn\\u0027t done and why, and tell your supervisor."],["pt","4. Housekeeping every shift."],["p","Trash out, wrap and pallet debris off the floor, spills cleaned immediately, cans in good condition."],["pt","5. Lift cleaning."],["p","If you clean off a lift in the warehouse, clean up what came off it."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Our sanitation schedule is how we prove to customers and auditors that the building is clean. That proof only works if the records are real. A blank line with an honest note is a minor issue. A signature for cleaning that didn\\u0027t happen can fail an audit and damage everyone\\u0027s credibility."],["p","Housekeeping is the everyday part: trash goes out every shift, wrap and pallet scraps get picked up, spills get cleaned now. Full cans and debris left overnight attract pests."],["call","SHOW IT: Show the current week on the Master Sanitation Cleaning Schedule and who owns each task."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The pre-signed log."],["p","To save time, a weekly sanitation log is signed for the whole month at once. An auditor notices the same pen, same handwriting and dates that haven\\u0027t happened yet. One shortcut put every record in question. Sign it when it\\u0027s done."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which sanitation task is hardest to get done on time, and why?"],["p","Listen for: Usually quarterly/high-level cleaning or zones blocked by product. Plan around it."],["h","7. KNOWLEDGE CHECK"],["pt","1. You couldn\\u0027t finish your assigned cleaning task. What do you write on the log?"],["p","Answer: That it wasn\\u0027t completed and why, then tell your supervisor. Never sign for work that wasn\\u0027t done."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Complete and sign your sanitation tasks today on the day you do them, and leave your area free of trash and debris at shift end."],["h","9. SUPERVISOR VERIFICATION"],["li","Review this week\\u0027s sanitation log entries against the schedule."],["li","Walk food-grade zones at shift end for trash and debris."],["li","Confirm cleaning supplies are stored in the chemical area, not near product."],["p","References: Master Sanitation WI and Cleaning Schedule 12.2.5 • Document Control and Records Policy 2.2.2 • GMP Policy PWH-POL-114-1 • Building placard: Cleaning Zone • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W46","week":46,"doc":"PWH-MTR-2027-W46","date":"2027-11-15","holiday":false,"month":11,"title":"Temperature-Sensitive Product and Dock Dwell Time","behavior":"Put away any temperature-sensitive receipts first today — nothing sensitive sits on the dock.","track":"Food","file":"Part 5 - Weekly Sep-Dec/W46 Nov 15 - Temperature-Sensitive Product and Dock Dwell Time.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nTemperature-Sensitive Product and Dock Dwell Time"]],["tr",["Doc No: PWH-MTR-2027-W46\\nWeek: 46 · Mon Nov 15, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 46 of 52 · November 2027"]],["tr",["Monday training title","Temperature-Sensitive Product and Dock Dwell Time"]],["tr",["Monthly theme","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Temperature-sensitive product moves from trailer to storage without sitting on the dock, and any excursion is reported immediately."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Some of what we store can be damaged by heat or cold. Every minute it sits on the dock counts."],["h","3. KEY TEACHING POINTS"],["pt","1. Know which product is sensitive."],["p","[SITE: customers/SKUs with temperature limits and the limits]."],["pt","2. Minimize dock dwell."],["p","Sensitive product goes from trailer to storage without staging on the dock [SITE: time limit]."],["pt","3. Doors closed when not working."],["p","Protects storage conditions and keeps pests out."],["pt","4. Read and log."],["p","Storage conditions are monitored and logged per [SITE: method]; readings are real readings."],["pt","5. Excursion = report and hold."],["p","Out-of-range reading or product left exposed: tell your supervisor; product is held for evaluation."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Most of our product is shelf-stable, but [SITE] customers have temperature or humidity limits. Those loads get priority: unload, scan and put away, no sitting on a hot or freezing dock while we work another trailer."],["p","If you see a temperature or humidity reading out of range, or a sensitive pallet left on the dock, tell me right away. The supervisor or SQF Practitioner decides whether it\\u0027s held."],["p","And logs are real readings from real instruments on the day they\\u0027re taken. If a reading was missed, it stays blank with a note."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The pallet that waited."],["p","A pallet of temperature-sensitive product is staged at the dock door while the crew finishes an outbound roll load. It sits in afternoon heat for two hours. The customer has to evaluate the lot. Unloading it first would have avoided the question."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Which of our customers\\u0027 products are temperature-sensitive, and how would you know?"],["p","Listen for: Name them; show labels, WMS flags or placards [SITE]."],["h","7. KNOWLEDGE CHECK"],["pt","1. You notice a temperature-sensitive pallet has been sitting on the dock for an hour. What do you do?"],["p","Answer: Move it to storage now and tell your supervisor so it can be evaluated and held if needed."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Put away any temperature-sensitive receipts first today — nothing sensitive sits on the dock."],["h","9. SUPERVISOR VERIFICATION"],["li","Check the dock for staged sensitive product every two hours."],["li","Review today\\u0027s temperature/humidity readings for gaps or excursions."],["li","Confirm any excursion has a hold and a supervisor note."],["p","References: Loading, Transport and Staging Practices PWH-POL-156-2 • Disposition of Non-conformance Product SOP 2.4.4 • [SITE: temperature/humidity monitoring procedure] • 21 CFR 117.206 (storage of TCS foods, where applicable) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W47","week":47,"doc":"PWH-MTR-2027-W47","date":"2027-11-22","holiday":false,"month":11,"title":"Food Defense and Traceability: Seals, Access and Lot Control","behavior":"Verify the seal on every trailer you open today and record the seal on every trailer you close.","track":"Food","file":"Part 5 - Weekly Sep-Dec/W47 Nov 22 - Food Defense and Traceability Seals, Access and Lot Control.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nFood Defense and Traceability: Seals, Access and Lot Control"]],["tr",["Doc No: PWH-MTR-2027-W47\\nWeek: 47 · Mon Nov 22, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 47 of 52 · November 2027"]],["tr",["Monday training title","Food Defense and Traceability: Seals, Access and Lot Control"]],["tr",["Monthly theme","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Seals are verified and recorded, unknown persons are challenged and escorted, and every move is scanned so lots can be traced."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Food defense is about protecting product from someone who wants to harm it. Traceability is how we find it fast if something goes wrong."],["h","3. KEY TEACHING POINTS"],["pt","1. Seals in, seals out."],["p","Verify inbound seal numbers against paperwork before opening; record outbound seal numbers on the load sheet."],["pt","2. Know who belongs here."],["p","Visitors and drivers sign in and are escorted per the Guest Policy 12.3.4. Politely challenge anyone you don\\u0027t recognize."],["pt","3. Report signs of tampering."],["p","Broken or mismatched seals, opened or re-taped packaging, unusual substances, unlocked areas that should be locked."],["pt","4. Scan every move."],["p","SKU, SKID ID and location; sync. Lot traceability depends on it."],["pt","5. Recall readiness."],["p","In a mock or real recall, we must find every case of a lot quickly. Unscanned moves cost time."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","A seal is how a customer knows nobody opened the trailer between their plant and ours. If an inbound seal is broken or doesn\\u0027t match, don\\u0027t open the doors. Call me."],["p","If you see someone in a storage area you don\\u0027t recognize, walk up and say, \\"Hi, can I help you find someone?\\" Then walk them to the office. Most of the time it\\u0027s a lost driver. Sometimes it isn\\u0027t."],["p","Our 2026 mock recall and trace tests showed that the time to find every pallet depends on whether every move was scanned and synced. Scan it every time."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The re-taped case."],["p","During put-away, an associate notices a case in a food-grade pallet that\\u0027s been opened and re-taped with different tape. He sets the pallet aside, tags it and tells the supervisor, who places the lot on hold and contacts the customer per the food defense SOP."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What would you say to someone you don\\u0027t recognize in a food-grade aisle?"],["p","Listen for: Polite challenge, walk them to the office, verify sign-in."],["h","7. KNOWLEDGE CHECK"],["pt","1. An inbound seal is broken. Do you unload?"],["p","Answer: No. Don\\u0027t open or unload; call your supervisor. It\\u0027s a possible tampering event."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Verify the seal on every trailer you open today and record the seal on every trailer you close."],["h","9. SUPERVISOR VERIFICATION"],["li","Review inbound and outbound seal records for today."],["li","Check the visitor log against people on the floor."],["li","Run a quick trace on one random pallet: does the WMS location match?"],["p","References: Food Defense and Food Fraud SOP 2.7 • Food Defense Plan 2.7.1 • Guest Policy 12.3.4 • Product Traceability, Recall \\u0026 Crisis Management SOP 2.6.1 • Piper WMS SOP PWH-SOP-214 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W48","week":48,"doc":"PWH-MTR-2027-W48","date":"2027-11-29","holiday":false,"month":11,"title":"Product on Hold: Suspect Product, Spills and Reporting","behavior":"If you find any suspect product today, isolate it, tag it with date, reason and your name, and tell me before you continue.","track":"Food","file":"Part 5 - Weekly Sep-Dec/W48 Nov 29 - Product on Hold Suspect Product, Spills and Reporting.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nProduct on Hold: Suspect Product, Spills and Reporting"]],["tr",["Doc No: PWH-MTR-2027-W48\\nWeek: 48 · Mon Nov 29, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 48 of 52 · November 2027"]],["tr",["Monday training title","Product on Hold: Suspect Product, Spills and Reporting"]],["tr",["Monthly theme","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","SQF training (PWH-WKI-147-1) / FDA CGMP food hygiene — refresher"]],["tr",["Training objective","Suspect, damaged, contaminated or recalled product is isolated, tagged, recorded and never shipped until released."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: The hold process is the last line of defense between a problem in our building and a problem at our customer\\u0027s. During peak it gets tested."],["h","3. KEY TEACHING POINTS"],["pt","1. What goes on hold:"],["p","Damaged packaging, wet or stained product, pest contact, chemical/fluid contact, temperature abuse, broken seals, tampering signs, glass or brittle plastic incidents, recalls and withdrawals."],["pt","2. Isolate."],["p","Move it to the hold area [SITE], or mark a temporary hold location if it can\\u0027t be moved safely."],["pt","3. Tag and record."],["p","Date, reason, your name; recorded per [SITE: hold log/WMS status]."],["pt","4. Never ship, return to stock or discard it yourself."],["p","Only the supervisor or SQF Practitioner releases or dispositions held product (SOP 2.4.4)."],["pt","5. Report the cause."],["p","So it doesn\\u0027t happen again."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When you find product that might be unsafe or damaged, you don\\u0027t decide whether it\\u0027s okay. You move it out of the flow, tag it and tell your supervisor. That keeps it from being picked and shipped by someone who doesn\\u0027t know."],["p","If the hold area is full, we make a marked temporary hold location. Held product is never put back in its rack with a note on the wrap."],["p","Disposition is decided by the supervisor or SQF Practitioner: release, rework, return or destroy, with a record."],["call","SHOW IT: Show a hold tag and the hold area [SITE]. Fill out a tag together."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The note on the wrap."],["p","A damaged pallet with a handwritten \\u0027DAMAGED\\u0027 note on the wrap is left in its location because the hold area is full. The next shift doesn\\u0027t see the note and ships it. The customer rejects it and files a complaint. A proper hold tag and isolation would have stopped it."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s slowed down the hold process here before?"],["p","Listen for: Full hold area, unclear tags, no one to disposition. Fix it before December."],["h","7. KNOWLEDGE CHECK"],["pt","1. Can you put a damaged pallet back in stock if you write \\u0027damaged\\u0027 on the wrap?"],["p","Answer: No. Isolate it in the hold area, tag it properly and tell your supervisor."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: If you find any suspect product today, isolate it, tag it with date, reason and your name, and tell me before you continue."],["h","9. SUPERVISOR VERIFICATION"],["li","Reconcile the hold area against the hold log."],["li","Confirm every held item has a tag and a disposition owner."],["li","Check that nothing on hold is in a pickable WMS status."],["p","References: Disposition of Recalled, Withdrawn and Non-conformance Product SOP 2.4.4 • Recall \\u0026 Withdraw SOP 2.6.3 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 13) • CAPA Policy 2.5.3 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W49","week":49,"doc":"PWH-MTR-2027-W49","date":"2027-12-06","holiday":false,"month":12,"title":"Rack Damage: What to Look For and How to Report It","behavior":"Look at the uprights and beam clips in every aisle you work today and report anything bent, twisted or missing.","track":"","file":"Part 5 - Weekly Sep-Dec/W49 Dec 6 - Rack Damage What to Look For and How to Report It.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nRack Damage: What to Look For and How to Report It"]],["tr",["Doc No: PWH-MTR-2027-W49\\nWeek: 49 · Mon Dec 6, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 49 of 52 · December 2027"]],["tr",["Monday training title","Rack Damage: What to Look For and How to Report It"]],["tr",["Monthly theme","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness + company procedure (OSHA 29 CFR 1910.176(b))"]],["tr",["Training objective","Employees recognize and report any rack contact or damage the same shift; damaged bays are unloaded and barricaded per supervisor."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Rack damage hides. A bent upright can look fine from the aisle and still be holding far less than it should."],["h","3. KEY TEACHING POINTS"],["pt","1. Any contact gets reported."],["p","Even if you see no damage (PWH-SOP-229-1 Sec. 14)."],["pt","2. What to look for:"],["p","Bent, twisted or creased uprights; dislodged or bent beams; missing beam safety clips; damaged base plates or missing anchors; product overhanging beams."],["pt","3. Damaged bay = stop."],["p","Don\\u0027t add load. Supervisor decides on unloading (top down) and barricading until inspected and repaired."],["pt","4. Beam capacity."],["p","Never exceed posted beam capacity or stacking height."],["pt","5. Prevent hits."],["p","Square approach to racks, slow at aisle ends, watch rear swing."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Rack uprights are designed to carry weight straight down. A dent or twist changes that, and the capacity can drop a lot. The first sign might be a beam that sags or a bay that shifts."],["p","If you touch a rack with a truck, report it, even if it looks fine. If you see damage, don\\u0027t put anything else in that bay. Tell me, and we\\u0027ll unload it from the top down and barricade it until it\\u0027s inspected."],["p","Most rack hits happen at aisle ends and when backing out with a turn. Square up, slow down and watch your rear swing."],["call","SHOW IT: Walk to the nearest rack run and point out uprights, beams, safety clips and base plates."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The upright that \\u0027had always looked like that\\u0027."],["p","During an inspection, an upright at an aisle end is found creased about two feet up. Nobody reported a hit. The bay is unloaded and the upright replaced, and an end-of-aisle guard is added."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do racks get hit most often in this building?"],["p","Listen for: Aisle ends, tight turns, near docks. Discuss guards and approach."],["h","7. KNOWLEDGE CHECK"],["pt","1. You bump a rack upright and see no damage. Do you report it?"],["p","Answer: Yes. Report every contact the same shift; damage isn\\u0027t always visible."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Look at the uprights and beam clips in every aisle you work today and report anything bent, twisted or missing."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk two rack runs looking for damage and missing clips."],["li","Confirm any damaged bay is unloaded, barricaded and tagged."],["li","Log rack damage and repair requests."],["p","References: OSHA 29 CFR 1910.176(b) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 9f, 14) • Safety Incident / Near Miss Report PWH-FRM-204-1 • ANSI MH16.1 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W50","week":50,"doc":"PWH-MTR-2027-W50","date":"2027-12-13","holiday":false,"month":12,"title":"Pallets, Unstable Loads and Falling Objects","behavior":"Check the bottom pallet before every lift today and pull any damaged pallet out of service.","track":"","file":"Part 5 - Weekly Sep-Dec/W50 Dec 13 - Pallets, Unstable Loads and Falling Objects.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nPallets, Unstable Loads and Falling Objects"]],["tr",["Doc No: PWH-MTR-2027-W50\\nWeek: 50 · Mon Dec 13, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 50 of 52 · December 2027"]],["tr",["Monday training title","Pallets, Unstable Loads and Falling Objects"]],["tr",["Monthly theme","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness + company procedure (PWH-SOP-208)"]],["tr",["Training objective","Damaged pallets and unstable loads are not lifted, stacked or stored, and pallets are stacked only to Piper standards."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Almost every falling-object injury starts with something that was leaning, overhanging or sitting on a broken pallet."],["h","3. KEY TEACHING POINTS"],["pt","1. Inspect before lifting."],["p","Broken deck boards, missing blocks, protruding nails, leaning or overhanging loads, loose wrap."],["pt","2. Triple stack only to standard."],["p","Same SKU and expiration, upright, within the yellow lines (PWH-SOP-208)."],["pt","3. Fix leaning or shifted pallets before moving on."],["p","Re-wrap, re-stack or replace the pallet."],["pt","4. Never stand under or beside a raised or unstable load."],["p","Stay out of the fall zone."],["pt","5. Damaged pallets out of service."],["p","Pull them, mark them and send them to the pallet area [SITE]."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","Before you pick up a pallet, look at the bottom one. A cracked board or missing block can let the whole stack drop when it\\u0027s lifted or bumped. If it\\u0027s damaged, don\\u0027t lift it; rework it onto a good pallet."],["p","Our put-away SOP allows triple-stacking only for the same SKU and expiration date, upright and inside the yellow lines. If a pallet is shifted or leaning, fix it before you move on."],["p","And stay out of the fall zone: never stand next to or under a raised load, and don\\u0027t walk between stacks that are being worked."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The bottom pallet."],["p","A triple stack is bumped by a pallet jack. The bottom pallet, which had a cracked deck board, gives way and the top pallet slides off into the aisle. No one is in the aisle. The near miss leads to a pallet-inspection step during put-away."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: Where do damaged pallets end up getting used anyway?"],["p","Listen for: Staging, rework, end-of-shift. Set up a clear damaged-pallet area."],["h","7. KNOWLEDGE CHECK"],["pt","1. You notice a leaning triple stack. What do you do?"],["p","Answer: Fix it before moving on (re-stack or rework), or stop and get a lead if it\\u0027s unstable. Keep people clear."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Check the bottom pallet before every lift today and pull any damaged pallet out of service."],["h","9. SUPERVISOR VERIFICATION"],["li","Walk storage for leaning, overhanging or over-height pallet stacks."],["li","Check the damaged-pallet area is marked and used."],["li","Coach anyone stacking outside the yellow lines."],["p","References: Storage \\u0026 Put Away SOP PWH-SOP-208 (Sec. 6) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 9b) • OSHA 29 CFR 1910.176(b) • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W51","week":51,"doc":"PWH-MTR-2027-W51","date":"2027-12-20","holiday":false,"month":12,"title":"Working Around Maintenance and Contractors","behavior":"Before you start, ask your lead what maintenance or contractor work is happening in your area today and where to stay clear.","track":"","file":"Part 5 - Weekly Sep-Dec/W51 Dec 20 - Working Around Maintenance and Contractors.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nWorking Around Maintenance and Contractors"]],["tr",["Doc No: PWH-MTR-2027-W51\\nWeek: 51 · Mon Dec 20, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 51 of 52 · December 2027"]],["tr",["Monday training title","Working Around Maintenance and Contractors"]],["tr",["Monthly theme","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Awareness (LOTO awareness 29 CFR 1910.147) + company contractor policy"]],["tr",["Training objective","Employees stay out of barricaded and locked-out work areas and stop unsafe contractor work."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Year-end is when doors, levelers and lights get fixed. That means people working over our heads and equipment locked out around us."],["h","3. KEY TEACHING POINTS"],["pt","1. Barricades mean stay out."],["p","Cones, tape or barriers around maintenance or contractor work are not to be crossed."],["pt","2. Never walk under lifts, ladders or raised loads."],["p","Including scissor lifts and boom lifts."],["pt","3. Never touch a lock or tag."],["p","Don\\u0027t operate locked-out equipment or try to start it."],["pt","4. Contractors sign in and are escorted."],["p","Per the Guest Policy and Contract Service Providers Policy; briefed on site rules."],["pt","5. Stop unsafe contractor work."],["p","No barricade over a walkway, hot work without a permit, ladders in traffic — stop it and get a supervisor."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","When maintenance or a contractor is working, the area should be barricaded. Walk around it, not through it. Never under a lift platform, ladder or raised load."],["p","If equipment is locked out, it stays locked out until the person who locked it removes the lock. Don\\u0027t try to use a dock door or leveler that\\u0027s tagged."],["p","Contractors are guests in our building. They follow our rules. If you see a contractor working unsafely — a ladder in a travel path, grinding with no permit, no barricade over a walkway — you have the same stop-work authority with them as with anyone."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The leveler repair."],["p","A contractor is repairing a dock leveler with the door locked out. A loader, not seeing the tag, tries to bring a trailer to that door. The lead stops him. The fix: a sign and cones on the dock face for any door under repair."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What maintenance or contractor work is scheduled here in the next few weeks?"],["p","Listen for: Share the schedule [SITE] so crews can plan around it."],["h","7. KNOWLEDGE CHECK"],["pt","1. A contractor\\u0027s ladder is set up in a main walkway with no barricade. What do you do?"],["p","Answer: Use stop-work authority, keep people clear and get a supervisor to barricade and reroute."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Before you start, ask your lead what maintenance or contractor work is happening in your area today and where to stay clear."],["h","9. SUPERVISOR VERIFICATION"],["li","Check every active maintenance or contractor area for barricades and LOTO."],["li","Confirm contractors are signed in and briefed."],["li","Confirm hot-work permits for any welding, cutting or grinding."],["p","References: Lockout/Tagout Procedure PWH-SOP-207 • Contract Service Providers Policy 2.3.3 • Guest Policy 12.3.4 • Repairs and Maintenance 12.2.1 • OSHA 29 CFR 1910.147 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]},{"code":"W52","week":52,"doc":"PWH-MTR-2027-W52","date":"2027-12-27","holiday":false,"month":12,"title":"Year-End Reset: 5S Housekeeping and Holiday Distraction","behavior":"Spend the first 15 minutes of your shift resetting your area to standard — exits and extinguishers first.","track":"","file":"Part 5 - Weekly Sep-Dec/W52 Dec 27 - Year-End Reset 5S Housekeeping and Holiday Distraction.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Safety Microtraining\\nYear-End Reset: 5S Housekeeping and Holiday Distraction"]],["tr",["Doc No: PWH-MTR-2027-W52\\nWeek: 52 · Mon Dec 27, 2027\\nDuration: 5–10 minutes\\nShift: ______________________\\nLed by: ______________________"]],["h","1. TRAINING INFORMATION"],["tr",["Week / Month","Week 52 of 52 · December 2027"]],["tr",["Monday training title","Year-End Reset: 5S Housekeeping and Holiday Distraction"]],["tr",["Monthly theme","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"]],["tr",["Estimated duration","5–10 minutes at shift start"]],["tr",["Classification","Company standard — awareness"]],["tr",["Training objective","Every area is reset to standard before year-end, and crews stay focused through holiday distractions and short staffing."]],["h","2. OPENING STATEMENT (30 sec)"],["call","SAY: Last Monday of the year. Let\\u0027s finish the way we started: clear, organized and focused."],["h","3. KEY TEACHING POINTS"],["pt","1. Sort."],["p","Remove what doesn\\u0027t belong: broken pallets, scrap wrap, unused tools, personal items."],["pt","2. Set in order."],["p","Everything in its marked place: trucks, chargers, cones, chocks, knives, sanitation tools."],["pt","3. Shine."],["p","Clean floors, trucks and work areas; empty trash."],["pt","4. Standardize."],["p","Fix faded lines, missing labels and signs; report anything that needs paint or repair."],["pt","5. Sustain — and stay focused."],["p","Holidays bring distraction, short staffing and fatigue. Same rules, every shift."],["h","4. SUPERVISOR SPEAKING NOTES (3–5 min)"],["p","This week we reset every area. Pull out what doesn\\u0027t belong. Put everything back where it\\u0027s marked. Clean. Note any faded floor lines, missing labels or broken equipment for January."],["p","Exits, extinguishers, panels and aisles first — those protect everyone."],["p","Holiday weeks are risky: people are thinking about family, crews are short, and some are covering unfamiliar jobs. If you\\u0027re doing a job you don\\u0027t normally do, ask before you start. If you\\u0027re tired or distracted, say so. Finish the year the way we started it: stop what isn\\u0027t safe, report what you see."],["call","SHOW IT: Take before photos of one area, run a 10-minute 5S reset with the crew, and take after photos."],["h","5. REAL-WORLD EXAMPLE"],["p","▸. The holiday cover."],["p","A picker covering for a clamp operator on holiday week is asked to \\u0027just move a couple of rolls\\u0027. He\\u0027s not authorized on the clamp truck. He says no and calls the lead, who reassigns the move. That\\u0027s the year\\u0027s lessons in one decision."],["h","6. EMPLOYEE ENGAGEMENT QUESTION (1–2 min)"],["p","Ask: What\\u0027s the one safety habit from this year you\\u0027ll keep in 2028?"],["p","Listen for: Collect answers; carry them into January\\u0027s kickoff."],["h","7. KNOWLEDGE CHECK"],["pt","1. What are the five S\\u0027s?"],["p","Answer: Sort, Set in order, Shine, Standardize, Sustain."],["h","8. TODAY\\u0027S SAFETY ACTION"],["call","THIS SHIFT: Spend the first 15 minutes of your shift resetting your area to standard — exits and extinguishers first."],["h","9. SUPERVISOR VERIFICATION"],["li","Before/after photos for each zone."],["li","Exits, extinguishers, panels and aisles clear in every zone."],["li","List repairs, paint and label needs for January work orders."],["p","References: Storage \\u0026 Put Away SOP PWH-SOP-208 • GMP Policy PWH-POL-114-1 • Master Sanitation Cleaning Schedule 12.2.5 • Manager Safety Walk (GEMBA) PWH-FRM-101-2 • Retain this sheet as a training record (PWH-WKI-147-1) in RECORDS 2.2.3. Date it the day it is delivered."],["h","ATTENDANCE"],["tr",["Printed Name","Signature","Printed Name","Signature"]],["p","Led by: ________________________ Signature: ______________________ Date: __________"],["p","Knowledge check: ______ of ______ answered correctly. Employees re-taught on shift: ______________________________"]]}],"monthly":[{"code":"M01","month":1,"doc":"PWH-MTG-2027-01","title":"Safety Leadership Kickoff: Stop-Work Authority, Hazard Recognition \\u0026 Near-Miss Reporting","objective":"Every employee can state the stop-work words, explain what a near miss is, and complete or describe the Safety Incident / Near Miss Report (PWH-FRM-204-1) before the meeting ends.","keyMessage":"Every one of us has the authority to stop unsafe work. This year we use it.","mondays":"4","file":"Part 2 - Monthly Company Meetings/01 January - Safety Leadership Kickoff.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — January 2027\\nStop-Work Authority · Hazard Recognition · Near-Miss Reporting · 2027 Program Launch"]],["tr",["Doc No: PWH-MTG-2027-01\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Safety Leadership Kickoff: Stop-Work Authority, Hazard Recognition \\u0026 Near-Miss Reporting"],["p","Every one of us has the authority to stop unsafe work. This year we use it."],["h","1. TRAINING INFORMATION"],["tr",["Month","January 2027 · Monthly meeting 1 of 12"]],["tr",["Training title","Safety Leadership Kickoff: Stop-Work Authority, Hazard Recognition \\u0026 Near-Miss Reporting"]],["tr",["Target audience","All warehouse employees, leads, supervisors, CSRs and managers — every shift"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","Company-specific policy + awareness training (stop-work, hazard and near-miss reporting)"]],["tr",["Training objective","Every employee can state the stop-work words, explain what a near miss is, and complete or describe the Safety Incident / Near Miss Report (PWH-FRM-204-1) before the meeting ends."]],["tr",["Bring to the meeting","Blank copies of the Safety Incident / Near Miss Report (PWH-FRM-204-1) — one per person\\nThe 2027 Monday training calendar (Part 1)\\nA red \\"STOP\\" card or tag for the demonstration\\n[SITE: last 12 months of near-miss and injury counts for this building]"]],["tr",["Monday sessions this month","Wk 1 Stop-Work Authority · Wk 2 Hazard Recognition \\u0026 Near Misses · Wk 3 PPE by Area · Wk 4 Winter Walking Surfaces"]],["p","Safety Measurables — December 2026 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Most serious warehouse injuries are preceded by warnings that somebody saw and nobody said out loud: the clamp truck that was drifting, the dock plate that never seated right, the trailer that crept forward an inch when the truck rolled in. A near miss is the building telling us exactly where the next injury will happen. The only question is whether we listen before or after someone gets hurt."],["p","In our buildings the stakes are high. A loaded clamp truck carrying a paper roll weighs several tons and cannot stop on a dime. A trailer that pulls away from the dock with a lift inside it is a fall of four feet with a truck on top of you. Food-grade product exposed to a leak, a pest or a forklift fluid spill can cost us a customer and our SQF certification. None of that starts as a disaster. It starts as something small that somebody noticed."],["p","This year Piper is running a 52-week safety program: one company meeting every month and a five-to-ten-minute Monday session every week. It starts here, with the two things that make everything else work: your authority to stop unsafe work, and your habit of reporting what you see."],["h","3. KEY LEARNING POINTS"],["pt","1. You have stop-work authority — and the responsibility to use it."],["p","Any employee can stop any task that looks unsafe, for themselves or anyone else, without asking permission first. Nobody is disciplined for a good-faith stop. Not stopping something you knew was unsafe is the violation."],["pt","2. The stop-work sequence is: Stop → Make it safe → Tell your supervisor → Fix it → Restart."],["p","Work only resumes when the hazard is corrected or controlled and a supervisor or lead has agreed it is safe to continue."],["pt","3. A near miss is an event that could have hurt someone or damaged product, equipment or the building — but didn\\u0027t."],["p","A roll that rocked when it was set down, a pedestrian who stepped out of an aisle in front of a truck, a lift that touched a rack upright. Every one gets reported on PWH-FRM-204-1 the same shift."],["pt","4. Unsafe conditions and unsafe acts get reported too."],["p","A cracked floor, a torn dock seal, a missing chock, a horn that doesn\\u0027t work — and also people taking shortcuts. Report the condition or the behavior, not to get someone in trouble, but to fix the process."],["pt","5. Reporting is measured as a good thing."],["p","In 2027 we track near-miss reports as a leading indicator. A rising number of reports means people are seeing hazards and speaking up. Silence is what worries us."],["pt","6. Supervisors own the follow-through."],["p","Every report gets a response, a corrective action with an owner and due date, and feedback to the person who reported it within one week."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Good morning. Before we start, I want you to think about the last time you saw something on the floor and thought, \\"that\\u0027s going to hurt somebody one day.\\" Maybe it was a dock plate, a stack that was leaning, or a truck coming out of an aisle too fast. Keep that picture in your head, because by the end of this meeting I\\u0027m going to ask you what you did about it."],["p","This is the first of twelve company meetings this year. Every month has one theme, and every Monday your supervisor will spend five to ten minutes on one specific piece of it. Today\\u0027s theme is the foundation for all the others: stopping unsafe work and reporting what you see."],["p","Stop-work authority (5 min)"],["p","Here is the rule, and I want it to be completely clear. Anyone in this building — a new hire on their first day, a temp, a driver, a supervisor — can stop a job that looks unsafe. You do not need to ask permission first. You do not need to be sure. If it looks wrong, you stop it."],["p","When you stop a job, use plain words: \\"Stop. That\\u0027s not safe.\\" Then make it safe if you can do that without putting yourself at risk: set the load down, shut the truck off, put a cone out, step out of the path. Then get your supervisor or lead. Together you fix the problem, and only then does the work restart."],["p","Here is what happens to the person who stops work: nothing bad. You will not be written up, yelled at, or moved off your job for a good-faith stop, even if it turns out the job was fine. What will get attention is the opposite: watching something unsafe happen and saying nothing. That is the violation."],["call","DEMO: Hand the red STOP card to one employee. Walk toward them pretending to carry a load with your view blocked. Have them stop you with the words. Then walk through the next four steps out loud: make it safe, tell the supervisor, fix it, restart."],["p","Near misses and hazards (5 min)"],["p","A near miss is anything that could have hurt someone or damaged something but didn\\u0027t. A roll that rocked when it was set on a column. A pedestrian who stepped out from behind a stack in front of a truck. A lift that touched a rack upright. A trailer that moved when the truck rolled onto the plate. Nobody was hurt, so it\\u0027s tempting to shake it off and keep working. Don\\u0027t. That near miss is a free lesson. The next time, the same thing happens with a person in the wrong spot."],["p","We report near misses on the Safety Incident / Near Miss Report, form PWH-FRM-204-1. You\\u0027ve got a copy in front of you. It takes about two minutes: what happened, where, what could have happened, and what you did right away. If you can\\u0027t write it, tell your supervisor and they will write it with you. Either way, it gets reported before the end of the shift."],["p","We also report unsafe conditions — a cracked floor, a torn dock seal, a missing chock, a horn that doesn\\u0027t work — and unsafe acts, like someone riding on the side of a truck. We\\u0027re not reporting to punish people. We\\u0027re reporting so we can fix the process that made the shortcut look like a good idea."],["call","ASK THE ROOM: Turn to the person next to you. Each of you name one near miss or hazard you\\u0027ve seen in this building in the last month. You have one minute."],["p","What management owes you (2 min)"],["p","If you report something, you are owed three things: an acknowledgment, a fix with a name and a date on it, and an answer within a week about what was done. If you report something and hear nothing back, tell me. That\\u0027s on us, not you."],["p","Starting this month, supervisors will be tracking near-miss reports, safety observations and how fast we close corrective actions. I\\u0027d rather see fifty near-miss reports and zero injuries than zero reports and one injury."],["p","Fill out the form together (3 min)"],["p","Let\\u0027s practice. Take the near miss you just told your partner about and fill out sections 1 through 6 of the form. Don\\u0027t worry about root cause or corrective actions; your supervisor completes those. I\\u0027ll walk around and help."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The trailer that moved."],["p","A clamp operator rolls onto a trailer at door [SITE] and feels the trailer shift toward the yard. He backs out, nothing falls, and he finishes the load after the driver backs in again. Nobody reports it."],["p","What should have happened: The operator stops loading, checks the vehicle restraint and chocks, and tells the lead. The lead confirms the trailer is secured, the event is written up on PWH-FRM-204-1, and the door\\u0027s restraint is checked by maintenance before the next trailer is loaded."],["pt","2. The new hire who didn\\u0027t speak up."],["p","On her second week, a new associate sees a lead walking under a raised roll to read a label. She thinks it\\u0027s dangerous but assumes he knows better and says nothing."],["p","What should have happened: She says \\"Stop — you\\u0027re under the load\\" and the operator lowers the roll. The lead thanks her. The supervisor uses the moment at the next huddle: anyone, at any level of experience, can and should stop unsafe work."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","What stops people from speaking up when they see something unsafe here? What would make it easier?"],["li","Think of the last near miss you saw. What could have happened if one thing had been different?"],["li","Where in this building do you think the next injury is most likely to happen? Why?"],["li","What should a supervisor do the moment someone stops a job?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. Who can stop a job that looks unsafe?"],["p","Answer: Anyone — any employee, temp, contractor or visitor. No permission is needed first."],["pt","2. What are the five steps after you call a stop?"],["p","Answer: Stop, make it safe, tell your supervisor, fix it, then restart only when it\\u0027s agreed safe."],["pt","3. A roll rocks when you set it on a column but doesn\\u0027t fall. Is that a near miss, and what do you do?"],["p","Answer: Yes. Make the stack safe, tell your supervisor, and report it on PWH-FRM-204-1 before the end of the shift."],["pt","4. What happens to an employee who stops a job in good faith and it turns out to be fine?"],["p","Answer: Nothing negative. Good-faith stops are never disciplined."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Stop it."],["p","If it looks unsafe, say \\"Stop, that\\u0027s not safe\\" and stop the work — yours or anyone\\u0027s."],["pt","2. Report it the same shift."],["p","Every near miss, unsafe condition and unsafe act goes on PWH-FRM-204-1 before you go home."],["pt","3. Follow up."],["p","If you reported something and haven\\u0027t heard back within a week, ask your supervisor what was done."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Whether employees speak up during the Monday sessions and on the floor; note who stops work and thank them publicly."],["li","Pedestrians walking under raised loads or near trucks, and whether anyone intervenes."],["p","Reinforce"],["li","Thank every employee who reports a near miss, by name, at the next huddle (with their permission)."],["li","When a stop is called, respond calmly and fix the issue before restarting — the crew is watching how you react."],["p","Verify and document"],["li","Every employee signed the sign-in sheet; absentees trained within 14 days."],["li","Near-miss reports logged this month and each one has a corrective action, owner and due date."],["li","Feedback given to each reporter within 7 days."],["li","Monthly GEMBA walk (PWH-FRM-101-2) completed with at least one hazard identified."],["h","10. CLOSING MESSAGE"],["call","Safety at Piper is not a poster or a slogan. It\\u0027s a decision each of us makes, every shift, to stop what isn\\u0027t right and say what we see. I would rather stop a hundred jobs that turned out fine than miss the one that wasn\\u0027t. Look out for each other. Speak up. That\\u0027s how everybody goes home the same way they came in."],["p","References: Piper Warehouse Safety Incident / Near Miss Report PWH-FRM-204-1 • Manager Safety Walk (GEMBA) PWH-FRM-101-2 • CAPA form PWH-FRM-216-1 • Food Safety Culture Policy PWH-POL-122-2 • OSH Act Section 11(c) (protection from retaliation for reporting) • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nJanuary 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-01\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the January 2027 company safety meeting: Safety Leadership Kickoff: Stop-Work Authority, Hazard Recognition \\u0026 Near-Miss Reporting."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M02","month":2,"doc":"PWH-MTG-2027-02","title":"Powered Industrial Truck Fundamentals","objective":"Operators can perform a complete pre-shift inspection, explain the stability triangle and tip-over response, apply the core operating rules, and park and refuel/charge correctly. Pedestrians can state the right-of-way and no-walking-under-loads rules.","keyMessage":"If you wouldn\\u0027t sign for it, it doesn\\u0027t move. If you can\\u0027t see, you don\\u0027t go.","mondays":"4","file":"Part 2 - Monthly Company Meetings/02 February - Powered Industrial Truck Fundamentals.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — February 2027\\nInspection · Stability · Operating Rules · Parking · Fueling \\u0026 Charging"]],["tr",["Doc No: PWH-MTG-2027-02\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Powered Industrial Truck Fundamentals"],["p","If you wouldn\\u0027t sign for it, it doesn\\u0027t move. If you can\\u0027t see, you don\\u0027t go."],["h","1. TRAINING INFORMATION"],["tr",["Month","February 2027 · Monthly meeting 2 of 12"]],["tr",["Training title","Powered Industrial Truck Fundamentals"]],["tr",["Target audience","All lift operators (forklift, roll clamp, bale clamp, reach truck); pedestrians, leads and supervisors attend the first 20 minutes"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","OSHA-required program refresher (29 CFR 1910.178) — does not replace operator training and evaluation"]],["tr",["Training objective","Operators can perform a complete pre-shift inspection, explain the stability triangle and tip-over response, apply the core operating rules, and park and refuel/charge correctly. Pedestrians can state the right-of-way and no-walking-under-loads rules."]],["tr",["Bring to the meeting","A staged truck for the walk-around (one forklift and one clamp truck if possible)\\nBlank Pre-Shift Inspection Forms\\nA DO NOT OPERATE tag\\nMHE Forklift Operation SOP PWH-SOP-229-1 and PWH-SOP-171\\n[SITE: authorized operator list with evaluation dates]"]],["tr",["Monday sessions this month","Wk 5 Pre-Shift Inspection · Wk 6 Seat Belts \\u0026 Tip-Over · Wk 7 Leaving a Truck Unattended · Wk 8 Battery Charging \\u0026 LP Changes"]],["call","NOT A CERTIFICATION. This session is refresher and awareness training. It does not replace OSHA-required powered industrial truck operator training and hands-on evaluation (29 CFR 1910.178(l), PWH-FRM-213-1), lockout/tagout authorized-employee training, or any other formal qualification."],["p","Safety Measurables — January 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Lifts are the most dangerous equipment in our buildings. OSHA estimates that forklift accidents cause tens of thousands of serious injuries nationally every year, and the most common fatal events are tip-overs, pedestrians struck, and operators crushed between the truck and a fixed object. Every one of those scenarios exists on our floor every shift."],["p","Our trucks are working harder than most. A clamp truck carrying a paper roll is handling several tons with the load\\u0027s center of gravity high and out in front. We drive in and out of trailers and railcars, cross dock plates and share aisles with pedestrians. One broken habit — an unbuckled belt, a skipped inspection, a quick turn with a load up — is all it takes."],["p","This meeting is a refresher on the fundamentals in our MHE Forklift Operation SOP (PWH-SOP-229-1) and the Rules of Safe Operation we teach every new hire. It is not certification. Every operator still needs formal training, a hands-on evaluation on PWH-FRM-213-1, supervisor authorization, and re-evaluation at least every three years."],["h","3. KEY LEARNING POINTS"],["pt","1. Only authorized operators drive."],["p","Training + hands-on evaluation + written authorization by the supervisor, age 18+. Re-evaluated every 3 years and after an accident, near miss, unsafe operation, a new truck type or a workplace change."],["pt","2. Inspect before first use, every shift."],["p","Every line of the Pre-Shift Inspection Form. A failed item that affects safe operation means the truck is tagged out, keyed and reported."],["pt","3. Keep the center of gravity inside the stability triangle."],["p","Never exceed the data plate. Carry loads 4–6 inches off the floor, tilted back. Never raise or lower while moving. Slow down for turns."],["pt","4. Seat belt on. If it tips: stay in, hold on, lean away."],["p","Never jump from a tipping truck."],["pt","5. Pedestrians have the right of way."],["p","Horn at intersections, aisle ends, doorways, trailers and railcars. Three truck lengths following distance. No riders. Nobody under a raised load. If the load blocks your view, travel in reverse."],["pt","6. Park it right; fuel and charge right."],["p","Unattended (25 ft or out of sight): forks flat, neutral, brake, power off, key out. LP and charging only in designated areas, no flames within 25 feet."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Our November meeting covered the habits we hold every operator to after a near miss in August. Nobody was hurt, and the point is to keep it that way. Today we go deeper on the fundamentals, and every Monday this month your supervisor will take one of them and drill it."],["p","First, a reminder about what this meeting is and isn\\u0027t. This is a refresher. If you\\u0027re not on the authorized operator list for a type of truck, you don\\u0027t drive it, even after today. Authorization comes from formal training, a hands-on test on PWH-FRM-213-1, and your supervisor\\u0027s signature."],["p","The inspection (5 min)"],["p","Let\\u0027s walk the truck together. With it off: forks or clamp arms, carriage, mast, chains, hoses. Tires and axles. Look underneath for drips. Overhead guard, backrest, data plate readable. LP tank locked in with the pin seated, or battery cables and connector good. Seat belt latches. Fire extinguisher present and charged. Clamp trucks: pads free of paper debris, no hose leaks, no loose bolts."],["p","Then turn it on. Horn. Lights. Backup alarm. Service brake and parking brake. Steering. Lift, lower and tilt smooth with no drift. Gauges. Clamp: rotates smoothly and releases cleanly."],["p","Fill out every line and sign it. If something fails that affects safe operation, the truck doesn\\u0027t move. Key out, DO NOT OPERATE tag on, parked out of the travel path, tell your supervisor. It comes back only when it\\u0027s repaired and released."],["call","DEMO: Perform the walk-around on the staged truck. Ask the crew to call out each item before you check it."],["p","Stability and tip-overs (4 min)"],["p","The stability triangle is the area between the two front wheels and the pivot of the rear axle. As long as the combined center of gravity of the truck and load stays inside it, the truck is stable. Overload it, raise the load while moving, turn too fast or brake hard, and the center of gravity moves out. That\\u0027s a tip-over."],["p","If it tips, you stay in the seat with the belt on, hold the wheel, brace your feet and lean away from the fall. People who jump get caught under the overhead guard. That\\u0027s why the belt is not optional."],["p","Operating rules and pedestrians (5 min)"],["p","Pedestrians always have the right of way. Never drive toward a person standing in front of a wall, rack or any fixed object. Sound the horn at intersections, blind corners, aisle ends, doorways, and when you go in or out of a trailer or railcar. Stay three truck lengths behind another truck. No riders, ever. Nobody stands or walks under a raised load, empty or loaded."],["p","Carry the load low, four to six inches off the floor, tilted back. If you can\\u0027t see over it, drive in reverse — and with rolls on a clamp truck, our SOP says you always drive in reverse. Never raise or lower a load while traveling. Slow down on wet floors, at corners, at doors and on docks."],["p","Pedestrians: you stay in marked walkways, you make eye contact with the operator before crossing their path, and you never assume they see you."],["call","ASK THE ROOM: Pedestrians in the room: where in this building do you feel least safe walking? Operators: where do you have the worst visibility?"],["p","Parking, fueling and charging (4 min)"],["p","If you\\u0027re more than 25 feet away or out of sight, the truck is unattended: forks or arms flat on the floor, neutral, brake set, power off, key out to key control. Park only in designated spots, never in aisles or in front of exits, extinguishers, panels or active dock doors."],["p","Propane changes and battery charging happen only in the designated areas, engine off, no smoking or flames within 25 feet. Glasses and insulated or leather gloves for LP. Face shield, chemical gloves and apron for battery service. Charger off before you connect or disconnect."],["p","Last point: every accident, injury, near miss and any contact with a rack, pole, door, product or person is reported before the end of the shift. The truck comes out of service until it\\u0027s checked, and the operator gets refresher training and re-evaluation before driving again. That isn\\u0027t punishment. It\\u0027s the OSHA requirement and our SOP."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The rack tap at the end of second shift."],["p","An operator backing out of an aisle clips a rack upright with the counterweight. It\\u0027s 20 minutes before shift end, there\\u0027s no visible dent, and he doesn\\u0027t want to stay late to fill out paperwork."],["p","What should have happened: He stops, sets the truck safe, and tells his lead. The upright is inspected and the rack bay unloaded if damaged. The contact is written up on PWH-FRM-204-1, and the operator gets refresher coaching per PWH-SOP-229-1 Sec. 14d."],["pt","2. The borrowed truck."],["p","A pallet-jack operator who has watched clamp trucks for months jumps on an idle clamp truck to move one roll while the clamp operator is on break."],["p","What should have happened: Nobody operates a truck type they are not trained, evaluated and authorized on — not even for one move. A lead who sees it uses stop-work authority. The supervisor schedules formal training and a PWH-FRM-213-1 evaluation if the employee wants to become an operator."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Which item on the pre-shift checklist gets skipped most on our trucks? Why?"],["li","Where do trucks and pedestrians come closest to each other in this building?"],["li","What would you do if your lead asked you to use a truck that just failed inspection \\u0027for one quick load\\u0027?"],["li","What do you need from us — equipment, time, layout changes — to follow these rules every shift?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. Your truck\\u0027s horn fails during inspection. What do you do?"],["p","Answer: Don\\u0027t operate it. Tag it out, remove the key, park it out of the travel path and tell your supervisor."],["pt","2. Your truck starts to tip. Do you jump?"],["p","Answer: No. Stay belted in, hold the wheel, brace your feet and lean away from the fall."],["pt","3. The load blocks your forward view. How do you travel?"],["p","Answer: In reverse, looking where you\\u0027re going, sounding the horn at intersections, doors and blind corners. Clamp trucks with rolls always travel in reverse."],["pt","4. How high do you carry a load?"],["p","Answer: 4–6 inches off the floor, tilted back. Never raise or lower while moving."],["pt","5. When is a truck \\u0027unattended\\u0027, and what must you do?"],["p","Answer: When you\\u0027re more than 25 feet away or can\\u0027t see it. Forks flat, neutral, brake set, power off, key removed."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Inspect it."],["p","Every line of the pre-shift form before the first move. Fail = tag out."],["pt","2. Belt it, low and slow."],["p","Seat belt on; load 4–6 inches up and tilted back; reverse if you can\\u0027t see; horn at every intersection and doorway."],["pt","3. Park it right."],["p","Forks flat, neutral, brake, power off, key out, in a designated spot."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Seat-belt use, load height, travel direction with obstructed loads, horn use at intersections and trailers."],["li","Pre-shift inspections actually being performed (not just signed) at shift start."],["li","Parked trucks: forks raised, power on, keys left in."],["p","Reinforce"],["li","Recognize operators who tag out a defective truck — that is the behavior we want."],["li","Correct any violation on the spot, privately and specifically: what you saw, the rule, the risk, the expected behavior."],["p","Verify and document"],["li","At least one PWH-FRM-MHE-01 observation per supervisor per day this month."],["li","100% of trucks in use have a completed, signed Pre-Shift Inspection Form every shift."],["li","Authorized operator list reviewed: every operator within 3 years of evaluation; overdue evaluations scheduled."],["li","Any operator involved in an incident or near miss this month received refresher training and re-evaluation."],["h","10. CLOSING MESSAGE"],["call","You are driving a machine that can kill someone in a second. You also know how to operate it so that never happens. Inspect it, belt it, keep it low and slow, give the pedestrian the right of way, and park it right. Do those five things every shift, and you will never be the operator in the incident report."],["p","References: OSHA 29 CFR 1910.178 • MHE Forklift Operation SOP PWH-SOP-229-1 • Rules of Safe Operation – New Hire Orientation SOP • PWH-SOP-171 Roll Clamp Truck Operation • Forklift / Clamp Truck Performance Test PWH-FRM-213-1 • MHE Operator WMS \\u0026 Safety Observation Audit PWH-FRM-MHE-01 • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nFebruary 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-02\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the February 2027 company safety meeting: Powered Industrial Truck Fundamentals."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M03","month":3,"doc":"PWH-MTG-2027-03","title":"Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control","objective":"Employees can explain how packaged food gets contaminated in a warehouse, follow Piper\\u0027s GMP rules, inspect food-grade receipts, keep chemicals and non-food items segregated, and report pest activity on the Pest Sighting Log 12.2.4.","keyMessage":"Our customers\\u0027 food is only as safe as the building it sits in.","mondays":"5","file":"Part 2 - Monthly Company Meetings/03 March - Food Safety I.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — March 2027\\nGMP Personal Practices · Receiving Inspection · Cross-Contamination · Pest Prevention"]],["tr",["Doc No: PWH-MTG-2027-03\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"],["p","Our customers\\u0027 food is only as safe as the building it sits in."],["h","1. TRAINING INFORMATION"],["tr",["Month","March 2027 · Monthly meeting 3 of 12"]],["tr",["Training title","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control"]],["tr",["Target audience","All employees in SQF / food-grade storage areas, plus anyone who receives, stores, loads or cleans in those areas (recommended: all employees)"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","SQF Storage \\u0026 Distribution training (Training Program PWH-WKI-147-1) and FDA CGMP food-hygiene refresher (21 CFR 117.4) — confirm scope with the SQF Practitioner"]],["tr",["Training objective","Employees can explain how packaged food gets contaminated in a warehouse, follow Piper\\u0027s GMP rules, inspect food-grade receipts, keep chemicals and non-food items segregated, and report pest activity on the Pest Sighting Log 12.2.4."]],["tr",["Bring to the meeting","GMP Policy PWH-POL-114-1 and a posted copy of the Food Safety Policy\\nPest Sighting Log 12.2.4\\nTrailer Inspection Sheet 12.6.5.2\\nOne damaged case or torn bag as a prop (from the hold area, kept bagged)\\n[SITE: food-grade zone map and pest device map]"]],["tr",["Monday sessions this month","Wk 9 Handwashing · Wk 10 GMP Personal Practices · Wk 11 Receiving Food-Grade Loads · Wk 12 Cross-Contamination · Wk 13 Pest Prevention"]],["p","Safety Measurables — February 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Piper Warehouse is SQF certified. That certificate is why food-grade customers trust us with their product, and it can be lost in one audit. Pests are one of the most common findings in storage-and-distribution audits, and a single contaminated shipment traced back to our building can end a customer relationship and trigger a recall."],["p","We don\\u0027t open food. But packaged food still gets contaminated in warehouses: a torn bag that attracts rodents, a forklift leak dripping on a pallet, a chemical stored on the rack above product, a trailer that arrives with an odor, or a door left open overnight. Every one of those is controlled by what we do on the floor, not by a document in an office."],["p","In 2027 SQF moves to Edition 10, which puts more weight on food safety culture: whether employees understand the rules, follow them when nobody is watching and speak up when something is wrong. This meeting and this month\\u0027s Monday sessions are part of how we show that."],["h","3. KEY LEARNING POINTS"],["pt","1. Packaged food is protected by its packaging — so packaging damage is product exposure."],["p","Torn, crushed, wet, stained or punctured packaging goes to the hold area and gets reported the same shift."],["pt","2. Follow Piper\\u0027s GMP rules (PWH-POL-114-1)."],["p","Wash hands after restrooms and before eating; eat, drink, chew gum or use tobacco only in designated areas; no open-toed shoes; no personal items in storage areas; report illness, cuts and sores; cover bandaged hands."],["pt","3. Inspect every food-grade trailer in and out."],["p","Clean, dry, odor-free, no pests, no holes or light through the roof or floor; seal number verified. Reject or hold what doesn\\u0027t pass and document it on the Trailer Inspection Sheet 12.6.5.2."],["pt","4. Segregate."],["p","Food-grade product is kept separate from non-food items, chemicals and hazardous materials — never stored under or beside chemicals, and dry goods away from wet areas."],["pt","5. Pest prevention is everyone\\u0027s job."],["p","Doors closed, 18-inch perimeter clear, spills cleaned now, hands off bait stations and traps, and every sighting logged on the Pest Sighting Log 12.2.4 before the end of the shift."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (3 min)"],["p","Hold up the damaged case. Ask: \\"If this were sitting in aisle [SITE] tonight, what happens next?\\" Let people answer: mice find it, ants find it, it gets shipped to a customer, an auditor finds it."],["p","That\\u0027s food safety in a warehouse. We don\\u0027t cook anything or open anything. Our job is to keep packaged food exactly as clean and intact as it was when it arrived. If the package is damaged, the food inside is exposed to the building — and we\\u0027re responsible for the building."],["p","Personal practices (5 min)"],["p","Our GMP policy is short, and every part of it matters. Wash your hands when you leave the restroom, before you eat and whenever they\\u0027re dirty. Eat, drink, chew gum and use tobacco only in the break room or designated areas — never on the floor, never in a truck. No open-toed shoes anywhere. Personal belongings stay in lockers, not on racks or in trucks."],["p","If you\\u0027re sick with something contagious, or you have an open cut or sore on your hands, tell your supervisor before your shift. Bandaged hands get covered with a glove."],["p","You may notice we don\\u0027t require hairnets or jewelry removal. That\\u0027s because our risk assessment found we never contact open product. If that ever changes for a customer or an area, the rules for that area will change too."],["p","Receiving, storage and segregation (6 min)"],["p","Every food-grade trailer gets inspected before we unload and before we load: clean, dry, no odor, no pests, no holes, no light through the roof or floor seams. Check the seal number against the paperwork. If it fails, we don\\u0027t just work around it — we stop, tell the supervisor, and document it."],["p","When product comes off the truck, look at every pallet: torn wrap, crushed corners, wet or stained cases, broken pallets. Damaged product goes to the hold area, gets tagged and reported. It never goes into a food-grade location."],["p","Segregation: food-grade product is never stored under or beside chemicals, cleaning products, pest materials, batteries or non-food freight. A forklift with a fluid leak doesn\\u0027t go into a product area. If fuel, oil or battery acid touches product or packaging, stop, isolate it and put it on hold."],["call","ASK THE ROOM: What are three things in this building that should never be stored next to food-grade product?"],["p","Pest prevention (5 min)"],["p","Our pest control operator comes on a schedule. We\\u0027re here every day. What we do between his visits is what keeps pests out. Six things: doors closed when freight isn\\u0027t moving through them; report pest signs and log them on the Pest Sighting Log 12.2.4; hands off bait stations and traps; clean spills and move damaged product now; keep the 18-inch perimeter along the walls clear; and no food or personal items on the floor."],["p","If a bait station gets hit by a truck, moved or goes missing, report it — don\\u0027t put it back yourself. A damaged or unaccounted-for device is an audit finding against us."],["p","Close (1 min)"],["p","This month\\u0027s Monday sessions take each of these one at a time. The question I want you to ask yourself every shift: if an auditor or a customer walked my area right now, what would they find?"],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The open door on third shift."],["p","Dock door [SITE] is left open for two hours overnight while the crew stages outbound loads. In the morning, droppings are found along the wall behind the first row of pallets."],["p","What should have happened: Doors close whenever freight isn\\u0027t actively moving. The sighting is logged on the Pest Sighting Log 12.2.4, the pest control operator is called, affected product is inspected and held if needed, and the event goes through CAPA."],["pt","2. The cleaner on the top beam."],["p","A sanitation associate leaves a jug of floor cleaner on a rack beam above food-grade pallets so it\\u0027s handy for the next shift."],["p","What should have happened: Chemicals are stored only in the designated chemical area, never above or beside food product. The product below is checked for leaks or contact, and the associate is coached on segregation."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Where in this building are pests most likely to get in right now?"],["li","What does a trailer have to look or smell like for you to stop unloading it?"],["li","What makes it hard to keep doors closed during busy shifts, and how could we fix that?"],["li","If you saw a co-worker eating on a truck in a food-grade aisle, how would you handle it?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. Where are employees allowed to eat, drink or chew gum?"],["p","Answer: Only in the break room or other designated areas — never on the warehouse floor or on a truck."],["pt","2. You find a torn bag of product in a food-grade aisle. What do you do?"],["p","Answer: Move it to the hold area, tag it, clean any spill, and report it the same shift."],["pt","3. A bait station has been knocked over by a truck. What do you do?"],["p","Answer: Don\\u0027t reset or move it yourself. Report it to your supervisor so the pest control operator services it."],["pt","4. What gets checked before unloading a food-grade trailer?"],["p","Answer: Seal number against paperwork; trailer clean, dry, odor-free, no pests, no holes or light through the floor or roof. Document it on the trailer inspection sheet."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Protect the package."],["p","Damaged or wet product goes to hold and gets reported the same shift."],["pt","2. Keep it separate."],["p","No chemicals, non-food items or leaking equipment near food-grade product."],["pt","3. Close it, clean it, log it."],["p","Doors closed, spills cleaned now, every pest sign logged on the Pest Sighting Log."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Dock doors left open with no freight moving; food or drinks outside designated areas; personal items on racks or trucks."],["li","Receiving: are trailers actually being inspected and documented before unloading?"],["p","Reinforce"],["li","Praise employees who reject or hold a bad trailer or damaged product — that protects the customer."],["li","Use the Monday sessions to walk one food-grade aisle with the crew."],["p","Verify and document"],["li","Monthly GMP inspection on the GEMBA form PWH-FRM-101-2 completed, signed by management, and findings entered into CAPA."],["li","Pest Sighting Log entries reviewed; each sighting has a corrective action."],["li","Trailer inspection sheets complete for every food-grade load this month."],["li","Training records filed in RECORDS 2.2.3 with the actual meeting date."],["h","10. CLOSING MESSAGE"],["call","Somewhere, a family is going to eat what\\u0027s sitting on our racks today. They\\u0027ll never know our names, but they\\u0027re trusting us anyway. Protect the package, keep it separate, close the doors and report what you see. That\\u0027s how we earn that trust every shift — and how we keep our SQF certificate on the wall."],["p","References: GMP Policy PWH-POL-114-1 • Food Safety Culture Policy PWH-POL-122-2 • Loading, Transport and Staging Practices PWH-POL-156-2 • Pest Control Devices SOP PWH-SOP-132-1 • Pest Sighting Log 12.2.4 • Trailer Inspection Sheet 12.6.5.2 • 10-Minute Food Safety Meeting PWH-REF-226-1 • 21 CFR Part 117 • SQF Food Safety Code: Storage \\u0026 Distribution • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nMarch 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-03\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the March 2027 company safety meeting: Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M04","month":4,"doc":"PWH-MTG-2027-04","title":"Pedestrian–Equipment Separation \\u0026 Traffic Management","objective":"Every employee follows the site traffic plan: pedestrians use marked walkways and crossings, operators control speed, sound the horn and confirm eye contact, and nobody enters a travel path a truck is using without being seen.","keyMessage":"Eye contact before you move. No eye contact, no movement.","mondays":"4","file":"Part 2 - Monthly Company Meetings/04 April - Pedestrianâ€“Equipment Separation \\u0026 Traffic Management.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — April 2027\\nWalkways · Speed · Horn \\u0026 Eye Contact · Blind Corners · Visibility"]],["tr",["Doc No: PWH-MTG-2027-04\\nDuration: 35 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Pedestrian–Equipment Separation \\u0026 Traffic Management"],["p","Eye contact before you move. No eye contact, no movement."],["h","1. TRAINING INFORMATION"],["tr",["Month","April 2027 · Monthly meeting 4 of 12"]],["tr",["Training title","Pedestrian–Equipment Separation \\u0026 Traffic Management"]],["tr",["Target audience","All employees — operators and pedestrians, including CSRs, office staff and visiting drivers\\u0027 escorts"]],["tr",["Estimated duration","35 minutes"]],["tr",["Training classification","OSHA PIT operating rules refresher (29 CFR 1910.178(m), (n)) + company traffic rules — awareness"]],["tr",["Training objective","Every employee follows the site traffic plan: pedestrians use marked walkways and crossings, operators control speed, sound the horn and confirm eye contact, and nobody enters a travel path a truck is using without being seen."]],["tr",["Bring to the meeting","Printed site traffic plan / floor map with walkways, crossings and speed limits [SITE]\\nMasking tape or cones to mark a \\u0027blind corner\\u0027 in the meeting space\\nA hi-vis vest"]],["tr",["Monday sessions this month","Wk 14 Walkways \\u0026 Crossings · Wk 15 Speed \\u0026 Cross-Aisle Horn · Wk 16 Eye Contact Before Movement · Wk 17 Blind Corners \\u0026 Obstructed View"]],["p","Safety Measurables — March 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Being struck by a lift is one of the most common ways people are seriously hurt or killed in warehouses — and the person hurt is very often not the operator. It\\u0027s someone who stepped out from behind a stack, walked through a dock to grab paperwork, or assumed the operator saw them."],["p","Our trucks spend half their time in reverse, carrying rolls that block the forward view, in aisles lined with stacks that hide people. Trucks and people share the same floor every shift. The only things separating them are the lines on the floor, the speed of the truck, the horn, and the eye contact between two people."],["h","3. KEY LEARNING POINTS"],["pt","1. Pedestrians stay in marked walkways and cross only at marked crossings."],["p","No shortcuts through aisles, staging lanes or dock lanes while trucks are working."],["pt","2. Operators control speed."],["p","Never faster than the posted limit [SITE: mph]; slow at intersections, aisle ends, doorways, docks and wet floors. Stop safely at all times."],["pt","3. Horn at every intersection, aisle end, blind corner, doorway, trailer and railcar — and slow down when you hear one."],["p","A horn means a truck is coming out."],["pt","4. Eye contact before movement."],["p","Operators don\\u0027t move toward or past a pedestrian until they\\u0027ve made eye contact. Pedestrians don\\u0027t step into a truck\\u0027s path until the operator has acknowledged them."],["pt","5. Never walk under a raised load or between a truck and a fixed object."],["p","Operators never drive toward a person standing in front of a wall, rack or stack."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (3 min)"],["p","I want everyone who mostly walks the floor to raise your hand. Now everyone who mostly drives. Here\\u0027s the thing: when a truck hits a person, both of those people did something that made it possible. Today\\u0027s meeting is for both groups."],["p","The traffic plan (5 min)"],["p","Hold up the floor map. These green [SITE: color] lines are pedestrian walkways. These are the crossings. These zones are no-pedestrian zones when trucks are working [SITE: list]. The posted speed limit is [SITE]. If you\\u0027re walking, you stay in the lines. If you need to go somewhere the lines don\\u0027t go, you stop at the edge and get an operator\\u0027s attention before you step in."],["p","We built the lines around where people actually need to go. If a line is in the wrong place, tell us and we\\u0027ll move it. What we won\\u0027t accept is people ignoring it."],["p","Speed and the horn (4 min)"],["p","Operators: speed is the one thing completely in your control. Our SOP says travel at a speed that lets you stop safely at all times — never faster than the posted limit, and slower at corners, doorways, docks and wet floors. A loaded clamp truck needs more distance to stop than you think."],["p","Use the horn at intersections, aisle ends, blind corners, doorways, and every time you enter or leave a trailer or railcar. When you hear a horn, slow down — it means another truck is coming out of an aisle or trailer."],["p","Eye contact and blind spots (5 min)"],["p","The rule is simple: no eye contact, no movement. An operator who sees a pedestrian stops or slows until they\\u0027ve made eye contact. A pedestrian who wants to cross a truck\\u0027s path waits until the operator looks at them and signals. A wave isn\\u0027t enough if you can\\u0027t see the operator\\u0027s eyes."],["p","Operators carrying rolls drive in reverse, so your view is over your shoulder and your mirrors. Pedestrians: if you\\u0027re behind a truck with a roll on, you\\u0027re in front of the operator. Stay out of the path."],["p","Nobody walks under a raised load, ever. And operators never drive toward someone standing in front of a rack, wall or stack — there\\u0027s nowhere for them to go."],["call","DEMO: Mark a blind corner with tape. Have one person walk toward it as a pedestrian and another approach as a \\u0027truck\\u0027 (walking backward). Show how neither sees the other until the last second, then repeat with a horn and a stop for eye contact."],["p","Close (1 min)"],["p","Every Monday this month we\\u0027ll cover one of these. This week, walk your normal routes and notice every time you leave the lines."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The CSR with the bill of lading."],["p","A CSR walks straight across the dock to hand a driver paperwork, cutting between a clamp truck backing out of a trailer and a staged roll lane. The operator is looking over his other shoulder."],["p","What should have happened: The CSR uses the marked walkway, stops at the dock edge and gets the operator\\u0027s eye contact before crossing — or hands paperwork through the designated driver window [SITE]. The operator sounds the horn leaving the trailer."],["pt","2. The aisle-end race."],["p","Two operators approach the same aisle end from different directions at the posted speed without sounding the horn. They see each other with about ten feet to spare and both brake hard; one roll shifts on the clamp."],["p","What should have happened: Both slow at the aisle end and sound the horn. The roll shift is reported as a near miss and the aisle end gets a mirror or stop sign if needed."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Where are the three spots in this building where trucks and people come closest together?"],["li","When do pedestrians most often leave the walkways, and why?"],["li","Operators: where is your visibility worst? What would help — mirrors, lights, a spotter, a layout change?"],["li","How do you get the attention of an operator who is wearing hearing protection or focused on a load?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. A truck carrying a roll is coming down the aisle you need to cross. What do you do?"],["p","Answer: Wait at the edge of the walkway or crossing until the operator makes eye contact and signals you across. Never step in front of or behind a moving truck."],["pt","2. When do operators sound the horn?"],["p","Answer: At intersections, aisle ends, blind corners, doorways, and when entering or leaving trailers and railcars."],["pt","3. What should you do when you hear a horn?"],["p","Answer: Slow down and look — another truck is coming out of an aisle, trailer or railcar."],["pt","4. Can you walk under a raised load if you\\u0027re quick?"],["p","Answer: Never. Nobody stands or passes under the raised portion of any truck, loaded or empty."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Walk the lines."],["p","Use marked walkways and crossings. No shortcuts."],["pt","2. No eye contact, no movement."],["p","Operators and pedestrians both wait for eye contact before getting close."],["pt","3. Slow down and sound it."],["p","Speed limit, horn at every intersection, doorway, trailer and railcar."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Pedestrians outside walkways; people under raised loads; operators not using the horn at aisle ends and trailers."],["li","Operator speed in main aisles and at the dock; travel direction with rolls."],["p","Reinforce"],["li","Stop and coach shortcuts immediately and politely; recognize operators who stop for eye contact."],["li","Ask employees where walkways or crossings are in the wrong place and fix them."],["p","Verify and document"],["li","Floor markings, walkway lines and crossing signs intact and visible; repaint requests submitted."],["li","Daily PWH-FRM-MHE-01 observations include speed, horn use and pedestrian distance."],["li","Any pedestrian–truck near miss this month investigated with root cause and corrective action."],["h","10. CLOSING MESSAGE"],["call","The person most likely to be hurt by a truck in this building is not the operator — it\\u0027s the person walking. Every one of us walks the floor. Stay in the lines, make eye contact, sound the horn and slow down. Look out for each other the way you\\u0027d want someone to look out for you."],["p","References: OSHA 29 CFR 1910.178(m) and (n) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 8) • Rules of Safe Operation SOP (Part C) • PWH-SOP-171 (Sec. 5.2) • [SITE: traffic plan / floor map] • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nApril 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-04\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the April 2027 company safety meeting: Pedestrian–Equipment Separation \\u0026 Traffic Management."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M05","month":5,"doc":"PWH-MTG-2027-05","title":"Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling","objective":"Clamp operators can inspect the clamp attachment, set and verify pressure for the roll being handled, pick up and place rolls square and centered, recognize roll damage, and stack to Piper standards.","keyMessage":"Squeeze the roll you have, not the roll you think you have.","mondays":"5","file":"Part 2 - Monthly Company Meetings/05 May - Paper Roll Clamp Operations I.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — May 2027\\nClamp Inspection · Clamp Pressure · Pickup \\u0026 Placement · Roll Damage · Stacking"]],["tr",["Doc No: PWH-MTG-2027-05\\nDuration: 45 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"],["p","Squeeze the roll you have, not the roll you think you have."],["h","1. TRAINING INFORMATION"],["tr",["Month","May 2027 · Monthly meeting 5 of 12"]],["tr",["Training title","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling"]],["tr",["Target audience","All roll clamp operators and trainees; leads, supervisors and inventory staff who direct roll moves"]],["tr",["Estimated duration","45 minutes"]],["tr",["Training classification","Company-specific procedure refresher (PWH-SOP-171) under the OSHA PIT program — does not replace PWH-FRM-213-1 evaluation"]],["tr",["Training objective","Clamp operators can inspect the clamp attachment, set and verify pressure for the roll being handled, pick up and place rolls square and centered, recognize roll damage, and stack to Piper standards."]],["tr",["Bring to the meeting","A clamp truck staged with a roll\\n[SITE: clamp pressure chart by roll grade/diameter/weight from the attachment manufacturer and each customer\\u0027s handling spec]\\nPhotos or a sample of a crushed core, out-of-round roll and edge damage [SITE]\\nPWH-SOP-171 and PWH-FRM-213-1 (Section 3, Roll Clamp Attachment)"]],["tr",["Monday sessions this month","Wk 18 Clamp Attachment Inspection · Wk 19 Clamp Pressure · Wk 20 Picking Up a Roll · Wk 21 Reading Roll Damage · Wk 22 Stacking \\u0026 Storage"]],["call","NOT A CERTIFICATION. This session is refresher and awareness training. It does not replace OSHA-required powered industrial truck operator training and hands-on evaluation (29 CFR 1910.178(l), PWH-FRM-213-1), lockout/tagout authorized-employee training, or any other formal qualification."],["p","Safety Measurables — April 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Paper rolls are what most of our customers pay us to handle. A single roll can weigh well over a ton, and stacked rolls form columns two, three or more high. When a roll falls, it doesn\\u0027t tip gently. It drops and rolls, and nothing in its path stops it. A roll falling off a clamp or a column can kill someone."],["p","Rolls are also easy to ruin. Too much clamp pressure crushes the core and makes the roll out-of-round; too little and it slips. A misaligned stack damages edges. A customer\\u0027s press line can\\u0027t run a roll with a crushed core or a damaged edge, and that becomes a claim, a chargeback, or a lost account."],["p","Our clamp truck SOP, PWH-SOP-171, is the standard we\\u0027re holding everyone to. Nothing in it is optional. This meeting goes through the first half: inspection, pressure, pickup, damage and storage. September covers travel, trailers, railcars and the most common mistakes."],["h","3. KEY LEARNING POINTS"],["pt","1. Inspect the clamp attachment every shift."],["p","Hydraulic system for leaks; clamp pads free of paper debris and not cracked or worn; arms and hoses undamaged; no loose bolts; clamp rotates and releases smoothly; test pressure per the manufacturer\\u0027s guidelines."],["pt","2. Pressure matches the roll."],["p","Adjust clamp pressure for roll size and weight using the posted chart and customer spec. Read the gauge every time you change grade or diameter. Too high crushes the core; too low lets the roll slip."],["pt","3. Approach square, clamp centered, clamp low."],["p","Approach the roll squarely, center the arms on the roll, engage near the bottom, and close with even pressure on both sides."],["pt","4. Know what damaged looks like."],["p","Crushed or out-of-round cores, flat spots, torn or gouged wrappers, edge/head damage, telescoping, water marks. Damaged rolls are set aside, tagged and reported before storage."],["pt","5. Stack to standard."],["p","Swept, level floor; upright compressed columns; each roll perfectly aligned on the one below; 2–3 inches (a fist) between columns; labels facing out at 45°; stack height per roll size and at least 5 feet below the ceiling and clear of sprinklers, lights and HVAC."],["pt","6. One package at a time."],["p","For rolls packaged two or more per pack, put away only one package at a time. Two packs (four rolls) at once will drop the bottom roll."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (3 min)"],["p","Ask: \\"What\\u0027s the heaviest roll we handle in this building?\\" Let operators answer [SITE]. Then: \\"Picture that roll falling off the top of a column and rolling down the aisle. What\\u0027s in its way?\\" That\\u0027s why we\\u0027re here."],["p","This is a refresher on our SOP. It does not certify anyone. To operate a clamp truck you must be trained, pass the hands-on test on PWH-FRM-213-1, including the clamp attachment section, and be authorized by your supervisor."],["p","Inspecting the clamp (6 min)"],["p","Your pre-shift inspection covers the truck. The clamp needs its own look. With the truck off: hydraulic hoses and fittings for leaks or wear; pads clean of paper debris and not cracked, torn or worn smooth; arms straight, no cracks at welds; no loose bolts. With it on: rotate both ways, open and close, check that it holds without drifting, and check the pressure gauge works."],["p","Paper debris on a pad is a slip waiting to happen — it acts like a ball bearing between the pad and the roll. Clean it off before your first lift."],["call","DEMO: On the staged truck, point out each inspection item on the clamp. Have an operator rotate, open and close the clamp and read the gauge."],["p","Pressure and pickup (8 min)"],["p","Every roll grade and diameter has a correct pressure range. It\\u0027s on the chart at [SITE] and comes from the clamp manufacturer and our customers\\u0027 handling specs. Before you pick up a different roll than the last one, check the chart and set the pressure. Then watch the gauge on the first squeeze."],["p","Too much pressure crushes the core. The roll goes out-of-round, and the customer\\u0027s press can\\u0027t run it. Too little and the roll slips in the arms — especially a heavy roll on a quick stop. Neither one is a judgment call. Use the chart."],["p","Pickup: approach squarely, not at an angle. Center the arms on the roll. Engage near the bottom of the roll. Close gently with even pressure on both sides. Lift only when you\\u0027re stopped, and carry 4 to 6 inches off the floor."],["call","ASK THE ROOM: Operators: what\\u0027s the most common pressure mistake you\\u0027ve seen? What happens when someone \\u0027feels it out\\u0027 instead of reading the gauge?"],["p","Roll damage (5 min)"],["p","Show the damage photos. Crushed core: the center hole is oval, not round. Out-of-round: the roll sits with a flat spot. Edge or head damage: dents or tears on the ends. Telescoping: layers shifted so the end looks like a cone. Wrapper damage, water marks, gouges from arms or pallet boards."],["p","If you find damage, the roll doesn\\u0027t go into storage. Set it aside, tag it, and tell the lead or CSR so it\\u0027s documented before it becomes our claim. If you caused it, report it. That\\u0027s how we fix the cause."],["p","Stacking and storage (6 min)"],["p","Before any roll goes down, the floor is swept and checked for bolts, cracks or uneven spots. Report any of those to management."],["p","Rolls stand upright in compressed columns. Each roll is perfectly aligned on the one below — misalignment damages edges and makes the column unstable. Leave 2 to 3 inches, about a fist, between columns so they don\\u0027t rub and so people can see between them. Labels face out at 45 degrees so anyone walking the aisle can read them. Stack height depends on roll size [SITE: chart], and every stack stays at least 5 feet below the ceiling and clear of sprinklers, lights and HVAC."],["p","And the rule that keeps rolls off the floor: if rolls come packaged two or more to a pack, put away one package at a time. Two packs — four rolls — at once will drop the bottom roll."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The grade change."],["p","An operator who has been moving heavy liner rolls all morning switches to lighter, smaller-diameter rolls for a customer order without changing the clamp pressure. Three rolls later, the customer reports crushed cores on that order."],["p","What should have happened: Every grade or diameter change starts with the pressure chart and a gauge check on the first squeeze. Crushed rolls found later are held and reported, and the operator is coached and re-checked on PWH-FRM-213-1 Section 3."],["pt","2. The leaning column."],["p","A lead notices a three-high column in aisle [SITE] where the top roll overhangs the middle roll by about an inch. The operator says it\\u0027s been fine for a week."],["p","What should have happened: Use stop-work authority. Rebuild the column with each roll perfectly aligned. Report it as an unsafe condition, check neighboring columns and the floor under the stack."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Which roll grades or customers are most likely to get crushed cores? Why?"],["li","What makes it hard to set pressure every time on a busy shift? What would make it easier?"],["li","Where in our storage are stacks closest to the ceiling, sprinklers or lights?"],["li","How do you tell a lead about a damaged roll you caused, and what should happen next?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. You switch from heavy rolls to smaller, lighter rolls. What do you do before the first pickup?"],["p","Answer: Check the pressure chart for the new roll, set the pressure, and verify on the gauge with the first squeeze."],["pt","2. How do you approach and clamp a roll?"],["p","Answer: Approach squarely, center the arms on the roll, engage near the bottom, close with even pressure on both sides."],["pt","3. How much space goes between roll columns, and which way do labels face?"],["p","Answer: 2–3 inches (a fist) between columns; labels face out at a 45° angle."],["pt","4. Can you put away two packs of rolls (four rolls) at once?"],["p","Answer: No. One package at a time — two packs at once will drop the bottom roll."],["pt","5. You find a roll with an oval core. What do you do?"],["p","Answer: Don\\u0027t store it. Set it aside, tag it, and report it to the lead or CSR."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Check the clamp, then the chart."],["p","Inspect pads, hoses and arms every shift; set pressure from the chart every time the roll changes."],["pt","2. Square, centered, low."],["p","Approach square, center the arms, engage near the bottom, even pressure."],["pt","3. Stack it straight."],["p","Aligned columns, a fist between them, labels at 45°, height limit and 5 feet below the ceiling."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Pressure gauge checks at grade changes; pickup technique (square, centered, low)."],["li","Stack alignment, column gaps, label orientation and stack height in every roll aisle."],["li","Paper debris on clamp pads at shift start."],["p","Reinforce"],["li","Recognize operators who report damage they caused — that\\u0027s how we find the cause."],["li","Correct misaligned or over-height stacks immediately; never leave them for the next shift."],["p","Verify and document"],["li","Clamp pressure chart posted, current and readable at [SITE]."],["li","PWH-FRM-MHE-01 \\u0027proper clamp pressure\\u0027, \\u0027stacking and alignment\\u0027 and \\u0027labels aligned\\u0027 items observed for every clamp operator this month."],["li","Every clamp operator\\u0027s PWH-FRM-213-1 (incl. Section 3) on file and within 3 years."],["li","Roll damage reports reviewed for trends by operator, customer and grade."],["h","10. CLOSING MESSAGE"],["call","A paper roll doesn\\u0027t give second chances. It either stays where you put it or it falls. Inspect your clamp, set your pressure from the chart, pick it up square and low, and stack it straight. Do that on every roll and our customers get perfect product and everyone in this building goes home safe."],["p","References: PWH-SOP-171 Roll Clamp Truck Operation, Stock Storage \\u0026 Loading/Unloading (internal no. PWH-SOP-169-1) • Forklift / Clamp Truck Performance Test PWH-FRM-213-1 • Storage \\u0026 Put Away SOP PWH-SOP-208 • MHE Operator WMS \\u0026 Safety Observation Audit PWH-FRM-MHE-01 • OSHA 29 CFR 1910.178(a)(4)–(5), (l) • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nMay 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-05\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the May 2027 company safety meeting: Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M06","month":6,"doc":"PWH-MTG-2027-06","title":"Dock, Trailer \\u0026 Railcar Safety","objective":"No trailer or railcar is entered by a truck until it is secured, inspected and properly plated, and every load follows the Controlled Trailer/Rail Inspection and Load/Unload Sheet.","keyMessage":"Secured, inspected, plated: then you go in.","mondays":"4","file":"Part 2 - Monthly Company Meetings/06 June - Dock, Trailer \\u0026 Railcar Safety.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — June 2027\\nSecured · Inspected · Plated — then you go in"]],["tr",["Doc No: PWH-MTG-2027-06\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Dock, Trailer \\u0026 Railcar Safety"],["p","Secured, inspected, plated: then you go in."],["h","1. TRAINING INFORMATION"],["tr",["Month","June 2027 · Monthly meeting 6 of 12"]],["tr",["Training title","Dock, Trailer \\u0026 Railcar Safety"]],["tr",["Target audience","Everyone who works the truck dock or rail dock: operators, loaders, leads, supervisors, CSRs; rail crew"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","OSHA PIT trucks \\u0026 railroad cars (29 CFR 1910.178(k), (m)(7)), dockboards (1910.30(a)) refresher + company loading policy"]],["tr",["Training objective","No trailer or railcar is entered by a truck until it is secured, inspected and properly plated, and every load follows the Controlled Trailer/Rail Inspection and Load/Unload Sheet."]],["tr",["Bring to the meeting","Controlled Trailer/Rail Inspection and Load/Unload Sheet\\nWheel chock and trailer stand (or point to them at the nearest door)\\n[SITE: dock door list showing which doors have vehicle restraints]\\n[SITE: rail procedure — blue flag, derail, car stops, serving railroad contact]"]],["tr",["Monday sessions this month","Wk 23 Trailer Secured Before Entry · Wk 24 Trailer Floors, Nose \\u0026 Dock Plates · Wk 25 Railcar Safety · Wk 26 Heat Inside Trailers \\u0026 Railcars"]],["call","NOT A CERTIFICATION. This session is refresher and awareness training. It does not replace OSHA-required powered industrial truck operator training and hands-on evaluation (29 CFR 1910.178(l), PWH-FRM-213-1), lockout/tagout authorized-employee training, or any other formal qualification."],["p","Safety Measurables — May 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","The dock is where the warehouse meets everything we don\\u0027t control: drivers who pull out early, trailers with rotted floors, railcars that roll, dock plates that slip. Trailer creep and early pull-aways can drop a lift and its operator four feet to the ground. A weak trailer floor can give way under a loaded clamp truck. A railcar moved by the railroad while a lift is inside can crush everything in its path."],["p","OSHA requires that trucks and trailers be braked and chocked or otherwise secured, that railcars be protected against movement, that trailer floors be checked before they\\u0027re driven onto, and that dock plates be properly secured. Our Operator Accountability Policy adds verification steps for every load because the dock is also where most of our loading errors and damage happen."],["h","3. KEY LEARNING POINTS"],["pt","1. Secured."],["p","Trailer held by the vehicle restraint or wheel chocks on the rear wheels; trailer stand under the nose of any trailer not coupled to a tractor; tandems slid back for roll loads. Railcars: blue-flag protection and derail in place, hand brake set, wheels blocked per [SITE: rail procedure]."],["pt","2. Inspected."],["p","Floor free of holes, cracks, soft spots, nails, debris and wet contamination — if light shines through the floorboards, reject the trailer. Roof free of holes and leaks. Food-grade: clean, dry, odor-free."],["pt","3. Plated."],["p","Dock plate or bridge plate rated for truck plus load, fully seated and secured so it can\\u0027t slip. Never exceed its rated capacity."],["pt","4. Load it right."],["p","Verify trailer number, door and order; follow the load plan; split weight over front and rear tandems; mat under every roll; strap split loads and the rear cluster."],["pt","5. Verify every load."],["p","Count, cross-reference to the pack list, supervisor/lead verification on every load, one active load per loader at a time."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Ask the room: \\"Has anyone here ever felt a trailer move while they were inside it?\\" Usually someone has. That\\u0027s the whole reason for this meeting."],["p","Secure it (8 min)"],["p","Before any lift enters a trailer, the trailer is secured. At doors with a vehicle restraint, the restraint is engaged and the light shows [SITE: green inside]. At doors without one, wheel chocks go against the rear wheels. If the trailer isn\\u0027t attached to a tractor, a trailer stand goes under the nose so it can\\u0027t tip forward when a heavy truck rolls to the front. For roll loads, the driver slides the tandems back first."],["p","OSHA\\u0027s wording on chocks has some legal history around who enforces it for over-the-road trucks. That doesn\\u0027t matter here. Piper\\u0027s rule is simple: every trailer is restrained or chocked, every time, before a lift goes in."],["p","Railcars: no one enters a railcar unless blue-flag protection and the derail are in place and the car\\u0027s hand brake is set [SITE: and wheels blocked]. The bridge plate is rated for the load and secured so it can\\u0027t slip. Never move or close railcar doors with the forks or clamp."],["call","DEMO: At the nearest door, show the chock placement, the restraint light, and the trailer stand. At the rail dock, point out the blue flag and derail."],["p","Inspect it (6 min)"],["p","Walk in before you drive in. Look for holes, cracks, missing or soft boards, nails, debris and water. Look up: if you see light through the floorboards or the roof, the floor or roof is weak. Weak floorboards mean the trailer is rejected. Record it on the inspection sheet."],["p","For food-grade loads, the trailer also has to be clean, dry and free of odors and pests. Sweep out debris before loading."],["p","Plate it and load it (6 min)"],["p","Dock plates and levelers have a rated capacity. Know the weight of your truck plus the load before you cross. The plate must be fully seated on the trailer bed, not resting on the edge. Cross slowly and straight."],["p","Inside, follow the load plan for the roll diameter or the customer\\u0027s pattern. Split the weight between the front and rear tandems. Every roll goes on a rubber mat. Split loads and the rear cluster get strapped. Sound the horn every time you enter or leave the trailer."],["p","Then the verification steps: trailer number and door match the paperwork; staged count matches the pack list; each roll or pallet is checked off as it\\u0027s loaded; physical count inside the trailer; supervisor or lead verifies every load. One loader, one active load."],["call","ASK THE ROOM: What\\u0027s the most common reason a load goes out wrong here? Which of these steps would have caught it?"],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The early pull-away."],["p","A driver at a door without a vehicle restraint is told the load is almost done and climbs into his cab. The chocks were never placed. He pulls forward as the clamp operator backs onto the plate."],["p","What should have happened: Chocks or the restraint go on before the first lift enters. Drivers wait in the designated area with keys handed over or per [SITE: key/glad-hand lock policy]. The operator stops work if the trailer isn\\u0027t secured."],["pt","2. The light through the floor."],["p","Loading a 40-roll order, the operator notices daylight between two floorboards near the nose but finishes the load because the customer is waiting."],["p","What should have happened: Light through the floorboards means weak boards: the trailer is rejected per PWH-SOP-171 Sec. 7.1. Unload, document on the inspection sheet, and request a replacement trailer from the carrier."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Which dock doors give us the most trouble with restraints, plates or seals?"],["li","What do you do if a driver insists on leaving before you\\u0027ve finished?"],["li","What slows us down most on the rail dock, and where are we tempted to cut corners?"],["li","How should a loader handle pressure to work two loads at once?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. What has to be true before a lift enters a trailer?"],["p","Answer: Trailer restrained or chocked; trailer stand in place if not coupled to a tractor; floor inspected; dock plate rated and seated; trailer number and door verified."],["pt","2. You see light through the trailer floorboards. What do you do?"],["p","Answer: Reject the trailer. Weak floorboards can collapse under a loaded truck. Document it."],["pt","3. What protection is required before entering a railcar?"],["p","Answer: Blue-flag protection and derail in place, hand brake set, wheels blocked, and the bridge plate rated and secured."],["pt","4. How is weight placed when loading rolls?"],["p","Answer: Split over the front and rear tandems per the load plan, with a mat under every roll and straps on split loads and the rear cluster."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Secured."],["p","Restraint or chocks, trailer stand, blue flag and derail — before the first lift goes in."],["pt","2. Inspected."],["p","Walk it first. Light through the floor = reject."],["pt","3. Plated and verified."],["p","Rated plate, fully seated; follow the load plan and verify every load."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Chocks/restraints and trailer stands at every active door; blue flag and derail at the rail dock."],["li","Operators walking trailers before entering; plates fully seated."],["p","Reinforce"],["li","Back every employee who refuses to load an unsecured trailer or weak floor — publicly."],["li","Coach any skipped verification step the same shift."],["p","Verify and document"],["li","Controlled Trailer/Rail Inspection and Load/Unload Sheets complete and signed by loader and supervisor for every load."],["li","Vehicle restraints and lights function-tested at every door this month; work orders for failures."],["li","Dock plates/levelers inspected; damaged ones tagged out."],["li","Rail procedure posted at the rail dock and reviewed with the serving railroad."],["h","10. CLOSING MESSAGE"],["call","Every dock injury story starts with one skipped step: the chock that wasn\\u0027t placed, the floor nobody walked, the plate that wasn\\u0027t seated. Secured, inspected, plated — then you go in. Every trailer, every railcar, every time."],["p","References: OSHA 29 CFR 1910.178(k), (m)(7) • OSHA 29 CFR 1910.30(a) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 10) • PWH-SOP-171 (Sec. 7) • Operator Accountability Policy and Controlled Trailer/Rail Inspection and Load/Unload Sheet • Trailer Inspection Sheet 12.6.5.2 • Rules of Safe Operation SOP (Part D) • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nJune 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-06\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the June 2027 company safety meeting: Dock, Trailer \\u0026 Railcar Safety."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M07","month":7,"doc":"PWH-MTG-2027-07","title":"Heat Stress, Fatigue \\u0026 First Response","objective":"Employees recognize heat exhaustion and heat stroke, know the response for each, follow hydration and acclimatization practices, report fatigue without penalty, and know how to report injuries and get help.","keyMessage":"Report the symptom early. Heat stroke doesn\\u0027t wait for break time.","mondays":"4","file":"Part 2 - Monthly Company Meetings/07 July - Heat Stress, Fatigue \\u0026 First Response.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — July 2027\\nHeat Illness · Hydration \\u0026 Acclimatization · Fatigue · Injury Reporting \\u0026 First Aid"]],["tr",["Doc No: PWH-MTG-2027-07\\nDuration: 35 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Heat Stress, Fatigue \\u0026 First Response"],["p","Report the symptom early. Heat stroke doesn\\u0027t wait for break time."],["h","1. TRAINING INFORMATION"],["tr",["Month","July 2027 · Monthly meeting 7 of 12"]],["tr",["Training title","Heat Stress, Fatigue \\u0026 First Response"]],["tr",["Target audience","All employees, with emphasis on dock, trailer and rail crews and anyone new or returning from time off"]],["tr",["Estimated duration","35 minutes"]],["tr",["Training classification","Awareness training. No final federal OSHA heat standard; OSHA enforces heat hazards under the General Duty Clause and its heat National Emphasis Program. First aid per 29 CFR 1910.151."]],["tr",["Training objective","Employees recognize heat exhaustion and heat stroke, know the response for each, follow hydration and acclimatization practices, report fatigue without penalty, and know how to report injuries and get help."]],["tr",["Bring to the meeting","[SITE: heat plan — water locations, cool-down area, rest schedule, who decides when heat procedures start]\\nA cold water bottle and an electrolyte packet\\nLocations of first-aid kits, AED and eyewash [SITE]\\nEmployee Refusal of Medical Treatment form PWH-FRM-229-1 (for supervisors)"]],["tr",["Monday sessions this month","Wk 27 Heat Illness Signs \\u0026 Response · Wk 28 Hydration \\u0026 Acclimatization · Wk 29 Fatigue · Wk 30 First Response"]],["p","Safety Measurables — June 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Inside a trailer or railcar sitting in a southern summer sun, temperatures climb far above the dock air temperature — and Atlanta summers are hot and humid. Heat illness comes on gradually, and the person suffering from it is often the last to notice because confusion is one of the symptoms. Heat stroke can kill."],["p","Fatigue works the same way. Long shifts, overtime during busy weeks and poor sleep slow reaction time like alcohol does. On a clamp truck, a half-second slower reaction is the difference between stopping and not."],["p","There is still no final federal OSHA heat standard, but OSHA re-issued its heat National Emphasis Program in April 2026 and cites employers for heat hazards under the General Duty Clause. More importantly, every heat illness is preventable."],["h","3. KEY LEARNING POINTS"],["pt","1. Know the signs."],["p","Heat exhaustion: heavy sweating, cramps, headache, dizziness, nausea, weakness, cool clammy skin. Heat stroke: confusion, slurred speech, fainting, seizures, hot skin (dry or sweating) — a medical emergency."],["pt","2. Respond fast."],["p","Exhaustion: stop work, move to a cool area, loosen clothing, sip cool water, cool the skin; get help if not better within [SITE: 15–30] minutes. Stroke: call 911, cool the person immediately (water, ice, wet cloths, fanning), stay with them."],["pt","3. Drink before you\\u0027re thirsty and acclimatize."],["p","About one cup every 15–20 minutes in heat. New and returning workers build up exposure over the first week or two."],["pt","4. Fatigue is a safety hazard — report it."],["p","If you\\u0027re too tired to operate safely, tell your supervisor. You\\u0027ll be reassigned, not disciplined."],["pt","5. Report every injury, every time, the same shift."],["p","Even if it seems minor. Know where the first-aid kits, AED and eyewash are."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Ask: \\"What\\u0027s the hottest place you\\u0027ve worked in this building?\\" (Inside trailers, railcars, the dock in the afternoon, the battery room.) \\"How long were you in there?\\" That\\u0027s where this starts."],["p","Heat illness (8 min)"],["p","Heat exhaustion is your body falling behind: heavy sweating, cramps, headache, dizziness, nausea, feeling weak, skin cool and clammy. If you feel that, stop. Tell your lead, get to [SITE: cool-down area], loosen your clothing, sip cool water, and put a cold, wet towel on your neck. If you\\u0027re not better in [SITE] minutes, we get medical help."],["p","Heat stroke is your body losing control. The big sign is confusion: slurred speech, acting strange, not knowing where they are, passing out. Skin may be hot and dry or still sweating. That\\u0027s 911, right away. Then cool them immediately: move them to shade or AC, soak them with cool water, put ice packs on the neck, armpits and groin, and fan them. Stay with them until help arrives."],["p","Because confusion is a symptom, the person with heat stroke often won\\u0027t ask for help. That\\u0027s why we watch each other."],["call","ASK THE ROOM: Pair up with the person you work closest to on the dock. You\\u0027re each other\\u0027s heat buddy this summer."],["p","Prevention (6 min)"],["p","Drink water before you\\u0027re thirsty — about a cup every 15 to 20 minutes when it\\u0027s hot, not a gallon at lunch. Water is at [SITE]. Electrolyte drinks help on long, sweaty shifts. Go easy on energy drinks."],["p","If you\\u0027re new, or coming back after a week or more off, your body isn\\u0027t used to the heat. We\\u0027ll rotate you out of trailers and railcars more often for your first week or two. Experienced people get heat illness too, especially on the first really hot days of the season."],["p","When the heat index reaches [SITE: trigger], we [SITE: rotate crews out of trailers every X minutes, add breaks, run fans]. Your supervisor will announce it."],["p","Fatigue (4 min)"],["p","If you are too tired to operate safely — nodding off, missing things, reacting slow — tell your supervisor. That is not a weakness, it\\u0027s a stop-work call on yourself. You\\u0027ll be moved to a different task. Supervisors: we never punish someone for being honest about fatigue."],["p","First response (5 min)"],["p","Every injury gets reported to your supervisor the same shift, even if it\\u0027s small. First-aid kits are at [SITE], the AED is at [SITE], and eyewash is at the battery area [SITE]. In an emergency, call 911 first, then your supervisor."],["p","If an employee declines medical treatment, the supervisor documents it on PWH-FRM-229-1. That doesn\\u0027t end our responsibility — we keep watching and offer care again if things change."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The quiet operator in the trailer."],["p","Mid-afternoon in July, an operator has been unloading a hot trailer for an hour. A co-worker notices he\\u0027s slurring his words and missed the dock plate twice. The operator says he\\u0027s fine."],["p","What should have happened: Treat confusion as heat stroke. Stop work, call 911, start cooling immediately, notify the supervisor, and stay with him. Don\\u0027t wait for him to ask."],["pt","2. The double shift."],["p","Short-staffed, an operator works a double. Around hour 14 he clips the side of a trailer door coming out with a roll and says he \\u0027blanked for a second\\u0027."],["p","What should have happened: Fatigue is a hazard. He reports it, the contact is written up as a near miss, and he\\u0027s moved off the truck. Scheduling is reviewed so doubles on equipment don\\u0027t happen without rest."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Where are the hottest work spots in this building, and what would make them cooler?"],["li","How would you tell a co-worker you think they\\u0027re showing heat illness signs?"],["li","What makes people hesitate to say they\\u0027re too tired to drive?"],["li","Do you know where the closest first-aid kit and AED are right now?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. What\\u0027s the key sign that separates heat stroke from heat exhaustion?"],["p","Answer: Confusion or altered mental state (slurred speech, fainting, acting strange). Heat stroke is a 911 emergency."],["pt","2. What do you do for someone with heat stroke while you wait for help?"],["p","Answer: Call 911, move them somewhere cool, and cool them fast with water, ice and fanning. Stay with them."],["pt","3. How much should you drink in hot conditions?"],["p","Answer: About one cup of water every 15–20 minutes, starting before you\\u0027re thirsty."],["pt","4. You\\u0027re too tired to operate safely. What do you do?"],["p","Answer: Tell your supervisor and get reassigned. Reporting fatigue is never punished."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Drink early, drink often."],["p","A cup every 15–20 minutes when it\\u0027s hot."],["pt","2. Watch your buddy."],["p","Confusion means heat stroke — call 911 and start cooling."],["pt","3. Say it out loud."],["p","Report fatigue, symptoms and every injury the same shift."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Water use and breaks during hot shifts; crews rotating out of trailers and railcars."],["li","New and returning employees during their first two weeks."],["p","Reinforce"],["li","Announce heat procedures each hot day at the shift huddle."],["li","Thank anyone who reports symptoms or fatigue — and act on it immediately."],["p","Verify and document"],["li","Water and cups stocked at every station each hot day."],["li","First-aid kits stocked, AED inspected, eyewash flushed per schedule."],["li","Every injury this month documented, with first aid or referral recorded and PWH-FRM-229-1 used when treatment is declined."],["li","OSHA 300 log reviewed for any recordables."],["h","10. CLOSING MESSAGE"],["call","Heat and fatigue sneak up on the strongest, most experienced people in the building. The fix is simple: drink early, take the breaks, watch each other, and say something the moment something feels wrong. We\\u0027ll never be upset that you spoke up. We\\u0027d never forgive ourselves if you didn\\u0027t."],["p","References: OSH Act Section 5(a)(1) (General Duty Clause) • OSHA Heat National Emphasis Program (revised April 10, 2026) • OSHA 29 CFR 1910.151 (Medical services and first aid) • Employee Refusal of Medical Treatment PWH-FRM-229-1 • [SITE: heat illness prevention plan] • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nJuly 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-07\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the July 2027 company safety meeting: Heat Stress, Fatigue \\u0026 First Response."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M08","month":8,"doc":"PWH-MTG-2027-08","title":"Ergonomics, Hand Safety \\u0026 Machine Guarding","objective":"Employees lift with good mechanics, never stop or steer a rolling roll by hand or foot, keep hands out of pinch points, use the right glove and safety knife, never bypass a guard, and recognize a locked-out machine.","keyMessage":"Use the tool, not your hands. Report the ache before it becomes an injury.","mondays":"5","file":"Part 2 - Monthly Company Meetings/08 August - Ergonomics, Hand Safety \\u0026 Machine Guarding.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — August 2027\\nLifting · Manual Roll Handling · Pinch Points \\u0026 Knives · Gloves · Guards \\u0026 LOTO Awareness"]],["tr",["Doc No: PWH-MTG-2027-08\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Ergonomics, Hand Safety \\u0026 Machine Guarding"],["p","Use the tool, not your hands. Report the ache before it becomes an injury."],["h","1. TRAINING INFORMATION"],["tr",["Month","August 2027 · Monthly meeting 8 of 12"]],["tr",["Training title","Ergonomics, Hand Safety \\u0026 Machine Guarding"]],["tr",["Target audience","All warehouse employees"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","Awareness training + OSHA LOTO awareness for affected/other employees (29 CFR 1910.147) and machine guarding (1910.212) — not authorized-employee LOTO training"]],["tr",["Training objective","Employees lift with good mechanics, never stop or steer a rolling roll by hand or foot, keep hands out of pinch points, use the right glove and safety knife, never bypass a guard, and recognize a locked-out machine."]],["tr",["Bring to the meeting","A safety knife and a razor blade (for comparison)\\nCut-resistant gloves and a regular work glove\\nA roll bar / roll pusher [SITE]\\nA lock, tag and hasp from the LOTO station\\nLockout/Tagout Procedure PWH-SOP-207"]],["tr",["Monday sessions this month","Wk 31 Lifting Mechanics · Wk 32 Never Stop a Moving Roll · Wk 33 Pinch Points, Banding \\u0026 Knives · Wk 34 Gloves · Wk 35 Machine Guarding \\u0026 LOTO Awareness"]],["p","Safety Measurables — July 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Strains, sprains and hand injuries are the most common injuries in warehousing. They rarely make the news, but they are what most often keeps people off work and on light duty for weeks: a back tweaked lifting a pallet board, a shoulder strained pushing a roll, a hand cut on a band or crushed between a roll and a column."],["p","Most of these injuries build up over time or happen in a split second when someone reaches in where they shouldn\\u0027t. Both are preventable with the right technique, the right tool and the discipline to keep hands out of danger zones."],["p","This month also covers machine guarding and lockout/tagout awareness. Most of you are not authorized to lock out equipment, but every one of you needs to recognize a lock or tag and know you never touch it."],["h","3. KEY LEARNING POINTS"],["pt","1. Lift in the power zone."],["p","Test the weight, get close, feet shoulder-width, bend at the knees and hips, keep your back straight, lift with your legs, keep the load between mid-thigh and mid-chest, pivot your feet — don\\u0027t twist. Get help or a tool for anything heavy or awkward."],["pt","2. Never stop, steer or catch a moving roll by hand or foot."],["p","Get out of its path. Use roll bars or pushers only as trained, and never try to save a falling roll."],["pt","3. Hands out of pinch points."],["p","Between a roll and a column, a pallet and a rack, a dock plate lip and the trailer bed, clamp arms and anything. If you can\\u0027t see your hands, they\\u0027re in the wrong place."],["pt","4. Right tool, right glove."],["p","Safety knives (not razor blades), cut away from your body; cut-resistant gloves for banding and wrap; insulated/leather for LP; chemical gloves for battery service."],["pt","5. Guards stay on. Locks and tags are never touched."],["p","Never reach into a conveyor, leveler, wrapper or baler that isn\\u0027t locked out. Only the person who applied a lock removes it (PWH-SOP-207)."],["pt","6. Report discomfort early."],["p","Aches, tingling or numbness that last more than a few days get reported before they become an injury."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Ask: \\"Who here has had a sore back or a cut hand from work in the last year?\\" Usually many hands go up. \\"Most of those didn\\u0027t get reported. This month we fix the cause.\\""],["p","Lifting (6 min)"],["p","Pallet boards, slip sheets, roll mats, dunnage, damaged cases — we lift things by hand every shift. The back gets hurt on the twist, not the lift. Get close to the load, bend your knees, keep it in the power zone between mid-thigh and mid-chest, and turn your feet instead of your waist."],["p","If it\\u0027s heavy, awkward or above your shoulders, get a second person or use a pallet jack or lift. Asking for help is part of the job."],["call","DEMO: Lift a box incorrectly (bending at the waist, twisting), then correctly (close, knees bent, pivot). Ask the crew to call out the differences."],["p","Rolls and pinch points (8 min)"],["p","A rolling paper roll weighs as much as a car and doesn\\u0027t stop for a hand or a boot. If a roll starts moving on its own, your only job is to get out of its way and warn others. Never try to stop it, steer it or catch it. We use the clamp truck to move rolls. Our SOP says never push or roll product with the clamp arms, and never by hand."],["p","Pinch points: between a roll and the column next to it, between pallets, between a dock plate lip and the trailer bed, around clamp arms and fork carriages. Before you put your hand somewhere, ask: if this moves, where does my hand go?"],["p","Knives and gloves (5 min)"],["p","Razor blades are not allowed for cutting bands or wrap. Use the safety knife with the self-retracting blade, cut away from your body, and keep your other hand out of the cutting path. Banding under tension can whip when it\\u0027s cut — stand to the side and hold the end."],["p","Gloves are task-specific. Cut-resistant for banding and wrap. Insulated or leather for propane. Chemical gloves for batteries. A regular work glove is not cut protection."],["call","DEMO: Show the safety knife next to a razor blade. Show the cut-resistant glove next to a regular glove."],["p","Guards and lockout awareness (6 min)"],["p","Guards on conveyors, dock levelers, wrappers, balers and chargers are there because something behind them can take a finger or a hand. Guards stay on. If one is missing or damaged, the machine is not used until it\\u0027s fixed."],["p","When maintenance or a contractor works on equipment, it\\u0027s locked out: a lock and tag on the power source so it can\\u0027t be started. If you see a lock or tag, you never remove it, never operate that switch or valve, and never try to start the machine. Only the person who put the lock on removes it, after the work is signed off."],["p","Most of you are \\u0027affected\\u0027 or \\u0027other\\u0027 employees under our LOTO procedure. That means you need to recognize lockout and stay clear. You are not authorized to perform lockout unless you\\u0027ve had the separate authorized-employee training."],["call","DEMO: Show a lock, tag and hasp. Ask: \\"If you saw this on a dock leveler control box, what would you do?\\""],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The roll that started to roll."],["p","A roll is set down slightly off the mat at the end of a column and begins to roll toward a lead walking the aisle. An associate nearby steps in and puts his boot against it."],["p","What should have happened: Nobody stops a moving roll. Shout a warning, get clear, and let it stop. Then report it as a near miss and find out why it was set down unstable."],["pt","2. The jammed leveler."],["p","A dock leveler lip won\\u0027t extend. An operator reaches under the lip to clear a piece of wood while another employee holds the control button."],["p","What should have happened: Never reach into equipment that isn\\u0027t locked out. Stop, tag the door out of service, and call maintenance to lock out and clear it."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","What do we lift by hand that we could use a tool or a second person for?"],["li","Where are the worst pinch points in your area?"],["li","Do you have the right gloves and a working safety knife today? If not, what\\u0027s missing?"],["li","Have you ever seen a guard removed or a lock bypassed? What happened?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. A roll starts rolling toward a co-worker. What do you do?"],["p","Answer: Shout a warning and get clear. Never try to stop, steer or catch a moving roll by hand or foot."],["pt","2. What do you use to cut bands and stretch wrap?"],["p","Answer: A safety knife with a self-retracting blade, cutting away from your body, with cut-resistant gloves. Never a razor blade."],["pt","3. You see a lock and tag on a leveler\\u0027s control box. Can you remove it if the work looks done?"],["p","Answer: No. Only the person who applied the lock removes it, after the work is signed off."],["pt","4. When do you report an ache or tingling in your hands or back?"],["p","Answer: Early — if it lasts more than a few days, before it becomes an injury."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Power zone, pivot, ask for help."],["p","Lift close and low, turn your feet, get help with heavy or awkward loads."],["pt","2. Hands out, tool in."],["p","Never stop a moving roll; keep hands out of pinch points; safety knife only."],["pt","3. Locks and guards are untouchable."],["p","Never bypass a guard or touch a lock or tag."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Lifting technique on manual tasks; anyone touching or stopping a moving roll."],["li","Use of safety knives vs. razor blades; glove choice by task."],["li","Guards on conveyors, levelers, wrappers and balers; any equipment worked on without lockout."],["p","Reinforce"],["li","Replace razor blades with safety knives on the spot."],["li","Thank employees who report early discomfort and look at the task with them."],["p","Verify and document"],["li","Safety knives and cut-resistant gloves stocked at [SITE]."],["li","Guards present and intact on all equipment; missing guards tagged out with work orders."],["li","Lockout Tagout Log (PWH-SOP-207 Attachment C) current; authorized employee list reviewed."],["li","Any strain, sprain or hand injury this month investigated for root cause."],["h","10. CLOSING MESSAGE"],["call","Your back and your hands have to last your whole career. Lift smart, keep your hands out of places they can be crushed or cut, use the right tool and never touch someone else\\u0027s lock. Small habits, every shift — that\\u0027s how you finish the year with all ten fingers and a healthy back."],["p","References: Lockout/Tagout Procedure PWH-SOP-207 (OP-005) • OSHA 29 CFR 1910.147 • OSHA 29 CFR 1910.212 • OSHA 29 CFR 1910.138 (Hand protection) • PWH-SOP-171 (Sec. 5.2: never push or roll product with clamp arms) • NIOSH lifting guidance • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nAugust 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-08\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the August 2027 company safety meeting: Ergonomics, Hand Safety \\u0026 Machine Guarding."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M09","month":9,"doc":"PWH-MTG-2027-09","title":"Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading, Common Mistakes","objective":"Clamp operators travel with rolls safely, load and secure roll trailers to plan, unload railcars without roll or car damage, and stop work on any unstable or damaged roll.","keyMessage":"Roll damage is a safety warning, not just a claim.","mondays":"4","file":"Part 2 - Monthly Company Meetings/09 September - Paper Roll Clamp Operations II.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — September 2027\\nTravel With Rolls · Load Patterns \\u0026 Securement · Railcar Unloading · Operator Mistakes · Stop Work"]],["tr",["Doc No: PWH-MTG-2027-09\\nDuration: 45 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading, Common Mistakes"],["p","Roll damage is a safety warning, not just a claim."],["h","1. TRAINING INFORMATION"],["tr",["Month","September 2027 · Monthly meeting 9 of 12"]],["tr",["Training title","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading, Common Mistakes"]],["tr",["Target audience","All roll clamp operators and trainees; loaders, leads, supervisors and CSRs who build load plans"]],["tr",["Estimated duration","45 minutes"]],["tr",["Training classification","Company-specific procedure refresher (PWH-SOP-171, Operator Accountability Policy) under the OSHA PIT program — does not replace PWH-FRM-213-1 evaluation"]],["tr",["Training objective","Clamp operators travel with rolls safely, load and secure roll trailers to plan, unload railcars without roll or car damage, and stop work on any unstable or damaged roll."]],["tr",["Bring to the meeting","Load-plan binder [SITE] and one sample load plan by roll diameter\\nRubber roll mat and a load strap\\nControlled Trailer/Rail Inspection and Load/Unload Sheet\\nMay\\u0027s damage photos for review"]],["tr",["Monday sessions this month","Wk 36 Traveling With Rolls · Wk 37 Trailer Loading for Rolls · Wk 38 Railcar Roll Unloading · Wk 39 Top Clamp Operator Mistakes"]],["call","NOT A CERTIFICATION. This session is refresher and awareness training. It does not replace OSHA-required powered industrial truck operator training and hands-on evaluation (29 CFR 1910.178(l), PWH-FRM-213-1), lockout/tagout authorized-employee training, or any other formal qualification."],["p","Safety Measurables — August 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","May covered how to pick up and stack a roll. This month covers everything that happens between: carrying it across the building, putting it on a trailer that\\u0027s going down the highway, and pulling it out of a railcar. Those are the moments when rolls fall, loads shift and trailers get damaged."],["p","A roll load that shifts in transit can come through a trailer wall or the doors at the receiver\\u0027s dock and hurt someone we\\u0027ll never meet. A poorly distributed load can overload an axle and get a driver fined, or make a trailer unstable. A roll with a crushed edge from loading means a claim, and a customer who starts looking at other warehouses."],["p","The mistakes that cause these events are well known. We\\u0027ve seen most of them in our own buildings. This meeting puts them on the table so nobody has to learn them the hard way."],["h","3. KEY LEARNING POINTS"],["pt","1. Travel low, slow and in reverse."],["p","Carry rolls 4–6 inches off the floor, always drive in reverse with a roll, never lift or lower while moving, no sharp turns, never stack while moving, never exceed posted speed."],["pt","2. Load to the plan."],["p","Correct documents from the CSR; verify the load against paperwork; tandems slid back; trailer stand on drop trailers; trailer inspected; load-plan binder pattern by roll diameter."],["pt","3. Distribute and secure."],["p","Split weight over front and rear tandems; mat under every roll; strap split loads and the rear cluster to unitize the load."],["pt","4. Railcar unloading."],["p","Blue flag, derail, hand brake, blocked wheels, rated and secured bridge plate; verify seal and car number; check for shifted rolls before entering; inspect rolls after unloading."],["pt","5. Know the common mistakes."],["p","Wrong pressure, angled pickups, two packs at once, forward travel with a roll, pushing rolls with arms, missing mats or straps, skipped trailer inspection, working two loads at once."],["pt","6. Stop work on any unstable or damaged roll."],["p","Set it down, make the area safe, call the lead."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (3 min)"],["p","Ask: \\"What\\u0027s the worst thing you\\u0027ve seen happen to a roll between the stack and the trailer?\\" Let operators tell stories. Then: \\"Every one of those had a cause. Today we name them.\\""],["p","Reminder: this is a refresher, not a certification. Clamp operation requires training, a passed PWH-FRM-213-1 evaluation including the clamp attachment section, and supervisor authorization."],["p","Traveling with rolls (6 min)"],["p","Our SOP is specific. Carry the roll 4 to 6 inches off the ground. Always drive in reverse when carrying a roll. Lift and lower only when stopped. No stacking while moving. No sharp turns — the roll can shift or the truck can tip. Stay under the posted speed. Keep a clear line of sight or use a spotter."],["p","Carrying multiple rolls: only carry what the truck, clamp and roll size allow per [SITE: rule], and for rolls packaged two or more per pack, one package at a time. Two packs at once drops the bottom roll."],["p","Loading trailers (10 min)"],["p","Before the first roll: get the loading documents from the CSR and verify the order. Confirm the trailer number and the door. Make sure the tandems are slid back. Drop trailer? Trailer stand on the nose. Walk the trailer: nails, damaged walls, uneven floors, holes, debris — sweep it. Light through the floorboards means reject."],["p","Use the load-plan binder for the roll diameter. The plan exists to split the weight between the front and rear tandems and keep rolls from shifting. Every roll goes on a rubber mat. Split loads and the rear cluster get strapped to unitize them."],["p","Then the Operator Accountability steps: staged count matches the pack list, each roll checked off as loaded, physical count in the trailer, supervisor or lead verification on every load, and one loader on one active load at a time."],["call","DEMO: Lay a roll mat and strap on the floor. Walk through the sample load plan and point out where weight sits over the tandems and where straps go."],["p","Railcar unloading (6 min)"],["p","Railcars: blue flag and derail in place, hand brake set, wheels blocked, bridge plate rated for truck plus roll and secured. Verify the seal and car number against the paperwork. Open the doors fully and secure them — never with the clamp."],["p","Before you drive in, look at how the rolls rode. Rolls shift in transit and can lean against the door or each other. If anything looks unstable, stop and get the lead before you touch it. After unloading, inspect every roll and report damage immediately so it\\u0027s documented against the railroad or shipper."],["p","The common mistakes (8 min)"],["p","Here are the mistakes we see most, and the rule that prevents each. Pressure not changed between grades — check the chart. Angled pickups — square up. Two packs at once — one package at a time. Forward travel with a roll — always reverse. Pushing or rolling rolls with the arms — never. Missing mats or straps — every roll, every split load. Skipped trailer walk — walk it before you drive it. Two loads at once — one at a time."],["p","And the one that ties them together: if a roll is unstable, damaged, leaning or not sitting right, you stop. Set it down if it\\u0027s safe to, keep people back, and call the lead."],["call","ASK THE ROOM: Which of these mistakes have you seen in the last month? Which one is most tempting when we\\u0027re behind?"],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The missing mats."],["p","Rushing to make a carrier appointment, a loader skips the mats on the last six rolls of a trailer. At the receiver, the rear rolls have shifted, two have crushed edges against the doors, and the receiver\\u0027s dock worker is nearly hit when the doors open."],["p","What should have happened: Mats under every roll and straps on the rear cluster are not optional, even when late. The supervisor verifies before the trailer is sealed. The carrier waits; the load goes out right."],["pt","2. The leaning roll in the boxcar."],["p","An operator opens a boxcar and sees a roll leaning against the door at a slight angle. He tries to clamp it from the plate to \\u0027stand it back up\\u0027."],["p","What should have happened: Stop. Keep people clear of the door. Get the lead to assess, and use an approved method to stabilize the roll before anyone works the car."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Which load plans are hardest to follow, and why?"],["li","When we\\u0027re running late on a carrier appointment, which step gets skipped first?"],["li","What do you do when a driver or CSR pushes you to finish faster than the SOP allows?"],["li","What rail-car condition have you seen that should have stopped the unload?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. Which direction do you travel when carrying a roll on a clamp truck?"],["p","Answer: Always in reverse, with the roll 4–6 inches off the floor."],["pt","2. What goes under every roll loaded on a trailer?"],["p","Answer: A rubber mat to prevent shifting."],["pt","3. How do you secure a split load or rear cluster of rolls?"],["p","Answer: Strap it to unitize the load."],["pt","4. Before entering a railcar to unload rolls, what do you check about the rolls?"],["p","Answer: Whether rolls shifted or are leaning in transit. If anything looks unstable, stop and get the lead."],["pt","5. Who verifies every outbound load before it ships?"],["p","Answer: The supervisor or lead — for all loads, no exceptions."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Low, slow, reverse."],["p","4–6 inches up, always reverse with a roll, never lift while moving."],["pt","2. Plan, mat, strap."],["p","Follow the load plan, mat every roll, strap split loads and the rear cluster."],["pt","3. Unstable = stop."],["p","Any leaning, shifted or damaged roll stops the job until the lead clears it."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Travel direction and height with rolls; sharp turns; multiple-roll carries."],["li","Mats and straps on every outbound roll trailer; tandems back; trailer stands."],["p","Reinforce"],["li","Back loaders who hold a trailer to finish it right."],["li","Use real damage claims (without names) at Monday huddles to show cause and effect."],["p","Verify and document"],["li","Every roll load has a completed and supervisor-signed load sheet."],["li","Load-plan binder current for all roll diameters we handle."],["li","Damage claims this month reviewed for root cause and linked to coaching or CAPA."],["li","Clamp operators\\u0027 evaluations current; refresher scheduled for any operator involved in a roll incident."],["h","10. CLOSING MESSAGE"],["call","Every roll that leaves this building carries our name to the customer. Travel it low and slow, load it to the plan, mat it, strap it and verify it. And the moment something looks unstable, stop. Damage is a warning — listen to it before it becomes an injury."],["p","References: PWH-SOP-171 Roll Clamp Truck Operation (Sec. 5.2, 7) • Operator Accountability Policy and Controlled Trailer/Rail Inspection and Load/Unload Sheet • Rules of Safe Operation SOP (Part D.2) • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 10) • PWH-FRM-213-1 • OSHA 29 CFR 1910.178 • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nSeptember 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-09\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the September 2027 company safety meeting: Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading, Common Mistakes."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M10","month":10,"doc":"PWH-MTG-2027-10","title":"Fire Prevention, Emergency Response \\u0026 Electrical Safety","objective":"Every employee knows the ignition controls in a paper warehouse, their evacuation route and assembly point, when (and when not) to use an extinguisher, and the basic electrical rules.","keyMessage":"Paper burns fast. Keep exits, sprinklers and panels clear every shift.","mondays":"4","file":"Part 2 - Monthly Company Meetings/10 October - Fire Prevention, Emergency Response \\u0026 Electrical Safety.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — October 2027\\nIgnition Control · Evacuation \\u0026 Headcount · Extinguishers · Electrical Awareness"]],["tr",["Doc No: PWH-MTG-2027-10\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Fire Prevention, Emergency Response \\u0026 Electrical Safety"],["p","Paper burns fast. Keep exits, sprinklers and panels clear every shift."],["h","1. TRAINING INFORMATION"],["tr",["Month","October 2027 · Monthly meeting 10 of 12"]],["tr",["Training title","Fire Prevention, Emergency Response \\u0026 Electrical Safety"]],["tr",["Target audience","All employees, office staff included"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","OSHA Emergency Action Plan and Fire Prevention Plan review (29 CFR 1910.38, 1910.39); extinguisher training if employees are designated to use them (1910.157(g)); electrical awareness (1910.331–.335)"]],["tr",["Training objective","Every employee knows the ignition controls in a paper warehouse, their evacuation route and assembly point, when (and when not) to use an extinguisher, and the basic electrical rules."]],["tr",["Bring to the meeting","[SITE: evacuation map with routes and assembly points]\\nA portable extinguisher (do not discharge indoors)\\nEmergency Action Plan and Fire Prevention Plan [SITE]\\nOctober 2026 mock fire drill record (crisis test) for lessons learned"]],["tr",["Monday sessions this month","Wk 40 Paper Warehouse Fire Risk · Wk 41 Evacuation \\u0026 Headcount · Wk 42 Fire Extinguishers · Wk 43 Electrical Awareness"]],["p","Safety Measurables — September 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","A paper warehouse is one of the highest fire-load buildings there is. Rolls of paper and pulp stacked high burn hot and spread fire upward fast. Our fire protection depends on sprinklers that need clear space above the stacks, exits that are never blocked, and ignition sources that are controlled every shift."],["p","Our ignition sources are ordinary: propane trucks, battery chargers, dock heaters, damaged cords, hot work by contractors, and smoking where it isn\\u0027t allowed. Most warehouse fires start with one of them and a pile of wrap or dust nearby."],["p","October includes Fire Prevention Week. We ran a mock fire drill in October 2026; this meeting uses what we learned from it."],["h","3. KEY LEARNING POINTS"],["pt","1. Control ignition sources."],["p","No smoking outside designated areas; no flames or sparks within 25 feet of LP or charging areas; hot work only with a permit [SITE]; damaged cords and chargers out of service; trash and wrap off the floor."],["pt","2. Keep fire protection clear."],["p","Stacks at least 5 feet below the ceiling and clear of sprinkler heads; exits, aisles to exits, extinguishers, pull stations and electrical panels never blocked."],["pt","3. Know your route and assembly point."],["p","On the alarm, stop work, shut off and park trucks if safe (do not block aisles or doors), leave by the nearest safe exit, go to [SITE: assembly point], and stay for headcount."],["pt","4. Extinguishers are for small, early fires only."],["p","Only if you\\u0027re trained, the fire is small, you have a clear exit behind you and the alarm has been raised. PASS: Pull, Aim, Squeeze, Sweep. Otherwise, get out."],["pt","5. Electrical basics."],["p","Keep 3 feet clear in front of panels; never use damaged cords or overload outlets; no daisy-chained power strips; report sparks, heat or burning smells immediately; only qualified people open panels."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Ask: \\"If the alarm went off right now, where would you go, and who would count you?\\" Pause. If people hesitate, that\\u0027s why we\\u0027re here."],["p","Why paper fires are different (6 min)"],["p","Stacked paper rolls and pulp bales hold a lot of fuel. Once a fire gets into a stack, it climbs. Sprinklers are designed to hit it from above, which only works if the water can reach it. That\\u0027s why we keep stacks at least 5 feet below the ceiling and clear of the heads."],["p","Most fires start small: a propane leak near a heater, a charger cable arcing, a cigarette in a trash can, sparks from a contractor\\u0027s grinder landing in wrap. Each of those has a rule: no smoking outside designated areas, no flames within 25 feet of LP or charging, hot work only with a permit and fire watch, and damaged cords out of service."],["p","Evacuation and headcount (8 min)"],["p","When the alarm sounds: stop. If you\\u0027re on a truck, lower the load, park out of the aisle and doorway, and shut it off — only if you can do that in a few seconds. Leave by the nearest safe exit. Don\\u0027t go back for anything. Go to [SITE: assembly point] and find your supervisor, who takes headcount from the shift roster [SITE]."],["p","Visitors and drivers go with you to the assembly point. Don\\u0027t re-enter until the fire department or [SITE: incident lead] says it\\u0027s clear."],["p","From our October 2026 mock drill: [SITE: insert one or two lessons learned, e.g., headcount took too long, a dock door exit was blocked]."],["call","DEMO: Hold up the evacuation map. Have each employee point to their nearest exit and their assembly point."],["p","Extinguishers (6 min)"],["p","An extinguisher is for a small fire in its first moments — a trash can, not a stack. Use it only if you\\u0027ve been trained, the alarm has been raised, the fire is smaller than you, and your exit is behind you. PASS: pull the pin, aim at the base of the fire, squeeze the handle, sweep side to side."],["p","If the fire is in a roll stack, spreading, or you\\u0027re not sure, don\\u0027t fight it. Get out and let the sprinklers and fire department do their job. Paper fires grow faster than people expect."],["call","DEMO: Show the extinguisher\\u0027s pin, nozzle and gauge. Do not discharge."],["p","Electrical (4 min)"],["p","Three feet clear in front of every electrical panel, always. Don\\u0027t park trucks or stage product in front of panels. Report damaged cords, cracked plugs, warm outlets, sparks or burning smells immediately and take that equipment out of service. No extension cords as permanent wiring and no power strips plugged into power strips. Only qualified electricians open panels or work on wiring, and it gets locked out first."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The heater and the propane cage."],["p","On a cold morning, someone moves a portable heater near the propane cylinder cage to warm up the dock desk area."],["p","What should have happened: Heat and ignition sources stay well away from LP storage (no flames or sparks within 25 feet). Move the heater, report it, and confirm the cage area is clear."],["pt","2. The blocked exit."],["p","During peak, pallets of empty roll mats are stacked in front of an exit door \\u0027just for the shift\\u0027. A drill alarm sounds and the crew nearest that door has to backtrack through a roll aisle."],["p","What should have happened: Exits and the paths to them are never blocked, even temporarily. Found blocked = cleared immediately and reported."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","What\\u0027s the most likely way a fire would start in this building?"],["li","Where do exits, extinguishers or panels most often get blocked?"],["li","What went wrong or slow in our last fire drill?"],["li","Who on your shift has been trained to use an extinguisher?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. When should you use a fire extinguisher?"],["p","Answer: Only if trained, the alarm has been raised, the fire is small and contained, and you have a clear exit behind you. Otherwise evacuate."],["pt","2. What does PASS stand for?"],["p","Answer: Pull the pin, Aim at the base, Squeeze the handle, Sweep side to side."],["pt","3. How much clearance stays in front of electrical panels?"],["p","Answer: At least 3 feet, always clear."],["pt","4. The alarm sounds while you\\u0027re carrying a roll. What do you do?"],["p","Answer: Lower the roll, park out of the aisle and doorway, shut the truck off if it takes only seconds, then evacuate to your assembly point."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Control it."],["p","No smoking outside designated areas, no flames near LP or chargers, report damaged cords."],["pt","2. Keep it clear."],["p","Exits, extinguishers, panels and sprinkler space — every shift."],["pt","3. Get out and get counted."],["p","Know your route and assembly point; extinguishers only for small fires if trained."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Blocked exits, extinguishers, panels; stacks near sprinkler heads."],["li","Smoking outside designated areas; heaters near LP or wrap."],["p","Reinforce"],["li","Clear any blockage on the spot and explain why."],["li","Run a short walk-through of the evacuation route with new employees."],["p","Verify and document"],["li","Monthly extinguisher visual inspections completed and tagged (1910.157(e))."],["li","Evacuation maps posted and current; assembly points marked."],["li","Emergency Action Plan and Fire Prevention Plan reviewed; [SITE] fire drill held and documented, including headcount time."],["li","Hot-work permits used for all contractor hot work this month."],["h","10. CLOSING MESSAGE"],["call","In a building full of paper, a fire doesn\\u0027t wait for us to figure out where to go. Keep the exits, sprinklers and panels clear, control every ignition source, and know your route and your assembly point. If it\\u0027s bigger than a trash can, get out and get counted."],["p","References: OSHA 29 CFR 1910.36–.39 (Exit routes, EAP, FPP) • OSHA 29 CFR 1910.157 • OSHA 29 CFR 1910.303(g) (working space) • OSHA 29 CFR 1910.331–.335 • MHE Forklift Operation SOP PWH-SOP-229-1 (Sec. 11) • Storage \\u0026 Put Away SOP PWH-SOP-208 • Crisis Management Plan SOP 2.6.4 • [SITE: Emergency Action Plan] • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nOctober 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-10\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the October 2027 company safety meeting: Fire Prevention, Emergency Response \\u0026 Electrical Safety."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M11","month":11,"doc":"PWH-MTG-2027-11","title":"Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense","objective":"Employees store and rotate food-grade product correctly, complete sanitation tasks on schedule, protect temperature-sensitive product, apply food defense and traceability controls, and handle suspect product through the hold process.","keyMessage":"Peak volume never changes the food safety standard.","mondays":"5","file":"Part 2 - Monthly Company Meetings/11 November - Food Safety II.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — November 2027\\nStorage \\u0026 Rotation · Sanitation · Temperature · Food Defense \\u0026 Traceability · Product on Hold"]],["tr",["Doc No: PWH-MTG-2027-11\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"],["p","Peak volume never changes the food safety standard."],["h","1. TRAINING INFORMATION"],["tr",["Month","November 2027 · Monthly meeting 11 of 12"]],["tr",["Training title","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense"]],["tr",["Target audience","All employees in SQF / food-grade storage areas; recommended for all employees"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","SQF Storage \\u0026 Distribution training (PWH-WKI-147-1) and FDA CGMP food hygiene refresher (21 CFR 117.4) — confirm scope with the SQF Practitioner"]],["tr",["Training objective","Employees store and rotate food-grade product correctly, complete sanitation tasks on schedule, protect temperature-sensitive product, apply food defense and traceability controls, and handle suspect product through the hold process."]],["tr",["Bring to the meeting","Master Sanitation Cleaning Schedule 12.2.5\\nFood Defense Plan 2.7.1 summary and Guest Policy 12.3.4\\nA hold tag [SITE]\\nA mock recall or trace test summary from 2026 (lessons only)"]],["tr",["Monday sessions this month","Wk 44 Food-Grade Storage · Wk 45 Sanitation \\u0026 Housekeeping · Wk 46 Temperature-Sensitive Product · Wk 47 Food Defense \\u0026 Traceability · Wk 48 Product on Hold"]],["p","Safety Measurables — October 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","November and December are our heaviest months. Volume goes up, crews are stretched and shortcuts are tempting. That is exactly when food safety systems break: a pallet stored against a wall, a sanitation task skipped, a trailer sealed without the number recorded, a damaged case shipped because the hold area was full."],["p","SQF Edition 10 audits are expected to begin in January 2027, and Edition 10 puts more emphasis on food safety culture: whether the rules hold when we\\u0027re busy. Our 2026 mock recall and trace tests also showed us that traceability only works if every move is scanned and every hold is documented."],["h","3. KEY LEARNING POINTS"],["pt","1. Store it right."],["p","Off the floor on clean pallets, 18-inch inspection perimeter clear along walls, food-grade segregated by SKU and lot/expiration, FEFO/FIFO or customer rotation, every move scanned and synced in the WMS."],["pt","2. Clean on schedule."],["p","Follow the Master Sanitation Cleaning Schedule 12.2.5; sign only for work actually done, on the day it\\u0027s done."],["pt","3. Protect temperature-sensitive product."],["p","Know which SKUs have temperature limits; minimize dock dwell; log and escalate any excursion. [SITE: ambient limits and logging method]."],["pt","4. Food defense."],["p","Seals verified and recorded; trailers locked or monitored; visitors and drivers signed in and escorted per the Guest Policy; challenge anyone unknown; report tampering signs."],["pt","5. Traceability and holds."],["p","Scan every move and sync. Suspect, damaged or recalled product is isolated, tagged, recorded and never shipped until released by the supervisor or SQF Practitioner."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening (2 min)"],["p","Ask: \\"When we\\u0027re slammed in December, what\\u0027s the first food safety rule to slip?\\" Write the answers down. Those are the ones we\\u0027ll watch this month."],["p","Storage (6 min)"],["p","Food-grade product sits on clean, undamaged pallets, never directly on the floor. We keep 18 inches clear along the walls so pest devices can be inspected and the walls can be cleaned. Product is segregated by SKU and lot or expiration, rotated FEFO or FIFO or per the customer, and every move is scanned and synced so we know where every lot is."],["p","During peak, the pressure is to put product anywhere it fits. Don\\u0027t. A pallet against a wall or mixed into another customer\\u0027s location is an audit finding and a traceability failure."],["p","Sanitation (6 min)"],["p","The Master Sanitation Cleaning Schedule tells us what gets cleaned, how often and by whom: weekly, monthly, quarterly, semi-annual and annual tasks. When you complete a task, sign it that day, with the real date and your real name. If a task couldn\\u0027t be done, write that down and tell your supervisor. A blank line we can explain. A signature for work that wasn\\u0027t done can fail an audit."],["p","Housekeeping is part of sanitation: trash out every shift, wrap and pallet debris off the floor, spills cleaned immediately."],["p","Temperature, food defense and traceability (8 min)"],["p","Some of what we store has temperature limits [SITE: which SKUs/customers]. Those loads move from the trailer to storage without sitting on the dock, and storage conditions are monitored and logged [SITE]. If you see a reading out of range or product left on a hot or cold dock, tell your supervisor right away."],["p","Food defense is about deliberate tampering. Seals are checked against paperwork when trailers arrive and recorded when they leave. Visitors and drivers sign in and are escorted. If you see someone you don\\u0027t know in a storage area, ask if you can help them and walk them to the office. Report broken seals, opened packaging or anything that looks tampered with."],["p","Traceability: in a recall, we have to find every case of a lot fast. That only works if every pallet and roll is scanned when it moves. Our 2026 mock recall work showed how much time a few unscanned moves can cost."],["call","ASK THE ROOM: What would make it faster to find every pallet of one lot in this building right now?"],["p","Product on hold (4 min)"],["p","Damaged, contaminated, suspect, temperature-abused or recalled product goes on hold: physically moved to the hold area [SITE], tagged with the date, reason and your name, and recorded. It is never shipped, moved back into stock or thrown away until the supervisor or SQF Practitioner releases or disposes of it per the Non-conformance Product SOP 2.4.4."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The full hold area."],["p","In mid-December the hold area is full, so a damaged pallet is put back in its rack location with a note on the wrap. It\\u0027s picked and shipped the next day."],["p","What should have happened: Hold product is never returned to stock. Expand the hold area or create a temporary marked hold location, tag it, and tell the supervisor. Shipped hold product triggers a customer notification and CAPA."],["pt","2. The unknown visitor."],["p","Second shift sees a man in a hi-vis vest walking through a food-grade aisle. Everyone assumes he\\u0027s a driver or a contractor."],["p","What should have happened: Approach politely: \\"Can I help you find someone?\\" Walk him to the office or dock desk. Verify he\\u0027s signed in per the Guest Policy 12.3.4. Report it if he isn\\u0027t."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Which food safety rule is most likely to slip during peak? How do we protect it?"],["li","Are any sanitation tasks hard to complete on schedule? Why?"],["li","How quickly could we find every pallet of one lot right now?"],["li","Would you feel comfortable challenging someone you don\\u0027t know in a food-grade aisle?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. What goes in the 18 inches along the warehouse walls?"],["p","Answer: Nothing — it stays clear so pest devices and walls can be inspected and cleaned."],["pt","2. You couldn\\u0027t complete a sanitation task today. What do you do?"],["p","Answer: Don\\u0027t sign it. Write down that it wasn\\u0027t done and tell your supervisor."],["pt","3. The hold area is full and you have a damaged pallet. Can you put it back in stock with a note?"],["p","Answer: No. Hold product is never returned to stock. Tell your supervisor to set up a marked hold location."],["pt","4. A trailer arrives with a seal number that doesn\\u0027t match the paperwork. What do you do?"],["p","Answer: Don\\u0027t unload. Tell your supervisor — it\\u0027s a possible tampering or food defense issue."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Store and scan."],["p","Off the floor, off the wall, segregated, rotated, every move scanned and synced."],["pt","2. Clean it, sign it honestly."],["p","Sanitation on schedule, signed the day it\\u0027s done."],["pt","3. Hold means hold."],["p","Suspect product is isolated, tagged and never shipped until released."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Product against walls or on the floor; mixed lots; unscanned moves."],["li","Sanitation sign-offs completed on the actual day; trash removed every shift."],["li","Visitors and drivers in storage areas without escort."],["p","Reinforce"],["li","Recognize employees who hold suspect product even under shipping pressure."],["li","Walk the perimeter with the crew once a week during peak."],["p","Verify and document"],["li","Monthly GMP inspection (PWH-FRM-101-2) completed with management sign-off and findings entered into CAPA."],["li","Master Sanitation Cleaning Schedule complete for the month, with real dates."],["li","Hold area log reconciled: every item tagged, recorded and dispositioned."],["li","One trace test on a random lot completed and timed [SITE]."],["h","10. CLOSING MESSAGE"],["call","Peak season tests whether our food safety is real or just paperwork. Store it right, clean it on schedule and sign it honestly, protect the seals, scan every move, and when something is wrong, hold it. Nothing we ship is worth our customers\\u0027 trust or our certificate."],["p","References: Food Safety \\u0026 Goods Storage Policy 2.2.1 • Master Sanitation WI and Cleaning Schedule 12.2.5 • Food Defense Plan 2.7.1 and Food Defense and Food Fraud SOP 2.7 • Guest Policy 12.3.4 • Product Traceability, Recall \\u0026 Crisis Management SOP 2.6.1 • Disposition of Recalled, Withdrawn and Non-conformance Product SOP 2.4.4 • Storage \\u0026 Put Away SOP PWH-SOP-208 • 21 CFR Part 117 • SQF Food Safety Code: Storage \\u0026 Distribution • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nNovember 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-11\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the November 2027 company safety meeting: Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]},{"code":"M12","month":12,"doc":"PWH-MTG-2027-12","title":"Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset","objective":"Employees recognize and report damaged racking, pallets and unstable stacks, stay clear of maintenance and contractor work, reset their areas to standard, and commit to one safety improvement for 2028.","keyMessage":"Report damage the day you see it. Finish the year the way we started it.","mondays":"4","file":"Part 2 - Monthly Company Meetings/12 December - Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset.docx","blocks":[["tr",["Piper Warehouse Inc.\\nCompany Safety Meeting — December 2027\\nRack \\u0026 Stack Damage · Falling Objects · Working Around Maintenance · 5S Reset · 2028 Commitments"]],["tr",["Doc No: PWH-MTG-2027-12\\nDuration: 40 minutes\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["p","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"],["p","Report damage the day you see it. Finish the year the way we started it."],["h","1. TRAINING INFORMATION"],["tr",["Month","December 2027 · Monthly meeting 12 of 12"]],["tr",["Training title","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset"]],["tr",["Target audience","All employees"]],["tr",["Estimated duration","40 minutes"]],["tr",["Training classification","Awareness + company-specific procedures (OSHA 29 CFR 1910.176(b) secure storage; LOTO awareness 1910.147)"]],["tr",["Training objective","Employees recognize and report damaged racking, pallets and unstable stacks, stay clear of maintenance and contractor work, reset their areas to standard, and commit to one safety improvement for 2028."]],["tr",["Bring to the meeting","Photos of damaged racking/uprights and pallets [SITE]\\nYear-to-date safety scorecard (Part 6) — near misses, observations, CAPA closure, injuries\\nCards or sticky notes for 2028 commitments"]],["tr",["Monday sessions this month","Wk 49 Rack Damage · Wk 50 Pallets, Unstable Loads \\u0026 Falling Objects · Wk 51 Working Around Maintenance \\u0026 Contractors · Wk 52 Year-End 5S Reset"]],["p","Safety Measurables — November 2027 (fill in before the meeting)"],["tr",["______\\nNear misses reported"]],["tr",["______\\nSafety observations completed"]],["tr",["______\\nCorrective actions closed / opened"]],["tr",["______\\nRecordable injuries"]],["h","2. WHY THIS TOPIC MATTERS (5 min)"],["p","Storage fails slowly and then all at once. A rack upright tapped by a truck in March can buckle under load in December. A cracked pallet at the bottom of a triple stack can give way when the stack is bumped. A roll column with one misaligned roll can lean for weeks before it falls."],["p","December also brings outside work: contractors repairing doors, levelers and lights before year-end, and maintenance catching up during slower days. That puts people on lifts and ladders over our heads and energy sources locked out around us."],["p","Finally, this is the last meeting of our 2027 program. We\\u0027ll look at what changed this year — near-miss reporting, observations, corrective actions, injuries — and decide what we commit to next year."],["h","3. KEY LEARNING POINTS"],["pt","1. Any rack contact gets reported — damage isn\\u0027t always visible."],["p","Bent, twisted or cracked uprights, dislodged beams, missing safety clips, damaged base plates or anchors: unload and barricade per supervisor, and report."],["pt","2. Inspect pallets and stacks before lifting or stacking."],["p","Broken boards, missing blocks, protruding nails, leaning or overhanging loads are not lifted or stacked. Pallets triple-stacked only same SKU/expiration and within the yellow lines."],["pt","3. Stay clear of overhead and maintenance work."],["p","Never walk under a raised load, a lift platform or a ladder in use; respect barricades and LOTO; contractors are signed in and escorted."],["pt","4. Reset to standard (5S)."],["p","Sort, Set in order, Shine, Standardize, Sustain: clear aisles and exits, return tools and equipment, clean, re-mark and label."],["pt","5. Commit to one improvement."],["p","Every employee leaves with one specific safety commitment for 2028."],["h","4. FACILITATOR SPEAKING NOTES (15 min) — read aloud or use as your script"],["p","Opening and the year in numbers (6 min)"],["p","Put up the year-to-date scorecard. Read the leading indicators first: \\"This year we reported [SITE] near misses, completed [SITE] safety observations and closed [SITE]% of corrective actions on time.\\" Then the injuries. Thank the crew by name for specific reports or stops that made a difference (with permission)."],["p","Be honest about what didn\\u0027t improve. That\\u0027s where 2028 starts."],["p","Racks and storage (8 min)"],["p","Racks are engineered to hold weight in a specific shape. When an upright gets bent or twisted, even slightly, its capacity drops. You often can\\u0027t see the damage from the aisle. That\\u0027s why any contact gets reported, and why a damaged bay is unloaded and barricaded until it\\u0027s inspected and repaired."],["p","Pallets: before you lift, look at the bottom pallet. Broken deck boards, missing blocks, nails sticking out — don\\u0027t lift it and don\\u0027t stack on it. Our put-away SOP allows triple-stacking only for the same SKU and expiration, stacked upright and within the yellow lines. A leaning pallet gets fixed before you move on."],["p","Rolls: the same rules from May — aligned columns, gaps, height limits, 5 feet below the ceiling."],["call","DEMO: Show photos of a damaged upright and a broken pallet. Ask the crew what they would do with each."],["p","Maintenance and contractors (6 min)"],["p","When maintenance or contractors work, the area is barricaded and energy sources may be locked out. Barricades mean stay out. Never walk under a lift platform, scissor lift, ladder or raised load. Never touch a lock or tag. Contractors sign in and are escorted per our Guest and Contract Service Provider policies, and if someone is working without a barricade over a walkway, stop the work and get a supervisor."],["p","Year-end reset (5 min)"],["p","Before the holidays, we reset every area to standard. Sort: remove what doesn\\u0027t belong. Set in order: everything has a marked place. Shine: clean it. Standardize: fix faded lines and labels. Sustain: keep it that way every shift. Exits, extinguishers, panels and aisles get special attention."],["call","ASK THE ROOM: Write one specific safety commitment for 2028 on your card: one thing you\\u0027ll do, stop or speak up about. We\\u0027ll post them [SITE]."],["h","5. REAL-WORLD WAREHOUSE SCENARIOS (10 min)"],["pt","1. The upright at the aisle end."],["p","A walk-through finds an upright at the end of aisle [SITE] bent about an inch. Nobody remembers hitting it. The bay is full of pallets."],["p","What should have happened: Report immediately. The supervisor has the bay unloaded from the top down and barricaded, and the rack inspected by a qualified person before reloading. Add an end-of-aisle guard if it\\u0027s a repeat hit spot."],["pt","2. The contractor\\u0027s ladder."],["p","A lighting contractor sets a ladder in a main walkway without barricades. Associates walk under and around it all morning."],["p","What should have happened: Stop the work and get the supervisor. Barricade the area, reroute pedestrian traffic, and confirm the contractor is signed in and briefed on site rules."],["h","6. EMPLOYEE ENGAGEMENT — DISCUSSION QUESTIONS"],["li","Where in this building do racks or stacks get hit most often?"],["li","What did we get better at this year? What didn\\u0027t change?"],["li","What\\u0027s one thing management should do differently in 2028 to make this a safer place to work?"],["li","Which Monday session this year changed how you work?"],["h","7. KNOWLEDGE CHECK (5 min) — ask out loud or on the sign-in sheet; record the score"],["pt","1. You tap a rack upright and see no damage. What do you do?"],["p","Answer: Report it the same shift. Rack damage isn\\u0027t always visible; the supervisor decides on inspection and unloading."],["pt","2. Can you stack a pallet on top of a pallet with broken deck boards?"],["p","Answer: No. Damaged pallets aren\\u0027t lifted or stacked; replace or rework them."],["pt","3. A contractor is working on a lift over a walkway with no barricade. What do you do?"],["p","Answer: Stop the work using stop-work authority, keep people clear, and get a supervisor to barricade and reroute."],["pt","4. What are the five S\\u0027s?"],["p","Answer: Sort, Set in order, Shine, Standardize, Sustain."],["h","8. EMPLOYEE TAKEAWAY — THREE THINGS TO DO EVERY SHIFT"],["pt","1. Report storage damage the same day."],["p","Racks, pallets, stacks — any contact, any damage."],["pt","2. Stay out from under."],["p","Never under raised loads, ladders or lift platforms; respect barricades and locks."],["pt","3. Reset and recommit."],["p","Leave your area at standard and keep your 2028 commitment."],["h","9. SUPERVISOR FOLLOW-UP"],["p","Observe"],["li","Damaged racks, missing beam clips, damaged pallets in storage, leaning or overhanging stacks."],["li","Contractor and maintenance work areas: barricades, LOTO, escorts."],["p","Reinforce"],["li","Thank employees who report rack contact — even when they caused it."],["li","Post 2028 commitments and refer to them in January huddles."],["p","Verify and document"],["li","Rack inspection completed for the building [SITE: frequency]; damaged bays unloaded and tagged; repairs scheduled."],["li","5S reset completed in every zone before the holiday shutdown, with before/after photos."],["li","Annual program review (Part 6) scheduled with leadership in January 2028."],["li","All 2027 training records complete and filed in RECORDS 2.2.3."],["h","10. CLOSING MESSAGE"],["call","We started the year by saying every one of us can stop unsafe work. Look at what this team did with that. Finish the year the same way: report what\\u0027s damaged, stay out from under what\\u0027s overhead, leave your area better than you found it, and come back in January ready to do it again. Thank you for keeping each other safe."],["p","References: Storage \\u0026 Put Away SOP PWH-SOP-208 • PWH-SOP-171 (Sec. 6) • Lockout/Tagout Procedure PWH-SOP-207 • Contract Service Providers Policy 2.3.3 • Guest Policy 12.3.4 • Repairs and Maintenance 12.2.1 • OSHA 29 CFR 1910.176(b) • ANSI MH16.1 (storage racks) • Retain the signed sign-in sheet and knowledge-check results as a training record (Training Program PWH-WKI-147-1) in RECORDS 2.2.3. Record the actual date of the meeting; never back-date."],["tr",["Piper Warehouse Inc.\\nCompany Meeting — Sign-In Sheet\\nDecember 2027 Company Safety Meeting"]],["tr",["Doc No: PWH-MTG-2027-12\\nDate: ______________________\\nLocation: ______________________\\nLed by: ______________________"]],["tr",["#","Printed Name","Signature","#","Printed Name","Signature"]],["p","Signing this sheet confirms you attended the December 2027 company safety meeting: Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset."],["p","Meeting led by: __________________________ Signature: ________________________ Date: ____________"],["p","Knowledge check: correct answers: ______ of: ______ Absent employees made up by (date): ____________"]]}],"docs":[{"title":"Part 1 - Executive Summary \\u0026 Calendar","file":"Part 1 - Executive Summary \\u0026 Calendar.docx","blocks":[["tr",["Piper Warehouse Inc.\\n2027 Warehouse Safety \\u0026 Training Program\\nPart 1 — Executive Summary, Objectives \\u0026 Annual Calendar"]],["tr",["Doc No: PWH-SAF-2027-P1\\nEffective: January 4, 2027\\nOwner: Operations Director\\nReview: Annual"]],["p","One standard. Every building. Every shift."],["p","12 company meetings and 52 Monday microtrainings for Indiana, Cincinnati and Atlanta"],["h","1. EXECUTIVE SUMMARY"],["p","Piper Warehouse will run a 64-session safety and training system in calendar year 2027: 12 company-wide monthly meetings (30–45 minutes) and 52 Monday supervisor microtrainings (5–10 minutes), each with its own facilitator handout in the Piper meeting format. The program is built on our own SOPs and forms — PWH-SOP-171 (roll clamp), PWH-SOP-229-1 (MHE forklift), the Rules of Safe Operation, PWH-SOP-207 (LOTO), PWH-FRM-204-1 (near miss), PWH-FRM-MHE-01 (observations), PWH-FRM-101-2 (GEMBA/GMP) and our SQF program — so what we teach is exactly what we audit."],["p","Each month has one theme. The monthly meeting sets the standard and the reason for it. The Monday sessions break that theme into one behavior per week, delivered by the supervisor at shift start and verified on the floor the same shift. The person who assigns the work is the person who sets the safety expectation."],["p","Two tracks get dedicated time because they carry our highest exposure: paper roll clamp handling (May and September, 11 Mondays) and food safety (March and November, 10 Mondays), timed ahead of spring pest season, SQF Edition 10 audits (expected from January 2, 2027) and year-end peak."],["p","Management will judge the program monthly on leading indicators — completion, knowledge checks, observations, near-miss reporting and corrective-action closure — with injuries reported but not used as the primary measure."],["call","AWARENESS IS NOT CERTIFICATION. Monday and monthly sessions reinforce behavior. They never replace OSHA-required powered industrial truck training and hands-on evaluation (29 CFR 1910.178(l); PWH-FRM-213-1), lockout/tagout authorized-employee training, extinguisher hands-on training where employees are designated to use them, or any other formal qualification."],["h","2. ANNUAL TRAINING PROGRAM OBJECTIVES"],["p","Targets marked (calibrate) are starting points; lock them after the January–March 2027 baseline."],["tr",["#","Objective","2027 target","Owner"]],["tr",["1","Deliver every scheduled session","52 of 52 Mondays on every shift; 12 of 12 monthly meetings","Site Ops Manager"]],["tr",["2","Reach every employee","≥95% attendance per monthly meeting; 100% of absentees made up within 14 days","Supervisors"]],["tr",["3","Verify understanding","≥90% first-pass knowledge-check accuracy (calibrate); every miss re-taught same shift","Supervisors"]],["tr",["4","Visible supervisor leadership","≥1 PWH-FRM-MHE-01 observation per supervisor per day (per SOP); monthly GEMBA per site","Site Ops Manager"]],["tr",["5","Surface risk early","Near-miss reports per 100 employees rise vs Q1 baseline, then hold (calibrate)","Safety Lead"]],["tr",["6","Close what we find","≥90% of corrective actions closed by due date; no open high-risk item \\u003e 7 days","Site Ops Manager"]],["tr",["7","Qualifications current","100% of PIT/clamp operators evaluated within 3 years; LOTO authorized list current","Safety Lead + HR"]],["tr",["8","SQF audit-ready records","100% of food-grade employees complete both food safety months; records retrievable in \\u003c 15 minutes; zero back-dated records","SQF Practitioner"]],["h","3. TRAINING CLASSIFICATION"],["tr",["Class","What it is","Examples at Piper","Does a Monday session satisfy it?"]],["tr",["OSHA-required / regulatory","Formal training with content, evaluation or frequency set by a standard","PIT \\u0026 clamp operator training + PWH-FRM-213-1 evaluation; LOTO authorized/affected; HazCom; PPE; EAP review; SQF/CGMP food hygiene","No. Sessions reinforce it; formal records kept separately."]],["tr",["Company-specific","Piper rules beyond the standard or site parameters","Clamp pressure by roll; stack height \\u0026 5 ft ceiling clearance; chock AND restrain every trailer; walkways; load plans","Partly. Communicates the rule; task qualification signed off by trainer."]],["tr",["Awareness","Hazard recognition for everyone","LOTO awareness; heat illness; pest signs; electrical awareness","Yes, with attendance + knowledge check."]],["tr",["Refresher","Re-emphasis of trained content","Monthly PIT, dock, fire and food safety meetings","As refresher only; never replaces a required re-evaluation."]],["h","4. 12-MONTH COMPANY MEETING CALENDAR"],["tr",["Month","Meeting (Doc No)","Objective","Key message","Mon."]],["tr",["January","Safety Leadership Kickoff: Stop-Work Authority, Hazard Recognition \\u0026 Near-Miss Reporting\\nPWH-MTG-2027-01","Every employee can state the stop-work words, explain what a near miss is, and complete or describe the Safety Incident / Near Miss Report (PWH-FRM-204-1) before the meeting ends.","Every one of us has the authority to stop unsafe work. This year we use it.","4"]],["tr",["February","Powered Industrial Truck Fundamentals\\nPWH-MTG-2027-02","Operators can perform a complete pre-shift inspection, explain the stability triangle and tip-over response, apply the core operating rules, and park and refuel/charge correctly. Pedestrians can state the right-of-way and no-walking-under-loads rules.","If you wouldn\\u0027t sign for it, it doesn\\u0027t move. If you can\\u0027t see, you don\\u0027t go.","4"]],["tr",["March","Food Safety I: Contamination Prevention, GMPs \\u0026 Pest Control\\nPWH-MTG-2027-03","Employees can explain how packaged food gets contaminated in a warehouse, follow Piper\\u0027s GMP rules, inspect food-grade receipts, keep chemicals and non-food items segregated, and report pest activity on the Pest Sighting Log 12.2.4.","Our customers\\u0027 food is only as safe as the building it sits in.","5"]],["tr",["April","Pedestrian–Equipment Separation \\u0026 Traffic Management\\nPWH-MTG-2027-04","Every employee follows the site traffic plan: pedestrians use marked walkways and crossings, operators control speed, sound the horn and confirm eye contact, and nobody enters a travel path a truck is using without being seen.","Eye contact before you move. No eye contact, no movement.","4"]],["tr",["May","Paper Roll Clamp Operations I: Equipment, Inspection \\u0026 Handling\\nPWH-MTG-2027-05","Clamp operators can inspect the clamp attachment, set and verify pressure for the roll being handled, pick up and place rolls square and centered, recognize roll damage, and stack to Piper standards.","Squeeze the roll you have, not the roll you think you have.","5"]],["tr",["June","Dock, Trailer \\u0026 Railcar Safety\\nPWH-MTG-2027-06","No trailer or railcar is entered by a truck until it is secured, inspected and properly plated, and every load follows the Controlled Trailer/Rail Inspection and Load/Unload Sheet.","Secured, inspected, plated: then you go in.","4"]],["tr",["July","Heat Stress, Fatigue \\u0026 First Response\\nPWH-MTG-2027-07","Employees recognize heat exhaustion and heat stroke, know the response for each, follow hydration and acclimatization practices, report fatigue without penalty, and know how to report injuries and get help.","Report the symptom early. Heat stroke doesn\\u0027t wait for break time.","4"]],["tr",["August","Ergonomics, Hand Safety \\u0026 Machine Guarding\\nPWH-MTG-2027-08","Employees lift with good mechanics, never stop or steer a rolling roll by hand or foot, keep hands out of pinch points, use the right glove and safety knife, never bypass a guard, and recognize a locked-out machine.","Use the tool, not your hands. Report the ache before it becomes an injury.","5"]],["tr",["September","Paper Roll Clamp Operations II: Travel, Trailer \\u0026 Railcar Loading, Common Mistakes\\nPWH-MTG-2027-09","Clamp operators travel with rolls safely, load and secure roll trailers to plan, unload railcars without roll or car damage, and stop work on any unstable or damaged roll.","Roll damage is a safety warning, not just a claim.","4"]],["tr",["October","Fire Prevention, Emergency Response \\u0026 Electrical Safety\\nPWH-MTG-2027-10","Every employee knows the ignition controls in a paper warehouse, their evacuation route and assembly point, when (and when not) to use an extinguisher, and the basic electrical rules.","Paper burns fast. Keep exits, sprinklers and panels clear every shift.","4"]],["tr",["November","Food Safety II: Storage, Sanitation, Temperature Control \\u0026 Food Defense\\nPWH-MTG-2027-11","Employees store and rotate food-grade product correctly, complete sanitation tasks on schedule, protect temperature-sensitive product, apply food defense and traceability controls, and handle suspect product through the hold process.","Peak volume never changes the food safety standard.","5"]],["tr",["December","Storage Integrity, Maintenance Hazards \\u0026 Year-End Reset\\nPWH-MTG-2027-12","Employees recognize and report damaged racking, pallets and unstable stacks, stay clear of maintenance and contractor work, reset their areas to standard, and commit to one safety improvement for 2028.","Report damage the day you see it. Finish the year the way we started it.","4"]],["p","Total: 12 meetings and 52 Mondays (4 + 4 + 5 + 4 + 5 + 4 + 4 + 5 + 4 + 4 + 5 + 4 = 52). Five-Monday months: March, May, August, November."],["h","5. 52-WEEK MONDAY MICROTRAINING CALENDAR"],["tr",["Wk","Monday","Microtraining (Doc No)","Behavior verified on shift","Track"]],["tr",["1","Jan 4","Your Stop-Work Authority: When and How to Call It\\nPWH-MTR-2027-W01","Find one thing on your shift that should be stopped or fixed — a leaning stack, a missing chock, a blocked exit — and call it out to me before lunch.","—"]],["tr",["2","Jan 11","Hazard Recognition and Near-Miss Reporting in Two Minutes\\nPWH-MTR-2027-W02","Do a three-level scan of your first work area before you start. Report at least one hazard or near miss to me by the end of the shift.","—"]],["tr",["3","Jan 18 *","PPE by Area: What You Wear, Where, and Why\\nPWH-MTR-2027-W03","Before your first task, check your own PPE for damage and make sure you have the task-specific items for anything you\\u0027ll do today.","—"]],["tr",["4","Jan 25","Winter Walking Surfaces: Ice, Snowmelt and Wet Dock Floors\\nPWH-MTR-2027-W04","Check the dock doors in your area at the start of the shift and after every third trailer. Cone and clean any water you find.","—"]],["tr",["5","Feb 1","The Pre-Shift Truck Inspection Done Right\\nPWH-MTR-2027-W05","Complete every line of your Pre-Shift Inspection Form today, including the hour meter and your signature, before the first lift.","PIT"]],["tr",["6","Feb 8","Seat Belts, the Stability Triangle and Tip-Over Response\\nPWH-MTR-2027-W06","Buckle your seat belt every time the truck moves today — including short moves at the dock.","PIT"]],["tr",["7","Feb 15","Leaving a Truck Unattended: Forks Down, Neutral, Brake, Power Off\\nPWH-MTR-2027-W07","Every time you step off your truck today, lower the forks or clamp arms flat to the floor before you leave the seat.","PIT"]],["tr",["8","Feb 22","Battery Charging and Propane Cylinder Changes\\nPWH-MTR-2027-W08","If you change a cylinder or charge a battery today, do it in the designated area with full PPE and the six steps — and I\\u0027ll come watch one.","PIT"]],["tr",["9","Mar 1","Handwashing and Hygiene: When, How, and Why Gloves Aren\\u0027t Enough\\nPWH-MTR-2027-W09","Wash your hands at every trigger point today — especially after breaks and after handling trash or damaged product.","Food"]],["tr",["10","Mar 8","GMP Personal Practices: Food, Drink, Shoes, Personal Items and Illness\\nPWH-MTR-2027-W10","Before you start, clear your truck and work area of any food, drink or personal items and put them in your locker or the break room.","Food"]],["tr",["11","Mar 15","Receiving Food-Grade Loads: Trailer Condition, Damaged Packaging, Odors\\nPWH-MTR-2027-W11","On every food-grade receipt today, complete the trailer inspection sheet before the first pallet comes off.","Food"]],["tr",["12","Mar 22","Cross-Contamination: Chemicals, Non-Food Items and Segregation\\nPWH-MTR-2027-W12","Look above and beside every food-grade location you work in today. Report or move anything that doesn\\u0027t belong there.","Food"]],["tr",["13","Mar 29","Pest Prevention: Signs to Report and Devices You Never Touch\\nPWH-MTR-2027-W13","Before you start moving freight, spend 60 seconds checking the door seals, the floor-to-wall line and behind the first row of pallets in your area. Report anything you find.","Food"]],["tr",["14","Apr 5","Walkways, Crossings and No-Pedestrian Zones\\nPWH-MTR-2027-W14","Walk only in marked walkways today. If you catch yourself leaving one, note where and tell me at end of shift.","—"]],["tr",["15","Apr 12","Speed Limits and the Cross-Aisle Horn Rule\\nPWH-MTR-2027-W15","Sound your horn at every aisle end and doorway today, and keep three truck lengths behind any truck in front of you.","PIT"]],["tr",["16","Apr 19","Eye Contact Before Movement: Communicating With Operators\\nPWH-MTR-2027-W16","Make eye contact with every operator or pedestrian before you move near them today — every time.","—"]],["tr",["17","Apr 26","Blind Corners, Mirrors and Traveling With an Obstructed View\\nPWH-MTR-2027-W17","Travel in reverse whenever a load blocks your view, and sound your horn and check the mirror at every blind corner today.","PIT"]],["tr",["18","May 3","Clamp Attachment Inspection: Pads, Arms, Hoses and Rotation\\nPWH-MTR-2027-W18","Wipe both clamp pads and check hoses, welds and rotation before your first roll today, and note it on your inspection form.","Clamp"]],["tr",["19","May 10","Clamp Pressure: Matching the Setting to the Roll\\nPWH-MTR-2027-W19","Check the pressure chart and your gauge at every grade or diameter change today.","Clamp"]],["tr",["20","May 17","Picking Up a Roll: Squared, Centered, Full Pad Contact\\nPWH-MTR-2027-W20","On every pickup today, stop, square up, center the arms and clamp near the bottom before you lift.","Clamp"]],["tr",["21","May 24","Reading Roll Damage: Out-of-Round, Crushed Cores, Head and Edge Damage\\nPWH-MTR-2027-W21","Look at the core and both ends of every roll you touch today, and report any damage before it goes into storage.","Clamp"]],["tr",["22","May 31 *","Stacking and Storage: Height Limits, Column Stability, Clearances\\nPWH-MTR-2027-W22","Before you set any roll down today, check the floor is clean, the roll will sit perfectly on the one below, and the label will face out at 45°.","Clamp"]],["tr",["23","Jun 7","Trailer Secured Before Entry: Restraint, Chocks and Dock Lights\\nPWH-MTR-2027-W23","Before your first entry into every trailer today, physically check the restraint or chocks and, for drop trailers, the stand.","—"]],["tr",["24","Jun 14","Trailer Floors, Nose Inspection and Dock Plates\\nPWH-MTR-2027-W24","Walk the full length of every trailer before your lift enters it today and check the plate is fully seated.","—"]],["tr",["25","Jun 21","Railcar Safety: Car Stops, Derails, Blue Flags and Bridge Plates\\nPWH-MTR-2027-W25","Before entering any railcar today, personally confirm the blue flag, derail, hand brake, wheel blocks and bridge plate.","Clamp"]],["tr",["26","Jun 28","Heat Inside Trailers and Railcars\\nPWH-MTR-2027-W26","Bring water to the dock today and check on anyone working inside a trailer or railcar near you.","—"]],["tr",["27","Jul 5 *","Heat Illness: Exhaustion vs. Stroke and What to Do\\nPWH-MTR-2027-W27","Know where the cool-down area, ice and the 911 address are before the afternoon heat hits today.","—"]],["tr",["28","Jul 12","Hydration and Acclimatization for New and Returning Workers\\nPWH-MTR-2027-W28","Fill your water bottle before shift start and drink a cup every 15–20 minutes while working the dock or inside trailers.","—"]],["tr",["29","Jul 19","Fatigue: Long Shifts, Overtime and Knowing When You\\u0027re Impaired\\nPWH-MTR-2027-W29","If you feel your attention drifting today, stop and tell me before you take the next load.","—"]],["tr",["30","Jul 26","First Response: Report Every Injury, Find the Kit, Call for Help\\nPWH-MTR-2027-W30","Before you start, walk to the nearest first-aid kit and AED from your work area so you know exactly where they are.","—"]],["tr",["31","Aug 2","Lifting Mechanics: Power Zone, Pivot, Don\\u0027t Twist\\nPWH-MTR-2027-W31","On every manual lift today, get close, bend your knees and pivot your feet instead of twisting.","—"]],["tr",["32","Aug 9","Never Stop a Moving Roll: Manual Roll Handling and Roll Bars\\nPWH-MTR-2027-W32","If you see any roll that looks like it could move — off a mat, on debris, out-of-round — stop and report it before anyone works near it.","Clamp"]],["tr",["33","Aug 16","Pinch Points, Banding and Safety Knives\\nPWH-MTR-2027-W33","Swap any razor blade you carry for a safety knife before you start, and keep your hands out of pinch points all shift.","—"]],["tr",["34","Aug 23","Gloves and Hand Protection: Right Glove, Right Task\\nPWH-MTR-2027-W34","Check that you have the right gloves for every task on your list today, and replace any damaged pair before you start.","—"]],["tr",["35","Aug 30","Machine Guarding and LOTO Awareness: Conveyors, Levelers, Wrappers, Balers\\nPWH-MTR-2027-W35","Before using any powered equipment today, confirm its guards are in place. Report any missing guard immediately.","—"]],["tr",["36","Sep 6 *","Traveling With Rolls: Load Low, Speed, Visibility\\nPWH-MTR-2027-W36","Every trip today: roll 4–6 inches up, reverse, no lifting while moving, no sharp turns.","Clamp"]],["tr",["37","Sep 13","Trailer Loading for Rolls: Pattern, Weight Distribution, Securement\\nPWH-MTR-2027-W37","On every roll trailer today, follow the load plan, mat every roll and strap the rear cluster before calling the lead to verify.","Clamp"]],["tr",["38","Sep 20","Railcar Roll Unloading: Car Condition, Plates and Roll Stability\\nPWH-MTR-2027-W38","Before entering any railcar today, look at the entire load from the plate and confirm every roll is stable.","Clamp"]],["tr",["39","Sep 27","The Top Clamp Operator Mistakes and When to Stop\\nPWH-MTR-2027-W39","If anything about a roll doesn\\u0027t feel right today, stop and call me before you continue.","Clamp"]],["tr",["40","Oct 4","Paper Warehouse Fire Risk: Ignition Sources and Hot Work\\nPWH-MTR-2027-W40","Clear any wrap, paper or trash from around chargers, heaters and lights in your area today.","—"]],["tr",["41","Oct 11","Evacuation Routes, Assembly Points and Headcount\\nPWH-MTR-2027-W41","Walk your primary and backup evacuation routes from your work area before lunch today.","—"]],["tr",["42","Oct 18","Fire Extinguishers: When to Use One and When to Leave\\nPWH-MTR-2027-W42","Find the extinguisher nearest your work area today and make sure nothing is blocking it.","—"]],["tr",["43","Oct 25","Electrical Awareness: Cords, Panels and Chargers\\nPWH-MTR-2027-W43","Check every cord you use today for damage, and make sure nothing is parked or stacked in front of a panel in your area.","—"]],["tr",["44","Nov 1","Food-Grade Storage: Off the Floor, Off the Wall, FIFO/FEFO\\nPWH-MTR-2027-W44","Check every food-grade location you put product in today: off the floor, off the wall, right zone, scanned.","Food"]],["tr",["45","Nov 8","Sanitation and Housekeeping in Food-Grade Zones\\nPWH-MTR-2027-W45","Complete and sign your sanitation tasks today on the day you do them, and leave your area free of trash and debris at shift end.","Food"]],["tr",["46","Nov 15","Temperature-Sensitive Product and Dock Dwell Time\\nPWH-MTR-2027-W46","Put away any temperature-sensitive receipts first today — nothing sensitive sits on the dock.","Food"]],["tr",["47","Nov 22","Food Defense and Traceability: Seals, Access and Lot Control\\nPWH-MTR-2027-W47","Verify the seal on every trailer you open today and record the seal on every trailer you close.","Food"]],["tr",["48","Nov 29","Product on Hold: Suspect Product, Spills and Reporting\\nPWH-MTR-2027-W48","If you find any suspect product today, isolate it, tag it with date, reason and your name, and tell me before you continue.","Food"]],["tr",["49","Dec 6","Rack Damage: What to Look For and How to Report It\\nPWH-MTR-2027-W49","Look at the uprights and beam clips in every aisle you work today and report anything bent, twisted or missing.","—"]],["tr",["50","Dec 13","Pallets, Unstable Loads and Falling Objects\\nPWH-MTR-2027-W50","Check the bottom pallet before every lift today and pull any damaged pallet out of service.","—"]],["tr",["51","Dec 20","Working Around Maintenance and Contractors\\nPWH-MTR-2027-W51","Before you start, ask your lead what maintenance or contractor work is happening in your area today and where to stay clear.","—"]],["tr",["52","Dec 27","Year-End Reset: 5S Housekeeping and Holiday Distraction\\nPWH-MTR-2027-W52","Spend the first 15 minutes of your shift resetting your area to standard — exits and extinguishers first.","—"]],["p","* Site holiday Monday in 2027 (MLK Day Jan 18, Memorial Day May 31, Independence Day observed Jul 5, Labor Day Sep 6). Deliver at the first shift start of that week. Never skip."],["h","6. SITE CUSTOMIZATION BEFORE JANUARY 4"],["li","Clamp pressure chart by roll grade, diameter and weight (manufacturer + customer specs) posted at each clamp truck area"],["li","Stack-height chart by roll size; confirm the 5-ft ceiling clearance and sprinkler clearance in each building"],["li","Dock door list: vehicle restraint vs chock-only doors; light sequence; trailer stand locations"],["li","Rail procedure: serving railroad, blue-flag/derail practice, who places and removes protection"],["li","Traffic plan and floor map: walkways, crossings, speed limit, no-pedestrian zones"],["li","Emergency action plan: assembly points, headcount owner, 911 address, AED/first-aid/eyewash locations"],["li","Heat plan: water stations, cool-down area, rotation triggers and schedule"],["li","Food-grade zone map, pest device map, hold area, temperature-sensitive SKUs and monitoring method"],["li","Add the PWH-MTG-2027 and PWH-MTR-2027 document numbers to the Master List of Controlled Documents (PWH-REF-100)"],["p","References: Every [SITE] marker in the handouts is a site value to fill in before delivery. Highlighted in yellow for easy finding."]]},{"title":"Supervisor Implementation Guide","file":"Part 6 - Implementation, Templates \\u0026 Scorecard/Supervisor Implementation Guide.docx","blocks":[["tr",["Piper Warehouse Inc.\\nSupervisor Implementation Guide\\nPart 6 — Delivery · Documentation · Observation · Accountability · Measurement · Annual Review"]],["tr",["Doc No: PWH-SAF-2027-P6\\nEffective: January 4, 2027\\nOwner: Operations Director\\nReview: Annual"]],["p","How we run the 2027 program"],["p","For supervisors, leads, site managers and the safety and SQF leads"],["p","Your job is not to read a handout. It\\u0027s to change what people do on the floor this shift, prove it with an observation, and fix what you find. This guide shows how."],["h","1. ROLES AND RESPONSIBILITIES"],["tr",["Role","Responsibilities"]],["tr",["Operations Director","Owns the program; approves annual calendar; chairs monthly scorecard review; removes barriers and funds fixes."]],["tr",["Site Operations Manager","Ensures every session is delivered on every shift; reviews attendance, knowledge checks and observations weekly; leads monthly meetings or assigns a facilitator; owns corrective-action closure."]],["tr",["Supervisor / Lead","Delivers every Monday session; runs knowledge checks; re-teaches misses; performs at least one PWH-FRM-MHE-01 observation per day; opens and follows up corrective actions; documents everything the same day."]],["tr",["Safety Lead","Keeps the authorized operator list and evaluation dates; trends near misses and incidents; audits records monthly; updates handouts after incidents or SOP changes."]],["tr",["SQF Practitioner","Owns food safety months; verifies training records meet SQF requirements; links findings to CAPA; confirms scope of 21 CFR 117.4 training."]],["tr",["Every employee","Attends, participates, applies the shift action, uses stop-work authority, reports hazards and near misses the same shift."]],["h","2. HOW TO CONDUCT A MONDAY MICROTRAINING (5–10 MINUTES)"],["pt","1. Prepare (5 min, the Friday before)."],["p","Read the handout. Fill in every [SITE] value. Pick the location (ideally where the hazard is). Have the prop ready if the handout has a SHOW IT."],["pt","2. Open (30 sec)."],["p","Read or paraphrase the Opening Statement. Make eye contact. Start on time — it tells the crew this matters."],["pt","3. Teach (3–5 min)."],["p","Use the speaking notes in your own words. Point at the real thing: the truck, the door, the chart. Keep it about this building."],["pt","4. Ask (1–2 min)."],["p","Ask the engagement question and wait. Silence is fine. Call on someone by name if needed. Write down hazards people raise and assign them."],["pt","5. Check (1 min)."],["p","Ask the knowledge-check question to two or three people. Record how many answered correctly."],["pt","6. Commit (30 sec)."],["p","State Today\\u0027s Safety Action. Tell them you\\u0027ll be watching for it."],["pt","7. Verify (during the shift)."],["p","Do the Supervisor Verification items. Log at least one observation tied to today\\u0027s topic."],["pt","8. Document (same day)."],["p","Sign-in sheet complete, knowledge-check score, re-teach notes, actual date. File per Section 5."],["call","SHIFTS: Every shift gets the same session on the same Monday. When Monday is a site holiday (2027: Jan 18, May 31, Jul 5, Sep 6), deliver at the first shift start that week. A missed session is made up within the same week and documented as a make-up."],["h","3. HOW TO PREPARE FOR AND RUN A MONTHLY MEETING"],["li","One week before: confirm room, time per shift and facilitator; print handouts and sign-in sheets; gather props; fill [SITE] values."],["li","Two days before: fill in the Safety Measurables (previous month\\u0027s near misses, observations, CAPA opened/closed, recordables) from the scorecard."],["li","Day of: start on time; follow the suggested 40-minute agenda (why 5, key points and script 15, scenarios and discussion 10, knowledge check 5, takeaways and close 5)."],["li","After: record attendance and knowledge-check score on the scorecard; list absentees and schedule make-ups within 14 days; log hazards and questions raised as corrective actions with owners."],["li","Spanish delivery: where crews need it, deliver in Spanish or with a bilingual co-facilitator and note the language on the sign-in sheet."],["h","4. MAKING TRAINING ENGAGING (NOT READING A SCRIPT)"],["pt","1. Teach at the hazard."],["p","Hold the session at the dock door, the LP cage, the roll aisle. Adults learn from what they can see and touch."],["pt","2. Use their stories."],["p","Ask for real near misses from this building. A crew member\\u0027s story beats any example in the handout."],["pt","3. Ask, then wait."],["p","Count to five after a question. Then call on someone by name, starting with experienced people to set the tone."],["pt","4. Show it."],["p","One real demonstration (chock placement, PASS, clamp gauge) is worth five minutes of talk."],["pt","5. Keep it short."],["p","Five to ten minutes on Mondays. Stop when the point is made."],["pt","6. Close the loop."],["p","Start each Monday by reporting what was fixed from last week\\u0027s hazards. People speak up when they see results."],["pt","7. Recognize behavior."],["p","Thank people by name for stops, reports and good catches — with their permission."],["h","5. DOCUMENTING ATTENDANCE AND TRAINING RECORDS"],["li","Every session has a signed attendance record: the sign-in page on each handout, or the Monday Roster (Template T1) for multi-shift sites."],["li","Record the actual date, shift, location, facilitator and knowledge-check result. Write the date the training happened — never earlier."],["li","File the original in the site training binder within 24 hours; scan and save to RECORDS 2.2.3 / [SITE path] by the end of the week. Food safety sessions are also logged on the Training Log 2.9.2.3."],["li","Retain records at least three years (Training Program PWH-WKI-147-1), or longer if a customer or regulation requires it."],["li","Make-ups use Template T2 and reference the original session number."],["call","RECORD INTEGRITY. A late or missing record is a fixable gap. A back-dated, pre-signed or re-created record can fail an SQF audit on its own. If a record was missed, leave it blank and write a dated, signed note explaining what happened and when it was corrected. Never sign for someone else, never pre-date, never recreate a record after the fact without labeling it as a re-transcription with the date, source and person."],["h","6. VERIFYING UNDERSTANDING"],["li","Knowledge check every session: ask at least three people (Monday) or the whole room (monthly). Score = correct answers ÷ questions asked."],["li","Ask for the behavior, not the words: \\"Show me where the chocks go\\" beats \\"What\\u0027s the rule for chocks?\\""],["li","Observe within the same shift. Understanding is proven when the behavior shows up on the floor."],["li","Track first-pass accuracy by topic on the scorecard. Under 80% on any topic = re-teach the whole crew next Monday."],["h","7. WHEN AN EMPLOYEE DOESN\\u0027T UNDERSTAND"],["pt","1. Re-teach on the spot, one-on-one."],["p","Different words, then demonstrate. Avoid repeating the same explanation louder."],["pt","2. Check for barriers."],["p","Language, literacy, hearing, new to the job, or the procedure itself is unclear. Use a bilingual lead or the Spanish handout; show instead of tell."],["pt","3. Have them show you."],["p","Ask the employee to perform the behavior while you watch."],["pt","4. Document the re-teach."],["p","Template T6 (Coaching / Re-teach Record) with date, topic and outcome."],["pt","5. Escalate when it\\u0027s a qualification issue."],["p","If it involves operating a truck, the employee does not operate until re-trained and re-evaluated on PWH-FRM-213-1."],["pt","6. Fix the training if many people miss it."],["p","Report to the Safety Lead so the handout or SOP gets clearer."],["h","8. REINFORCING TRAINING THROUGH THE WEEK"],["li","Monday: deliver the session and the shift action."],["li","Tuesday–Thursday: one observation per day focused on that week\\u0027s behavior (PWH-FRM-MHE-01 for operators; Template T3 for general/pedestrian behaviors)."],["li","Mid-week huddle: 60 seconds — \\"Here\\u0027s what I saw yesterday\\" (one good catch, one correction)."],["li","Friday: review the week\\u0027s near misses and corrective actions; pick one to report back on next Monday."],["li","Monthly: GEMBA walk and GMP inspection (PWH-FRM-101-2) with management sign-off, themed on that month\\u0027s topic."],["h","9. CONDUCTING SAFETY OBSERVATIONS"],["pt","1. Plan."],["p","Pick the behavior from this week\\u0027s session and a task where it happens."],["pt","2. Observe 5–10 minutes without interrupting"],["p","unless there is an immediate serious hazard — then stop the work."],["pt","3. Record facts."],["p","What you saw, where, when; safe and at-risk behaviors (PWH-FRM-MHE-01 or Template T3)."],["pt","4. Talk to the employee the same shift."],["p","Start with what they did right. Then the at-risk behavior, the risk, and the expected behavior. Ask what made the at-risk choice easier — that\\u0027s often a process problem."],["pt","5. Act."],["p","Open a corrective action for any condition or process issue (Template T4 / CAPA PWH-FRM-216-1)."],["pt","6. Submit."],["p","Observations go to the Operations Director daily per PWH-FRM-MHE-01 and roll up to the scorecard."],["h","10. TRACKING CORRECTIVE ACTIONS"],["li","Every hazard, near miss, observation finding and audit finding gets a corrective action with a description, owner, due date and risk level."],["li","Due dates by risk: High (could cause serious injury or food safety failure) — make safe immediately, permanent fix within 7 days; Medium — 30 days; Low — 60 days. (Calibrate with the Safety Lead.)"],["li","Log on the Corrective Action Tracking Log (Template T4). Food safety items also go in the CAPA Log 2.5.3."],["li","Close only with evidence: photo, work order, signed re-inspection or observation showing the fix works."],["li","Report back to the person who raised it within 7 days."],["li","Review open items weekly; anything overdue is escalated to the Site Operations Manager."],["h","11. HOLDING EMPLOYEES AND SUPERVISORS ACCOUNTABLE"],["p","Employees"],["li","Coach first: most at-risk behavior is a habit or a process problem, not defiance."],["li","Repeat at-risk behavior after coaching follows the Employee Handbook progressive discipline process. The Operator Accountability Policy applies to loading errors."],["li","Willful violations of life-critical rules (riding forks, walking under loads, removing locks, bypassing guards, operating without authorization) are handled immediately per the Handbook."],["li","Good-faith stop-work, near-miss reports and fatigue reports are never disciplined."],["p","Supervisors and managers"],["li","Measured monthly on: sessions delivered, attendance, knowledge-check follow-up, observations completed, corrective actions closed on time, and records complete."],["li","Reviewed in the monthly Manager Review (Manager Review Follow-Up Template) and the monthly SQF/management review."],["li","Missing sessions or records two months in a row = an action plan with the Operations Director."],["h","12. TRAINING EFFECTIVENESS \\u0026 MEASUREMENT SYSTEM"],["p","Leading indicators drive the scorecard. Lagging indicators (injuries) are reported but not used alone to judge the program. Monthly Safety Performance Scorecard: see Piper_2027_Safety_Scorecard.xlsx."],["tr",["Metric","Formula","Source","Freq.","Owner","Target"]],["tr",["Training completion %","Employees trained (incl. make-ups) ÷ active employees scheduled","Sign-in sheets, T1, T2","Monthly","Site Ops Mgr","100% within 14 days"]],["tr",["Session delivery %","Sessions delivered ÷ sessions scheduled (all shifts)","T1 / scorecard","Weekly","Site Ops Mgr","100%"]],["tr",["Monthly meeting attendance %","Attendees ÷ active employees","Sign-in sheet","Monthly","Supervisors","≥95%"]],["tr",["Employee participation","Hazards / questions raised in sessions ÷ sessions held","T1 notes","Monthly","Supervisors","≥1 per session (calibrate)"]],["tr",["Knowledge-check accuracy","Correct answers ÷ questions asked","T1, sign-in sheets","Monthly","Supervisors","≥90% (calibrate)"]],["tr",["Safety observation completion","Observations completed ÷ required (1/supervisor/day)","PWH-FRM-MHE-01, T3","Weekly","Site Ops Mgr","≥100%"]],["tr",["Near-miss reporting rate","Near-miss reports × 100 ÷ average headcount","PWH-FRM-204-1","Monthly","Safety Lead","Above Q1 baseline"]],["tr",["Corrective action closure %","Actions closed by due date ÷ actions due","T4, CAPA Log 2.5.3","Weekly","Site Ops Mgr","≥90%; 0 high-risk \\u003e 7 days"]],["tr",["Repeat safety violations","Employees with 2+ at-risk observations for same behavior in 90 days","PWH-FRM-MHE-01, T3, T6","Monthly","Safety Lead","Downward trend"]],["tr",["Recordable injury rate (TRIR)","Recordables × 200,000 ÷ hours worked","OSHA 300 log, payroll","Monthly (rolling 12)","Safety Lead","Downward trend (lagging)"]],["tr",["Supervisor engagement","Avg. of delivery %, observation %, CAPA closure % and records-complete % per supervisor","Scorecard","Monthly","Ops Director","≥90%"]],["tr",["Operator qualification currency","Operators with evaluation ≤ 3 yrs ÷ active operators","Authorized operator list, PWH-FRM-213-1","Monthly","Safety Lead","100%"]],["p","TRIR uses the standard OSHA rate formula: (number of recordable cases × 200,000) ÷ total hours worked. 200,000 represents 100 full-time employees working 40 hours per week for 50 weeks."],["p","Scorecard status rules"],["li","Green: at or better than target. Yellow: within 10 points of target or improving two months in a row. Red: more than 10 points below target or worsening two months in a row."],["li","Any Red metric requires a written action with owner and date in the monthly review minutes."],["li","Present the scorecard in the monthly Management \\u0026 SQF Review; keep minutes with management attendance recorded."],["h","13. ANNUAL PROGRAM REVIEW \\u0026 CONTINUOUS IMPROVEMENT"],["p","Hold the annual review in January 2028 using DMAIC, with the Operations Director, Site Operations Managers, Safety Lead, SQF Practitioner and at least two hourly employees from each site."],["pt","1. Define."],["p","Confirm program goals and the CTQs: sessions delivered, behaviors changed, records audit-ready."],["pt","2. Measure."],["p","12-month scorecard trends by site and shift; incident and near-miss data by category (PWH-FRM-204-1 Section 2); audit findings (SQF, customer, internal)."],["pt","3. Analyze."],["p","Pareto of near misses and injuries by category, location and topic; compare knowledge-check scores and observation findings by topic; identify sessions that didn\\u0027t change behavior; root-cause the top three issues."],["pt","4. Improve."],["p","Rewrite weak handouts; move topics to the months where incidents cluster; add sessions for new equipment, layouts, customers or regulations; retire what\\u0027s no longer needed. Update SOPs where training revealed gaps."],["pt","5. Control."],["p","Approve the 2028 calendar; update the Master List of Controlled Documents; set 2028 targets from 2027 actuals; assign owners."],["p","Mid-year and trigger reviews"],["li","Mid-year (July): quick review of Q1–Q2 scorecard and handout feedback; adjust Q3–Q4 sessions if needed."],["li","Triggered review within 30 days of any recordable injury, serious near miss, SQF major finding, new SOP, new equipment type or new building (e.g., the third Atlanta building in 2027)."],["li","Regulatory check: re-verify every OSHA, FDA and SQF reference against the current source each January (eCFR, SQFI). Note: SQF Edition 10 audits are expected from January 2, 2027, pending GFSI benchmarking."],["p","Program quality-control checklist (verified for 2027)"],["li","Exactly 12 monthly company meetings, each with its own handout and sign-in sheet"],["li","Exactly 52 Monday microtrainings mapped to the actual 2027 Mondays; no Monday skipped"],["li","Every session has written speaking notes, a real-world example, an engagement question, a knowledge check with answer and a verification step"],["li","Food safety: 2 monthly meetings + 10 Mondays; paper roll clamp: 2 monthly meetings + 11 Mondays"],["li","Every PIT/clamp session states it is not certification"],["li","Supervisor instructions, documentation templates and a measurable scorecard included"],["p","References: Training Program PWH-WKI-147-1 • Food Safety Culture Policy PWH-POL-122-2 • MHE Forklift Operation SOP PWH-SOP-229-1 • PWH-SOP-171 • PWH-FRM-MHE-01 • PWH-FRM-204-1 • PWH-FRM-101-2 • CAPA PWH-FRM-216-1 and CAPA Policy 2.5.3 • Document Control and Records Policy 2.2.2 • Employee Handbook • OSHA 29 CFR 1904, 1910.178(l)"]]},{"title":"Training Documentation \\u0026 Attendance Templates","file":"Part 6 - Implementation, Templates \\u0026 Scorecard/Training Documentation \\u0026 Attendance Templates.docx","blocks":[["tr",["Piper Warehouse Inc.\\nMonday Microtraining Roster \\u0026 Knowledge Check\\nT1 — one sheet per shift per Monday session"]],["tr",["Form No: PWH-SAF-2027-T1\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["Week # / Title",""]],["tr",["Date delivered (actual)",""]],["tr",["Shift / Location",""]],["tr",["Language(s) used","☐ English ☐ Spanish ☐ Other: ________"]],["tr",["#","Printed Name","Signature","KC ✓/✗","Re-taught?"]],["p","Hazards/questions raised: ____________________________________________________________"],["p","Facilitator: __________________________ Signature: ________________________ Date: ____________"],["tr",["Piper Warehouse Inc.\\nMake-Up Training Record\\nT2 — for employees absent from a scheduled session"]],["tr",["Form No: PWH-SAF-2027-T2\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["Employee","Session missed (Doc No)","Original date","Make-up date","Method","KC result","Trainer"]],["p","Method: one-on-one, next shift huddle, or monthly make-up session. Make-ups within 14 days of the original session."],["tr",["Piper Warehouse Inc.\\nSafety Observation Card — General \\u0026 Pedestrian\\nT3 — use PWH-FRM-MHE-01 for MHE operator observations"]],["tr",["Form No: PWH-SAF-2027-T3\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["Observer / Date / Time",""]],["tr",["Area / Task observed",""]],["tr",["This week\\u0027s Monday topic",""]],["tr",["Employees observed (#)",""]],["tr",["Behavior","Safe","At-risk","N/A","Comment"]],["tr",["PPE correct for area and task","☐","☐","☐",""]],["tr",["Walking in marked walkways / crossings","☐","☐","☐",""]],["tr",["Eye contact with operators before crossing","☐","☐","☐",""]],["tr",["Clear of raised loads and fall zones","☐","☐","☐",""]],["tr",["Lifting in power zone, no twisting","☐","☐","☐",""]],["tr",["Hands clear of pinch points; safety knife used","☐","☐","☐",""]],["tr",["Trailer/railcar secured before entry","☐","☐","☐",""]],["tr",["Exits, extinguishers, panels clear","☐","☐","☐",""]],["tr",["GMP: no food/drink/personal items in storage","☐","☐","☐",""]],["tr",["Dock doors closed when idle","☐","☐","☐",""]],["tr",["Spills/damage handled; hold process followed","☐","☐","☐",""]],["tr",["This week\\u0027s topic behavior: ______________","☐","☐","☐",""]],["p","Feedback given (safe + at-risk): ________________________________________"],["p","Corrective action # (if any): ____________________ Observer signature: ________________________"],["tr",["Piper Warehouse Inc.\\nCorrective Action Tracking Log\\nT4 — hazards, near misses, observation and audit findings"]],["tr",["Form No: PWH-SAF-2027-T4\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["#","Date found","Source","Description / location","Risk H/M/L","Owner","Due","Closed / evidence","Reporter told"]],["p","Source: NM (PWH-FRM-204-1), OBS (PWH-FRM-MHE-01/T3), GEMBA (PWH-FRM-101-2), MTG (training session), AUD (audit). Due: High 7 days (make safe now), Medium 30, Low 60. Food safety items also entered in CAPA Log 2.5.3."],["tr",["Piper Warehouse Inc.\\nMonthly Training Completion Summary\\nT5 — completed by the Site Operations Manager by the 5th of the next month"]],["tr",["Form No: PWH-SAF-2027-T5\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["Session","Scheduled (shifts)","Delivered","Attendees","Active emp.","Attendance %","KC correct / asked","Make-ups due / done"]],["tr",["Monthly meeting","","","","","","",""]],["tr",["Monday wk ___","","","","","","",""]],["tr",["Monday wk ___","","","","","","",""]],["tr",["Monday wk ___","","","","","","",""]],["tr",["Monday wk ___","","","","","","",""]],["tr",["Monday wk ___","","","","","","",""]],["tr",["TOTAL","","","","","","",""]],["p","Observations completed / required: ____________________ Near misses reported: __________"],["p","Corrective actions closed on time / due: ____________________ Recordables: __________"],["p","Site Ops Manager: __________________________ Signature: ______________________ Date: ____________"],["tr",["Piper Warehouse Inc.\\nCoaching / Re-Teach Record\\nT6 — one per employee coaching event"]],["tr",["Form No: PWH-SAF-2027-T6\\nSite: ______________________\\nMonth: ______________________\\nSupervisor: ______________________"]],["tr",["Employee",""]],["tr",["Date / Shift",""]],["tr",["Topic / session (Doc No)",""]],["tr",["What was observed or missed",""]],["tr",["Barrier identified","☐ Language ☐ New to task ☐ Procedure unclear ☐ Equipment/tool ☐ Habit ☐ Other: ______"]],["tr",["How it was re-taught",""]],["tr",["Employee demonstrated correctly?","☐ Yes ☐ No — follow-up date: __________"]],["tr",["Truck operation affected?","☐ No ☐ Yes — removed from truck pending re-training and PWH-FRM-213-1 re-evaluation"]],["tr",["Follow-up observation date / result",""]],["p","Employee signature: ________________________ Supervisor signature: ________________________ Date: ____________"]]}]};`]);

// ===================== views/mhe.js =====================
ATL_SRC.push(['@atl/views/mhe.js', 0, `// MHE Fleet (#/mhe): equipment management for every Piper site. Overview (status at a glance, what needs attention),
// Equipment (find any unit; each has a profile page), Maintenance (work orders: Reported → Under Review → Scheduled →
// In Progress → Completed), Inspections (daily pre-shift, deficiencies, corrective actions), Documents, Reports
// (Excel / PDF), plus the Hours & Service Log, Operators (certifications), Exceptions and the workbook import.
import { store } from '@atl/store.js';
import { esc, fmtNum, fmtPct, fmtMoney, fmtDate, isISO, toast, $, $$, todayISO, norm, num, addDays, downloadXLSX } from '@atl/util.js';
import { chart, chartBox, kpi, barList, ask } from '@atl/ui.js';
import { logBlock, bindLogs, logState, editRow, editors } from '@atl/views/logs.js';
import { derive } from '@atl/calc.js';
import { COLLS, SITES, REGION, SITE_BLDG, config, fleetStats, weeklyHours, operatorPeople, operatorRows, serviceRows, hoursRows, isTruck, assets, readRegister, SERVICE_CATS, planImport, applyImport, planTableHtml,
  CLASSES, UNIT_STATUS, WO_FLOW, PRIORITY, DOC_CATS, DEFAULT_TYPES, equipmentTypes, assetById, needsMaint, workOrderRows, inspectionRows, woOpen, lockText } from '@atl/mhe.js';
import { openAssetForm, openWorkOrder, openInspection, openUpload, openBulkInspections, openLoto, openLotoRelease, openInvoices } from '@atl/views/mheforms.js';
import { renderUnit, bindUnit, woCard, bindWoCards } from '@atl/views/mheunit.js';
import { PRESETS, presetRange, buildReport, sectionHtml, drawReportChart, exportExcel, exportPdf } from '@atl/views/mhereports.js';
import { openDoc, fmtSize } from '@atl/mhedocs.js';
import { openChecklistPrint } from '@atl/views/mhechecklist.js';

const st = { tab: 'dashboard', site: '', eq: { q: '', type: '', cls: '', status: '', maint: '', sort: 'assetId', dir: 1, view: 'list' }, wo: { prio: '', q: '' }, rp: { preset: 'ytd', from: '', to: '' }, doc: { q: '', cat: '' } };
const TABS = [['dashboard', 'Overview'], ['register', 'Equipment'], ['maintenance', 'Maintenance'], ['inspections', 'Inspections'], ['loto', 'Lockout / tagout'], ['documents', 'Documents'], ['reports', 'Reports'],
  ['hours', 'Hours & service log'], ['operators', 'Operators'], ['exceptions', 'Exceptions & pairings'], ['import', 'Settings & import']];
const PRIMARY = 7; // the first seven tabs are the everyday ones; the rest follow a divider
const MAINT_FILTERS = [['', 'Any maintenance status'], ['needs', 'Needs maintenance'], ['openWO', 'Open work order'], ['locked', 'Locked out'], ['pmOverdue', 'PM overdue'], ['pmDue', 'PM due in 14 days'], ['pmNone', 'No PM on record'], ['inspOverdue', 'Inspection overdue'], ['inspNone', 'No inspection on record']];
const maintMatch = (a, m) => !m || (m === 'needs' ? needsMaint(a) : m === 'openWO' ? a.openWO > 0 : m === 'locked' ? a.lockedOut : m === 'pmOverdue' ? a.pmStatus === 'Overdue' : m === 'pmDue' ? a.pmStatus === 'Due in 14 Days' : m === 'pmNone' ? a.pmStatus === 'Not Scheduled' && isTruck(a)
  : m === 'inspOverdue' ? a.inspStatus === 'Overdue' : m === 'inspNone' ? a.inspStatus === 'None on record' : true);

// Rows in the MHE logs open the equipment forms (a unit opens its profile page).
editors.mheAssets = row => { if (row) location.hash = \`#/mhe?tab=unit&id=\${encodeURIComponent(row.assetId || row.id)}\`; else openAssetForm(null, st.site ? { site: st.site } : {}); return true; };
editors.mheWorkOrders = (row, d) => { openWorkOrder(row?.id || null, row ? {} : d); return true; };
editors.mheInspections = (row, d) => { openInspection(row?.id || null, row ? {} : d); return true; };
editors.mheLoto = (row, d) => { openLoto(row?.id || null, row ? {} : d); return true; };
editors.mheService = row => { if (row?.workOrder) { openWorkOrder(row.workOrder); return true; } return false; };
const SITE_COLORS = ['#222b36', '#c0392b', '#c0904d', '#4d6f99', '#1a9e7a', '#7d5ba6', '#9aa3b8'];
const legend = { position: 'bottom', labels: { boxWidth: 12, padding: 14 } };
const dash = v => (v ? fmtNum(v) : '-');
const us = iso => (isISO(iso) ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(2, 4)}\` : esc(iso || ''));
const pill = (text, tone) => \`<span class="pill \${tone}">\${esc(text)}</span>\`;
const certTone = s => (s === 'Expired' ? 'bad' : s === 'Current' ? 'good' : 'warn');
const pmTone = s => (s === 'Overdue' ? 'bad' : s === 'Due in 14 Days' ? 'warn' : s === 'Current' ? 'good' : 'neutral');
const sevTone = s => (s === 'Critical' || s === 'High' ? 'bad' : s === 'Medium' ? 'warn' : 'info');
const siteLabel = s => (SITE_BLDG[s] ? \`\${s} (\${SITE_BLDG[s]})\` : s);
let parsed = null, busy = false;

const head = (title, desc, meta) => \`<div class="xl-dash-head rail-head">
    <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;\${title}</h1><p>\${desc}</p></div>
    <div class="xl-meta">\${meta}<span class="xl-meta-title">MHE Fleet</span></div></div>\`;
const chips = () => \`<nav class="rail-chips mhe-chips" aria-label="MHE Fleet pages">
    \${TABS.filter(([k]) => k !== 'import' || store.can('edit')).map(([k, l], i) => \`\${i === PRIMARY ? '<i class="mhe-chip-sep" aria-hidden="true"></i>' : ''}<a class="rchip\${st.tab === k || (k === 'register' && st.tab === 'unit') ? ' on' : ''}\${i >= PRIMARY ? ' sub' : ''}" href="#/mhe?tab=\${k}"\${st.tab === k ? ' aria-current="page"' : ''}>\${l}</a>\`).join('')}</nav>\`;
// Find any unit from every MHE page, plus the three things people add most.
const actionBar = () => \`<div class="mhe-bar">
    \${st.tab === 'register' ? '' : \`<div class="mhe-find" role="search"><input type="search" data-find placeholder="Find equipment — Asset ID, serial, make, model, type…" aria-label="Find equipment" autocomplete="off"><div class="mhe-hits" data-hits hidden></div></div>\`}
    \${st.tab === 'unit' ? '' : \`<div class="mhe-quick">\${store.can('edit') ? '<button class="btn primary" data-quick="wo">+ Report issue</button><button class="btn" data-quick="insp">+ Inspection</button><button class="btn" data-quick="loto">🔒 Lock out</button><button class="btn" data-quick="asset">+ Add equipment</button>' : ''}<button class="btn" data-mhe-checklist title="Print the weekly Pre-Operational Daily Forklift Checklist for each Atlanta truck, serial numbers filled in (English or Spanish)">🖨 MHE Inspection</button></div>\`}
  </div>\`;
/** Find box: matches as you type (ID first, then serial, make / model, type, site); Enter or click opens the unit. */
function bindFind(root) {
  const inp = $('[data-find]', root), box = $('[data-hits]', root); if (!inp) return;
  let hits = [], on = 0;
  const draw = () => {
    const q = norm(inp.value).trim(); if (!q) { box.hidden = true; return; }
    const qs = q.replace(/\\s+/g, ''), A = assets();
    const score = a => (norm(a.assetId) === q ? 0 : norm(a.assetId).startsWith(q) ? 1 : norm(a.serial).replace(/\\s+/g, '').includes(qs) ? 2 : norm(a.assetId).includes(q) ? 3
      : norm([a.make, a.model, a.family, a.type, a.site, a.operator, a.location].join(' ')).includes(q) ? 4 : 9);
    hits = A.map(a => [a, score(a)]).filter(([, s]) => s < 9).sort((x, y) => x[1] - y[1] || String(x[0].assetId).localeCompare(String(y[0].assetId), undefined, { numeric: true })).slice(0, 8).map(([a]) => a);
    on = 0;
    box.innerHTML = hits.length ? hits.map((a, i) => \`<a href="#/mhe?tab=unit&id=\${encodeURIComponent(a.assetId)}" class="mhe-hit\${i === on ? ' on' : ''}"><b class="mono">\${esc(a.assetId)}</b><span>\${esc([a.family || a.type, [a.make, a.model].filter(Boolean).join(' ')].filter(Boolean).join(' · '))}<small>\${esc(a.site)}\${a.serial ? \` · SN \${esc(a.serial)}\` : ''}</small></span>\${pill(a.status, tn(a.status))}</a>\`).join('')
      : \`<p class="mhe-hit none">No equipment matches “\${esc(inp.value)}”.</p>\`;
    box.hidden = false;
  };
  inp.addEventListener('input', draw);
  inp.addEventListener('focus', draw);
  inp.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); on = (on + (e.key === 'ArrowDown' ? 1 : -1) + hits.length) % Math.max(1, hits.length); $$('.mhe-hit', box).forEach((h, i) => h.classList.toggle('on', i === on)); }
    if (e.key === 'Enter' && hits[on]) { e.preventDefault(); location.hash = \`#/mhe?tab=unit&id=\${encodeURIComponent(hits[on].assetId)}\`; }
    if (e.key === 'Escape') { inp.value = ''; box.hidden = true; }
  });
  if (!bindFind.once) { bindFind.once = true; document.addEventListener('click', e => { if (!e.target.closest('.mhe-find')) $$('[data-hits]').forEach(b => { b.hidden = true; }); }); }
}
const rsSection = (title, body) => \`<section class="card rail-perf"><div class="rs-title">\${title}</div>\${body}</section>\`;
const cell = (label, value, note, cls = '') => \`<div class="rs-cell"><div class="rs-label">\${label}</div><div class="rs-value \${cls}">\${value}</div><div class="rs-note">\${note}</div></div>\`;
const mheChart = (title, id, h, aria, cls = '') => \`<div class="rs-chart \${cls}"><h4>\${title}</h4>\${chartBox(id, h, aria)}</div>\`;
const siteMatch = r => !st.site || r.site === st.site;
const formerIds = () => new Set(operatorRows().filter(o => o.former).map(o => o.id));
const opMatch = o => !st.site || o.building === st.site || (o.building === 'Both (ATL)' && REGION[st.site] === 'Atlanta');

// ---------------------------------------------------------------- dashboard
function topStrip(S) {
  const clamp = S.trucks.filter(a => /clamp truck/i.test(a.family || '') && !/bale/i.test(a.family || '')).length;
  // UX audit: the 4 numbers that need action as tiles; fleet facts as one quiet line under them (was 9 tiles).
  const fact = (label, value, note) => \`<span class="mhe-fact"><b>\${value}</b> \${label}\${note ? \` <small>\${note}</small>\` : ''}</span>\`;
  return \`<div class="rail-strip rail-strip-4">\${[
    cell('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days · \${fmtNum(S.pmNone)} trucks no PM\`, S.pmOverdue.length ? 'down' : ''),
    cell('Open service items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days open\` : 'nothing waiting', S.open.length ? 'warn' : ''),
    cell('Operators certified', fmtNum(new Set(S.opActive.map(o => norm(o.employee))).size), \`\${fmtNum(S.opExpired.length)} expired · \${fmtNum(S.opExpiring.length)} expiring\`, S.opExpired.length ? 'warn' : ''),
    cell('Open critical / high', fmtNum(S.critHigh), \`\${fmtNum(S.openExc.length)} open exceptions · \${fmtNum(S.needAction)} records not verified\`, S.critHigh ? 'warn' : ''),
  ].join('')}</div>
  <div class="mhe-facts">\${[
    fact('assets', fmtNum(S.total), \`\${fmtNum(S.attach)} attachments · \${fmtNum(S.facility)} facility\`),
    fact('powered trucks', fmtNum(S.trucks.length), \`\${fmtNum(clamp)} clamp\`),
    fact('owned outright', S.owned === '' ? 'n/a' : fmtPct(S.owned, 0), ''),
    // "None yet", not $0: no invoice amounts recorded is not the same as spending nothing.
    fact(\`service spend \${todayISO().slice(0, 4)}\`, S.spendYTD ? fmtMoney(S.spendYTD) : 'None yet', S.spendYTD ? '' : 'no invoice amounts recorded'),
    fact('avg hrs / truck / wk', S.avgHrs === '' ? 'n/a' : fmtNum(S.avgHrs, 1), \`\${fmtNum(S.hrsTrucks)} trucks reporting\`),
  ].join('')}</div>\`;
}

function watchlist(S) {
  const pm = [...S.pmOverdue, ...S.pmDue].filter(isTruck).sort((a, b) => String(a.nextPM).localeCompare(String(b.nextPM)));
  // Narrow half-width tables: status second, detail as a small second line (the status column used to be cut off).
  const pmRows = pm.slice(0, 10).map(a => \`<tr><td class="cust"><b>\${esc(a.assetId)}</b><small class="cc-sub">\${esc(a.site)} · \${esc(a.family || a.type || '')}</small></td><td>\${pill(a.pmStatus, pmTone(a.pmStatus))}</td><td>\${us(a.nextPM)}<small class="cc-sub">last \${us(a.lastPM)}</small></td></tr>\`).join('');
  const openRows = S.open.slice(0, 10).map(s => \`<tr><td class="cust"><b>\${esc(s.assetId || s.serial)}</b><small class="cc-sub">\${esc(s.site)} · \${esc(s.category)}</small></td><td><span class="pill \${s.daysOpen > 30 ? 'bad' : 'warn'}">\${fmtNum(s.daysOpen)} days</span></td><td class="cust clip" title="\${esc(s.performed)}"><div class="clip-in">\${esc(s.performed || '')}</div><small class="cc-sub">opened \${us(s.serviceDate)}</small></td></tr>\`).join('');
  const certs = [...S.opExpired, ...S.opExpiring, ...S.opCheck].sort((a, b) => (a.daysToExpiry === '' ? 1e9 : a.daysToExpiry) - (b.daysToExpiry === '' ? 1e9 : b.daysToExpiry));
  const certRows = certs.slice(0, 12).map(o => \`<tr><td class="cust"><b>\${esc(o.employee)}</b><small class="cc-sub">\${esc(o.equipment)} · \${esc(o.building)}</small></td><td>\${pill(o.status === 'Expired' ? \`Expired \${fmtNum(-o.daysToExpiry)} d\` : o.status, certTone(o.status))}</td><td>\${us(o.expires)}</td></tr>\`).join('');
  return \`<div class="rs-pair rs-risk">
    \${rsSection(\`Maintenance watchlist <span class="pill \${pm.length + S.open.length ? 'bad' : 'good'}">\${pm.length + S.open.length ? \`\${pm.length} PM · \${S.open.length} open\` : 'All clear'}</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Truck</th><th>PM status</th><th>Next PM due</th></tr></thead>
      <tbody>\${pmRows || '<tr><td colspan="3">No PMs overdue or due in the next 14 days.</td></tr>'}</tbody></table></div>
      <div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Asset</th><th>Open</th><th class="cust">Service performed</th></tr></thead>
      <tbody>\${openRows || '<tr><td colspan="3">No open service items.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">PM interval \${fmtNum(config().pmInterval)} days from the last Preventive Maintenance in the Service Log. \${S.pmNone ? \`\${fmtNum(S.pmNone)} powered trucks have no PM on record yet (Not Scheduled).\` : ''} <a href="#/mhe?tab=hours">Hours &amp; service ›</a></p>\`)}
    \${rsSection(\`Operator certifications needing action <span class="pill \${certs.length ? 'bad' : 'good'}">\${certs.length ? \`\${certs.length} cert\${certs.length === 1 ? '' : 's'}\` : 'None'}</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Operator</th><th>Status</th><th>Expires</th></tr></thead>
      <tbody>\${certRows || '<tr><td colspan="3">Every certification is current.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">OSHA 1910.178(l): an operator is re-evaluated at least every 3 years. Expiring = within \${fmtNum(config().expiringDays)} days.\${certs.length > 12 ? \` \${certs.length - 12} more on the Operators tab.\` : ''} <a href="#/mhe?tab=operators">Operators ›</a></p>\`)}
  </div>\`;
}

function compositionTable(S) {
  const rows = S.bySite, tot = k => rows.reduce((t, r) => t + r[k], 0);
  const maxT = Math.max(1, ...rows.map(r => r.total));
  const row = (r, isTotal) => \`<tr\${isTotal ? ' class="total"' : ''}><td class="cust">\${isTotal ? 'Total' : \`<a href="#/mhe?tab=register&site=\${encodeURIComponent(r.site)}">\${esc(siteLabel(r.site))}</a>\`}</td><td class="cust">\${isTotal ? '' : esc(r.region)}</td>
    <td class="num">\${dash(r.clamp)}</td><td class="num">\${dash(r.other)}</td><td class="num"><b>\${dash(r.trucks)}</b></td><td class="num">\${dash(r.attach)}</td><td class="num">\${dash(r.facility)}</td>
    <td class="num bar">\${isTotal ? '' : \`<i style="width:\${(r.total / maxT) * 100}%"></i>\`}<span>\${fmtNum(r.total)}</span></td>
    <td class="num">\${dash(r.owned)}</td><td class="num">\${dash(r.lto)}</td><td class="num \${r.unconf && !isTotal ? 'hl' : ''}">\${dash(r.unconf)}</td><td class="num">\${dash(r.rental)}</td><td class="num \${r.notRec && !isTotal ? 'hl' : ''}">\${dash(r.notRec)}</td>
    <td class="num \${r.issues && !isTotal ? 'hl' : ''}">\${dash(r.issues)}</td><td class="num \${r.pmOverdue ? 'neg' : ''}">\${dash(r.pmOverdue)}</td><td class="num">\${r.leaseSpend ? fmtMoney(r.leaseSpend) : '-'}</td></tr>\`;
  const T = { clamp: tot('clamp'), other: tot('other'), trucks: tot('trucks'), attach: tot('attach'), facility: tot('facility'), total: tot('total'), owned: tot('owned'), lto: tot('lto'), unconf: tot('unconf'), rental: tot('rental'), notRec: tot('notRec'), issues: tot('issues'), pmOverdue: tot('pmOverdue'), leaseSpend: tot('leaseSpend') };
  return rsSection('Fleet composition &amp; ownership by site', \`<div class="table-wrap"><table class="perf">
    <thead><tr><th class="cust">Site</th><th class="cust">Region</th><th>Clamp<br>Trucks</th><th>Other<br>Trucks</th><th>Total<br>Trucks</th><th>Attach-<br>ments</th><th>Facility<br>Equip.</th><th>Total<br>Assets</th>
      <th>Owned</th><th>Lease-to-<br>Own</th><th>Owned/LTO<br>Unconfirmed</th><th>Rental</th><th>Not<br>Recorded</th><th>Records<br>w/ Issues</th><th>PM<br>Overdue</th><th>Monthly<br>Lease $</th></tr></thead>
    <tbody>\${rows.map(r => row(r)).join('')}\${row(T, true)}</tbody></table></div>
    <p class="rs-foot">Ownership is for every asset at the site (trucks, attachments, facility). Records w/ Issues = Data Status other than Verified. Monthly lease $ counts active leases with a payment on file.</p>\`);
}

function mixTable(S) {
  const regions = ['Atlanta', 'Indiana', 'Ohio'];
  return rsSection('Equipment mix by region', \`<div class="table-wrap"><table class="perf">
    <thead><tr><th class="cust">Equipment family</th><th class="cust">Class</th>\${regions.map(r => \`<th>\${r}</th>\`).join('')}<th>Total</th></tr></thead>
    <tbody>\${S.mix.map(m => \`<tr><td class="cust">\${esc(m.family)}</td><td class="cust">\${esc(m.cls)}</td>\${regions.map(r => \`<td class="num">\${dash(m[r])}</td>\`).join('')}<td class="num"><b>\${fmtNum(m.total)}</b></td></tr>\`).join('')}
      <tr class="total"><td class="cust">Total</td><td></td>\${regions.map(r => \`<td class="num">\${dash(S.mix.reduce((t, m) => t + m[r], 0))}</td>\`).join('')}<td class="num">\${fmtNum(S.total)}</td></tr></tbody></table></div>\`);
}

function exceptionsAndLeases(S) {
  const sev = ['Critical', 'High', 'Medium', 'Low'];
  const top = [...S.openExc].sort((a, b) => sev.indexOf(a.severity) - sev.indexOf(b.severity) || String(a.id).localeCompare(String(b.id), undefined, { numeric: true })).slice(0, 8);
  const leased = S.A.filter(a => a.leaseStatus);
  return \`<div class="rs-pair">
    \${rsSection(\`Top priorities — open exceptions <span class="pill \${S.critHigh ? 'bad' : 'good'}">\${fmtNum(S.openExc.length)} open</span>\`, \`<div class="mhe-sev">\${sev.map(s => { const n = S.openExc.filter(x => x.severity === s).length; return \`<div class="mhe-sev-cell \${sevTone(s)}"><b>\${fmtNum(n)}</b><span>\${s}</span></div>\`; }).join('')}</div>
      <div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">ID</th><th>Severity</th><th class="cust">Site</th><th class="cust">Issue</th><th class="cust">Owner</th></tr></thead>
      <tbody>\${top.map(x => \`<tr><td class="cust"><b>\${esc(x.id)}</b></td><td>\${pill(x.severity, sevTone(x.severity))}</td><td class="cust">\${esc(x.site)}</td><td class="cust clip" title="\${esc(x.issue)}"><div class="clip-in">\${esc(x.issue)}</div></td><td class="cust">\${esc(x.owner || '')}</td></tr>\`).join('') || '<tr><td colspan="5">No open exceptions.</td></tr>'}</tbody></table></div>
      <p class="rs-foot"><a href="#/mhe?tab=exceptions">All exceptions ›</a></p>\`)}
    \${rsSection('Lease exposure', \`<div class="mhe-sev">
        <div class="mhe-sev-cell info"><b>\${fmtNum(S.leases.length)}</b><span>Active leases</span></div>
        <div class="mhe-sev-cell neutral"><b>\${fmtMoney(S.leaseMonthly)}</b><span>Monthly payments</span></div>
        <div class="mhe-sev-cell neutral"><b>\${fmtMoney(S.leaseRemaining)}</b><span>Remaining obligation</span></div>
        <div class="mhe-sev-cell \${S.leaseMissing ? 'warn' : 'good'}"><b>\${fmtNum(S.leaseMissing)}</b><span>Missing lease data</span></div></div>
      <div class="table-wrap"><table class="perf"><thead><tr><th class="cust">Status</th><th>Units</th><th>Monthly $</th><th>Remaining $</th></tr></thead>
      <tbody>\${['Active', 'Ending in 90 Days', 'Expired - Confirm Buyout', 'Not Started', 'Missing Data'].map(s => { const u = leased.filter(a => a.leaseStatus === s); return u.length ? \`<tr><td class="cust">\${pill(s, s === 'Active' ? 'good' : s === 'Missing Data' || s === 'Ending in 90 Days' ? 'warn' : s === 'Not Started' ? 'info' : 'bad')}</td><td class="num">\${fmtNum(u.length)}</td><td class="num">\${fmtMoney(u.reduce((t, a) => t + (+a.leasePayment || 0), 0))}</td><td class="num">\${fmtMoney(u.reduce((t, a) => t + (+a.leaseRemaining || 0), 0))}</td></tr>\` : ''; }).join('') || '<tr><td colspan="4">No leased units.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">Lease-to-Own, Rental and Unconfirmed units need lessor, contract, start date, term and payment (Fleet register ▸ open a unit). Remaining = payments left + buyout until the lease ends.</p>\`)}
  </div>\`;
}

function drawDashboard(S) {
  const W = weeklyHours(12, st.site);
  chart('ch-mhe-hours', { type: 'bar', data: { labels: W.weeks.map(w => \`\${+w.slice(5, 7)}/\${+w.slice(8, 10)}\`), datasets: W.data.map(d => ({ label: d.site, data: d.values, backgroundColor: SITE_COLORS[Math.max(0, SITES.indexOf(d.site)) % SITE_COLORS.length], stack: 'h', borderRadius: 1 })) },
    options: { plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.y > 0, callbacks: { label: t => \`\${t.dataset.label}: \${fmtNum(t.parsed.y, 1)} hrs\`, footer: it => \`Total \${fmtNum(it.reduce((a, t) => a + t.parsed.y, 0), 1)} hrs\` } } },
      scales: { x: { stacked: true, grid: { display: false }, title: { display: true, text: 'Week ending' } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: 'Hours used' } } } } });
  const own = [['Owned', '#1f4a85'], ['Lease-to-Own', '#5f84b8'], ['Owned/LTO - Unconfirmed', '#c0904d'], ['Rental', '#9db3d3'], ['Not Recorded', '#c0392b']];
  chart('ch-mhe-own', { type: 'bar', data: { labels: S.bySite.map(r => r.site), datasets: own.map(([o, c]) => ({ label: o, data: S.bySite.map(r => S.A.filter(a => a.site === r.site && (o === 'Not Recorded' ? !a.ownership || a.ownership === o : a.ownership === o)).length || null), backgroundColor: c, stack: 'o' })) },
    options: { indexAxis: 'y', plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.x > 0 } }, scales: { x: { stacked: true, beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: 'Assets' } }, y: { stacked: true, grid: { display: false } } } } });
  const svc = serviceRows().filter(siteMatch).filter(s => isISO(s.serviceDate) && +s.amount);
  const months = [...new Set(svc.map(s => s.serviceDate.slice(0, 7)))].sort().slice(-12);
  const cats = SERVICE_CATS.filter(c => svc.some(s => s.category === c));
  chart('ch-mhe-spend', { type: 'bar', data: { labels: months.map(m => new Date(m + '-01T00:00:00Z').toLocaleString('en-US', { month: 'short', year: '2-digit', timeZone: 'UTC' })), datasets: cats.map((c, i) => ({ label: c, data: months.map(m => svc.filter(s => s.category === c && s.serviceDate.startsWith(m)).reduce((t, s) => t + +s.amount, 0) || null), backgroundColor: ['#1f4a85', '#c0392b', '#c0904d', '#1a9e7a', '#7d5ba6', '#9aa3b8'][i % 6], stack: 's' })) },
    options: { plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.y > 0, callbacks: { label: t => \`\${t.dataset.label}: \${fmtMoney(t.parsed.y)}\`, footer: it => \`Total \${fmtMoney(it.reduce((a, t) => a + t.parsed.y, 0))}\` } } },
      scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, ticks: { callback: v => fmtMoney(v) }, title: { display: true, text: 'Invoice $' } } } } });
}

// ---------------------------------------------------------------- tabs
const tiles = list => \`<div class="xl-tiles q" style="grid-template-columns:repeat(\${list.length}, minmax(0, 1fr))">\${list.join('')}</div>\`;
const tile = (label, value, note = '', tone = '') => kpi(label, value, note, tone);

function hoursTab(S) {
  const H = hoursRows().filter(siteMatch), flagged = H.filter(h => h.check !== 'OK' && h.check !== 'Excluded' && h.check !== 'Not used');
  const lastWeek = H.map(h => h.weekEnding).filter(isISO).sort().at(-1) || '';
  const svc = serviceRows().filter(siteMatch), yr = todayISO().slice(0, 4);
  return \`<section class="card rail-sum"><div class="rs-title">Hours log\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Readings', fmtNum(H.length), lastWeek ? \`latest week ending \${us(lastWeek)}\` : 'none yet'), tile('Readings to check', fmtNum(flagged.length), 'End < Start · over max · below prior · unknown serial', flagged.length ? 'warn' : 'good'),
        tile('Avg hours / truck / wk', S.avgHrs === '' ? 'n/a' : fmtNum(S.avgHrs, 1), \`\${fmtNum(S.hrsTrucks)} trucks reporting\`), tile('Trucks with no reading', fmtNum(S.trucks.filter(a => a.hourMeter === '').length), 'powered trucks')])}
      <div class="rail-cust-chart">\${mheChart('Truck hours by week and site (OK readings)', 'ch-mhe-hours', 240, 'Hours used per week, stacked by site')}</div>
      \${flagged.length ? \`<p class="rs-foot"><a href="#" data-show-flagged>Show the \${fmtNum(flagged.length)} reading\${flagged.length === 1 ? '' : 's'} to check ▸</a></p>\` : ''}
      \${store.can('edit') ? '<div class="mhe-pad"><button class="btn primary" data-bulk-hours>+ Enter hours for several units</button> <span class="muted small">One week, one site: every truck in a list — type the end hours and save them together.</span></div>' : ''}</section>
    <section class="card log-card">\${logBlock('mheHours', { stateKey: 'mhe:hours', filter: siteMatch, colFilters: true })}</section>
    <section class="card rail-sum"><div class="rs-title">Service log\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Open items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days open\` : 'nothing waiting', S.open.length ? 'warn' : 'good'), tile('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days · interval \${fmtNum(config().pmInterval)} days\`, S.pmOverdue.length ? 'bad' : 'good'),
        tile(\`Service events \${yr}\`, fmtNum(svc.filter(s => String(s.serviceDate).startsWith(yr)).length), \`\${fmtNum(svc.length)} on file\`), tile(\`Spend \${yr}\`, fmtMoney(S.spendYTD), 'invoice amounts')])}
      <div class="rail-cust-chart">\${mheChart('Service spend by month and category', 'ch-mhe-spend', 240, 'Invoice dollars per month stacked by service category')}</div></section>
    <section class="card log-card">\${logBlock('mheService', { stateKey: 'mhe:service', filter: siteMatch, colFilters: true })}</section>\`;
}

function operatorsTab() {
  // Former employees (not Active on the Employee Roster) are left out unless "Show former employees" is ticked.
  const formerPeople = operatorPeople(true).filter(p => p.certs.every(c => c.former) && p.certs.some(opMatch));
  const people = (st.showFormer ? operatorPeople(true) : operatorPeople()).filter(p => p.certs.some(opMatch));
  const certs = people.filter(p => !p.certs.every(c => c.former)).flatMap(p => p.certs.filter(opMatch));
  const n = s => certs.filter(c => (typeof s === 'function' ? s(c) : c.status === s)).length;
  const step = (label, d) => \`<span class="mhe-step \${isISO(d) ? 'ok' : 'miss'}" title="\${esc(label)}\${isISO(d) ? ' ' + us(d) : ' — not recorded'}"><i>\${isISO(d) ? '✓' : '!'}</i>\${esc(label)}<b>\${isISO(d) ? us(d) : '—'}</b></span>\`;
  const card = p => p.certs.every(c => c.former) ? \`<article class="mhe-op neutral mhe-former">
      <header><div><h3>\${esc(p.name)}</h3><p>\${esc(p.building || 'Not Recorded')} · <span class="mhe-warn">\${esc(p.roster === 'Not on roster' ? 'No record on the Employee Roster' : p.roster)} — former employee</span></p></div>
        <div class="mhe-op-st">\${pill('Former employee', 'neutral')}<small>Not counted in certification warnings</small>
          \${!store.can('edit') ? '' : p.certs.some(c => c.formerBy === 'roster') ? '<small class="muted">Set by the Employee Roster</small>' : \`<button type="button" class="btn ghost small" data-mark-former="\${esc(p.name)}" data-val="N" title="Still works here: show them and count their certifications again">Mark as current employee</button>\`}</div></header>
      \${p.certs.filter(opMatch).map(c => \`<div class="mhe-cert" data-cert="\${esc(c.id)}" tabindex="0" role="button" aria-label="Open \${esc(c.employee)} \${esc(c.equipment)} certification">
        <div class="mhe-cert-h"><b>\${esc(c.equipment || '—')}</b>\${c.certNo ? \`<span class="mono">Cert #\${esc(c.certNo)}</span>\` : ''}<span class="grow"></span><span>Expires \${c.expires ? us(c.expires) : '—'}</span></div></div>\`).join('')}
    </article>\` : \`<article class="mhe-op \${certTone(p.worst)}">
      <header><div><h3>\${esc(p.name)}</h3><p>\${esc(p.building || 'Not Recorded')}\${p.home ? \` · home \${esc(p.home)}\` : ''} · <span class="\${p.roster === 'Active' ? '' : 'mhe-warn'}">\${esc(p.roster === 'Active' ? 'Active on roster' : p.roster)}</span></p></div>
        <div class="mhe-op-st">\${pill(p.worst, certTone(p.worst))}<small>\${p.canOperate.length ? \`Cleared: \${esc(p.canOperate.join(', '))}\` : 'Not cleared to operate'}</small>
          \${store.can('edit') && p.roster !== 'Active' ? \`<button type="button" class="btn ghost small" data-mark-former="\${esc(p.name)}" data-val="Y" title="No longer works here: hide them and stop counting their certifications">Mark as former employee</button>\` : ''}</div></header>
      \${p.certs.filter(opMatch).map(c => \`<div class="mhe-cert" data-cert="\${esc(c.id)}" tabindex="0" role="button" aria-label="Open \${esc(c.employee)} \${esc(c.equipment)} certification">
        <div class="mhe-cert-h"><b>\${esc(c.equipment || '—')}</b>\${c.certNo ? \`<span class="mono">Cert #\${esc(c.certNo)}</span>\` : ''}<span>Trainer: \${c.trainer ? esc(c.trainer) : '<em class="mhe-warn">not recorded</em>'}</span>
          <span class="grow"></span><span>Expires \${c.expires ? us(c.expires) : '—'}\${c.daysToExpiry !== '' ? \` (\${c.daysToExpiry < 0 ? \`\${fmtNum(-c.daysToExpiry)} days ago\` : \`\${fmtNum(c.daysToExpiry)} days\`})\` : ''}</span>\${pill(c.status, certTone(c.status))}</div>
        <div class="mhe-steps">\${c.steps.map(([l, d]) => step(l, d)).join('<span class="mhe-arrow">›</span>')}</div>
        \${c.notes ? \`<p class="mhe-note">\${esc(c.notes)}</p>\` : ''}</div>\`).join('')}
    </article>\`;
  return \`<section class="card rail-sum"><div class="rs-title">Operators &amp; certifications\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Operators', fmtNum(people.length), \`\${fmtNum(certs.length)} certifications on file\`), tile('Cleared to operate', fmtNum(people.filter(p => p.canOperate.length).length), 'at least one current certification', 'good'),
        tile('Expiring', fmtNum(n(c => /^Expiring/.test(c.status))), \`within \${fmtNum(config().expiringDays)} days\`, n(c => /^Expiring/.test(c.status)) ? 'warn' : ''), tile('Expired', fmtNum(n('Expired')), 'retrain and re-evaluate', n('Expired') ? 'bad' : 'good'),
        tile('Dates to check', fmtNum(n(c => c.status === 'Check Dates' || c.status === 'Missing Expiry')), 'expiry missing or on/before the card date', n(c => c.status === 'Check Dates' || c.status === 'Missing Expiry') ? 'warn' : ''),
        tile('Missing prerequisites', fmtNum(certs.filter(c => c.missing.length).length), 'classroom, practical, evaluation, card or trainer not recorded', certs.some(c => c.missing.length) ? 'warn' : '')])}
      <div class="toolbar mhe-op-tools"><input type="search" class="search" placeholder="Search operators…" value="\${esc(st.opQ || '')}" data-op-q aria-label="Search operators">
        <select data-op-st aria-label="Status"><option value="">All statuses</option>\${['Needs action', 'Current', 'Expiring', 'Expired', 'Check Dates', 'Missing Expiry', 'Not on roster'].map(s => \`<option \${st.opSt === s ? 'selected' : ''}>\${s}</option>\`).join('')}</select>
        \${formerPeople.length ? \`<label class="mhe-former-tog"><input type="checkbox" data-show-former \${st.showFormer ? 'checked' : ''}> Show former employees (\${fmtNum(formerPeople.length)})</label>\` : ''}
        <span class="grow"></span>\${store.can('edit') ? '<button class="btn primary" data-add-cert>+ Add certification</button>' : ''}</div>
      <p class="rs-foot">Prerequisites in order: classroom (formal instruction) › practical (hands-on training) › evaluation › certified › card issued. OSHA 1910.178(l) requires a re-evaluation at least every 3 years. Click a certification to edit it. Former employees are hidden and not counted as expired or past due\${formerPeople.length ? \` (\${fmtNum(formerPeople.length)} now)\` : ''}: anyone not Active on the Employee Roster, with no record on it, or marked as former. If someone with no roster record still works here, tick <b>Show former employees</b> and use <b>Mark as current employee</b> on their card.</p></section>
    <div class="mhe-ops">\${people.filter(p => {
      const q = norm(st.opQ || ''); if (q && !norm([p.name, p.building, ...p.certs.map(c => c.equipment + ' ' + c.trainer + ' ' + c.certNo)].join(' ')).includes(q)) return false;
      const s = st.opSt || ''; if (!s) return true;
      if (s === 'Not on roster') return p.roster === 'Not on roster';
      return p.certs.some(c => (s === 'Needs action' ? c.status !== 'Current' || c.missing.length : s === 'Expiring' ? /^Expiring/.test(c.status) : c.status === s));
    }).map(card).join('') || '<p class="muted">No operators match.</p>'}</div>
    <section class="card log-card"><div class="rs-title">Certification log</div>\${logBlock('mheOperators', { stateKey: 'mhe:ops', filter: o => opMatch(o) && (st.showFormer || !formerIds().has(o.id)) })}</section>\`;
}

function exceptionsTab(S) {
  const pairs = S.A.filter(a => isTruck(a) && a.paired).map(a => ({ truck: a, att: S.A.find(x => x.assetId === a.paired) }));
  const unpaired = S.A.filter(a => /attachment/i.test(a.assetClass || '') && !a.paired);
  return \`<section class="card rail-sum"><div class="rs-title">Exceptions\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      <div class="mhe-sev">\${['Critical', 'High', 'Medium', 'Low'].map(s => \`<div class="mhe-sev-cell \${sevTone(s)}"><b>\${fmtNum(S.openExc.filter(x => x.severity === s).length)}</b><span>\${s} open</span></div>\`).join('')}<div class="mhe-sev-cell good"><b>\${fmtNum(S.exc.length - S.openExc.length)}</b><span>Closed</span></div></div></section>
    <section class="card log-card">\${logBlock('mheExceptions', { stateKey: 'mhe:exc', filter: x => !st.site || String(x.site || '').includes(st.site) })}</section>
    \${rsSection(\`Truck ↔ attachment pairings <span class="pill info">\${fmtNum(pairs.length)} pairs</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Truck</th><th class="cust">Truck serial</th><th class="cust">Attachment</th><th class="cust">Attachment serial</th><th class="cust">Site</th><th class="cust">Truck type</th><th class="cust">Attachment size</th><th>Data status</th></tr></thead>
      <tbody>\${pairs.map(({ truck: t, att: a }) => \`<tr><td class="cust"><b>\${esc(t.assetId)}</b></td><td class="cust mono">\${esc(t.serial)}</td><td class="cust"><b>\${esc(t.paired)}</b></td><td class="cust mono">\${esc(a?.serial || '')}</td><td class="cust">\${esc(t.site)}</td><td class="cust">\${esc(t.family || t.type)}</td><td class="cust">\${esc(a?.attachSize || '')}</td><td>\${pill(t.dataStatus || '—', t.dataStatus === 'Verified' ? 'good' : t.dataStatus === 'Conflict' ? 'bad' : 'warn')}</td></tr>\`).join('') || '<tr><td colspan="8">No pairings recorded.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">Pairings come from each unit's Paired Asset (Fleet register).\${unpaired.length ? \` \${fmtNum(unpaired.length)} attachment\${unpaired.length === 1 ? ' is' : 's are'} not paired with a truck.\` : ''}</p>\`)}\`;
}

function importTab() {
  const cfg = config(), have = COLLS.filter(c => c.startsWith('mhe') && c !== 'mheConfig').map(c => [c, store.rows(c).length]);
  const p = parsed;
  return \`\${rsSection('Import the MHE Fleet Register workbook', \`<div class="mhe-pad">
      <p>Drop <b>Piper Logistics - MHE Fleet Register.xlsx</b> (or a newer copy). The app reads the Fleet Register, Lease Schedule, Hours Log, Service Log, Operators and Exceptions sheets. Calculated columns (hour meter, PM dates, statuses, days to expiry …) are worked out by the app, so only the entered data is loaded.</p>
      <label class="wk-drop" data-drop tabindex="0"><input type="file" accept=".xlsx,.xlsm" data-file hidden><b>\${busy ? 'Reading…' : 'Drop the workbook here or click to choose'}</b><small>Nothing is saved until you press Load.</small></label>
      \${p ? \`<p><b>\${esc(p.file)}</b></p>\${planTableHtml(planImport(p))}
        <div class="toolbar"><button class="btn primary" data-load \${busy ? 'disabled' : ''}>Update the app from this file</button><button class="btn ghost" data-cancel>Cancel</button></div>\` : ''}
      <p class="rs-foot">In the app now: \${have.map(([c, nn]) => \`\${{ mheAssets: 'assets', mheHours: 'hour readings', mheService: 'service events', mheOperators: 'certifications', mheExceptions: 'exceptions' }[c]} \${fmtNum(nn)}\`).join(' · ')}.</p></div>\`)}
    \${rsSection('MHE settings', \`<form class="mhe-pad mhe-cfg" data-cfg>
      <label>PM interval (days) <input type="number" name="pmInterval" min="7" max="365" value="\${cfg.pmInterval}"></label>
      <label>Weekly hours flag (hrs / week) <input type="number" name="maxHrsWeek" min="10" max="168" value="\${cfg.maxHrsWeek}"></label>
      <label>Certification "expiring" window (days) <input type="number" name="expiringDays" min="7" max="365" value="\${cfg.expiringDays}"></label>
      <label>PM every (hours, optional) <input type="number" name="pmHours" min="0" max="5000" value="\${esc(cfg.pmHours)}" placeholder="off"></label>
      <label>Inspection overdue after (days without one) <input type="number" name="inspOverdueDays" min="1" max="60" value="\${cfg.inspOverdueDays}"></label>
      <label>Planned inspection every (days) <input type="number" name="planInspDays" min="30" max="1100" value="\${cfg.planInspDays}"></label>
      <label>"Due soon" window (days) <input type="number" name="dueSoonDays" min="7" max="180" value="\${cfg.dueSoonDays}"></label>
      <label>Expected service life (years) <input type="number" name="lifeYears" min="1" max="40" value="\${cfg.lifeYears}"></label>
      <label class="wide">Equipment types (one per line — offered when adding a unit; types already on units are always offered)<textarea name="types" rows="5">\${esc((cfg.types?.length ? cfg.types : DEFAULT_TYPES).join('\\n'))}</textarea></label>
      \${store.can('edit') ? '<button class="btn primary">Save settings</button>' : ''}</form>\`)}\`;
}

// ---------------------------------------------------------------- equipment management pages
const tn = s => ({ 'In Service': 'good', 'Out of Service': 'bad', Retired: 'neutral', Overdue: 'bad', 'Due in 14 Days': 'warn', Current: 'good', 'Not Scheduled': 'neutral', 'None on record': 'warn', 'Not required': 'neutral',
  Critical: 'bad', High: 'bad', Medium: 'warn', Low: 'info', Pass: 'good', 'Pass with deficiencies': 'warn', 'Fail - out of service': 'bad' }[s] || 'neutral');
const unitLink = id => \`<a class="mono" href="#/mhe?tab=unit&id=\${encodeURIComponent(id)}"><b>\${esc(id)}</b></a>\`;
const eqLink = (params, label) => \`#/mhe?tab=register\${st.site ? '&site=' + encodeURIComponent(st.site) : ''}&\${params}\`;
/** A KPI tile that opens the matching list. */
const linkTile = (label, value, note, tone, href) => \`<a class="mhe-kpi \${tone}" href="\${href}"><span>\${label}</span><b>\${value}</b><small>\${note}</small></a>\`;

function overviewTab(S) {
  const act = S.active, avail = act.length ? S.inService.length / act.length : '';
  const certs = S.opExpired.length + S.opExpiring.length + S.opCheck.length, yr = todayISO().slice(0, 4);
  const crit = S.openWO.filter(w => /Critical|High/.test(w.priority)).length;
  const tiles = \`<div class="mhe-kpis">
    \${linkTile('Total equipment', fmtNum(act.length), \`\${fmtNum(S.trucks.filter(a => a.status !== 'Retired').length)} trucks · \${fmtNum(act.length - S.trucks.filter(a => a.status !== 'Retired').length)} attachments &amp; facility\${S.retired.length ? \` · \${fmtNum(S.retired.length)} retired\` : ''}\`, '', eqLink('status='))}
    \${linkTile('In service', fmtNum(S.inService.length), avail === '' ? '' : \`\${fmtPct(avail, 0)} of the fleet available\`, avail !== '' && avail < 0.9 ? 'warn' : 'good', eqLink('status=In Service'))}
    \${linkTile('Out of service', fmtNum(S.outOfService.length), S.outOfService.length ? \`longest \${fmtNum(Math.max(...S.outOfService.map(a => num(a.daysDown))))} days down\` : 'every unit is available', S.outOfService.length ? 'bad' : 'good', eqLink('status=Out of Service'))}
    \${linkTile('Locked out', fmtNum(S.lockedUnits.length), S.lockedUnits.length ? (n => \`\${fmtNum(n)} lock\${n === 1 ? '' : 's'} on\${S.loto.some(l => l.active && l.gaps.length) ? ' · record incomplete' : ''}\`)(S.loto.filter(l => l.active).reduce((t, l) => t + l.locksOn.length, 0)) : 'no lockouts active', S.lockedUnits.length ? 'bad' : 'good', '#/mhe?tab=loto')}
    \${linkTile('Needs maintenance', fmtNum(S.maintUnits.length), \`\${fmtNum(S.openWO.length)} open work order\${S.openWO.length === 1 ? '' : 's'}\${crit ? \` · \${fmtNum(crit)} critical/high\` : ''} · \${fmtNum(S.pmOverdue.length)} PM overdue\`, S.maintUnits.length ? 'warn' : 'good', eqLink('maint=needs'))}
    \${linkTile('PM due in 14 days', fmtNum(S.pmDue.length), \`\${fmtNum(S.pmNone)} trucks have no PM on record\`, S.pmDue.length ? 'warn' : '', eqLink('maint=pmDue'))}
    \${linkTile('Inspections overdue', fmtNum(S.inspOverdue.length), \`\${fmtNum(S.inspNone.length)} of \${fmtNum(S.dailyDue.length)} trucks have none on record\${S.openCA.length ? \` · \${fmtNum(S.openCA.length)} corrective actions open\` : ''}\`, S.inspOverdue.length ? 'bad' : S.inspNone.length ? 'warn' : 'good', '#/mhe?tab=inspections')}
    \${linkTile(\`Maintenance spend \${yr}\`, fmtMoney(S.spendYTD), 'invoices and completed work orders', '', '#/mhe?tab=reports')}
    \${linkTile('Utilization', S.avgHrs === '' ? 'n/a' : \`\${fmtNum(S.avgHrs, 1)} <small>hrs/wk</small>\`, \`avg per truck, last 8 OK weeks · \${fmtNum(S.hrsTrucks)} reporting\`, '', '#/mhe?tab=hours')}
    \${S.valueUnits ? linkTile('Fleet value', fmtMoney(S.fleetValue), \`current value on \${fmtNum(S.valueUnits)} units\${S.replaceValue ? \` · replacement \${fmtMoney(S.replaceValue)}\` : ''}\`, '', '#/mhe?tab=reports') : ''}
    \${linkTile('Operator certifications', fmtNum(certs), certs ? \`\${fmtNum(S.opExpired.length)} expired · \${fmtNum(S.opExpiring.length)} expiring\` : 'all current', S.opExpired.length ? 'bad' : certs ? 'warn' : 'good', '#/mhe?tab=operators')}
  </div>\`;
  const down = [...S.outOfService].sort((a, b) => num(b.daysDown) - num(a.daysDown));
  const downList = down.length ? \`<ul class="mhe-list">\${down.slice(0, 8).map(a => \`<li>\${unitLink(a.assetId)} <span>\${esc(a.family || '')} · \${esc(a.site)}</span><em>\${a.lockedOut ? '🔒 ' : ''}\${esc(a.statusReason || 'no reason given')}</em><b class="pill bad">\${a.daysDown !== '' ? \`\${fmtNum(a.daysDown)} d\` : 'down'}</b></li>\`).join('')}</ul>\${down.length > 8 ? \`<p class="rs-foot"><a href="\${eqLink('status=Out of Service')}">All \${fmtNum(down.length)} ›</a></p>\` : ''}\` : '<p class="mu-ok">✓ Every unit is in service.</p>';
  const woList = S.openWO.length ? \`<ul class="mhe-list">\${S.openWO.slice(0, 8).map(w => \`<li data-wo-open="\${esc(w.id)}" tabindex="0" role="button">\${unitLink(w.assetId)} <span>\${esc(w.issue)}</span><em>\${esc(w.status)}\${w.daysOpen !== '' ? \` · \${fmtNum(w.daysOpen)} d\` : ''}</em>\${pill(w.priority, tn(w.priority))}</li>\`).join('')}</ul>
    <p class="rs-foot"><a href="#/mhe?tab=maintenance">Maintenance board ›</a></p>\` : \`<p class="mu-ok">✓ No open work orders.</p>\${S.legacyOpen.length ? \`<p class="rs-foot">\${fmtNum(S.legacyOpen.length)} open item\${S.legacyOpen.length === 1 ? '' : 's'} on the Service Log. <a href="#/mhe?tab=hours">Service log ›</a></p>\` : ''}\`;
  const due = [...S.inspOverdue.map(a => [a, 'bad', \`No inspection for \${fmtNum(a.daysSinceInsp)} days\`]), ...S.pmOverdue.filter(a => a.status !== 'Retired').map(a => [a, 'bad', \`PM overdue since \${us(a.nextPM)}\`]),
    ...S.openCA.map(i => [assetById(i.assetId) || { assetId: i.assetId }, i.caState === 'Overdue' ? 'bad' : 'warn', \`Corrective action \${i.caState === 'Overdue' ? 'overdue' : 'open'}: \${i.failedItems || i.deficiencies || ''}\`]),
    ...S.pmDue.map(a => [a, 'warn', \`PM due \${us(a.nextPM)}\`]), ...S.plannedDue.map(a => [a, a.plannedStatus === 'Overdue' ? 'bad' : 'warn', \`Planned inspection \${a.plannedStatus === 'Overdue' ? 'overdue' : 'due'} \${us(a.plannedDue)}\`])];
  const dueList = due.length ? \`<ul class="mhe-list">\${due.slice(0, 10).map(([a, t, m]) => \`<li>\${unitLink(a.assetId)} <span>\${esc(a.family || '')}\${a.site ? ' · ' + esc(a.site) : ''}</span><em class="\${t === 'bad' ? 'neg' : ''}">\${esc(m)}</em></li>\`).join('')}</ul>\${due.length > 10 ? \`<p class="rs-foot">\${fmtNum(due.length - 10)} more — <a href="#/mhe?tab=inspections">Inspections ›</a></p>\` : ''}\`
    : \`<p class="mu-ok">✓ No PMs or inspections overdue.</p>\`;
  const noneNote = S.inspNone.length ? \`<p class="rs-foot">\${fmtNum(S.inspNone.length)} truck\${S.inspNone.length === 1 ? ' has' : 's have'} no inspection on record yet. <a href="#/mhe?tab=inspections">Record daily inspections ›</a></p>\` : '';
  const sites = S.bySite.map(r => { const u = act.filter(a => a.site === r.site); return { site: r.site, n: u.length, ins: u.filter(a => a.status === 'In Service').length, out: u.filter(a => a.status === 'Out of Service').length, wo: u.reduce((t, a) => t + a.openWO, 0), pm: u.filter(a => a.pmStatus === 'Overdue').length, insp: u.filter(a => a.inspStatus === 'Overdue').length }; }).filter(r => r.n);
  const maxN = Math.max(1, ...sites.map(r => r.n));
  const siteTable = rsSection('Fleet by warehouse', \`<div class="table-wrap"><table class="perf"><thead><tr><th class="cust">Site</th><th>Units</th><th>In service</th><th>Out of service</th><th>Available</th><th>Open WOs</th><th>PM overdue</th><th>Insp. overdue</th></tr></thead><tbody>
    \${sites.map(r => \`<tr><td class="cust"><a href="#/mhe?tab=register&site=\${encodeURIComponent(r.site)}">\${esc(siteLabel(r.site))}</a></td><td class="num bar"><i style="width:\${(r.n / maxN) * 100}%"></i><span>\${fmtNum(r.n)}</span></td><td class="num">\${fmtNum(r.ins)}</td><td class="num \${r.out ? 'neg' : ''}">\${dash(r.out)}</td><td class="num">\${fmtPct(r.ins / r.n, 0)}</td><td class="num \${r.wo ? 'hl' : ''}">\${dash(r.wo)}</td><td class="num \${r.pm ? 'neg' : ''}">\${dash(r.pm)}</td><td class="num \${r.insp ? 'neg' : ''}">\${dash(r.insp)}</td></tr>\`).join('')}</tbody></table></div>\`);
  const types = [...new Set(act.map(a => a.family || 'Not recorded'))].map(f => [f, act.filter(a => (a.family || 'Not recorded') === f).length]).sort((a, b) => b[1] - a[1]);
  return \`<section class="card mhe-tiles-card">\${tiles}</section>
    <div class="mhe-attn">
      \${rsSection(\`Unavailable equipment <span class="pill \${down.length ? 'bad' : 'good'}">\${fmtNum(down.length)}</span>\`, downList)}
      \${rsSection(\`Open work orders <span class="pill \${S.openWO.length ? 'warn' : 'good'}">\${fmtNum(S.openWO.length)}</span>\`, woList)}
      \${rsSection(\`PM &amp; inspections due <span class="pill \${due.some(d => d[1] === 'bad') ? 'bad' : due.length ? 'warn' : 'good'}">\${fmtNum(due.length)}</span>\`, dueList + noneNote)}
    </div>
    <div class="rs-pair">\${siteTable}\${rsSection('Fleet by type', \`<div class="mhe-pad">\${barList(types, v => fmtNum(v), 14)}</div>\`)}</div>
    \${rsSection('Trends', \`<div class="rs-charts">\${mheChart('Maintenance spend by month and category', 'ch-mhe-spend', 260, 'Invoice dollars per month stacked by service category')}\${mheChart('Truck hours by week and site (OK readings)', 'ch-mhe-hours', 260, 'Hours used per week, stacked by site')}</div>\`)}
    <details class="mhe-detail"><summary>Fleet detail — ownership, leases, equipment mix, operator certifications and register exceptions</summary>
      <section class="card rail-top">\${topStrip(S)}</section>\${watchlist(S)}\${compositionTable(S)}\${mixTable(S)}\${exceptionsAndLeases(S)}
      \${rsSection('Fleet by site and ownership', \`<div class="rs-charts one">\${mheChart('Fleet by site and ownership', 'ch-mhe-own', 280, 'Assets per site stacked by ownership')}</div>\`)}</details>
    <p class="rail-note">Status, work orders and inspections are kept in the app; hours come from the weekly Hours Log (OK readings), PM due dates from the Service Log and completed Preventive Maintenance work orders (\${fmtNum(config().pmInterval)}-day interval, or a unit's own). An inspection is overdue after \${fmtNum(config().inspOverdueDays)} days without one (Settings). Greensboro = building 6021, Fulton = 6049.</p>\`;
}

function equipmentTab(S) {
  const E = st.eq, list = equipmentList(S);
  const types = [...new Set(S.A.map(a => a.family).filter(Boolean))].sort();
  const filtered = E.q || E.type || E.cls || E.status || E.maint || st.site;
  const sel = (key, opts, label) => \`<select data-eq="\${key}" aria-label="\${label}">\${opts.map(([v, l]) => \`<option value="\${esc(v)}" \${E[key] === v ? 'selected' : ''}>\${esc(l)}</option>\`).join('')}</select>\`;
  const cols = [['assetId', 'Equipment'], ['make', 'Make / model'], ['serial', 'Serial #'], ['site', 'Site'], ['status', 'Status'], ['hourMeter', 'Hours'], ['nextPM', 'Next PM'], ['lastInsp', 'Last inspection'], ['openWO', 'Open WOs'], ['purchasePrice', 'Purchase price'], ['monthlyCost', 'Monthly cost'], ['remainingCost', 'Remaining cost'], ['monthlyDep', 'Monthly depreciation']];
  const MONEY = ['purchasePrice', 'monthlyCost', 'remainingCost', 'monthlyDep'], $c = v => (v !== '' && v != null && !isNaN(+v) && String(v).trim() !== '' ? fmtMoney(+v) : '');
  const arrow = k => (E.sort === k ? (E.dir > 0 ? ' ▴' : ' ▾') : '');
  const toolbar = \`<div class="toolbar mhe-eq-tools">
      <input type="search" class="search" data-eq-q value="\${esc(E.q)}" placeholder="Search ID, serial, make, model, operator…" aria-label="Search equipment">
      <select data-eq-site aria-label="Site"><option value="">All sites</option>\${SITES.map(s => \`<option value="\${esc(s)}" \${s === st.site ? 'selected' : ''}>\${esc(siteLabel(s))}</option>\`).join('')}</select>
      \${sel('type', [['', 'All types'], ...types.map(t => [t, t])], 'Type')}\${sel('cls', [['', 'All classes'], ...CLASSES.map(c => [c, c])], 'Class')}
      \${sel('status', [['', 'Active (in + out of service)'], ...UNIT_STATUS.map(s => [s, s]), ['all', 'All, including retired']], 'Status')}\${sel('maint', MAINT_FILTERS, 'Maintenance status')}
      \${filtered ? '<button class="btn ghost small" data-eq-clear>Clear filters ✕</button>' : ''}
      <span class="count" aria-live="polite">\${fmtNum(list.length)} unit\${list.length === 1 ? '' : 's'}</span><span class="grow"></span>
      <div class="mhe-view" role="group" aria-label="View"><button class="btn small \${E.view === 'list' ? 'on' : 'ghost'}" data-eq-view="list">List</button><button class="btn small \${E.view === 'all' ? 'on' : 'ghost'}" data-eq-view="all" title="Every register column, with column filters">All columns</button></div>
      <button class="btn ghost" data-eq-xlsx>⬇ Excel</button></div>\`;
  if (E.view === 'all') return \`<section class="card rail-sum"><div class="rs-title">Equipment — all register columns\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      <div class="mhe-pad mhe-pad-tight">\${toolbar.replace(/<input type="search"[^>]*>/, '').replace(/<select data-eq="(type|cls|status|maint)"[\\s\\S]*?<\\/select>/g, '')}</div>
      \${tiles([tile('Assets', fmtNum(S.total), \`\${fmtNum(S.trucks.length)} trucks · \${fmtNum(S.attach)} attachments\`), tile('Verified records', fmtNum(S.total - S.needAction), \`\${fmtNum(S.needAction)} conflict / incomplete / unverified\`, S.needAction ? 'warn' : 'good'),
        tile('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days\`, S.pmOverdue.length ? 'bad' : 'good'), tile('Open service items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days\` : '', S.open.length ? 'warn' : ''), tile('Active leases', fmtNum(S.leases.length), \`\${fmtNum(S.leaseMissing)} missing lease data\`)])}
      <p class="rs-foot">Click a unit to open its profile. Filter any column in the row under the headings. Hour meter, PM dates, open items and lease status calculate from the logs.</p></section>
    <section class="card log-card">\${logBlock('mheAssets', { stateKey: 'mhe:assets', filter: siteMatch, colFilters: true, canAdd: false })}</section>\`;
  return \`<section class="card mhe-eq">\${toolbar}
    \${list.length ? \`<div class="table-wrap"><table class="grid mhe-eq-table"><thead><tr>\${cols.map(([k, l]) => \`<th data-eq-sort="\${k}" tabindex="0" role="button" class="\${['hourMeter', 'openWO', ...MONEY].includes(k) ? 'num' : ''}">\${l}\${arrow(k)}</th>\`).join('')}</tr></thead><tbody>
      \${list.slice(0, st.eqLimit || 300).map(a => \`<tr class="clickable" tabindex="0" data-unit="\${esc(a.assetId)}">
        <td data-l="Equipment"><b class="mono">\${esc(a.assetId)}</b><small>\${esc(a.family || a.assetClass || '')}</small></td>
        <td data-l="Make / model">\${esc([a.make, a.model].filter(Boolean).join(' ')) || '<span class="muted">—</span>'}</td><td data-l="Serial #" class="mono">\${esc(a.serial || '') || '<span class="mhe-warn">none</span>'}</td>
        <td data-l="Site">\${esc(a.site)}</td><td data-l="Status">\${pill(a.status, tn(a.status))}\${a.lockedOut ? ' <span class="pill bad" title="Locked out">🔒</span>' : ''}\${a.status === 'Out of Service' && a.daysDown !== '' ? \` <small>\${fmtNum(a.daysDown)} d</small>\` : ''}</td>
        <td data-l="Hours" class="num">\${a.hourMeter !== '' ? fmtNum(a.hourMeter, 0) : ''}</td>
        <td data-l="Next PM">\${isTruck(a) || a.nextPM ? \`\${a.nextPM ? us(a.nextPM) + ' ' : ''}\${a.pmStatus !== 'Current' ? pill(a.pmStatus === 'Due in 14 Days' ? 'Due soon' : a.pmStatus === 'Not Scheduled' ? 'None' : a.pmStatus, tn(a.pmStatus)) : ''}\` : ''}</td>
        <td data-l="Last inspection">\${a.lastInsp ? us(a.lastInsp) + ' ' : ''}\${a.inspStatus === 'Overdue' || (a.inspStatus === 'None on record') ? pill(a.inspStatus === 'Overdue' ? 'Overdue' : 'None', tn(a.inspStatus)) : a.lastInspResult && a.lastInspResult !== 'Pass' ? pill(a.lastInspResult.replace(' - out of service', ''), tn(a.lastInspResult)) : ''}</td>
        <td data-l="Open WOs" class="num">\${a.openWO ? pill(String(a.openWO), tn(a.worstPriority)) : ''}</td>
        <td data-l="Purchase price" class="num">\${$c(a.purchasePrice)}</td><td data-l="Monthly cost" class="num">\${$c(a.monthlyCost)}</td>
        <td data-l="Remaining cost" class="num">\${$c(a.remainingCost)}</td><td data-l="Monthly depreciation" class="num" title="\${a.monthlyDep === 0 ? 'Fully depreciated' : ''}">\${a.monthlyDep === 0 ? '<small class="muted">fully dep.</small>' : $c(a.monthlyDep)}</td></tr>\`).join('')}</tbody>
      \${(t => \`<tfoot><tr><td colspan="\${cols.length - 4}"><b>Total (\${fmtNum(list.length)} units)</b></td>\${MONEY.map(k => \`<td class="num"><b>\${fmtMoney(t[k])}</b></td>\`).join('')}</tr></tfoot>\`)(Object.fromEntries(MONEY.map(k => [k, list.reduce((s, a) => s + num(a[k]), 0)])))}</table></div>
      \${list.length > (st.eqLimit || 300) ? \`<div class="more"><button class="btn ghost" data-eq-more>Show all \${fmtNum(list.length)}</button></div>\` : ''}\`
    : \`<p class="mhe-pad muted">No equipment matches these filters. <button class="btn ghost small" data-eq-clear>Clear filters</button></p>\`}
    <p class="rs-foot">Click a unit to open its profile — specs, status, maintenance and inspection history, documents and metrics. <b>All columns</b> shows every register field with filters on each column.</p></section>\`;
}
function equipmentList(S) {
  const E = st.eq, q = norm(E.q).replace(/\\s+/g, ' ');
  const rows = S.A.filter(a => (E.status === 'all' ? true : E.status ? a.status === E.status : a.status !== 'Retired') && (!E.type || a.family === E.type) && (!E.cls || a.assetClass === E.cls) && maintMatch(a, E.maint)
    && (!q || norm([a.assetId, a.serial, a.make, a.model, a.family, a.type, a.site, a.location, a.department, a.operator, a.fleetUnit, a.notes].join(' ')).includes(q) || norm(a.serial).replace(/\\s+/g, '').includes(q.replace(/\\s+/g, ''))));
  const k = E.sort, d = E.dir;
  return rows.sort((x, y) => { const a = x[k] ?? '', b = y[k] ?? ''; const c = typeof a === 'number' && typeof b === 'number' ? a - b : a === '' && b !== '' ? 1 : b === '' && a !== '' ? -1 : String(a).localeCompare(String(b), undefined, { numeric: true }); return c * d || String(x.assetId).localeCompare(String(y.assetId), undefined, { numeric: true }); });
}

function maintenanceTab(S) {
  const W = S.wos, F = st.wo, q = norm(F.q);
  const match = w => (!F.prio || w.priority === F.prio) && (!q || norm([w.id, w.assetId, w.issue, w.provider, w.category, w.family].join(' ')).includes(q));
  const since = addDays(todayISO(), -30), yr = todayISO().slice(0, 4);
  const col = s => W.filter(w => w.status === s && match(w) && (s !== 'Completed' || String(w.completedDate) >= since));
  const done = W.filter(w => w.status === 'Completed' && String(w.completedDate) >= since);
  const ytd = W.filter(w => w.status === 'Completed' && String(w.completedDate).startsWith(yr));
  const withEst = ytd.filter(w => w.estCost !== '' && w.estCost != null && w.actualCost !== '' && w.actualCost != null);
  return \`<section class="card rail-sum"><div class="rs-title">Maintenance work orders\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Open work orders', fmtNum(S.openWO.length), \`\${fmtNum(S.openWO.filter(w => w.status === 'Reported').length)} new · \${fmtNum(S.openWO.filter(w => w.status === 'In Progress').length)} in progress\`, S.openWO.length ? 'warn' : 'good'),
        tile('Critical / high', fmtNum(S.openWO.filter(w => /Critical|High/.test(w.priority)).length), 'open, by priority', S.openWO.some(w => /Critical|High/.test(w.priority)) ? 'bad' : 'good'),
        tile('Units out of service', fmtNum(S.outOfService.length), (n => \`\${fmtNum(n)} work order\${n === 1 ? '' : 's'} holding a unit down\`)(S.openWO.filter(w => norm(w.downtime) === 'Y').length), S.outOfService.length ? 'bad' : 'good'),
        tile('Past scheduled date', fmtNum(S.openWO.filter(w => w.late).length), 'scheduled but not finished', S.openWO.some(w => w.late) ? 'warn' : ''),
        tile('Completed (30 days)', fmtNum(done.length), done.length ? \`avg \${fmtNum(done.reduce((t, w) => t + num(w.daysOpen), 0) / done.length, 1)} days to close\` : ''),
        tile(\`Actual cost \${yr}\`, fmtMoney(ytd.reduce((t, w) => t + num(w.actualCost), 0)), withEst.length ? (v => \`\${fmtMoney(Math.abs(v))} \${v > 0 ? 'over' : v < 0 ? 'under' : 'on'} estimate (\${fmtNum(withEst.length)} with both)\`)(withEst.reduce((t, w) => t + num(w.actualCost) - num(w.estCost), 0)) : 'completed work orders')])}
      <div class="toolbar mhe-pad-tight"><input type="search" class="search" data-wo-q value="\${esc(F.q)}" placeholder="Search work orders…" aria-label="Search work orders">
        <select data-wo-prio aria-label="Priority"><option value="">All priorities</option>\${PRIORITY.map(p => \`<option \${F.prio === p ? 'selected' : ''}>\${p}</option>\`).join('')}</select>
        <span class="grow"></span>\${store.can('edit') ? '<button class="btn primary" data-quick="wo">+ Report issue / maintenance</button>' : ''}</div>
      \${store.can('edit') ? \`<div class="mhe-pad mhe-pad-tight"><div class="wk-drop mf-drop inv-drop" data-inv-drop tabindex="0" role="button"><b>⬆ Drop invoices here — PMs, repairs &amp; work</b><span>PDF invoices are read and matched to the unit by serial number. A repair closes the unit's open work order with the provider, actual cost and completion date; a PM closes the open PM line or logs a completed PM. You review everything before it is saved.</span></div></div>\` : ''}
      <div class="wo-board">\${WO_FLOW.map(s => { const c = col(s); return \`<div class="wo-col" data-col="\${esc(s)}"><h4>\${esc(s)} <span>\${fmtNum(c.length)}</span>\${s === 'Completed' ? '<small>last 30 days</small>' : ''}</h4>\${c.slice(0, 12).map(w => woCard(w, { showUnit: true })).join('') || '<p class="wo-empty">None</p>'}\${c.length > 12 ? \`<p class="wo-empty">\${fmtNum(c.length - 12)} more in the list below</p>\` : ''}</div>\`; }).join('')}</div>
      <p class="rs-foot">Click a card to open it; <b>Move to …</b> takes it to the next step (Completed asks for the cost). A work order marked "takes the unit out of service" keeps the unit Out of Service until it is completed or cancelled. Every work order also appears in the Service Log, so completed Preventive Maintenance sets each unit's next PM date.</p></section>
    <section class="card log-card"><div class="rs-title">All work orders</div>\${logBlock('mheWorkOrders', { stateKey: 'mhe:wo', filter: siteMatch, colFilters: true })}</section>
    <p class="rail-note">Older PMs, repairs and invoices from the workbook are in the <a href="#/mhe?tab=hours">Service Log</a>.</p>\`;
}

function inspectionsTab(S) {
  const since = addDays(todayISO(), -30), I = S.insp, recent = I.filter(i => i.date >= since);
  const cov = S.dailyDue.length ? S.inspCurrent.length / S.dailyDue.length : '';
  const lst = (arr, f) => arr.length ? \`<ul class="mhe-list">\${arr.slice(0, 12).map(f).join('')}</ul>\${arr.length > 12 ? \`<p class="rs-foot">\${fmtNum(arr.length - 12)} more</p>\` : ''}\` : '<p class="mu-ok">✓ None.</p>';
  const inspBtn = a => (store.can('edit') ? \`<button class="btn ghost small" data-insp-unit="\${esc(a.assetId)}">Inspect</button>\` : '');
  return \`<section class="card rail-sum"><div class="rs-title">Inspections &amp; safety\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Trucks needing daily inspection', fmtNum(S.dailyDue.length), 'powered trucks in service'),
        tile('Inspected on time', cov === '' ? 'n/a' : fmtPct(cov, 0), \`\${fmtNum(S.inspCurrent.length)} trucks within \${fmtNum(config().inspOverdueDays)} days\`, cov !== '' && cov < 0.9 ? 'warn' : 'good'),
        tile('Overdue', fmtNum(S.inspOverdue.length), 'had inspections, none lately', S.inspOverdue.length ? 'bad' : 'good'), tile('None on record', fmtNum(S.inspNone.length), 'never inspected in the app', S.inspNone.length ? 'warn' : 'good'),
        tile('Failed (30 days)', fmtNum(recent.filter(i => /^fail/i.test(i.result || '')).length), \`\${fmtNum(recent.length)} inspections · \${fmtNum(recent.filter(i => i.deficiency).length)} with deficiencies\`),
        tile('Corrective actions open', fmtNum(S.openCA.length), \`\${fmtNum(S.openCA.filter(i => i.caState === 'Overdue').length)} past due\`, S.openCA.some(i => i.caState === 'Overdue') ? 'bad' : S.openCA.length ? 'warn' : 'good')])}
      \${store.can('edit') ? '<div class="mhe-pad mhe-pad-tight"><button class="btn primary" data-quick="insp">+ Inspection</button> <button class="btn" data-bulk-insp>✓ Daily inspections for several units</button> <span class="muted small">One site, one date: mark each truck Pass (or note what was found) and save together.</span></div>' : ''}</section>
    <div class="mhe-attn">
      \${rsSection(\`Overdue inspections <span class="pill \${S.inspOverdue.length ? 'bad' : 'good'}">\${fmtNum(S.inspOverdue.length)}</span>\`, lst([...S.inspOverdue].sort((a, b) => b.daysSinceInsp - a.daysSinceInsp), a => \`<li class="bad">\${unitLink(a.assetId)} <span>\${esc(a.family || '')} · \${esc(a.site)}</span><em class="neg">\${fmtNum(a.daysSinceInsp)} days since \${us(a.lastInsp)}</em>\${inspBtn(a)}</li>\`))}
      \${rsSection(\`Open corrective actions <span class="pill \${S.openCA.length ? 'warn' : 'good'}">\${fmtNum(S.openCA.length)}</span>\`, lst(S.openCA, i => \`<li data-insp-open="\${esc(i.id)}" tabindex="0" role="button">\${unitLink(i.assetId)} <span>\${esc(i.failedItems || i.deficiencies || i.result)}</span><em class="\${i.caState === 'Overdue' ? 'neg' : ''}">\${i.caDue ? \`due \${us(i.caDue)}\` : \`found \${us(i.date)}\`}\${i.workOrderId ? \` · \${esc(i.workOrderId)}\` : ''}</em>\${pill(i.caState, i.caState === 'Overdue' ? 'bad' : 'warn')}</li>\`))}
      \${rsSection(\`No inspection on record <span class="pill \${S.inspNone.length ? 'warn' : 'good'}">\${fmtNum(S.inspNone.length)}</span>\`, lst(S.inspNone, a => \`<li>\${unitLink(a.assetId)} <span>\${esc(a.family || '')} · \${esc(a.site)}</span>\${inspBtn(a)}</li>\`)
        + (S.plannedDue.length ? \`<p class="rs-foot"><b>Planned inspections due:</b> \${S.plannedDue.map(a => \`\${unitLink(a.assetId)} \${us(a.plannedDue)}\`).join(', ')}</p>\` : ''))}
    </div>
    <section class="card log-card"><div class="rs-title">Inspection log</div>\${logBlock('mheInspections', { stateKey: 'mhe:insp', filter: siteMatch, colFilters: true })}</section>
    <p class="rail-note">OSHA 1910.178(q)(7): industrial trucks are examined before being placed in service, at least daily (after each shift when used round the clock). A truck is overdue after \${fmtNum(config().inspOverdueDays)} days without an inspection (Settings) — weekends are allowed for. A Fail takes the truck out of service until its work order is completed.</p>\`;
}

function lotoTab(S) {
  const L = S.loto, on = L.filter(l => l.active), since30 = addDays(todayISO(), -30), since90 = addDays(todayISO(), -90);
  const rel30 = L.filter(l => !l.active && String(l.releasedDate || '') >= since30), sup90 = L.filter(l => l.supRemoval && String(l.releasedDate || '') >= since90);
  const locksOn = on.reduce((t, l) => t + l.locksOn.length, 0), gaps = on.filter(l => l.gaps.length), longest = on.reduce((m, l) => Math.max(m, num(l.hoursOn)), 0);
  const when = iso => (iso ? new Date(iso).toLocaleString('en-US', { month: 'numeric', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : '');
  const card = l => \`<article class="lk-card\${l.gaps.length ? ' gap' : ''}" data-loto-open="\${esc(l.id)}" tabindex="0" role="button" aria-label="Open lockout \${esc(l.id)}">
      <header><b>🔒 \${esc(l.id)}</b> \${unitLink(l.assetId)} <small>\${esc([l.family, l.site].filter(Boolean).join(' · '))}</small><span class="grow"></span><small>since \${esc(when(l.appliedAt))}\${l.hoursOn !== '' ? \` · \${fmtNum(l.hoursOn, 1)} hrs\` : ''}</small></header>
      <p>\${esc(l.reason || '')}\${l.workOrderId ? \` <span class="mono muted">(\${esc(l.workOrderId)})</span>\` : ''}</p>
      <ul>\${l.locksOn.map(k => \`<li>\${esc(lockText(k))}</li>\`).join('')}</ul>
      \${l.gaps.length ? \`<p class="lk-gap">⚠ \${esc(l.gapText)}</p>\` : ''}
      <footer><small>\${esc(l.method || '')} · \${esc(l.energy || '')}</small>\${store.can('edit') ? \`<button type="button" class="btn danger small" data-loto-release="\${esc(l.id)}">🔓 Release…</button>\` : ''}</footer></article>\`;
  return \`<section class="card rail-sum"><div class="rs-title">Lockout / tagout\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Locked out now', fmtNum(on.length), \`\${fmtNum(S.lockedUnits.length)} unit\${S.lockedUnits.length === 1 ? '' : 's'} · \${fmtNum(locksOn)} lock\${locksOn === 1 ? '' : 's'} on\`, on.length ? 'bad' : 'good'),
        tile('Longest active', on.length ? \`\${fmtNum(longest, 1)} hrs\` : '—', on.length ? 'since applied' : 'none active'),
        tile('Record incomplete', fmtNum(gaps.length), 'active lockouts missing a check (verified, affected told …)', gaps.length ? 'bad' : 'good'),
        tile('Released (30 days)', fmtNum(rel30.length), rel30.length ? \`avg \${fmtNum(rel30.reduce((t, l) => t + num(l.hoursOn), 0) / rel30.length, 1)} hrs locked out\` : ''),
        tile('Supervisor removals (90 days)', fmtNum(sup90.length), 'lock removed by someone other than who applied it', sup90.length ? 'warn' : '')])}
      \${store.can('edit') ? '<div class="mhe-pad mhe-pad-tight"><button class="btn primary" data-quick="loto">🔒 Lock out equipment</button> <span class="muted small">Takes the unit out of service until the lockout is released.</span></div>' : ''}</section>
    \${rsSection(\`Active lockouts <span class="pill \${on.length ? 'bad' : 'good'}">\${fmtNum(on.length)}</span>\`, on.length ? \`<div class="lk-grid">\${on.map(card).join('')}</div>\` : '<p class="mu-ok">✓ Nothing is locked out.</p>')}
    <section class="card log-card"><div class="rs-title">Lockout Tagout Log</div>\${logBlock('mheLoto', { stateKey: 'mhe:loto', filter: siteMatch, colFilters: true })}</section>
    <p class="rail-note">Piper LOTO policy (Attachment C — Lockout Tagout Log) and OSHA 1910.147: before servicing, tell affected employees, shut the unit down, isolate every energy source (key, battery connector, propane), release or block stored energy (lower the forks, relieve hydraulic pressure), put on each person's own lock and tag, and verify it will not start. Only the person who applied a lock removes it; if they are not available, a supervisor may — after confirming they are not on site, trying to reach them and making sure they are told before they start work again. A tag without a lock needs one more safety measure. Energy control procedures are inspected and certified each year.</p>\`;
}

function documentsTab(S) {
  const D = st.doc, q = norm(D.q), siteOf = new Map(S.A.map(a => [a.assetId, a]));
  const all = store.rows('mheDocs').filter(d => !st.site || siteOf.has(d.assetId));
  const docs = all.filter(d => (!D.cat || d.category === D.cat) && (!q || norm([d.assetId, d.title, d.name, d.category, d.notes, d.addedBy].join(' ')).includes(q))).sort((a, b) => String(b.addedAt).localeCompare(String(a.addedAt)));
  return \`<section class="card rail-sum"><div class="rs-title">Documents &amp; photos\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      <div class="mhe-doc-cats">\${DOC_CATS.map(c => { const n = all.filter(d => d.category === c).length; return \`<button class="mhe-doc-cat \${D.cat === c ? 'on' : ''}" data-doc-cat="\${esc(c)}"><b>\${fmtNum(n)}</b><span>\${esc(c)}</span></button>\`; }).join('')}</div>
      <div class="toolbar mhe-pad-tight"><input type="search" class="search" data-doc-q value="\${esc(D.q)}" placeholder="Search by unit, title or file name…" aria-label="Search documents">
        \${D.cat || D.q ? '<button class="btn ghost small" data-doc-clear>Clear ✕</button>' : ''}<span class="count">\${fmtNum(docs.length)} file\${docs.length === 1 ? '' : 's'}</span><span class="grow"></span>
        \${store.can('edit') ? '<button class="btn primary" data-upload>⬆ Add documents or photos</button>' : ''}</div>
      \${docs.length ? \`<div class="table-wrap"><table class="grid mu-table"><thead><tr><th></th><th>Unit</th><th>Category</th><th>Title</th><th>File</th><th>Added</th><th>Linked to</th></tr></thead><tbody>
        \${docs.slice(0, 300).map(d => { const a = siteOf.get(d.assetId); return \`<tr class="clickable" tabindex="0" data-doc-open="\${esc(d.id)}"><td class="mhe-thumb">\${d.thumb ? \`<img src="\${d.thumb}" alt="">\` : '<span>📄</span>'}</td><td data-l="Unit">\${unitLink(d.assetId)}\${a ? \`<small> \${esc(a.site)}</small>\` : ''}</td><td data-l="Category">\${esc(d.category)}</td><td data-l="Title">\${esc(d.title)}\${d.notes ? \`<br><small class="muted">\${esc(d.notes)}</small>\` : ''}</td>
          <td data-l="File" class="small">\${esc(d.name)} · \${fmtSize(d.size || 0)}</td><td data-l="Added">\${us(String(d.addedAt).slice(0, 10))}\${d.addedBy ? \` · \${esc(d.addedBy)}\` : ''}</td><td data-l="Linked" class="mono">\${esc(d.woId || d.inspectionId || '')}</td></tr>\`; }).join('')}</tbody></table></div>\`
        : \`<p class="mhe-pad muted">\${all.length ? 'No files match.' : 'No documents yet. Open a unit and use <b>⬆ Document / photo</b>, or add them here.'}</p>\`}
      <p class="rs-foot">Click a file to open it (photos and PDFs open in a new tab; other files download). Each file is also on its unit's profile under Documents.</p></section>\`;
}

function reportsTab() {
  const R0 = st.rp, [pf, pt] = presetRange(R0.preset), from = R0.preset === 'custom' && isISO(R0.from) ? R0.from : pf, to = R0.preset === 'custom' && isISO(R0.to) ? R0.to : pt;
  const R = buildReport(st.site, from, to > from ? to : from); st.lastReport = R;
  return \`<section class="card rail-sum rp-head"><div class="rs-title">Reports</div>
      <div class="toolbar mhe-pad-tight">
        <label class="inline">Site <select data-rp-site>\${['', ...SITES].map(s => \`<option value="\${esc(s)}" \${s === st.site ? 'selected' : ''}>\${s ? esc(siteLabel(s)) : 'All sites'}</option>\`).join('')}</select></label>
        <label class="inline">Period <select data-rp-preset>\${PRESETS.map(([k, l]) => \`<option value="\${k}" \${R0.preset === k ? 'selected' : ''}>\${l}</option>\`).join('')}<option value="custom" \${R0.preset === 'custom' ? 'selected' : ''}>Custom dates</option></select></label>
        <label class="inline">From <input type="date" data-rp-from value="\${from}"></label><label class="inline">To <input type="date" data-rp-to value="\${to}"></label>
        <span class="grow"></span><button class="btn" data-rp-xlsx>⬇ Excel</button><button class="btn" data-rp-pdf>⬇ PDF</button></div>
      <nav class="rail-chips rp-jump">\${R.sections.map(s => \`<a class="rchip" href="#" data-rp-jump="rp-\${s.id}">\${esc(s.title)}</a>\`).join('')}</nav>
      <p class="rs-foot">Every figure is counted from the records in the app — nothing is estimated. Where a field isn't recorded yet (model year, purchase price, value), the section says how many units have it.</p></section>
    \${R.sections.map(s => sectionHtml(s)).join('')}\`;
}

// ---------------------------------------------------------------- enter hours for several units at once
/** The week-ending date to offer: the latest date up to today on the same weekday as the log's latest week. */
function defaultWeek() {
  const last = store.rows('mheHours').map(h => h.weekEnding).filter(isISO).sort().at(-1);
  const d = new Date(todayISO() + 'T00:00:00Z'), want = last ? new Date(last + 'T00:00:00Z').getUTCDay() : 6;
  while (d.getUTCDay() !== want) d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}
function bulkHours(rerender) {
  const trucksAt = site => assets().filter(a => isTruck(a) && a.site === site);
  const sitesWithTrucks = SITES.filter(s => trucksAt(s).length);
  let site = st.site && sitesWithTrucks.includes(st.site) ? st.site : sitesWithTrucks[0] || SITES[0], week = defaultWeek();
  const max = config().maxHrsWeek, k = v => norm(v).replace(/\\s+/g, '');
  const back = document.createElement('div');
  back.className = 'modal-back';
  back.innerHTML = \`<form class="modal mhe-bulk" novalidate>
    <div class="modal-head"><h2>Enter hours for several units</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
    <div class="toolbar"><label class="field"><span>Week ending</span><input type="date" name="week" value="\${week}" required></label>
      <label class="field"><span>Site</span><select name="site">\${SITES.map(s => \`<option value="\${esc(s)}" \${s === site ? 'selected' : ''}>\${esc(siteLabel(s))} (\${fmtNum(trucksAt(s).length)})</option>\`).join('')}</select></label></div>
    <p class="muted small">Start hours fill in from each truck's last OK reading. Type the <b>end</b> hours for the trucks you have, or tick <b>Not used</b> for a truck that sat idle all week (End = Start, kept out of the hours averages); rows left blank are skipped. A reading already entered for this week is updated.</p>
    <div class="table-wrap" data-rows></div>
    <div class="modal-foot"><span class="muted small" data-sum></span><div><button type="button" class="btn ghost" data-close>Cancel</button><button type="submit" class="btn primary">Save readings</button></div></div>
  </form>\`;
  document.body.appendChild(back);
  const f = $('form', back), close = () => back.remove();
  const prior = new Map(); // serial -> latest OK reading before the week
  const fill = () => {
    week = f.week.value; site = f.site.value;
    const H = hoursRows(); prior.clear();
    for (const h of H) if ((h.check === 'OK' || h.check === 'Not used') && isISO(h.weekEnding) && h.weekEnding < week) prior.set(k(h.serial), h);
    const list = trucksAt(site).sort((a, b) => String(a.assetId).localeCompare(String(b.assetId), undefined, { numeric: true }));
    // Operator: the employee who ran the truck that week (pick-list = active Employee Roster). Pre-filled from this week's
    // saved reading, else the truck's Assigned Operator, else last week's operator.
    const people = store.rows('employees').filter(e => e.name && norm(e.rosterStatus) === 'ACTIVE').map(e => e.name).sort();
    $('[data-rows]', back).innerHTML = list.length ? \`<datalist id="mhe-bulk-ops">\${people.map(n => \`<option value="\${esc(n)}">\`).join('')}</datalist><table class="grid"><thead><tr><th>Asset ID</th><th>Equipment</th><th>Serial #</th><th>Operator</th><th>Last reading</th><th class="num">Start hours</th><th class="num">End hours</th><th>Not used</th><th class="num">Used</th><th>Check</th></tr></thead><tbody>
      \${list.map(a => {
        const p = prior.get(k(a.serial)), ex = store.rows('mheHours').find(h => h.weekEnding === week && k(h.serial) === k(a.serial));
        const start = ex ? ex.startHours : p ? p.endHours : '';
        const op = ex ? ex.operator || '' : a.operator || p?.operator || '';
        return \`<tr data-serial="\${esc(a.serial)}" data-asset="\${esc(a.assetId)}" data-ex="\${esc(ex?.id || '')}" data-was="\${ex ? esc(\`\${ex.startHours}|\${ex.endHours}|\${ex.operator || ''}|\${norm(ex.notUsed) === 'Y' ? 'Y' : ''}\`) : ''}"><td class="mono"><b>\${esc(a.assetId)}</b></td><td>\${esc(a.family || a.type || '')}</td><td class="mono">\${esc(a.serial)}</td>
          <td><input type="text" list="mhe-bulk-ops" data-op value="\${esc(op)}" placeholder="Employee name" autocomplete="off" aria-label="\${esc(a.assetId)} operator" style="min-width:150px"></td>
          <td class="muted small">\${p ? \`\${us(p.weekEnding)} · \${fmtNum(num(p.endHours), 1)}\` : 'none'}\${ex ? '<br><b>already entered — will update</b>' : ''}</td>
          <td class="num"><input type="number" step="0.1" data-start value="\${esc(start ?? '')}" aria-label="\${esc(a.assetId)} start hours"></td>
          <td class="num"><input type="number" step="0.1" data-end value="\${esc(ex?.endHours ?? '')}" aria-label="\${esc(a.assetId)} end hours"\${ex && norm(ex.notUsed) === 'Y' ? ' disabled' : ''}></td>
          <td class="mhe-nu"><label><input type="checkbox" data-nu\${ex && norm(ex.notUsed) === 'Y' ? ' checked' : ''} aria-label="\${esc(a.assetId)} not used this week"> Not used</label></td>
          <td class="num" data-used></td><td data-chk></td></tr>\`;
      }).join('')}</tbody></table>\` : \`<p class="muted">No powered trucks on the register at \${esc(site)}.</p>\`;
    check();
  };
  const check = () => {
    let n = 0, bad = 0;
    $$('tr[data-serial]', back).forEach(tr => {
      const nu = $('[data-nu]', tr).checked, s = $('[data-start]', tr).value, p = prior.get(k(tr.dataset.serial));
      const e = nu ? s : $('[data-end]', tr).value;
      const used = s !== '' && e !== '' ? +(e - s).toFixed(1) : '';
      const msg = nu ? (s === '' ? 'Start missing' : 'Not used') : e === '' ? '' : s === '' ? 'Start missing' : used < 0 ? 'End < Start' : used > max ? \`Over \${max} hrs\` : p && +s < num(p.endHours) ? 'Below prior week' : 'OK';
      $('[data-used]', tr).textContent = used === '' ? '' : fmtNum(used, 1);
      $('[data-chk]', tr).innerHTML = msg ? pill(msg, msg === 'OK' ? 'good' : msg === 'Not used' ? 'neutral' : 'warn') : '';
      if ((nu || e !== '') && tr.dataset.was !== \`\${+s}|\${+e}|\${$('[data-op]', tr).value.trim()}|\${nu ? 'Y' : ''}\`) { n++; if (msg !== 'OK' && msg !== 'Not used') bad++; }
    });
    $('[data-sum]', back).textContent = n ? \`\${fmtNum(n)} new or changed reading\${n === 1 ? '' : 's'} to save\${bad ? \` · \${fmtNum(bad)} to check (saved anyway, flagged in the log)\` : ''}\` : 'No new end hours typed yet';
  };
  fill();
  f.week.addEventListener('change', fill); f.site.addEventListener('change', fill);
  back.addEventListener('input', e => {
    // Not used: End = Start (locked); a Start typed while it's ticked is copied across.
    const tr = e.target.closest('tr[data-serial]');
    if (tr && e.target.matches('[data-nu],[data-start]') && $('[data-nu]', tr).checked) $('[data-end]', tr).value = $('[data-start]', tr).value;
    if (tr && e.target.matches('[data-nu]')) $('[data-end]', tr).disabled = e.target.checked;
    if (e.target.matches('[data-start],[data-end],[data-op],[data-nu]')) check();
  });
  // Enter in an End box moves to the next truck's End box.
  back.addEventListener('keydown', e => {
    if (e.key === 'Escape') close();
    if (e.key === 'Enter' && e.target.matches('[data-end]')) { e.preventDefault(); const all = $$('[data-end]', back), i = all.indexOf(e.target); (all[i + 1] || $('button[type=submit]', back)).focus(); }
  });
  back.addEventListener('click', e => { if (e.target === back || e.target.closest('[data-close]')) close(); });
  f.addEventListener('submit', async e => {
    e.preventDefault();
    if (!isISO(f.week.value)) return toast('Choose the week-ending date', 'bad');
    const docs = [], missing = [];
    for (const tr of $$('tr[data-serial]', back)) {
      const nu = $('[data-nu]', tr).checked, s = $('[data-start]', tr).value, en = nu ? s : $('[data-end]', tr).value, op = $('[data-op]', tr).value.trim();
      if (nu && s === '') { missing.push(tr.dataset.asset); continue; }
      if (en === '' || tr.dataset.was === \`\${+s}|\${+en}|\${op}|\${nu ? 'Y' : ''}\`) continue; // blank, or already saved as is
      if (s === '') { missing.push(tr.dataset.asset); continue; }
      const ex = tr.dataset.ex ? store.rows('mheHours').find(h => h.id === tr.dataset.ex) : null;
      docs.push({ ...(ex || {}), id: ex?.id || \`\${week}_\${tr.dataset.serial}\`.replace(/[^\\w-]/g, '-'), weekEnding: week, serial: tr.dataset.serial, assetId: tr.dataset.asset, site, startHours: +s, endHours: +en, operator: op, notUsed: nu ? 'Y' : '', exclude: ex?.exclude || '' });
    }
    if (missing.length) return toast(\`Start hours missing for \${missing.join(', ')}\`, 'bad');
    if (!docs.length) return toast('Nothing new to save — type the end hours for at least one truck', 'bad');
    const btn = $('button[type=submit]', back); btn.disabled = true;
    try { await store.writeMany('mheHours', docs); toast(\`Saved \${fmtNum(docs.length)} hour reading\${docs.length === 1 ? '' : 's'} for week ending \${us(week)}\`); close(); rerender(); }
    catch (err) { btn.disabled = false; toast(err.message, 'bad'); }
  });
  $('[data-end]', back)?.focus();
}

// ---------------------------------------------------------------- view
export default {
  needs: () => COLLS,
  render(p) {
    const q = p.query || {};
    if (q.tab && (TABS.some(([k]) => k === q.tab) || q.tab === 'unit')) st.tab = q.tab;
    if (q.site !== undefined) st.site = SITES.includes(q.site) ? q.site : '';
    // Links from the Overview tiles (…&status=Out of Service, &maint=pmOverdue) set the Equipment filters once.
    if (location.hash !== st.lastHash) {
      st.lastHash = location.hash;
      if (st.tab === 'register' && (q.status !== undefined || q.maint !== undefined)) Object.assign(st.eq, { status: q.status || '', maint: q.maint || '', q: '', type: '', cls: '', view: 'list' });
    }
    if (st.tab === 'import' && !store.can('edit')) st.tab = 'dashboard';
    const S = fleetStats(st.site);
    const siteSel = \`<label class="xl-chg">Site <select data-site aria-label="Site"><option value="">All sites</option>\${SITES.map(s => \`<option value="\${esc(s)}" \${s === st.site ? 'selected' : ''}>\${esc(siteLabel(s))}</option>\`).join('')}</select></label>\`;
    const meta = \`<b>Equipment</b><span class="xl-year">\${fmtNum(S.active.length)}</span><b>In service</b><span class="xl-thru">\${fmtNum(S.inService.length)}</span><b>Out</b><span class="xl-thru \${S.outOfService.length ? 'neg' : ''}">\${fmtNum(S.outOfService.length)}</span><b>As of</b><span class="xl-thru">\${us(todayISO())}</span>\${['import', 'unit', 'reports'].includes(st.tab) ? '' : siteSel}\`;
    const empty = !store.rows('mheAssets').length;
    const body = st.tab === 'import' ? importTab()
      : empty ? \`<section class="card rail-perf"><div class="mhe-pad"><h3>No MHE data yet</h3><p>\${store.can('edit') ? 'Load the MHE Fleet Register workbook on the <a href="#/mhe?tab=import">Settings &amp; import</a> tab to fill the register, hours, service, operator and exception logs — or add the first unit with <b>+ Add equipment</b>.' : 'Ask a supervisor to load the MHE Fleet Register workbook.'}</p></div></section>\`
      : st.tab === 'unit' ? renderUnit(q.id || st.unit || '', q)
      : st.tab === 'register' ? equipmentTab(S) : st.tab === 'maintenance' ? maintenanceTab(S) : st.tab === 'inspections' ? inspectionsTab(S) : st.tab === 'loto' ? lotoTab(S) : st.tab === 'documents' ? documentsTab(S) : st.tab === 'reports' ? reportsTab()
      : st.tab === 'hours' ? hoursTab(S) : st.tab === 'operators' ? operatorsTab() : st.tab === 'exceptions' ? exceptionsTab(S) : overviewTab(S);
    if (st.tab === 'unit') st.unit = q.id || st.unit;
    const desc = { dashboard: 'Equipment status at a glance: what is available, what is down, and what needs maintenance or an inspection — at every Piper site.', register: 'Find any unit by ID, serial, make, model, site, type or status. Click one to open its profile.',
      unit: 'Specs, status, maintenance and inspection history, documents and metrics for one unit.', maintenance: 'Work orders from report to completion: Reported → Under Review → Scheduled → In Progress → Completed, with priority and estimated vs actual cost.',
      inspections: 'Daily pre-shift inspections, deficiencies and corrective actions. Overdue inspections are flagged.',
      loto: 'The Lockout Tagout Log: what is locked out now, whose locks are on, and every lockout applied and released.', documents: 'Invoices, manuals, warranty papers, inspection reports, certifications and photos for every unit.',
      reports: 'Fleet, cost, downtime, repair, inspection, age and cost-of-ownership reports by site and date range — export to Excel or PDF.',
      hours: 'Weekly hour-meter readings and the service log (PMs, repairs, tires, batteries, inspections and invoices).', operators: 'Each operator, the equipment they are certified on and every prerequisite: classroom, practical, evaluation, certification, card and expiry.', exceptions: 'Register data issues to resolve, and which attachment goes with which truck.', import: 'Load the MHE Fleet Register workbook; set PM, inspection and replacement intervals and the equipment types.' }[st.tab];
    const title = st.tab === 'unit' ? \`Equipment \${esc(q.id || '')}\` : TABS.find(([k]) => k === st.tab)?.[1] || 'Overview';
    return \`<div class="rail-theme rail-xl mhe">\${head(\`MHE Fleet — \${title}\`, desc, meta)}\${chips()}\${st.tab === 'import' ? '' : actionBar()}\${body}</div>\`;
  },
  after(root, p, rerender) {
    const go = () => { location.hash = \`#/mhe?tab=\${st.tab}\${st.site ? '&site=' + encodeURIComponent(st.site) : ''}\`; };
    $('[data-site]', root)?.addEventListener('change', e => { st.site = e.target.value; go(); });
    bindLogs(root, rerender);
    // Back to the top when moving to another page or unit (the app keeps the scroll position on a redraw).
    const where = st.tab + '|' + (st.tab === 'unit' ? st.unit : '');
    if (where !== st.lastWhere) { st.lastWhere = where; setTimeout(() => window.scrollTo(0, 0)); }
    if (st.tab === 'dashboard' && store.rows('mheAssets').length) drawDashboard(fleetStats(st.site));
    if (st.tab === 'hours') drawDashboard(fleetStats(st.site));
    if (st.tab === 'unit') bindUnit(root, st.unit, rerender);
    if (st.tab === 'reports' && st.lastReport) drawReportChart(st.lastReport);
    bindWoCards(root);
    bindFind(root);
    $$('[data-quick]', root).forEach(b => b.addEventListener('click', () => {
      const unit = st.tab === 'unit' ? st.unit : '';
      ({ wo: () => openWorkOrder(null, unit ? { assetId: unit } : {}), insp: () => openInspection(null, unit ? { assetId: unit } : {}), loto: () => openLoto(null, unit ? { assetId: unit } : {}), asset: () => openAssetForm(null, st.site ? { site: st.site } : {}) })[b.dataset.quick]();
    }));
    $$('[data-wo-open]', root).forEach(li => { const o = e => { if (e.target.closest('a')) return; openWorkOrder(li.dataset.woOpen); }; li.addEventListener('click', o); li.addEventListener('keydown', e => { if (e.key === 'Enter') o(e); }); });
    $$('[data-insp-open]', root).forEach(li => { const o = e => { if (e.target.closest('a')) return; openInspection(li.dataset.inspOpen); }; li.addEventListener('click', o); li.addEventListener('keydown', e => { if (e.key === 'Enter') o(e); }); });
    if (st.tab !== 'unit') $$('[data-loto-open]', root).forEach(el => { const o = e => { if (e.target.closest('a,button')) return; openLoto(el.dataset.lotoOpen); }; el.addEventListener('click', o); el.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target === el) o(e); }); });
    $$('[data-loto-release]', root).forEach(b => b.addEventListener('click', e => { e.stopPropagation(); openLotoRelease(b.dataset.lotoRelease); }));
    $$('[data-insp-unit]', root).forEach(b => b.addEventListener('click', () => openInspection(null, { assetId: b.dataset.inspUnit })));
    $('[data-bulk-insp]', root)?.addEventListener('click', () => openBulkInspections(st.site));
    $$('[data-mhe-checklist]', root).forEach(b => b.addEventListener('click', openChecklistPrint));
    $('[data-upload]', root)?.addEventListener('click', () => openUpload({}));
    const invDrop = $('[data-inv-drop]', root);
    if (invDrop) {
      const pick = () => { const i = Object.assign(document.createElement('input'), { type: 'file', multiple: true, accept: '.pdf,application/pdf,image/*' }); i.onchange = () => openInvoices([...i.files]); i.click(); };
      invDrop.addEventListener('click', pick); invDrop.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(); } });
      invDrop.addEventListener('dragover', e => { e.preventDefault(); invDrop.classList.add('over'); });
      invDrop.addEventListener('dragleave', () => invDrop.classList.remove('over'));
      invDrop.addEventListener('drop', e => { e.preventDefault(); invDrop.classList.remove('over'); openInvoices([...e.dataTransfer.files]); });
    }
    // Equipment list: filters, sort, view, open a unit, export.
    const E = st.eq, cleanHash = () => { if (/[?&](status|maint)=/.test(location.hash)) go(); else rerender(); };
    let et; const eqQ = $('[data-eq-q]', root);
    eqQ?.addEventListener('input', () => { clearTimeout(et); et = setTimeout(() => { E.q = eqQ.value; st.eqLimit = 300; rerender(); setTimeout(() => { const n = $('[data-eq-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 200); });
    $$('[data-eq]', root).forEach(s => s.addEventListener('change', () => { E[s.dataset.eq] = s.value; cleanHash(); }));
    $('[data-eq-site]', root)?.addEventListener('change', e => { st.site = e.target.value; go(); });
    $$('[data-eq-clear]', root).forEach(b => b.addEventListener('click', () => { Object.assign(E, { q: '', type: '', cls: '', status: '', maint: '' }); st.site = ''; go(); }));
    $$('[data-eq-view]', root).forEach(b => b.addEventListener('click', () => { E.view = b.dataset.eqView; rerender(); }));
    $('[data-eq-more]', root)?.addEventListener('click', () => { st.eqLimit = 1e6; rerender(); });
    $$('[data-eq-sort]', root).forEach(th => { const s = () => { E.dir = E.sort === th.dataset.eqSort ? -E.dir : 1; E.sort = th.dataset.eqSort; rerender(); }; th.addEventListener('click', s); th.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); s(); } }); });
    $$('tr[data-unit]', root).forEach(tr => { const o = () => { location.hash = \`#/mhe?tab=unit&id=\${encodeURIComponent(tr.dataset.unit)}\`; }; tr.addEventListener('click', o); tr.addEventListener('keydown', e => { if (e.key === 'Enter') o(); }); });
    $('[data-eq-xlsx]', root)?.addEventListener('click', () => {
      const list = equipmentList(fleetStats(st.site));
      const cols = [['Asset ID', 'assetId'], ['Type', 'family'], ['Class', 'assetClass'], ['Make', 'make'], ['Model', 'model'], ['Year', 'modelYear'], ['Serial #', 'serial'], ['Site', 'site'], ['Location', 'location'], ['Department', 'department'], ['Assigned operator', 'operator'], ['Status', 'status'], ['Status since', 'statusSince'], ['Status reason', 'statusReason'],
        ['Hour meter', 'hourMeter'], ['Avg hrs / wk', 'avgHrsWk'], ['Last PM', 'lastPM'], ['Next PM', 'nextPM'], ['PM status', 'pmStatus'], ['Last inspection', 'lastInsp'], ['Inspection status', 'inspStatus'], ['Open work orders', 'openWO'], ['Ownership', 'ownership'],
        ['Purchase date', 'purchaseDate'], ['Purchase price', 'purchasePrice'], ['Monthly cost', 'monthlyCost'], ['Remaining cost', 'remainingCost'], ['Monthly depreciation', 'monthlyDep'], ['Book value', 'bookValue'], ['Current value', 'currentValue'], ['Warranty ends', 'warrantyEnd'], ['Maintenance $ (12 mo)', 'spend12'], ['Notes', 'notes']];
      downloadXLSX(\`MHE Equipment \${todayISO()}.xlsx\`, 'Equipment', cols.map(c => c[0]), list.map(a => cols.map(([, k]) => (typeof a[k] === 'number' ? +a[k].toFixed(2) : a[k] ?? ''))));
      toast(\`Exported \${fmtNum(list.length)} units to Excel\`);
    });
    // Maintenance board filters.
    let wt; const woQ = $('[data-wo-q]', root);
    woQ?.addEventListener('input', () => { clearTimeout(wt); wt = setTimeout(() => { st.wo.q = woQ.value; rerender(); setTimeout(() => { const n = $('[data-wo-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $('[data-wo-prio]', root)?.addEventListener('change', e => { st.wo.prio = e.target.value; rerender(); });
    // Documents.
    let dt; const dq = $('[data-doc-q]', root);
    dq?.addEventListener('input', () => { clearTimeout(dt); dt = setTimeout(() => { st.doc.q = dq.value; rerender(); setTimeout(() => { const n = $('[data-doc-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $$('[data-doc-cat]', root).forEach(b => b.addEventListener('click', () => { st.doc.cat = st.doc.cat === b.dataset.docCat ? '' : b.dataset.docCat; rerender(); }));
    $('[data-doc-clear]', root)?.addEventListener('click', () => { st.doc = { q: '', cat: '' }; rerender(); });
    $$('[data-doc-open]', root).forEach(tr => { const o = async e => { if (e.target.closest('a')) return; try { await openDoc(store.rows('mheDocs').find(d => d.id === tr.dataset.docOpen)); } catch (err) { toast(err.message, 'bad'); } }; tr.addEventListener('click', o); tr.addEventListener('keydown', e => { if (e.key === 'Enter') o(e); }); });
    // Reports.
    $('[data-rp-site]', root)?.addEventListener('change', e => { st.site = e.target.value; go(); });
    $('[data-rp-preset]', root)?.addEventListener('change', e => { st.rp.preset = e.target.value; if (e.target.value === 'custom') { const [f, t] = presetRange('ytd'); st.rp.from ||= f; st.rp.to ||= t; } rerender(); });
    $$('[data-rp-from],[data-rp-to]', root).forEach(i => i.addEventListener('change', () => { st.rp = { preset: 'custom', from: $('[data-rp-from]', root).value, to: $('[data-rp-to]', root).value }; rerender(); }));
    $('[data-rp-xlsx]', root)?.addEventListener('click', () => exportExcel(st.lastReport));
    $('[data-rp-pdf]', root)?.addEventListener('click', () => exportPdf(st.lastReport));
    $$('[data-rp-jump]', root).forEach(a => a.addEventListener('click', e => { e.preventDefault(); document.getElementById(a.dataset.rpJump)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }));
    $('[data-show-flagged]', root)?.addEventListener('click', e => {
      e.preventDefault();
      Object.assign(logState('mhe:hours'), { ids: hoursRows().filter(siteMatch).filter(h => h.check !== 'OK' && h.check !== 'Excluded' && h.check !== 'Not used').map(h => h.id), year: 'all', q: '', limit: 200 });
      rerender(); setTimeout(() => document.querySelector('[data-state="mhe:hours"]')?.scrollIntoView({ behavior: 'smooth' }), 50);
    });
    // Operators: search / status filter, open a certification, add one.
    const opQ = $('[data-op-q]', root); let t;
    opQ?.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => { st.opQ = opQ.value; rerender(); setTimeout(() => { const n = $('[data-op-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $('[data-op-st]', root)?.addEventListener('change', e => { st.opSt = e.target.value; rerender(); });
    $('[data-show-former]', root)?.addEventListener('change', e => { st.showFormer = e.target.checked; rerender(); });
    // Mark someone not on the roster as a former employee (or back to current): sets Former employee on all their certifications.
    $$('[data-mark-former]', root).forEach(b => b.addEventListener('click', async e => {
      e.stopPropagation();
      const name = b.dataset.markFormer, val = b.dataset.val;
      const docs = store.rows('mheOperators').filter(o => norm(o.employee) === norm(name));
      if (!docs.length) return;
      if (val === 'Y' && !await ask(\`Mark \${name} as a former employee? Their \${docs.length} certification\${docs.length === 1 ? '' : 's'} will be hidden and no longer counted as expired or past due. You can undo this with "Show former employees".\`, { ok: 'Mark as former', danger: false })) return;
      try { await store.writeMany('mheOperators', docs.map(d => ({ ...d, leftCompany: val }))); toast(val === 'Y' ? \`\${name} marked as a former employee\` : \`\${name} is back as a current employee\`); rerender(); }
      catch (err) { toast(err.message, 'bad'); }
    }));
    $$('[data-cert]', root).forEach(el => {
      const open = () => editRow('mheOperators', derive('mheOperators').find(r => r.id === el.dataset.cert));
      el.addEventListener('click', open); el.addEventListener('keydown', e => { if (e.key === 'Enter') open(); });
    });
    $('[data-bulk-hours]', root)?.addEventListener('click', () => bulkHours(rerender));
    $('[data-add-cert]', root)?.addEventListener('click', () => editRow('mheOperators', null, st.site ? { building: st.site } : {}));
    // Import
    const file = $('[data-file]', root), drop = $('[data-drop]', root);
    const read = async f => {
      if (!f) return; busy = true; rerender();
      try { parsed = await readRegister(f); } catch (e) { parsed = null; toast(e.message, 'bad'); }
      busy = false; rerender();
    };
    drop?.addEventListener('click', () => file.click());
    file?.addEventListener('change', () => read(file.files[0]));
    drop?.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('over'); });
    drop?.addEventListener('dragleave', () => drop.classList.remove('over'));
    drop?.addEventListener('drop', e => { e.preventDefault(); drop.classList.remove('over'); read(e.dataTransfer.files[0]); });
    $('[data-cancel]', root)?.addEventListener('click', () => { parsed = null; rerender(); });
    $('[data-load]', root)?.addEventListener('click', async () => {
      const d = parsed; if (!d) return;
      busy = true; rerender();
      try {
        const plan = await applyImport(d);
        toast(\`MHE Fleet updated: \${plan.reduce((t, x) => t + x.add.length, 0)} new, \${plan.reduce((t, x) => t + x.upd.length, 0)} updated rows\`);
        parsed = null; st.tab = 'dashboard';
      } catch (e) { toast(e.message, 'bad'); }
      busy = false; go(); rerender();
    });
    $('[data-cfg]', root)?.addEventListener('submit', async e => {
      e.preventDefault(); const f = new FormData(e.target);
      const types = [...new Set(String(f.get('types') || '').split(/\\r?\\n/).map(s => s.trim()).filter(Boolean))];
      try {
        await store.set('mheConfig', 'main', { ...(store.rows('mheConfig').find(d => d.id === 'main') || {}), id: undefined, pmInterval: +f.get('pmInterval') || 90, maxHrsWeek: +f.get('maxHrsWeek') || 100, expiringDays: +f.get('expiringDays') || 60,
          pmHours: +f.get('pmHours') || '', inspOverdueDays: +f.get('inspOverdueDays') || 3, planInspDays: +f.get('planInspDays') || 365, dueSoonDays: +f.get('dueSoonDays') || 30, lifeYears: +f.get('lifeYears') || 10, types });
        toast('MHE settings saved');
      } catch (err) { toast(err.message, 'bad'); }
    });
  },
};`]);
